12: 
13: class UpdateCategoryRequest extends FormRequest
14: {
15:     use NormalizesCatalogInput;
16: 
17:     protected function prepareForValidation(): void
18:     {
19:         parent::prepareForValidation();
20:         $this->normalizeCatalogIdentifiers();
21:     }
22: 
23:     public function authorize(): bool
24:     {
25:         return $this->user() !== null;
26:     }
27: 
28:     /**
29:      * @return array<string, array<mixed>|string|ValidationRule>
30:      */
31:     public function rules(): array
32:     {
33:         return [
34:             'parent_id' => ['sometimes', 'nullable', 'integer', Rule::exists('categories', 'id')->whereNull('deleted_at')],
35:             'name_ar' => ['sometimes', 'required', 'string', 'max:150'],
36:             'name_en' => ['sometimes', 'required', 'string', 'max:150'],
37:             'slug' => ['sometimes', 'nullable', 'string', 'max:180', 'alpha_dash:ascii', new UniqueCatalogIdentifier('categories', 'slug', $this->route('category')->id)],
38:             'description_ar' => ['sometimes', 'nullable', 'string'],
39:             'description_en' => ['sometimes', 'nullable', 'string'],
