11:     {
12:         return strtr($term, ['\\' => '\\\\', '%' => '\\%', '_' => '\\_']);
13:     }
14: 
15:     public static function pattern(string $term): string
16:     {
17:         return '%'.self::escape($term).'%';
18:     }
