  28: function BranchForm({ open, initial, onClose, onSave }) {
  29:   const blank = { name: '', code: '', type: 'branch', phone: '', email: '', address: '', city: '', active: true };
  30:   const [f, setF] = useState(blank);
  31:   const [err, setErr] = useState({});
  32:   const [busy, setBusy] = useState(false);
  33:   useEffect(() => { if (open) {
  34:     setF(initial ? { id: initial.id, name: initial.name || '', code: initial.code || '', type: initial.type || 'branch', phone: initial.phone || '', email: initial.email || '', address: initial.address || '', city: initial.city || '', active: initial.is_active } : blank);
  35:     setErr({}); setBusy(false);
  36:   } }, [open]);
  37:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
  38:   const submit = async () => {
  39:     const e = {};
  40:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
  41:     if (!f.code.trim()) e.code = 'الكود مطلوب';
  42:     if (f.email.trim() && !/^\S+@\S+\.\S+$/.test(f.email.trim())) e.email = 'صيغة البريد غير صحيحة';
  43:     // The API leaves city optional (StoreBranchRequest: nullable) — the UI stays
  44:     // optional too on purpose instead of forcing a 422-prone required field.
  45:     setErr(e);
  46:     if (Object.keys(e).length) return;
  47:     setBusy(true);
  48:     const res = await onSave(f);
  49:     setBusy(false);
  50:     if (res && (res.fields || res.message)) setErr({ ...res.fields, ...(res.message ? { _form: res.message } : {}) });
  51:   };
  52:   return (
  53:     <Modal open={open} onClose={onClose} width="max-w-2xl"
  54:       title={initial ? 'تعديل ' + (initial.type === 'warehouse' ? 'المخزن' : 'الفرع') : 'إضافة فرع أو مخزن'}
  55:       sub="المخزن يُسجَّل كنوع من الفروع ويملك مواقع تخزين خاصة به."
  56:       footer={<>
  57:         <button className="btn btn-dark" onClick={submit} disabled={busy}>
  58:           {busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />}
  59:           {initial ? 'حفظ التعديلات' : 'إضافة'}
  60:         </button>
  61:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
  62:       </>}>
  63:       <div className="space-y-4">
  64:         {err._form && <InlineAlert kind="red">{err._form}</InlineAlert>}
  65:         <div>
  66:           <span className="field-label">النوع</span>
  67:           <div className="grid grid-cols-2 gap-2.5">
  68:             {[['branch', 'فرع', 'store', 'نقطة بيع تستقبل العملاء'], ['warehouse', 'مخزن', 'warehouse', 'تخزين وتوزيع فقط']].map(([k, l, ic, d]) => (
  69:               <button key={k} type="button" onClick={() => set('type', k)}
  70:                 className={`rounded-2xl p-3.5 flex items-center gap-3 text-right transition border ${f.type === k ? 'border-[var(--accent-orange)]' : 'border-transparent'}`}
  71:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>
  72:                 <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.type === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'}`}><Icon n={ic} s={16} /></span>
  73:                 <span><span className="block text-[13px] font-semibold c-primary">{l}</span><span className="block text-[11px] c-secondary">{d}</span></span>
  74:               </button>
  75:             ))}
  76:           </div>
  77:         </div>
  78:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
  79:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="مثال: فرع مدينة نصر" /></Field>
  80:           <Field label="الكود" req error={err.code} hint="فريد على مستوى النظام"><input dir="ltr" maxLength={50} className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="BR-XXX" /></Field>
  81:           <Field label="الهاتف" error={err.phone}><input dir="ltr" className="inp num text-left" value={f.phone} onChange={e => set('phone', e.target.value)} placeholder="01xxxxxxxxx" /></Field>
  82:           <Field label="البريد الإلكتروني" error={err.email}><input dir="ltr" className={`inp mono text-left ${err.email ? 'err' : ''}`} value={f.email} onChange={e => set('email', e.target.value)} placeholder="branch@company.com" /></Field>
  83:           <Field label="المدينة" error={err.city}><input className={`inp ${err.city ? 'err' : ''}`} value={f.city} onChange={e => set('city', e.target.value)} maxLength={100} /></Field>
  84:           <Field label="العنوان" error={err.address}><input className="inp" value={f.address} onChange={e => set('address', e.target.value)} /></Field>
  85:         </div>
  86:         <div className="v-subcard p-3.5 flex items-center justify-between">
  87:           <div>
  88:             <div className="text-[13px] font-semibold c-primary">الحالة: {f.active ? 'نشط' : 'غير نشط'}</div>
  89:             <div className="text-[11px] c-secondary">الفروع غير النشطة لا تظهر في عمليات التحويل والتسوية.</div>
  90:           </div>
  91:           <Toggle on={f.active} onChange={v => set('active', v)} />
  92:         </div>
  93:       </div>
  94:     </Modal>
  95:   );
  96: }
