 289: function LocationsScreen({ go, params }) {
 290:   const { toast, can, branchesQuery, reloadBranches } = useInv();
 291:   const branchId = Number(params.branchId);
 292:   const [form, setForm] = useState({ open: false, initial: null });
 293:   const [del, setDel] = useState(null);
 294:   const [delBusy, setDelBusy] = useState(false);
 295:   const [delErr, setDelErr] = useState(null);
 296:   const [tf, setTf] = useState('all');
 297: 
 298:   const shared = branchesQuery.data || [];
 299:   const br = shared.find(b => b.id === branchId);
 300:   const sharedPhase = apiPhase(branchesQuery, shared.length === 0);
 301:   const locQuery = useApi(signal => (br ? fetchAllLocations(br.id, signal) : Promise.resolve([])), [br ? br.id : 0]);
 302:   const locPhase = apiPhase(locQuery, (locQuery.data || []).length === 0);
 303: 
 304:   const restriction = useRestrictedBranch();
 305:   if (!canAny(can, 'locations.view', 'locations.manage')) return <NoPerm title="مواقع التخزين" perm="locations.view" go={go} />;
 306:   if (restriction.locked && branchId !== Number(restriction.branchId)) return <NoPerm title="مواقع التخزين" perm="inventory.all_branches" go={go} />;
 307:   const branchOptions = (restriction.locked ? shared.filter(b => b.id === restriction.branchId) : shared.filter(b => b.is_active))
 308:     .map(b => ({ value: b.id, label: `${b.name} · ${b.type === 'warehouse' ? 'مخزن' : 'فرع'}` }));
 309: 
 310:   const phase = sharedPhase.phase === 'ready' ? locPhase.phase : sharedPhase.phase;
 311:   const error = sharedPhase.phase === 'ready' ? locPhase.error : sharedPhase.error;
 312:   const onRetry = () => { reloadBranches(); locQuery.reload(); };
 313:   const onBack = () => go('branches');
 314: 
 315:   if (sharedPhase.phase === 'ready' && !br) {
 316:     return (
 317:       <section className="space-y-5">
 318:         <PageHead title="مواقع التخزين" back={{ label: 'الفروع والمخازن', onClick: onBack }} />
 319:         <Card><EmptyState icon="pin" title="الفرع غير موجود" sub="ربما تم حذفه. اختر فرعًا آخر من القائمة."
 320:           action={<button className="btn btn-dark btn-sm" onClick={onBack}>رجوع لقائمة الفروع</button>} /></Card>
 321:       </section>
 322:     );
 323:   }
 324: 
 325:   const all = locQuery.data || [];
 326:   const rows = all.filter(l => tf === 'all' || l.type === tf);
 327:   const canAdd = canAny(can, 'locations.create', 'locations.manage');
 328:   const canEdit = canAny(can, 'locations.update', 'locations.manage');
 329:   const canDelete = canAny(can, 'locations.delete', 'locations.manage');
 330: 
 331:   const payload = f => ({ name: f.name.trim(), code: f.code.trim(), type: f.type, is_active: !!f.active });
 332:   const save = async f => {
 333:     try {
 334:       if (f.id) {
 335:         const cur = all.find(l => l.id === f.id) || {};
 336:         const next = payload(f);
 337:         const diff = {};
 338:         ['name', 'code', 'type', 'is_active'].forEach(k => { if ((next[k] ?? null) !== (cur[k] ?? null)) diff[k] = next[k] ?? null; });
 339:         if (Object.keys(diff).length) await locationsApi.update(br.id, f.id, diff);
 340:       } else {
 341:         await locationsApi.create(br.id, payload(f));
 342:       }
 343:     } catch (e) {
 344:       const ne = normalizeError(e);
 345:       return { fields: ne.fields, message: ne.message };
 346:     }
 347:     setForm({ open: false, initial: null });
 348:     reloadBranches(); locQuery.reload(); toast('تم حفظ موقع التخزين');
 349:     return null;
 350:   };
 351:   const toggle = async l => {
 352:     try {
 353:       await locationsApi.update(br.id, l.id, { is_active: !l.is_active });
 354:       reloadBranches(); locQuery.reload(); toast(l.is_active ? 'تم تعطيل الموقع' : 'تم تفعيل الموقع');
 355:     } catch (e) { toast(normalizeError(e).message); }
 356:   };
 357:   const doDelete = async () => {
 358:     setDelBusy(true); setDelErr(null);
 359:     try {
 360:       await locationsApi.remove(br.id, del.id);
 361:       setDel(null); reloadBranches(); locQuery.reload(); toast('تم حذف الموقع');
 362:     } catch (e) {
 363:       setDelErr(normalizeError(e).message);
 364:     } finally { setDelBusy(false); }
 365:   };
 366: 
 367:   const typeCounts = Object.keys(LOCATION_TYPES).reduce((a, k) => ({ ...a, [k]: all.filter(l => l.type === k).length }), {});
 368: 
 369:   return (
 370:     <section className="space-y-5">
 371:       <PageHead title="مواقع التخزين" back={{ label: 'الفروع والمخازن', onClick: onBack }}
 372:         sub={br && <span className="flex items-center gap-2">{br.name} <span className="mono text-[11.5px] c-muted" dir="ltr">{br.code}</span> <TypeBadge type={br.type} /></span>}
 373:         actions={<>
 374:           <Sel value={br?.id} onChange={id => id && go('locations', { branchId: id })} options={branchOptions} placeholder="اختر الفرع" className="!rounded-full !py-2 w-56" disabled={restriction.locked} />
 375:           {canAdd && <button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة موقع</button>}
 376:         </>} />
 377: 
 378:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
 379:         <Card className="lg:col-span-4" stagger={2}>
 380:           <div className="v-orange-card rounded-[18px] p-5">
 381:             <div className="flex items-center justify-between">
 382:               <span className="text-[12.5px] font-medium text-white/90">إجمالي المواقع</span>
 383:               <span className="w-7 h-7 rounded-full bg-white/15 flex items-center justify-center"><Icon n="pin" s={14} /></span>
 384:             </div>
 385:             <div className="font-display text-[40px] font-bold num text-right mt-2">{phase === 'ready' ? all.length : '—'}</div>
 386:             <div className="text-[11.5px] text-white/80">{all.filter(l => l.is_active).length} نشط · {all.filter(l => !l.is_active).length} معطّل</div>
 387:           </div>
 388:           <div className="mt-4 space-y-1">
 389:             {Object.entries(LOCATION_TYPES).map(([k, t]) => (
 390:               <button key={k} onClick={() => setTf(tf === k ? 'all' : k)} className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition ${tf === k ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]'}`}>
 391:                 <span className="flex items-center gap-2.5 text-[12.5px] c-primary"><Badge cls={({ shelf: 'b-gray', zone: 'b-blue', bin: 'b-gray', damaged: 'b-red', receiving: 'b-amber' })[k]}>{t}</Badge></span>
 392:                 <span className="flex items-center gap-3">
 393:                   <span className="w-20 h-1.5 rounded-full hatched overflow-hidden"><span className="block h-full bg-[var(--accent-orange)] rounded-full" style={{ width: `${all.length ? typeCounts[k] / all.length * 100 : 0}%` }} /></span>
 394:                   <span className="num text-[12px] font-semibold c-primary w-4 text-left">{typeCounts[k]}</span>
 395:                 </span>
 396:               </button>
 397:             ))}
 398:           </div>
 399:         </Card>
 400: 
 401:         <Card className="lg:col-span-8" stagger={3}>
 402:           <CardHead title="المواقع" meta={tf === 'all' ? 'كل الأنواع' : LOCATION_TYPES[tf]}
 403:             right={tf !== 'all' && <button className="btn btn-ghost btn-sm" onClick={() => setTf('all')}><Icon n="x" s={12} /> إزالة الفلتر</button>} />
 404:           <Phase phase={phase} cols={5} rows={5} error={error} onRetry={onRetry} onBack={onBack}
 405:             empty={<EmptyState icon="pin" title="لا توجد مواقع تخزين في هذا الفرع" sub="أضف رفوفًا ومناطق وخانات لتحديد مكان كل صنف بدقة."
 406:               action={canAdd && <button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة موقع</button>} />}>
 407:             {rows.length === 0 ? <EmptyState icon="pin" title="لا توجد مواقع من هذا النوع" /> : (
 408:               <table className="vt">
 409:                 <thead><tr><th>الاسم</th><th>الكود</th><th>النوع</th><th>الحالة</th><th></th></tr></thead>
 410:                 <tbody>
 411:                   {rows.map(l => (
 412:                     <tr key={l.id} className={l.is_active ? '' : 'opacity-60'}>
 413:                       <td className="font-semibold c-primary">{l.name}</td>
 414:                       <td><Sku>{l.code}</Sku></td>
 415:                       <td><Badge cls={({ shelf: 'b-gray', zone: 'b-blue', bin: 'b-gray', damaged: 'b-red', receiving: 'b-amber' })[l.type] || 'b-gray'}>{LOCATION_TYPES[l.type] || l.type}</Badge></td>
 416:                       <td>
 417:                         <div className="flex items-center gap-2.5">
 418:                           {canEdit && <Toggle on={l.is_active} onChange={() => toggle(l)} />}
 419:                           <span className={`text-[11.5px] font-semibold ${l.is_active ? '' : 'c-muted'}`} style={l.is_active ? { color: 'var(--badge-green-text)' } : {}}>{l.is_active ? 'نشط' : 'معطّل'}</span>
 420:                         </div>
 421:                       </td>
 422:                       <td>
 423:                         {(canEdit || canDelete) && (
 424:                           <div className="flex items-center gap-0.5 justify-end">
 425:                             {canEdit && <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: l })}><Icon n="edit" s={15} /></button>}
 426:                             {canDelete && <button className="icon-btn" title="حذف" onClick={() => { setDel(l); setDelErr(null); }}><Icon n="trash" s={15} /></button>}
 427:                           </div>
 428:                         )}
 429:                       </td>
 430:                     </tr>
 431:                   ))}
 432:                 </tbody>
 433:               </table>
 434:             )}
 435:           </Phase>
 436:         </Card>
 437:       </div>
 438: 
 439:       <LocationForm open={form.open} initial={form.initial} branchId={br?.id} branchName={br?.name} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 440:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger busy={delBusy} error={delErr} title="حذف موقع التخزين؟" confirmLabel="حذف"
 441:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>) من {br?.name}.</>} />
 442:     </section>
 443:   );
 444: }
