 623: function CountDetail({ go, params }) {
 624:   const { toast, can, variantCache } = useInv();
 625:   const id = Number(params.id);
 626:   const [vals, setVals] = useState({});
 627:   const [filter, setFilter] = useState('all');
 628:   const [confirm, setConfirm] = useState(false);
 629:   const [pendingAction, setPendingAction] = useState(null);
 630:   const [busy, setBusy] = useState(false);
 631:   const [err, setErr] = useState(null);
 632:   const [dirty, setDirty] = useState(false);
 633:   const [stale, setStale] = useState({ itemIds: [], variantIds: [] });
 634:   const canEdit = canAny(can, 'stocktakes.update', 'stocktakes.manage');
 635:   const canApprove = canAny(can, 'stocktakes.approve', 'stocktakes.manage');
 636:   const canDelete = canAny(can, 'stocktakes.delete', 'stocktakes.manage');
 637: 
 638:   const query = useApi(signal => stocktakesApi.show(id, signal).then(t => {
 639:     cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
 640:     return t;
 641:   }), [id]);
 642: 
 643:   useEffect(() => {
 644:     const t = query.data;
 645:     if (t && !dirty) {
 646:       setVals(Object.fromEntries((t.items || []).map(it => [it.product_variant_id, it.counted_qty === null ? '' : String(it.counted_qty)])));
 647:     }
 648:   }, [query.data]);
 649: 
 650:   useEffect(() => {
 651:     if (!dirty) return;
 652:     const warn = e => { e.preventDefault(); e.returnValue = ''; };
 653:     window.addEventListener('beforeunload', warn);
 654:     return () => window.removeEventListener('beforeunload', warn);
 655:   }, [dirty]);
 656:   useEffect(() => {
 657:     window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: dirty }));
 658:     return () => window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: false }));
 659:   }, [dirty]);
 660: 
 661:   if (!canAny(can, 'stocktakes.view', 'stocktakes.manage')) return <NoPerm title="تفاصيل الجرد" perm="stocktakes.view" go={go} />;
 662: 
 663:   const c = query.data;
 664:   const { phase, error } = apiPhase(query, !c);
 665:   const onRetry = () => { query.reload(); };
 666: 
 667:   // "" means "not counted yet", "0" means an actual zero — never coerce "" to 0.
 668:   const countedOf = v => (v === '' || v === undefined ? null : Number(toLatinDigits(v)));
 669:   const rows = ((c?.items) || []).map(it => {
 670:     const v = vals[it.product_variant_id];
 671:     const a = countedOf(v);
 672:     const changed = a !== (it.counted_qty == null ? null : Number(it.counted_qty));
 673:     const diff = changed ? (a === null ? null : +((a - Number(it.system_qty)).toFixed(4))) : (it.difference == null ? null : Number(it.difference));
 674:     return { ...it, a, diff, isStale: stale.itemIds.includes(it.id) || stale.variantIds.includes(it.product_variant_id) };
 675:   });
 676:   const counted = rows.filter(r => r.a !== null).length;
 677:   const shown = rows.filter(r => filter === 'all' || (filter === 'uncounted' && r.a === null) || (filter === 'diff' && r.diff) || (filter === 'match' && r.diff === 0) || (filter === 'stale' && r.isStale));
 678:   const diffs = rows.filter(r => r.diff);
 679:   const editable = c && !['approved', 'cancelled'].includes(c.status) && canEdit;
 680: 
 681:   const chunked = arr => { const out = []; for (let i = 0; i < arr.length; i += 500) out.push(arr.slice(i, i + 500)); return out; };
 682:   const saveCounts = async (only = null) => {
 683:     if (busy) return;
 684:     if (rows.some(r => {
 685:       const v = vals[r.product_variant_id];
 686:       return v !== '' && v !== undefined && (!QTY_RE.test(toLatinDigits(v)) || Number(toLatinDigits(v)) > QTY_MAX);
 687:     })) { setErr('الكمية يجب أن تكون صفرًا أو أكبر، وبحد أقصى أربع خانات عشرية.'); return; }
 688:     setBusy(true); setErr(null);
 689:     const targets = only ? rows.filter(r => only.includes(r.product_variant_id)) : rows.filter(r => {
 690:       const cur = c.items.find(it => it.product_variant_id === r.product_variant_id);
 691:       return r.a !== (cur?.counted_qty == null ? null : Number(cur.counted_qty));
 692:     });
 693:     try {
 694:       for (const part of chunked(targets)) {
 695:         await stocktakesApi.updateItems(id, part.map(r => ({
 696:           product_variant_id: r.product_variant_id, counted_qty: r.a,
 697:           ...(r.isStale ? { recount: true } : {}),
 698:         })));
 699:       }
 700:       const savedIds = new Set(targets.map(r => r.product_variant_id));
 701:       setDirty(rows.some(r => !savedIds.has(r.product_variant_id) && r.a !== (c.items.find(it => it.product_variant_id === r.product_variant_id)?.counted_qty == null ? null : Number(c.items.find(it => it.product_variant_id === r.product_variant_id).counted_qty))));
 702:       setStale(s => ({ itemIds: s.itemIds.filter(x => !targets.some(r => r.id === x)), variantIds: s.variantIds.filter(x => !savedIds.has(x)) }));
 703:       toast('تم حفظ العدّ'); query.reload();
 704:     } catch (e) { setErr(normalizeError(e).message); }
 705:     setBusy(false);
 706:   };
 707:   const startCounting = async () => {
 708:     setBusy(true); setErr(null);
 709:     try { await stocktakesApi.update(id, { status: 'in_progress' }); toast('بدأ العدّ'); query.reload(); }
 710:     catch (e) { setErr(normalizeError(e).message); }
 711:     setBusy(false);
 712:   };
 713:   const changeStatus = async () => {
 714:     if (busy) return;
 715:     setBusy(true); setErr(null);
 716:     try {
 717:       if (pendingAction === 'delete') {
 718:         const res = await stocktakesApi.remove(id);
 719:         setDirty(false); window.dispatchEvent(new CustomEvent('inventory:dirty', { detail: false }));
 720:         toast(res.message || 'تم حذف الجرد'); go('counts');
 721:       } else {
 722:         await stocktakesApi.update(id, { status: 'cancelled' });
 723:         setDirty(false); query.reload(); toast('تم إلغاء الجرد');
 724:       }
 725:       setPendingAction(null);
 726:     } catch (e) { setErr(normalizeError(e).message); }
 727:     setBusy(false);
 728:   };
 729:   const approve = async () => {
 730:     setBusy(true); setErr(null);
 731:     try {
 732:       const res = await stocktakesApi.approve(id);
 733:       setConfirm(false); setStale({ itemIds: [], variantIds: [] });
 734:       toast(res.message || 'تم اعتماد الجرد وترحيل الفروق'); query.reload();
 735:     } catch (e) {
 736:       const ne = normalizeError(e);
 737:       if (/لم تُعدّ/.test(ne.message)) { setFilter('uncounted'); query.reload(); }
 738:       if (ne.fields?.recount_item_ids || ne.fields?.recount_variant_ids) {
 739:         setStale({
 740:           itemIds: (ne.fields.recount_item_ids || []).map(Number),
 741:           variantIds: (ne.fields.recount_variant_ids || []).map(Number),
 742:         });
 743:         setFilter('stale');
 744:       }
 745:       setErr(ne.message);
 746:     }
 747:     setBusy(false);
 748:   };
 749: 
 750:   return (
 751:     <section className="space-y-5">
 752:       <PageHead title={c ? <span className="mono" dir="ltr">{c.stocktake_number}</span> : 'تفاصيل الجرد'} back={{ label: 'الجرد', onClick: () => go('counts') }}
 753:         sub={c && <span className="flex items-center gap-2 flex-wrap">{c.branch?.name || '—'} <span className="c-muted">·</span> {c.location ? <span className="mono" dir="ltr">{c.location.name}</span> : 'كل المواقع'} <Badge cls={({ draft: 'b-gray', in_progress: 'b-amber', approved: 'b-green', cancelled: 'b-red' })[c.status] || 'b-gray'} dot>{STOCKTAKE_STATUS[c.status] || c.status}</Badge></span>}
 754:         actions={c && c.status !== 'approved' && <>
 755:           {canDelete && ['draft', 'cancelled'].includes(c.status) && <button className="btn btn-danger" disabled={busy} onClick={() => { setErr(null); setPendingAction('delete'); }}>حذف الجرد</button>}
 756:           {editable && <button className="btn btn-soft" disabled={busy} onClick={() => { setErr(null); setPendingAction('cancel'); }}>إلغاء الجرد</button>}
 757:           {c.status === 'draft' && canEdit && <button className="btn btn-soft" disabled={busy} onClick={startCounting}>بدء العدّ</button>}
 758:           {editable && <button className="btn btn-soft" disabled={!dirty || busy} onClick={() => saveCounts()}>{busy ? 'جارٍ الحفظ…' : 'حفظ العدّ'}</button>}
 759:           {c.status !== 'cancelled' && (canApprove
 760:             ? <button className="btn btn-orange" onClick={() => { setErr(null); setConfirm(true); }} disabled={busy || dirty || !rows.length || counted < rows.length}><Icon n="check" s={14} w={2.2} /> اعتماد الجرد</button>
 761:             : <span className="inline-flex items-center gap-1.5 text-[11.5px] c-muted px-3 py-1.5 rounded-full v-subcard"><Icon n="lock" s={12} /> الاعتماد يتطلب صلاحية</span>)}
 762:         </>} />
 763: 
 764:       {dirty && <InlineAlert kind="amber" icon="info" title="تغييرات غير محفوظة">احفظ العدّ قبل مغادرة الصفحة حتى لا تضيع الكميات المدخلة.</InlineAlert>}
 765:       {err && !confirm && <InlineAlert kind="red">{err}<button className="btn btn-soft btn-sm" disabled={busy} onClick={() => saveCounts()}>إعادة المحاولة</button></InlineAlert>}
 766: 
 767:       <Phase phase={phase} cols={5} rows={5} error={error} onRetry={onRetry} onBack={() => go('counts')} empty={<Card><EmptyState icon="clipboard" title="لا توجد بنود في هذا الجرد" /></Card>}>
 768:         {c && (<>
 769:         <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
 770:           <KPI hot label="تم العدّ" icon="clipboard" value={`${counted}/${rows.length}`} sub={counted < rows.length ? `${rows.length - counted} بند لم يُعدّ بعد` : 'اكتمل العدّ'} />
 771:           <KPI label="مطابق" icon="check" value={rows.filter(r => r.diff === 0).length} />
 772:           <KPI label="بفروق" icon="alert" value={diffs.length} />
 773:           <KPI label="صافي الفرق" icon="sliders" value={(() => { const n = diffs.reduce((a, r) => a + r.diff, 0); return (n > 0 ? '+' : '') + formatQty(n); })()} sub="بالوحدات" />
 774:         </div>
 775: 
 776:         <Card stagger={3}>
 777:           <CardHead title="جدول العدّ" right={
 778:             <div className="seg">
 779:               {[['all', 'الكل'], ['uncounted', 'لم يُعدّ'], ['diff', 'بفروق'], ['match', 'مطابق'], ...(stale.itemIds.length || stale.variantIds.length ? [['stale', 'يحتاج إعادة عدّ']] : [])].map(([k, l]) => <button key={k} className={filter === k ? 'on' : ''} onClick={() => setFilter(k)}>{l}</button>)}
 780:             </div>} />
 781:           {counted < rows.length && c.status !== 'approved' && <div className="mb-3"><InlineAlert kind="amber" icon="info" title="الحقل الفارغ ≠ صفر">الخانة الفارغة المظللة تعني «لم يتم العدّ». إذا كان الصنف غير موجود فعليًا اكتب 0 أو اضغط «صفر».</InlineAlert></div>}
 782:           {stale.itemIds.length + stale.variantIds.length > 0 && <div className="mb-3"><InlineAlert kind="red" icon="alert" title="أصناف تحتاج إعادة عدّ">تغيّر رصيدها بعد عدّها. عدّها من جديد ثم اضغط «إعادة العدّ» على البند.</InlineAlert></div>}
 783:           {shown.length === 0 ? <EmptyState icon="filter" title="لا توجد بنود بهذا الفلتر" /> : (
 784:             <table className="vt">
 785:               <thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">كمية النظام</th><th className="t-num" style={{ width: 200 }}>الكمية الفعلية</th><th className="t-num">الفرق</th><th>الحالة</th></tr></thead>
 786:               <tbody>
 787:                 {shown.map(r => (
 788:                   <tr key={r.product_variant_id} className={r.isStale ? 'ring-1 ring-inset' : ''} style={r.isStale ? { background: 'var(--badge-red-bg)' } : {}}>
 789:                     <td><Sku>{r.sku || `#${r.product_variant_id}`}</Sku></td>
 790:                     <td><div className="font-medium c-primary truncate">{variantDisplayName(variantCache, r.product_variant_id, r.sku)}</div></td>
 791:                     <td className="t-num num c-secondary">{formatQty(r.system_qty)}</td>
 792:                     <td className="t-num">
 793:                       {editable ? (
 794:                         <div className="flex items-center gap-1.5 justify-end">
 795:                           {r.a === null && <button className="btn btn-ghost btn-sm !px-2 !py-1 text-[11px]" onClick={() => { setVals(v => ({ ...v, [r.product_variant_id]: '0' })); setDirty(true); }}>صفر</button>}
 796:                           <div className={`rounded-[10px] w-28 ${r.a === null ? 'uncounted' : ''}`}>
 797:                             <NumInput small value={vals[r.product_variant_id] ?? ''} placeholder="لم يُعدّ" onChange={v => { setVals(x => ({ ...x, [r.product_variant_id]: v })); setDirty(true); }} className={r.a === null ? '!bg-transparent' : ''} />
 798:                           </div>
 799:                           {r.a !== null && <button className="icon-btn !w-6 !h-6" title="مسح (لم يُعدّ)" onClick={() => { setVals(v => ({ ...v, [r.product_variant_id]: '' })); setDirty(true); }}><Icon n="x" s={11} /></button>}
 800:                           {r.isStale && <button className="btn btn-soft btn-sm" disabled={busy} onClick={() => saveCounts([r.product_variant_id])}>إعادة العدّ</button>}
 801:                         </div>
 802:                       ) : <span className="num font-semibold c-primary">{r.a === null ? <span className="c-muted font-normal">لم يُعدّ</span> : formatQty(r.a)}</span>}
 803:                     </td>
 804:                     <td className="t-num num font-bold" style={{ color: r.diff === null ? 'var(--text-muted)' : r.diff > 0 ? 'var(--badge-green-text)' : r.diff < 0 ? 'var(--badge-red-text)' : 'var(--text-secondary)' }}>
 805:                       {r.diff === null ? '—' : r.diff === 0 ? '0' : (r.diff > 0 ? '+' : '−') + formatQty(Math.abs(r.diff))}
 806:                     </td>
 807:                     <td>{r.isStale ? <Badge cls="b-red">تحتاج إعادة عدّ</Badge> : r.a === null ? <Badge cls="b-gray">لم يُعدّ</Badge> : r.a === 0 ? <Badge cls={r.diff ? 'b-red' : 'b-green'}>صفر فعلي</Badge> : r.diff === 0 ? <Badge cls="b-green">مطابق</Badge> : <Badge cls={r.diff > 0 ? 'b-blue' : 'b-red'}>{r.diff > 0 ? 'زيادة' : 'عجز'}</Badge>}</td>
 808:                   </tr>
 809:                 ))}
 810:               </tbody>
 811:             </table>
 812:           )}
 813:         </Card>
 814:         </>)}
 815:       </Phase>
 816: 
 817:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={approve} busy={busy} error={err} title="اعتماد الجرد" confirmLabel="اعتماد وترحيل الفروق"
 818:         body={<>سيتم ترحيل <b className="num c-primary">{diffs.length}</b> فرق كحركات «فرق جرد» وتحديث الأرصدة. لا يمكن تعديل العدّ بعد الاعتماد.</>} />
 819:       <ConfirmDialog open={!!pendingAction} onClose={() => setPendingAction(null)} onConfirm={changeStatus} busy={busy} error={err} danger
 820:         title={pendingAction === 'delete' ? 'حذف الجرد؟' : 'إلغاء الجرد؟'} confirmLabel={pendingAction === 'delete' ? 'حذف الجرد' : 'إلغاء الجرد'}
 821:         body="سيُقفل الجرد وتُفقد أي تغييرات غير محفوظة. لن تتغير الأرصدة بهذه العملية." />
 822:     </section>
 823:   );
 824: }
