 832: function ProductionScreen({ go }) {
 833:   const { toast, can, variantCache } = useInv();
 834:   const [open, setOpen] = useState(false);
 835:   const [view, setView] = useState(null);
 836:   const [page, setPage] = useState(1);
 837:   const canEnter = can('inventory.adjust') && can('products.view_cost');
 838:   const showCost = can('products.view_cost');
 839: 
 840:   const history = useApi(signal => productionApi.list({ per_page: 15, page }, signal), [page]);
 841:   const optsQuery = useApi(signal => productionApi.options('', signal), []);
 842:   useEffect(() => {
 843:     const d = optsQuery.data;
 844:     if (d) {
 845:       (d.variants || []).forEach(v => {
 846:         cacheVariantOptions(variantCache, [v]);
 847:       });
 848:     }
 849:   }, [optsQuery.data]);
 850: 
 851:   const branchName = useMemo(() => {
 852:     const m = new Map();
 853:     (optsQuery.data?.branches || []).forEach(b => m.set(b.id, b.name));
 854:     return id => m.get(id) || `#${id}`;
 855:   }, [optsQuery.data]);
 856:   const locName = useMemo(() => {
 857:     const m = new Map();
 858:     (optsQuery.data?.branches || []).forEach(b => (b.locations || []).forEach(l => m.set(l.id, l.name)));
 859:     return id => (id ? m.get(id) || `#${id}` : '—');
 860:   }, [optsQuery.data]);
 861: 
 862:   const rows = history.data?.data || [];
 863:   if (!can('inventory.view')) return <NoPerm title="استلام الإنتاج" perm="inventory.view" go={go} />;
 864:   const { phase, error } = apiPhase(history, rows.length === 0);
 865:   // Raw Laravel paginator (data/current_page/last_page/…) — NOT under meta, so it
 866:   // gets its own small mapper instead of the ResourceCollection one.
 867: 
 868:   return (
 869:     <section className="space-y-5">
 870:       <PageHead title="استلام الإنتاج" sub="تسجيل المنتجات التامة الواردة من التصنيع إلى المخزن مع تكلفة الوحدة."
 871:         actions={canEnter ? <button className="btn btn-dark" onClick={() => setOpen(true)}><Icon n="plus" s={14} w={2.2} /> تسجيل استلام</button>
 872:           : <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-pill-surface"><Icon n="lock" s={12} /> يتطلب صلاحية تسوية المخزون وعرض التكلفة</span>} />
 873:       <Card stagger={2}>
 874:         <CardHead title="سجل الاستلامات" meta={phase === 'ready' ? `${rows.length} استلام` : null} />
 875:         <Phase phase={phase} cols={6} error={error} onRetry={() => history.reload()}
 876:           empty={<EmptyState icon="factory" title="لا توجد استلامات إنتاج" sub="عند وصول دفعة من التصنيع سجّلها هنا لتُضاف إلى رصيد المخزن." action={canEnter && <button className="btn btn-dark btn-sm" onClick={() => setOpen(true)}><Icon n="plus" s={13} /> تسجيل استلام</button>} />}>
 877:           <table className="vt">
 878:             <thead><tr><th>رقم الدفعة</th><th>الفرع</th><th>الموقع</th><th className="t-num">البنود</th><th className="t-num">إجمالي الكمية</th>{showCost && <th className="t-num">إجمالي التكلفة</th>}<th>التاريخ</th></tr></thead>
 879:             <tbody>
 880:               {rows.map(p => (
 881:                 <tr key={p.id} className="cursor-pointer" onClick={() => setView(p)}>
 882:                   <td><Sku>{p.batch_number}</Sku></td>
 883:                   <td className="c-primary font-medium">{branchName(p.branch_id)}</td>
 884:                   <td className="mono text-[11.5px] c-secondary" dir="ltr">{locName(p.location_id)}</td>
 885:                   <td className="t-num num c-secondary">{(p.items || []).length}</td>
 886:                   <td className="t-num num font-semibold c-primary">{(p.items || []).reduce((a, l) => a + Number(l.quantity || 0), 0)}</td>
 887:                   {showCost && <td className="t-num num c-primary">{formatCurrency((p.items || []).reduce((a, l) => a + Number(l.quantity || 0) * Number(l.unit_cost || 0), 0))}</td>}
 888:                   <td className="num text-[11.5px] c-secondary">{formatDate(p.created_at, { includeTime: true })}</td>
 889:                 </tr>
 890:               ))}
 891:             </tbody>
 892:           </table>
 893:           {history.data && history.data.last_page > 1 && (
 894:             <div className="flex items-center justify-between mt-4">
 895:               <button className="btn btn-soft btn-sm" disabled={page <= 1} onClick={() => setPage(p => Math.max(1, p - 1))}>السابق</button>
 896:               <span className="text-[12px] c-muted num">صفحة {history.data.current_page} من {history.data.last_page}</span>
 897:               <button className="btn btn-soft btn-sm" disabled={page >= history.data.last_page} onClick={() => setPage(p => p + 1)}>التالي</button>
 898:             </div>
 899:           )}
 900:         </Phase>
 901:       </Card>
 902:       <ProductionForm open={open} onClose={() => setOpen(false)} branches={optsQuery.data?.branches || []} onSaved={() => { history.reload(); }} />
 903:       <Modal open={!!view} onClose={() => setView(null)} width="max-w-xl" title={view ? <span className="mono" dir="ltr">{view.batch_number}</span> : ''} sub={view && `${branchName(view.branch_id)} · ${locName(view.location_id)}`}>
 904:         {view && <table className="vt mb-4"><thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">الكمية</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}</tr></thead>
 905:           <tbody>{(view.items || []).map((l, i) => <tr key={i}><td><Sku>{variantCache.get(Number(l.product_variant_id))?.sku || `#${l.product_variant_id}`}</Sku></td><td><div className="font-medium c-primary truncate">{variantDisplayName(variantCache, l.product_variant_id, null)}</div></td><td className="t-num num font-semibold">{formatQty(l.quantity)}</td>{showCost && <td className="t-num num">{l.unit_cost != null ? formatCurrency(l.unit_cost) : '—'}</td>}</tr>)}</tbody></table>}
 906:       </Modal>
 907:     </section>
 908:   );
 909: }
