 911: function ProductionForm({ open, onClose, branches, onSaved }) {
 912:   const { toast, variantCache } = useInv();
 913:   const { keyFor, reset } = useIdempotencyKey();
 914:   const restriction = useRestrictedBranch();
 915:   const [f, setF] = useState({ batch: '', branchId: null, locId: null, note: '' });
 916:   const [lines, setLines] = useState([newPrLine()]);
 917:   const [tried, setTried] = useState(false);
 918:   const [busy, setBusy] = useState(false);
 919:   const [err, setErr] = useState(null);
 920:   const [rowErrs, setRowErrs] = useState({});
 921:   useEffect(() => { if (open) { setF({ batch: '', branchId: restriction.locked ? restriction.branchId : null, locId: null, note: '' }); setLines([newPrLine()]); setTried(false); setErr(null); setRowErrs({}); setBusy(false); } }, [open]);
 922:   const upd = (k, p) => { setLines(ls => ls.map(l => l.key === k ? { ...l, ...p } : l)); setRowErrs({}); };
 923:   const bad = l => {
 924:     if (!l.variantId) return true;
 925:     const qv = toLatinDigits(l.qty);
 926:     if (!/^\d+$/.test(qv) || !(Number(qv) >= 1) || Number(qv) > 99999999) return true;
 927:     const cv = toLatinDigits(l.cost);
 928:     if (cv === '' || !QTY_RE.test(cv) || Number(cv) < 0 || Number(cv) > QTY_MAX) return true;
 929:     return false;
 930:   };
 931:   const valid = f.batch.trim() && f.batch.trim().length <= 100 && f.branchId && lines.length && lines.length <= PRD_MAX && lines.every(l => !bad(l));
 932:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId) !== i).length;
 933:   const total = lines.reduce((a, l) => a + (Number(toLatinDigits(l.qty)) || 0) * (Number(toLatinDigits(l.cost)) || 0), 0);
 934:   const locOpts = ((branches.find(b => b.id === f.branchId)?.locations) || []).map(l => ({ value: l.id, label: l.name }));
 935:   const submit = async () => {
 936:     setTried(true); if (!valid || dupes || busy) return;
 937:     setBusy(true); setErr(null); setRowErrs({});
 938:     const payload = {
 939:       batch_number: f.batch.trim(), branch_id: f.branchId,
 940:       ...(f.locId ? { location_id: f.locId } : {}),
 941:       notes: f.note.trim() ? f.note.trim().slice(0, 1000) : null,
 942:       items: lines.map(l => ({ product_variant_id: l.variantId, quantity: Number(toLatinDigits(l.qty)), unit_cost: Number(toLatinDigits(l.cost)) })),
 943:     };
 944:     try {
 945:       // Idempotency-Key is REQUIRED here (422 without it); same payload reuses
 946:       // the same key so a double-click records one receipt only.
 947:       const res = await productionApi.create(payload, keyFor(payload));
 948:       reset();
 949:       toast(res.message || 'تم تسجيل استلام الإنتاج');
 950:       onClose(); onSaved();
 951:     } catch (e) {
 952:       const ne = normalizeError(e);
 953:       setRowErrs({ ...ne.fields, ...groupItemsErrors(ne.fields) });
 954:       setErr(ne.message);
 955:       setBusy(false);
 956:     }
 957:   };
 958:   return (
 959:     <Modal open={open} onClose={onClose} width="max-w-4xl" title="تسجيل استلام إنتاج" sub={`حتى ${PRD_MAX} بندًا · الكميات أعداد صحيحة · المتغيرات مميزة`}
 960:       footer={<>
 961:         <button className="btn btn-orange" onClick={submit} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} تسجيل الاستلام</button>
 962:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
 963:         <span className="flex-1" />
 964:         <span className="text-[12px] c-secondary">إجمالي التكلفة <span className="num font-display text-[18px] font-bold c-primary mr-1">{formatCurrency(total)}</span></span>
 965:       </>}>
 966:       <div className="space-y-4">
 967:         {err && <InlineAlert kind="red" title="رفض الخادم العملية">{err}</InlineAlert>}
 968:         {dupes > 0 && <InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر — المتغيرات يجب أن تكون مميزة، احذف التكرار قبل التسجيل.</InlineAlert>}
 969:         <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
 970:           <Field label="رقم الدفعة" req error={tried && !f.batch.trim() ? 'مطلوب' : rowErrs.batch_number}><input dir="ltr" className={`inp mono text-left ${tried && !f.batch.trim() ? 'err' : ''}`} maxLength={100} value={f.batch} onChange={e => setF({ ...f, batch: e.target.value.toUpperCase() })} placeholder="B-2610-08" /></Field>
 971:           <Field label="الفرع / المخزن" req error={tried && !f.branchId ? 'مطلوب' : rowErrs.branch_id}><Sel value={f.branchId} disabled={restriction.locked} onChange={v => setF({ ...f, branchId: v || null, locId: null })} placeholder="اختر…" options={branches.filter(b => !restriction.locked || b.id === restriction.branchId).map(b => ({ value: b.id, label: b.name }))} /></Field>
 972:           <Field label="الموقع" hint="اختياري"><Sel value={f.locId} onChange={v => setF({ ...f, locId: v || null })} placeholder={f.branchId ? 'الموقع الافتراضي' : '—'} disabled={!f.branchId} options={locOpts} /></Field>
 973:         </div>
 974:         <div>
 975:           <div className="flex items-center justify-between mb-2">
 976:             <span className="field-label !mb-0">البنود <span className="num c-muted">{lines.length}/{PRD_MAX}</span></span>
 977:             <button className="btn btn-soft btn-sm" disabled={lines.length >= PRD_MAX} onClick={() => setLines(ls => [...ls, newPrLine()])}><Icon n="plus" s={13} /> إضافة بند</button>
 978:           </div>
 979:           <table className="vt">
 980:             <thead><tr><th className="w-8">#</th><th style={{ minWidth: 300 }}>المتغير / SKU</th><th style={{ width: 120 }}>الكمية</th><th style={{ width: 140 }}>تكلفة الوحدة</th><th className="t-num">الإجمالي</th><th></th></tr></thead>
 981:             <tbody>
 982:               {lines.map((l, i) => {
 983:                 const re = rowErrs[i] || {};
 984:                 return (
 985:                 <tr key={l.key}>
 986:                   <td className="num c-muted">{i + 1}</td>
 987:                   <td><div className={(tried && !l.variantId) || re.product_variant_id ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
 988:                     {re.product_variant_id && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.product_variant_id}</div>}</td>
 989:                   <td><NumInput small integer value={l.qty} onChange={v => upd(l.key, { qty: v })} err={(tried && bad(l)) || re.quantity} />
 990:                     {re.quantity && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.quantity}</div>}</td>
 991:                   <td><NumInput small decimals={4} value={l.cost} onChange={v => upd(l.key, { cost: v })} err={(tried && bad(l)) || re.unit_cost} placeholder="0.00" />
 992:                     {re.unit_cost && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.unit_cost}</div>}</td>
 993:                   <td className="t-num num c-primary font-semibold">{formatCurrency((Number(toLatinDigits(l.qty)) || 0) * (Number(toLatinDigits(l.cost)) || 0))}</td>
 994:                   <td><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
 995:                 </tr>
 996:                 );
 997:               })}
 998:             </tbody>
 999:           </table>
1000:         </div>
1001:         <Field label="ملاحظات"><textarea maxLength={1000} className="inp" rows={2} value={f.note} onChange={e => setF({ ...f, note: e.target.value })} /></Field>
1002:       </div>
1003:     </Modal>
1004:   );
1005: }
