1010: function FilterBar({ children, onReset, active }) {
1011:   return (
1012:     <div className="v-subcard p-3 flex flex-wrap items-end gap-2.5 mb-4">
1013:       {children}
1014:       {active > 0 && <button onClick={onReset} className="btn btn-ghost btn-sm mb-0.5"><Icon n="x" s={12} /> مسح ({active})</button>}
1015:     </div>
1016:   );
1017: }
1018: const FItem = ({ label, w = 'w-44', children }) => (
1019:   <div className={w}><div className="text-[10.5px] font-medium c-muted mb-1 pr-1">{label}</div>{children}</div>
