1425:                           <td className="t-num num text-[12px]"><span className="c-muted">{formatQty(m.balance_before)}</span> <span className="c-muted mx-1">→</span> <span className="font-semibold c-primary">{formatQty(m.balance_after)}</span></td>
1426:                           {showCost && <td className="t-num num c-secondary">{m.unit_cost != null ? formatCurrency(m.unit_cost) : '—'}</td>}
