1689:                         <td><Sel small value={l.toLoc} onChange={v => upd(l.key, { toLoc: v || null })} placeholder={to ? 'موقع الاستلام الافتراضي' : '—'} disabled={!to} options={toLocOpts} /></td>
1690:                         <td>
1691:                           <NumInput small value={l.req} onChange={v => upd(l.key, { req: v })} err={(tried && lineBad(l)) || re.requested_qty} placeholder="0.0000" />
1692:                           {re.requested_qty && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{re.requested_qty}</div>}
1693:                         </td>
1694:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1695:                       </tr>
1696:                     );
1697:                   })}
1698:                 </tbody>
1699:               </table>
1700:             </div>
1701:           </Card>
1702:         </>)}
1703:       </Phase>
1704:     </section>
