1708: function TransferDetail({ go, params }) {
1709:   const { toast, can, variantCache } = useInv();
1710:   const restriction = useRestrictedBranch();
1711:   const id = Number(params.id);
1712:   const [stage, setStage] = useState(null); // 'approve' | 'ship' | 'receive'
1713:   const [qtys, setQtys] = useState({});
1714:   const [confirm, setConfirm] = useState(null);
1715:   const [busy, setBusy] = useState(false);
1716:   const [err, setErr] = useState(null);
1717:   const [conflict, setConflict] = useState(null);
1718:   const [stageErrors, setStageErrors] = useState({});
1719:   const [delBusy, setDelBusy] = useState(false);
