1721: 
1722:   const query = useApi(signal => transfersApi.show(id, signal).then(t => {
1723:     cacheVariantNames(variantCache, (t.items || []).map(it => ({ id: it.product_variant_id, sku: it.sku })));
1724:     return t;
1725:   }), [id]);
1726: 
1727:   if (!canView) return <NoPerm title="تفاصيل التحويل" perm="transfers.view" go={go} />;
1728: 
1729:   const t = query.data;
1730:   const { phase, error } = apiPhase(query, !t);
1731:   const onRetry = () => { setConflict(null); query.reload(); };
1732: 
1733:   const stageMeta = {
1734:     approve: { col: 'approved_qty', srcCol: 'requested_qty', label: 'اعتماد', perm: 'transfers.approve', hint: 'حدّد الكمية المعتمدة لكل بند. البند الغائب يأخذ الكمية المطلوبة تلقائيًا.' },
1735:     ship:    { col: 'shipped_qty', srcCol: 'approved_qty', label: 'شحن', perm: 'transfers.ship', hint: 'أدخل الكمية المشحونة فعليًا. سيتم خصمها من المصدر وتظهر «قيد النقل».' },
1736:     receive: { col: 'received_qty', srcCol: 'shipped_qty', label: 'استلام', perm: 'transfers.receive', hint: 'أدخل الكمية المستلمة فعليًا في الوجهة. أي فرق يُسجَّل كعجز تحويل.' },
1737:   };
1738:   const startStage = s => { const m = stageMeta[s]; setStageErrors({}); setErr(null); setStage(s); setQtys(Object.fromEntries((t.items || []).map((l, i) => [i, String(l[m.srcCol] ?? '')]))); };
1739:   const idx = t ? TR_FLOW.indexOf(t.status) : -1;
1740: 
1741:   const stagePayload = () => {
1742:     const m = stageMeta[stage];
1743:     return {
1744:       expected_version: t.version,
1745:       items: (t.items || []).map((l, i) => ({ id: l.id, [m.col]: Number(toLatinDigits(qtys[i])) })),
1746:     };
1747:   };
1748:   const commit = async () => {
1749:     if (busy) return;
1750:     setBusy(true); setErr(null);
1751:     try {
1752:       const res = await transfersApi[stage](id, stagePayload());
1753:       setConfirm(null); setStage(null);
