1808: 
1809:       {conflict && <InlineAlert kind="amber" title="تعارض — تم تعديل التحويل" onClose={() => setConflict(null)}>{conflict}<div className="mt-2"><button className="btn btn-dark btn-sm" onClick={onRetry}><Icon n="refresh" s={13} /> إعادة تحميل وراجعة الكميات</button></div></InlineAlert>}
