1917: // ============ Shared Vortix UI primitives (RTL) ============
1918: 
1919: 
1920: const InvCtx = createContext(null);
1921: const useInv = () => useContext(InvCtx);
1922: 
1923: // Dropdowns share successful location reads for this authenticated inventory
1924: // session. Branch/location writes invalidate the context cache before reloading.
1925: export function useBranchesWithLocations(branchId) {
1926:   const { branchesQuery, locationCache } = useInv();
1927:   const query = useApi(async signal => {
1928:     if (!branchId) return [];
1929:     if (locationCache.has(Number(branchId))) return locationCache.get(Number(branchId));
1930:     const rows = await fetchAllLocations(Number(branchId), signal);
1931:     if (!signal.aborted) locationCache.set(Number(branchId), rows);
1932:     return rows;
1933:   }, [branchId || 0, branchesQuery.data]);
1934:   return { ...query, branches: (branchesQuery.data || []).filter(b => b.is_active) };
1935: }
1936: 
1937: 
1938: // ---------- Inventory API layer (Phases 1-2) ----------
1939: // All inventory screens are API-backed. Screens
1940: // use catalog/useApi + @alfarid/api-client with the shared context cache below.
1941: 
1942: // Branch-scoped users (branch_id set, not super admin, no inventory.all_branches)
1943: // are locked to their branch: the backend rejects anything else, and the UI
1944: // hides other branches from dropdowns and disables the branch switcher.
1945: function useRestrictedBranch() {
1946:   const user = useAuthStore(s => s.user);
1947:   const perms = user?.permissions;
1948:   const elevated = hasPermission(perms, '*') || hasPermission(perms, 'inventory.all_branches')
1949:     || (user?.roles || []).some(r => /super[\s_-]?admin/i.test(String(r)));
1950:   const branchId = user?.branch_id ?? null;
1951:   if (branchId == null || elevated) return { branchId: null, locked: false };
1952:   return { branchId: Number(branchId), locked: true };
1953: }
1954: 
1955: // Variant name cache: list endpoints (movements/transfers/stocktakes) return SKU
1956: // only, so every variant seen from any source (options, StockLevel.variant) is
1957: // cached here and reused for display. Never one request per row.
1958: function cacheVariantNames(cache, list) {
1959:   (list || []).forEach(v => {
1960:     if (v && v.id != null) {
1961:       const old = cache.get(Number(v.id)) || {};
1962:       cache.set(Number(v.id), { ...old, name_ar: v.product_name_ar ?? v.name_ar ?? old.name_ar, name_en: v.product_name_en ?? v.name_en ?? old.name_en, sku: v.sku ?? old.sku });
1963:     }
1964:   });
1965: }
1966: function cacheVariantOptions(cache, options) {
1967:   options.forEach(v => {
1968:     const old = cache.get(Number(v.id)) || {};
1969:     const parts = (v.label || '').split(' / ');
1970:     const sku = parts.pop();
1971:     cache.set(Number(v.id), { ...old, label: v.label, name_ar: old.name_ar || parts.join(' / '), sku: old.sku || sku });
1972:   });
1973: }
1974: function variantDisplayName(cache, id, sku) {
1975:   const hit = cache.get(Number(id));
1976:   if (hit) return hit.name_ar || hit.name_en || hit.sku || sku || '—';
1977:   return sku || '—';
1978: }
