2130: function ErrorState({ msg = 'تعذّر الاتصال بالخادم. تحقّق من الاتصال وحاول مرة أخرى.', code = 'HTTP 503', onRetry }) {
2131:   const { reload } = useInv();
2132:   const retry = onRetry || reload;
2133:   return (
2134:     <div className="py-12 px-6 flex flex-col items-center text-center rounded-2xl fade-in" style={{ background: 'var(--badge-red-bg)' }}>
2135:       <div className="w-12 h-12 rounded-full flex items-center justify-center mb-3" style={{ background: 'var(--bg-card)', color: 'var(--badge-red-text)' }}>
2136:         <Icon n="alert" s={20} />
2137:       </div>
2138:       <div className="font-display text-[15px] font-semibold" style={{ color: 'var(--badge-red-text)' }}>حدث خطأ أثناء تحميل البيانات</div>
2139:       <div className="text-[12.5px] c-secondary mt-1 max-w-md">{msg}</div>
2140:       <div className="mono text-[10.5px] c-muted mt-2">{code}</div>
2141:       <button onClick={retry} className="btn btn-dark btn-sm mt-4"><Icon n="refresh" s={13} /> إعادة المحاولة</button>
2142:     </div>
2143:   );
2144: }
