2146: // Wrap list content with phase handling
2147: // List phases: loading | ready | empty | denied (403) |
2148: // notfound (404 + back to list) | conflict (409 banner + reload). Server
2149: // messages are Arabic — rendered verbatim, never translated.
2150: function Phase({ phase, cols, rows, empty, children, error, onRetry, onBack }) {
2151:   const { go } = useInv();
2152:   const back = onBack || (() => go('stock'));
2153:   if (phase === 'loading') return <SkeletonRows cols={cols} rows={rows} />;
2154:   if (phase === 'denied') return <NoPerm message={error?.message} go={back} />;
2155:   if (phase === 'notfound') return <Card><EmptyState icon="search" title="العنصر غير موجود" sub={error?.message || 'ربما تم حذفه.'} action={<button className="btn btn-dark btn-sm" onClick={back}>رجوع للقائمة</button>} /></Card>;
2156:   if (phase === 'conflict') return (<div className="space-y-4"><InlineAlert kind="amber" title="تعارض مع الخادم (409)"><p>{error?.message || 'تغيّرت البيانات على الخادم.'}</p><div className="mt-2"><button className="btn btn-dark btn-sm" onClick={onRetry}><Icon n="refresh" s={13} /> إعادة تحميل</button></div></InlineAlert>{children}</div>);
2157:   if (phase === 'error') return <ErrorState msg={error?.message} code={error?.status ? `HTTP ${error.status}` : undefined} onRetry={onRetry} />;
2158:   if (phase === 'empty') return empty;
2159:   return children;
2160: }
