2162: function InlineAlert({ kind = 'red', icon = 'alert', title, children, onClose }) {
2163:   const map = { red: ['--badge-red-bg', '--badge-red-text'], amber: ['--badge-amber-bg', '--badge-amber-text'], blue: ['--badge-blue-bg', '--badge-blue-text'], green: ['--badge-green-bg', '--badge-green-text'] }[kind];
2164:   return (
2165:     <div className="rounded-2xl px-4 py-3 flex items-start gap-3 fade-in" style={{ background: `var(${map[0]})` }}>
2166:       <span style={{ color: `var(${map[1]})` }} className="mt-0.5"><Icon n={icon} s={16} /></span>
2167:       <div className="flex-1 text-[12.5px]">
2168:         {title && <div className="font-semibold" style={{ color: `var(${map[1]})` }}>{title}</div>}
2169:         <div className="c-primary opacity-80 mt-0.5">{children}</div>
2170:       </div>
2171:       {onClose && <button onClick={onClose} className="c-secondary"><Icon n="x" s={14} /></button>}
2172:     </div>
2173:   );
2174: }
