2229: // ---------- Variant picker: product → variant/SKU (never stops at product) ----------
2230: // API-backed (Phase 3): GET production-receipts/options?search=, 300ms debounce,
2231: // max 50 active variants. Empty query shows "اكتب للبحث", never a fake full list.
2232: // Disabled variants are rejected by the server on input, so their absence here
2233: // is correct; to decrease a disabled variant, open stock → adjust with variantId.
2234: function VariantPicker({ value, onChange, placeholder = 'ابحث بالاسم أو SKU أو الباركود', small, exclude = [], allowClear }) {
2235:   const { variantCache } = useInv();
2236:   const [open, setOpen] = useState(false);
2237:   const [q, setQ] = useState('');
2238:   const [dq, setDq] = useState('');
2239:   const ref = useRef();
2240:   useEffect(() => {
2241:     // composedPath: the inventory shell renders inside a shadow root, where a document-level listener sees a retargeted target (the host) — contains() would always close. composedPath() crosses the boundary correctly.
2242:     const h = e => { const path = typeof e.composedPath === 'function' ? e.composedPath() : []; const inside = path.length ? path.includes(ref.current) : (ref.current && ref.current.contains(e.target)); if (!inside) setOpen(false); };
2243:     document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h);
2244:   }, []);
2245:   useEffect(() => { const t = setTimeout(() => setDq(q), 300); return () => clearTimeout(t); }, [q]);
2246:   const term = dq.trim();
2247:   const optsQuery = useApi(signal => term ? productionApi.options(term, signal) : Promise.resolve({ branches: [], variants: [] }), [term]);
2248:   const variants = useMemo(() => {
2249:     const list = (optsQuery.data?.variants || []).filter(v => !exclude.includes(v.id));
2250:     list.forEach(v => {
2251:       cacheVariantOptions(variantCache, [v]);
2252:     });
2253:     return list;
2254:   }, [optsQuery.data, exclude.join(',')]);
2255:   const cached = value ? variantCache.get(Number(value)) : null;
2256:   const label = cached?.name_ar || cached?.name_en || cached?.label || null;
2257:   const sku = cached?.sku || null;
2258: 
2259:   return (
2260:     <div ref={ref} className="relative">
2261:       <button type="button" onClick={() => setOpen(o => !o)} className={`inp ${small ? 'inp-sm' : ''} flex items-center justify-between gap-2 text-right`}>
2262:         {value ? (
2263:           <span className="flex items-center gap-2 min-w-0">
2264:             <span className="truncate c-primary">{label || `صنف #${value}`}</span>
2265:             {sku && <span className="mono text-[10.5px] px-1.5 py-0.5 rounded-md shrink-0" style={{ background: 'var(--icon-well-bg)' }} dir="ltr">{sku}</span>}
2266:           </span>
2267:         ) : <span className="c-muted truncate">{placeholder}</span>}
2268:         <span className="flex items-center gap-1 shrink-0">
2269:           {allowClear && value && <span onClick={e => { e.stopPropagation(); onChange(null); }} className="c-muted hover:c-primary"><Icon n="x" s={12} /></span>}
2270:           <Icon n="chevD" s={13} className="c-muted" />
2271:         </span>
2272:       </button>
2273:       {open && (
2274:         <div className="absolute z-40 mt-1.5 w-full min-w-[320px] v-card shadow-2xl p-2 modal-in" style={{ borderRadius: 16 }}>
2275:           <div className="v-subcard px-3 py-2 rounded-xl flex items-center gap-2 mb-1.5">
2276:             <Icon n="search" s={14} className="c-muted" />
2277:             <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="اسم المنتج، SKU، باركود…" className="bg-transparent text-[12.5px] outline-none flex-1 c-primary" />
2278:             <Icon n="barcode" s={14} className="c-muted" />
2279:           </div>
2280:           <div className="max-h-[260px] overflow-y-auto">
2281:             {!term && <div className="text-center text-[12px] c-muted py-6">اكتب للبحث عن صنف — لا تُعرض القائمة كاملة</div>}
2282:             {term && optsQuery.loading && <div className="text-center text-[12px] c-muted py-6">جارٍ البحث…</div>}
2283:             {term && optsQuery.error && <div className="text-center text-[12px] py-6" style={{ color: 'var(--badge-red-text)' }}>{optsQuery.error.message} <button className="underline" onClick={() => optsQuery.reload()}>إعادة المحاولة</button></div>}
2284:             {term && !optsQuery.loading && !optsQuery.error && variants.length === 0 && <div className="text-center text-[12px] c-muted py-6">لا توجد نتائج مطابقة</div>}
2285:             {term && !optsQuery.loading && !optsQuery.error && variants.map(v => {
2286:               const [nm, sk] = (v.label || '').split('/').map(s => s.trim());
2287:               return (
2288:                 <button type="button" key={v.id} onClick={() => { onChange(v.id); setOpen(false); setQ(''); }}
2289:                   className={`w-full flex items-center justify-between gap-3 px-2.5 py-2 rounded-xl text-right hover:bg-[var(--bg-subcard)] ${value === v.id ? 'bg-[var(--bg-subcard)]' : ''}`}>
2290:                   <span className="text-[12.5px] c-primary pr-4">{nm || v.label}</span>
2291:                   <span className="flex items-center gap-2">
2292:                     <span className="mono text-[11px] font-semibold c-primary" dir="ltr">{sk || ''}</span>
2293:                     {value === v.id && <Icon n="check" s={13} className="c-orange" />}
2294:                   </span>
2295:                 </button>
2296:               );
2297:             })}
2298:           </div>
2299:         </div>
2300:       )}
