  89: function InvApp() {
  90:   const [t, setTweak] = useTweaks(window.INV_TWEAK_DEFAULTS);
  91:   const [nav, setNav] = useState(() => {
  92:     try { return JSON.parse(localStorage.getItem('vortix-inv-route')) || { route: 'stock', params: {} }; } catch { return { route: 'stock', params: {} }; }
  93:   });
  94:   const [db, setDb] = useState(() => ({ branches: INV_BRANCHES, locations: INV_LOCATIONS, transfers: INV_TRANSFERS, counts: INV_COUNTS, production: INV_PRODUCTION }));
  95:   const [toastMsg, setToastMsg] = useState(null);
  96:   const [reloadKey, setReloadKey] = useState(0);
  97:   const tRef = useRef();
  98: 
  99:   const go = (route, params = {}) => { setNav({ route, params }); window.scrollTo({ top: 0, behavior: 'smooth' }); };
 100:   useEffect(() => { localStorage.setItem('vortix-inv-route', JSON.stringify(nav)); }, [nav]);
 101:   const toast = text => { setToastMsg({ text }); clearTimeout(tRef.current); tRef.current = setTimeout(() => setToastMsg(null), 2400); };
 102: 
 103:   const ctx = { db, setDb, toast, role: t.role, demoState: t.demoState, reloadKey, reload: () => { setReloadKey(k => k + 1); if (t.demoState === 'error') setTweak('demoState', 'live'); } };
 104: 
 105:   const screens = {
 106:     branches: BranchesScreen, locations: LocationsScreen, stock: StockScreen, adjust: AdjustScreen, moves: MovesScreen,
 107:     transfers: TransfersScreen, transfer: TransferDetail, 'transfer-edit': TransferEdit, counts: CountsScreen, count: CountDetail, production: ProductionScreen,
 108:   };
 109:   const Screen = screens[nav.route] || StockScreen;
 110:   const screenKey = nav.route + JSON.stringify(nav.params);
 111:   const label = (INV_NAV.find(n => n.match.includes(nav.route)) || {}).label;
 112: 
 113:   return (
 114:     <InvCtx.Provider value={ctx}>
 115:       <div id="app-viewport" className={t.theme === 'dark' ? 'theme-dark' : 'theme-light'}>
 116:         <div className="max-w-[1440px] mx-auto px-4 sm:px-7 pt-5 pb-10">
 117:           <InvHeader route={nav.route} go={go} theme={t.theme} role={t.role} />
 118:           <div className="flex gap-6 items-start">
 119:             <InvSidebar route={nav.route} go={go} theme={t.theme} setTheme={v => setTweak('theme', v)} />
 120:             <main className="flex-1 min-w-0" data-screen-label={label}>
 121:               <Screen key={screenKey} go={go} params={nav.params} />
 122:             </main>
 123:           </div>
 124:         </div>
 125:         <Toast toast={toastMsg} />
 126:       </div>
 127: 
 128:       <div dir="ltr">
 129:       <TweaksPanel title="Tweaks">
 130:         <TweakSection label="الصلاحية">
 131:           <TweakRadio label="الدور" value={t.role} onChange={v => setTweak('role', v)}
 132:             options={[{ value: 'admin', label: 'مدير' }, { value: 'storekeeper', label: 'أمين مخزن' }, { value: 'viewer', label: 'عرض فقط' }]} />
 133:         </TweakSection>
 134:         <TweakSection label="حالة البيانات">
 135:           <TweakSelect label="محاكاة الاستجابة" value={t.demoState} onChange={v => setTweak('demoState', v)}
 136:             options={[{ value: 'live', label: 'بيانات فعلية' }, { value: 'loading', label: 'تحميل' }, { value: 'empty', label: 'فارغ' }, { value: 'error', label: 'خطأ من السيرفر' }]} />
 137:         </TweakSection>
 138:         <TweakSection label="المظهر">
 139:           <TweakRadio label="الوضع" value={t.theme} onChange={v => setTweak('theme', v)} options={[{ value: 'light', label: 'فاتح' }, { value: 'dark', label: 'داكن' }]} />
 140:         </TweakSection>
 141:       </TweaksPanel>
 142:       </div>
 143:     </InvCtx.Provider>
 144:   );
 145: }
