 242:   tr_in:       { label: 'تحويل وارد',       cls: 'b-blue',  sign: 1 },
 243:   count:       { label: 'فرق جرد',          cls: 'b-gray',  sign: 0 },
 244:   production:  { label: 'استلام إنتاج',     cls: 'b-orange',sign: 1 },
 245:   sale:        { label: 'بيع',              cls: 'b-gray',  sign: -1 },
