 358: function BranchForm({ open, initial, onClose, onSave }) {
 359:   const blank = { name: '', code: '', type: 'branch', phone: '', email: '', address: '', city: '', active: true };
 360:   const [f, setF] = useState(blank);
 361:   const [err, setErr] = useState({});
 362:   const [busy, setBusy] = useState(false);
 363:   const { db } = useInv();
 364:   useEffect(() => { if (open) { setF(initial ? { ...initial } : blank); setErr({}); setBusy(false); } }, [open]);
 365:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 366:   const submit = () => {
 367:     const e = {};
 368:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 369:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 370:     else if (db.branches.some(b => b.code.toLowerCase() === f.code.trim().toLowerCase() && b.id !== f.id)) e.code = 'هذا الكود مستخدم لفرع آخر';
 371:     if (f.email && !/^\S+@\S+\.\S+$/.test(f.email)) e.email = 'صيغة البريد غير صحيحة';
 372:     if (!f.city.trim()) e.city = 'المدينة مطلوبة';
 373:     setErr(e);
 374:     if (Object.keys(e).length) return;
 375:     setBusy(true);
 376:     setTimeout(() => onSave(f), 600);
 377:   };
 378:   return (
 379:     <Modal open={open} onClose={onClose} width="max-w-2xl"
 380:       title={initial ? 'تعديل ' + (initial.type === 'warehouse' ? 'المخزن' : 'الفرع') : 'إضافة فرع أو مخزن'}
 381:       sub="المخزن يُسجَّل كنوع من الفروع ويملك مواقع تخزين خاصة به."
 382:       footer={<>
 383:         <button className="btn btn-dark" onClick={submit} disabled={busy}>
 384:           {busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />}
 385:           {initial ? 'حفظ التعديلات' : 'إضافة'}
 386:         </button>
 387:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
 388:       </>}>
 389:       <div className="space-y-4">
 390:         <div>
 391:           <span className="field-label">النوع</span>
 392:           <div className="grid grid-cols-2 gap-2.5">
 393:             {[['branch', 'فرع', 'store', 'نقطة بيع تستقبل العملاء'], ['warehouse', 'مخزن', 'warehouse', 'تخزين وتوزيع فقط']].map(([k, l, ic, d]) => (
 394:               <button key={k} type="button" onClick={() => set('type', k)}
 395:                 className={`rounded-2xl p-3.5 flex items-center gap-3 text-right transition border ${f.type === k ? 'border-[var(--accent-orange)]' : 'border-transparent'}`}
 396:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>
 397:                 <span className={`w-9 h-9 rounded-full flex items-center justify-center ${f.type === k ? 'bg-[var(--accent-orange)] text-white' : 'v-icon-well'}`}><Icon n={ic} s={16} /></span>
 398:                 <span><span className="block text-[13px] font-semibold c-primary">{l}</span><span className="block text-[11px] c-secondary">{d}</span></span>
 399:               </button>
 400:             ))}
 401:           </div>
 402:         </div>
 403:         <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
 404:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="مثال: فرع مدينة نصر" /></Field>
 405:           <Field label="الكود" req error={err.code} hint="فريد على مستوى النظام"><input className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="BR-XXX" /></Field>
 406:           <Field label="الهاتف"><input className="inp num text-left" value={f.phone} onChange={e => set('phone', e.target.value)} placeholder="01xxxxxxxxx" /></Field>
 407:           <Field label="البريد الإلكتروني" error={err.email}><input className={`inp mono text-left ${err.email ? 'err' : ''}`} value={f.email} onChange={e => set('email', e.target.value)} placeholder="branch@company.com" /></Field>
 408:           <Field label="المدينة" req error={err.city}><input className={`inp ${err.city ? 'err' : ''}`} value={f.city} onChange={e => set('city', e.target.value)} /></Field>
 409:           <Field label="العنوان"><input className="inp" value={f.address} onChange={e => set('address', e.target.value)} /></Field>
 410:         </div>
 411:         <div className="v-subcard p-3.5 flex items-center justify-between">
 412:           <div>
 413:             <div className="text-[13px] font-semibold c-primary">الحالة: {f.active ? 'نشط' : 'غير نشط'}</div>
 414:             <div className="text-[11px] c-secondary">الفروع غير النشطة لا تظهر في عمليات التحويل والتسوية.</div>
 415:           </div>
 416:           <Toggle on={f.active} onChange={v => set('active', v)} />
 417:         </div>
 418:       </div>
 419:     </Modal>
 420:   );
 421: }
