 532: function LocationForm({ open, initial, branchId, onClose, onSave }) {
 533:   const { db } = useInv();
 534:   const blank = { name: '', code: '', type: 'shelf', active: true, branchId };
 535:   const [f, setF] = useState(blank);
 536:   const [err, setErr] = useState({});
 537:   useEffect(() => { if (open) { setF(initial ? { ...initial } : blank); setErr({}); } }, [open]);
 538:   const set = (k, v) => setF(p => ({ ...p, [k]: v }));
 539:   const submit = () => {
 540:     const e = {};
 541:     if (!f.name.trim()) e.name = 'الاسم مطلوب';
 542:     if (!f.code.trim()) e.code = 'الكود مطلوب';
 543:     else if (db.locations.some(l => l.branchId === branchId && l.code.toLowerCase() === f.code.trim().toLowerCase() && l.id !== f.id)) e.code = 'الكود مستخدم بالفعل داخل هذا الفرع';
 544:     setErr(e);
 545:     if (!Object.keys(e).length) onSave(f);
 546:   };
 547:   return (
 548:     <Modal open={open} onClose={onClose} title={initial ? 'تعديل موقع التخزين' : 'إضافة موقع تخزين'} sub={`تابع لـ ${invBranch(branchId)?.name || ''}`}
 549:       footer={<><button className="btn btn-dark" onClick={submit}>{initial ? 'حفظ' : 'إضافة'}</button><button className="btn btn-soft" onClick={onClose}>إلغاء</button></>}>
 550:       <div className="space-y-4">
 551:         <div className="grid grid-cols-2 gap-4">
 552:           <Field label="الاسم" req error={err.name}><input className={`inp ${err.name ? 'err' : ''}`} value={f.name} onChange={e => set('name', e.target.value)} placeholder="رف A-01" /></Field>
 553:           <Field label="الكود" req error={err.code} hint="فريد داخل الفرع"><input className={`inp mono text-left ${err.code ? 'err' : ''}`} value={f.code} onChange={e => set('code', e.target.value.toUpperCase())} placeholder="A-01" /></Field>
 554:         </div>
 555:         <div>
 556:           <span className="field-label">النوع</span>
 557:           <div className="grid grid-cols-5 gap-2">
 558:             {Object.entries(INV_LOC_TYPES).map(([k, t]) => (
 559:               <button key={k} type="button" onClick={() => set('type', k)}
 560:                 className={`rounded-xl py-2.5 text-[12px] font-medium transition border ${f.type === k ? 'border-[var(--accent-orange)] c-primary font-semibold' : 'border-transparent c-secondary'}`}
 561:                 style={{ background: f.type === k ? 'var(--accent-orange-light)' : 'var(--bg-subcard)' }}>{t.label}</button>
 562:             ))}
 563:           </div>
 564:         </div>
 565:         <div className="v-subcard p-3.5 flex items-center justify-between">
 566:           <span className="text-[13px] font-semibold c-primary">{f.active ? 'نشط' : 'معطّل'}</span>
 567:           <Toggle on={f.active} onChange={v => set('active', v)} />
 568:         </div>
 569:       </div>
 570:     </Modal>
 571:   );
 572: }
