 574: function LocationsScreen({ go, params }) {
 575:   const { db, setDb, toast } = useInv();
 576:   const can = useCan();
 577:   const phase = useLoad('loc' + params.branchId);
 578:   const br = db.branches.find(b => b.id === params.branchId) || db.branches[0];
 579:   const [form, setForm] = useState({ open: false, initial: null });
 580:   const [del, setDel] = useState(null);
 581:   const [delErr, setDelErr] = useState(null);
 582:   const [tf, setTf] = useState('all');
 583:   const all = db.locations.filter(l => l.branchId === br.id);
 584:   const rows = all.filter(l => tf === 'all' || l.type === tf);
 585: 
 586:   const save = f => {
 587:     if (f.id) setDb(d => ({ ...d, locations: d.locations.map(l => l.id === f.id ? f : l) }));
 588:     else setDb(d => ({ ...d, locations: [...d.locations, { ...f, id: 'l' + Date.now(), branchId: br.id }] }));
 589:     setForm({ open: false, initial: null }); toast('تم حفظ موقع التخزين');
 590:   };
 591:   const toggle = l => { setDb(d => ({ ...d, locations: d.locations.map(x => x.id === l.id ? { ...x, active: !x.active } : x) })); toast(l.active ? 'تم تعطيل الموقع' : 'تم تفعيل الموقع'); };
 592:   const doDelete = () => {
 593:     const stock = INV_STOCK.filter(s => s.locId === del.id);
 594:     if (stock.length) { setDelErr(`الموقع «${del.code}» يحتوي على ${stock.length} رصيد مخزون. انقل الكميات أو عطّل الموقع بدلًا من حذفه. (409 Conflict)`); return; }
 595:     setDb(d => ({ ...d, locations: d.locations.filter(x => x.id !== del.id) })); setDel(null); toast('تم حذف الموقع');
 596:   };
 597: 
 598:   const typeCounts = Object.keys(INV_LOC_TYPES).reduce((a, k) => ({ ...a, [k]: all.filter(l => l.type === k).length }), {});
 599: 
 600:   return (
 601:     <section className="space-y-5">
 602:       <PageHead title="مواقع التخزين" back={{ label: 'الفروع والمخازن', onClick: () => go('branches') }}
 603:         sub={<span className="flex items-center gap-2">{br.name} <span className="mono text-[11.5px] c-muted">{br.code}</span> <TypeBadge type={br.type} /></span>}
 604:         actions={<>
 605:           <Sel value={br.id} onChange={id => id && go('locations', { branchId: id })} options={branchOpts()} className="!rounded-full !py-2 w-56" />
 606:           <Can perm="branches.manage"><button className="btn btn-dark" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={14} w={2.2} /> إضافة موقع</button></Can>
 607:         </>} />
 608: 
 609:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5">
 610:         <Card className="lg:col-span-4" stagger={2}>
 611:           <div className="v-orange-card rounded-[18px] p-5">
 612:             <div className="flex items-center justify-between">
 613:               <span className="text-[12.5px] font-medium text-white/90">إجمالي المواقع</span>
 614:               <span className="w-7 h-7 rounded-full bg-white/15 flex items-center justify-center"><Icon n="pin" s={14} /></span>
 615:             </div>
 616:             <div className="font-display text-[40px] font-bold num text-right mt-2">{all.length}</div>
 617:             <div className="text-[11.5px] text-white/80">{all.filter(l => l.active).length} نشط · {all.filter(l => !l.active).length} معطّل</div>
 618:           </div>
 619:           <div className="mt-4 space-y-1">
 620:             {Object.entries(INV_LOC_TYPES).map(([k, t]) => (
 621:               <button key={k} onClick={() => setTf(tf === k ? 'all' : k)} className={`w-full flex items-center justify-between px-3 py-2.5 rounded-xl transition ${tf === k ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]'}`}>
 622:                 <span className="flex items-center gap-2.5 text-[12.5px] c-primary"><Badge cls={t.cls}>{t.label}</Badge></span>
 623:                 <span className="flex items-center gap-3">
 624:                   <span className="w-20 h-1.5 rounded-full hatched overflow-hidden"><span className="block h-full bg-[var(--accent-orange)] rounded-full" style={{ width: `${all.length ? typeCounts[k] / all.length * 100 : 0}%` }} /></span>
 625:                   <span className="num text-[12px] font-semibold c-primary w-4 text-left">{typeCounts[k]}</span>
 626:                 </span>
 627:               </button>
 628:             ))}
 629:           </div>
 630:         </Card>
 631: 
 632:         <Card className="lg:col-span-8" stagger={3}>
 633:           <CardHead title="المواقع" meta={tf === 'all' ? 'كل الأنواع' : INV_LOC_TYPES[tf].label}
 634:             right={tf !== 'all' && <button className="btn btn-ghost btn-sm" onClick={() => setTf('all')}><Icon n="x" s={12} /> إزالة الفلتر</button>} />
 635:           <Phase phase={phase} cols={5} rows={5}
 636:             empty={<EmptyState icon="pin" title="لا توجد مواقع تخزين في هذا الفرع" sub="أضف رفوفًا ومناطق وخانات لتحديد مكان كل صنف بدقة."
 637:               action={<Can perm="branches.manage"><button className="btn btn-dark btn-sm" onClick={() => setForm({ open: true, initial: null })}><Icon n="plus" s={13} /> إضافة موقع</button></Can>} />}>
 638:             {rows.length === 0 ? <EmptyState icon="pin" title="لا توجد مواقع من هذا النوع" /> : (
 639:               <table className="vt">
 640:                 <thead><tr><th>الاسم</th><th>الكود</th><th>النوع</th><th>الحالة</th><th></th></tr></thead>
 641:                 <tbody>
 642:                   {rows.map(l => (
 643:                     <tr key={l.id} className={l.active ? '' : 'opacity-60'}>
 644:                       <td className="font-semibold c-primary">{l.name}</td>
 645:                       <td><Sku>{l.code}</Sku></td>
 646:                       <td><Badge cls={INV_LOC_TYPES[l.type].cls}>{INV_LOC_TYPES[l.type].label}</Badge></td>
 647:                       <td>
 648:                         <div className="flex items-center gap-2.5">
 649:                           {can('branches.manage') && <Toggle on={l.active} onChange={() => toggle(l)} />}
 650:                           <span className={`text-[11.5px] font-semibold ${l.active ? '' : 'c-muted'}`} style={l.active ? { color: 'var(--badge-green-text)' } : {}}>{l.active ? 'نشط' : 'معطّل'}</span>
 651:                         </div>
 652:                       </td>
 653:                       <td>
 654:                         {can('branches.manage') && (
 655:                           <div className="flex items-center gap-0.5 justify-end">
 656:                             <button className="icon-btn" title="تعديل" onClick={() => setForm({ open: true, initial: l })}><Icon n="edit" s={15} /></button>
 657:                             <button className="icon-btn" title="حذف" onClick={() => { setDel(l); setDelErr(null); }}><Icon n="trash" s={15} /></button>
 658:                           </div>
 659:                         )}
 660:                       </td>
 661:                     </tr>
 662:                   ))}
 663:                 </tbody>
 664:               </table>
 665:             )}
 666:           </Phase>
 667:         </Card>
 668:       </div>
 669: 
 670:       <LocationForm open={form.open} initial={form.initial} branchId={br.id} onClose={() => setForm({ open: false, initial: null })} onSave={save} />
 671:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} onConfirm={doDelete} danger error={delErr} title="حذف موقع التخزين؟" confirmLabel="حذف"
 672:         body={<>سيتم حذف <b className="c-primary">{del?.name}</b> (<span className="mono">{del?.code}</span>) من {br.name}.</>} />
 673:     </section>
 674:   );
 675: }
