 880: const PRD_MAX = 50;
 881: let __prKey = 1;
 882: const newPrLine = () => ({ key: __prKey++, variantId: null, qty: '', cost: '' });
 883: 
 884: function ProductionScreen({ go }) {
 885:   const { db, setDb, toast } = useInv();
 886:   const can = useCan();
 887:   const allowed = can('stock.adjust') && can('cost.view');
 888:   const phase = useLoad('prod');
 889:   const [open, setOpen] = useState(false);
 890:   const [view, setView] = useState(null);
 891: 
 892:   return (
 893:     <section className="space-y-5">
 894:       <PageHead title="استلام الإنتاج" sub="تسجيل المنتجات التامة الواردة من التصنيع إلى المخزن مع تكلفة الوحدة."
 895:         actions={allowed ? <button className="btn btn-dark" onClick={() => setOpen(true)}><Icon n="plus" s={14} w={2.2} /> تسجيل استلام</button>
 896:           : <span className="inline-flex items-center gap-1.5 text-[12px] c-muted px-3.5 py-2 rounded-full v-pill-surface"><Icon n="lock" s={12} /> يتطلب صلاحية تسوية المخزون وعرض التكلفة</span>} />
 897:       <Card stagger={2}>
 898:         <CardHead title="سجل الاستلامات" meta={phase === 'ready' ? `${db.production.length} استلام` : null} />
 899:         <Phase phase={phase} cols={6}
 900:           empty={<EmptyState icon="factory" title="لا توجد استلامات إنتاج" sub="عند وصول دفعة من التصنيع سجّلها هنا لتُضاف إلى رصيد المخزن." action={allowed && <button className="btn btn-dark btn-sm" onClick={() => setOpen(true)}><Icon n="plus" s={13} /> تسجيل استلام</button>} />}>
 901:           <table className="vt">
 902:             <thead><tr><th>رقم الاستلام</th><th>رقم الدفعة</th><th>الفرع</th><th>الموقع</th><th className="t-num">البنود</th><th className="t-num">إجمالي الكمية</th>{can('cost.view') && <th className="t-num">إجمالي التكلفة</th>}<th>المنفّذ</th><th>التاريخ</th></tr></thead>
 903:             <tbody>
 904:               {db.production.map(p => (
 905:                 <tr key={p.id} className="cursor-pointer" onClick={() => setView(p)}>
 906:                   <td><span className="mono text-[12px] font-semibold c-orange">{p.no}</span></td>
 907:                   <td><Sku>{p.batch}</Sku></td>
 908:                   <td className="c-primary font-medium">{invBranch(p.branchId).name}</td>
 909:                   <td className="mono text-[11.5px] c-secondary">{p.locId ? invLoc(p.locId).code : '—'}</td>
 910:                   <td className="t-num num c-secondary">{p.lines.length}</td>
 911:                   <td className="t-num num font-semibold c-primary">{invFmt(p.lines.reduce((a, l) => a + l.qty, 0))}</td>
 912:                   {can('cost.view') && <td className="t-num num c-primary">{invMoney(p.lines.reduce((a, l) => a + l.qty * l.cost, 0))}</td>}
 913:                   <td className="c-secondary">{p.user}</td>
 914:                   <td className="num text-[11.5px] c-secondary">{p.date}</td>
 915:                 </tr>
 916:               ))}
 917:             </tbody>
 918:           </table>
 919:         </Phase>
 920:       </Card>
 921:       <ProductionForm open={open} onClose={() => setOpen(false)} onSave={p => { setDb(d => ({ ...d, production: [p, ...d.production] })); setOpen(false); toast('تم تسجيل استلام الإنتاج'); }} />
 922:       <Modal open={!!view} onClose={() => setView(null)} width="max-w-xl" title={view?.no} sub={view && `دفعة ${view.batch} · ${invBranch(view.branchId).name}`}>
 923:         {view && <table className="vt mb-4"><thead><tr><th>SKU</th><th>الصنف</th><th className="t-num">الكمية</th><th className="t-num">تكلفة الوحدة</th></tr></thead>
 924:           <tbody>{view.lines.map((l, i) => <tr key={i}><td><Sku id={l.variantId} /></td><td><VariantCell id={l.variantId} /></td><td className="t-num num font-semibold">{l.qty}</td><td className="t-num num">{invMoney(l.cost)}</td></tr>)}</tbody></table>}
 925:       </Modal>
 926:     </section>
 927:   );
 928: }
