 930: function ProductionForm({ open, onClose, onSave }) {
 931:   const { demoState } = useInv();
 932:   const [f, setF] = useState({ batch: '', branchId: null, locId: null, note: '' });
 933:   const [lines, setLines] = useState([newPrLine()]);
 934:   const [tried, setTried] = useState(false);
 935:   const [busy, setBusy] = useState(false);
 936:   const [err, setErr] = useState(null);
 937:   useEffect(() => { if (open) { setF({ batch: '', branchId: null, locId: null, note: '' }); setLines([newPrLine()]); setTried(false); setErr(null); } }, [open]);
 938:   const upd = (k, p) => setLines(ls => ls.map(l => l.key === k ? { ...l, ...p } : l));
 939:   const bad = l => !l.variantId || !(parseInt(l.qty) > 0) || !(parseFloat(l.cost) >= 0 && l.cost !== '');
 940:   const valid = f.batch.trim() && f.branchId && lines.every(l => !bad(l));
 941:   const total = lines.reduce((a, l) => a + (parseInt(l.qty) || 0) * (parseFloat(l.cost) || 0), 0);
 942:   const submit = () => {
 943:     setTried(true); if (!valid) return;
 944:     setBusy(true); setErr(null);
 945:     setTimeout(() => {
 946:       setBusy(false);
 947:       if (demoState === 'error') { setErr('رقم الدفعة B-2610-07 مسجّل مسبقًا. (422 Unprocessable)'); return; }
 948:       onSave({ id: 'pr' + Date.now(), no: 'PRD-2026-00089', ...f, date: '2026-10-23', user: 'أحمد سمير', lines: lines.map(l => ({ variantId: l.variantId, qty: parseInt(l.qty), cost: parseFloat(l.cost) })) });
 949:     }, 800);
 950:   };
 951:   return (
 952:     <Modal open={open} onClose={onClose} width="max-w-4xl" title="تسجيل استلام إنتاج" sub={`حتى ${PRD_MAX} بندًا · الكميات أعداد صحيحة`}
 953:       footer={<>
 954:         <button className="btn btn-orange" onClick={submit} disabled={busy}>{busy && <span className="w-3.5 h-3.5 rounded-full border-2 border-current border-t-transparent animate-spin" />} تسجيل الاستلام</button>
 955:         <button className="btn btn-soft" onClick={onClose}>إلغاء</button>
 956:         <span className="flex-1" />
 957:         <span className="text-[12px] c-secondary">إجمالي التكلفة <span className="num font-display text-[18px] font-bold c-primary mr-1">{invMoney(total)}</span></span>
 958:       </>}>
 959:       <div className="space-y-4">
 960:         {err && <InlineAlert kind="red" title="رفض الخادم العملية">{err}</InlineAlert>}
 961:         <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
 962:           <Field label="رقم الدفعة" req error={tried && !f.batch.trim() ? 'مطلوب' : null}><input className={`inp mono text-left ${tried && !f.batch.trim() ? 'err' : ''}`} value={f.batch} onChange={e => setF({ ...f, batch: e.target.value.toUpperCase() })} placeholder="B-2610-08" /></Field>
 963:           <Field label="الفرع / المخزن" req error={tried && !f.branchId ? 'مطلوب' : null}><Sel value={f.branchId} onChange={v => setF({ ...f, branchId: v, locId: null })} placeholder="اختر…" options={branchOpts(b => b.active)} /></Field>
 964:           <Field label="الموقع" hint="اختياري"><Sel value={f.locId} onChange={v => setF({ ...f, locId: v })} placeholder={f.branchId ? 'الموقع الافتراضي' : '—'} disabled={!f.branchId} options={f.branchId ? locOpts(f.branchId) : []} /></Field>
 965:         </div>
 966:         <div>
 967:           <div className="flex items-center justify-between mb-2">
 968:             <span className="field-label !mb-0">البنود <span className="num c-muted">{lines.length}/{PRD_MAX}</span></span>
 969:             <button className="btn btn-soft btn-sm" disabled={lines.length >= PRD_MAX} onClick={() => setLines(ls => [...ls, newPrLine()])}><Icon n="plus" s={13} /> إضافة بند</button>
 970:           </div>
 971:           <table className="vt">
 972:             <thead><tr><th className="w-8">#</th><th style={{ minWidth: 300 }}>المتغير / SKU</th><th style={{ width: 120 }}>الكمية</th><th style={{ width: 140 }}>تكلفة الوحدة</th><th className="t-num">الإجمالي</th><th></th></tr></thead>
 973:             <tbody>
 974:               {lines.map((l, i) => (
 975:                 <tr key={l.key}>
 976:                   <td className="num c-muted">{i + 1}</td>
 977:                   <td><div className={tried && !l.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v, cost: l.cost || (v ? String(invVariant(v).cost) : '') })} /></div></td>
 978:                   <td><NumInput small integer value={l.qty} onChange={v => upd(l.key, { qty: v })} err={tried && !(parseInt(l.qty) > 0)} /></td>
 979:                   <td><NumInput small decimals={4} value={l.cost} onChange={v => upd(l.key, { cost: v })} err={tried && l.cost === ''} placeholder="0.00" /></td>
 980:                   <td className="t-num num c-primary font-semibold">{invMoney((parseInt(l.qty) || 0) * (parseFloat(l.cost) || 0))}</td>
 981:                   <td><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
 982:                 </tr>
 983:               ))}
 984:             </tbody>
 985:           </table>
