 997:     <div className="v-subcard p-3 flex flex-wrap items-end gap-2.5 mb-4">
 998:       {children}
 999:       {active > 0 && <button onClick={onReset} className="btn btn-ghost btn-sm mb-0.5"><Icon n="x" s={12} /> مسح ({active})</button>}
