1012:     <FItem label="المتغير / SKU"><Sel small value={f.variantId} onChange={v => set({ variantId: v })} placeholder={prod ? 'كل المتغيرات' : 'اختر منتجًا أولًا'} disabled={!prod}
1013:       options={(prod?.variants || []).map(v => ({ value: v.id, label: `${v.sku} · ${v.attrs}` }))} className="!bg-[var(--bg-card)]" /></FItem>
1014:   </>;
1015: }
