1020:     <FItem label="الموقع" w="w-40"><Sel small value={f.locId} onChange={v => set({ locId: v })} placeholder={f.branchId ? 'كل المواقع' : 'اختر فرعًا أولًا'} disabled={!f.branchId} options={f.branchId ? locOpts(f.branchId) : []} className="!bg-[var(--bg-card)]" /></FItem>
1021:   </>;
