1024: // ---------------- 3. Stock balances ----------------
1025: function StockScreen({ go }) {
1026:   const can = useCan();
1027:   const phase = useLoad('stock');
1028:   const [f, setF] = useState({ branchId: null, locId: null, productId: null, variantId: null, low: false });
1029:   const set = p => setF(x => ({ ...x, ...p }));
1030:   const [adj, setAdj] = useState(null);
1031: 
1032:   const rows = INV_STOCK.filter(s => {
1033:     const v = invVariant(s.variantId);
1034:     return (!f.branchId || s.branchId === f.branchId) && (!f.locId || s.locId === f.locId)
1035:       && (!f.productId || v.productId === f.productId) && (!f.variantId || s.variantId === f.variantId)
1036:       && (!f.low || s.available <= s.reorder);
1037:   });
1038:   const active = ['branchId', 'locId', 'productId', 'variantId'].filter(k => f[k]).length + (f.low ? 1 : 0);
1039:   const lowCount = INV_STOCK.filter(s => s.available <= s.reorder).length;
1040:   const sum = k => rows.reduce((a, s) => a + s[k], 0);
1041: 
1042:   return (
1043:     <section className="space-y-5">
1044:       <PageHead title="أرصدة المخزون" sub="الكميات الحالية لكل SKU في كل فرع وموقع. لتغيير أي كمية استخدم عملية مخزنية."
1045:         actions={<Can perm="stock.adjust"><button className="btn btn-dark" onClick={() => go('adjust')}><Icon n="sliders" s={14} /> تسوية جديدة</button></Can>} />
1046: 
1047:       <div className="grid grid-cols-2 lg:grid-cols-4 gap-3.5 stagger-item stagger-2">
1048:         <KPI hot label="المتاح" icon="box" value={phase === 'ready' ? invFmt(sum('available'), 2) : '—'} sub={`${rows.length} سطر رصيد`} />
1049:         <KPI label="المحجوز" icon="lock" value={phase === 'ready' ? invFmt(sum('reserved'), 2) : '—'} sub="لطلبات مفتوحة" />
1050:         <KPI label="قيد النقل" icon="truck" value={phase === 'ready' ? invFmt(sum('inTransit'), 2) : '—'} sub="في تحويلات مشحونة" />
1051:         <button onClick={() => set({ low: !f.low })} className="text-right">
1052:           <KPI label="تحت حد إعادة الطلب" icon="alert" value={phase === 'ready' ? lowCount : '—'} sub={f.low ? 'الفلتر مفعّل · اضغط للإلغاء' : 'اضغط لعرضها فقط'} />
1053:         </button>
1054:       </div>
1055: 
1056:       <Card stagger={3}>
1057:         <CardHead title="الأرصدة" meta={phase === 'ready' ? `${rows.length} سطر` : null}
1058:           right={<span className="text-[11.5px] c-muted flex items-center gap-1.5"><Icon n="eye" s={13} /> للعرض فقط</span>} />
1059:         <FilterBar active={active} onReset={() => setF({ branchId: null, locId: null, productId: null, variantId: null, low: false })}>
1060:           <BranchLocFilters f={f} set={set} />
1061:           <ProductVariantFilters f={f} set={set} />
1062:           <label className="flex items-center gap-2.5 px-3 py-2 rounded-full cursor-pointer mb-0.5" style={{ background: f.low ? 'var(--accent-orange-light)' : 'var(--bg-card)' }}>
1063:             <Toggle on={f.low} onChange={v => set({ low: v })} />
1064:             <span className="text-[12px] font-medium c-primary">المخزون المنخفض فقط</span>
1065:           </label>
1066:         </FilterBar>
1067:         <Phase phase={phase} cols={10} rows={7}
1068:           empty={<EmptyState icon="box" title="لا توجد أرصدة مسجّلة بعد" sub="سجّل الكميات الافتتاحية عن طريق تسوية زيادة مع سبب واضح مثل «رصيد افتتاحي»."
1069:             action={<Can perm="stock.adjust"><button className="btn btn-dark btn-sm" onClick={() => go('adjust')}><Icon n="plus" s={13} /> إدخال رصيد افتتاحي</button></Can>} />}>
1070:           {rows.length === 0 ? <EmptyState icon="filter" title="لا توجد أرصدة تطابق الفلاتر" sub="غيّر الفلاتر أو امسحها لعرض كل الأرصدة." /> : (
1071:             <div className="overflow-x-auto -mx-1 px-1">
1072:               <table className="vt">
1073:                 <thead><tr>
1074:                   <th>المنتج</th><th>SKU</th><th>الباركود</th><th>الفرع</th><th>الموقع</th>
1075:                   <th className="t-num">الموجود</th><th className="t-num">المحجوز</th><th className="t-num">التالف</th><th className="t-num">قيد النقل</th><th className="t-num">المتاح</th><th className="t-num">حد الطلب</th><th>آخر تحديث</th><th></th>
1076:                 </tr></thead>
1077:                 <tbody>
1078:                   {rows.map(s => {
1079:                     const low = s.available <= s.reorder;
1080:                     const pct = Math.min(100, s.reorder ? s.available / (s.reorder * 2) * 100 : 100);
1081:                     return (
1082:                       <tr key={s.id}>
1083:                         <td><VariantCell id={s.variantId} /></td>
1084:                         <td><Sku id={s.variantId} /></td>
1085:                         <td className="mono text-[11.5px] c-secondary">{invVariant(s.variantId).barcode}</td>
1086:                         <td className="c-secondary">{invBranch(s.branchId).name}</td>
1087:                         <td><span className="mono text-[11.5px] c-secondary">{invLoc(s.locId).code}</span></td>
1088:                         <td className="t-num num font-semibold c-primary">{invFmt(s.onHand)}</td>
1089:                         <td className="t-num num c-secondary">{invFmt(s.reserved)}</td>
1090:                         <td className="t-num num" style={{ color: s.damaged ? 'var(--badge-red-text)' : 'var(--text-muted)' }}>{invFmt(s.damaged)}</td>
1091:                         <td className="t-num num" style={{ color: s.inTransit ? 'var(--badge-blue-text)' : 'var(--text-muted)' }}>{invFmt(s.inTransit)}</td>
1092:                         <td className="t-num">
1093:                           <div className="flex flex-col items-end gap-1">
1094:                             <span className={`num font-bold ${low ? '' : 'c-primary'}`} style={low ? { color: 'var(--accent-orange)' } : {}}>{invFmt(s.available)}</span>
1095:                             <span className="w-16 h-1 rounded-full hatched overflow-hidden flex justify-end" style={{ direction: 'ltr' }}>
1096:                               <span className="block h-full rounded-full" style={{ width: pct + '%', background: low ? 'var(--accent-orange)' : 'var(--text-primary)' }} />
1097:                             </span>
1098:                           </div>
1099:                         </td>
1100:                         <td className="t-num num c-muted">{invFmt(s.reorder)}</td>
1101:                         <td className="num text-[11.5px] c-muted">{s.updated}</td>
1102:                         <td>
1103:                           <div className="flex items-center gap-0.5 justify-end">
1104:                             <button className="icon-btn" title="حركات الصنف" onClick={() => go('moves', { variantId: s.variantId, productId: invVariant(s.variantId).productId, branchId: s.branchId })}><Icon n="history" s={15} /></button>
1105:                             {can('stock.adjust') && <button className="icon-btn" title="تسوية" onClick={() => go('adjust', { branchId: s.branchId, locId: s.locId, variantId: s.variantId })}><Icon n="sliders" s={15} /></button>}
1106:                           </div>
1107:                         </td>
1108:                       </tr>
1109:                     );
1110:                   })}
1111:                 </tbody>
1112:               </table>
1113:             </div>
1114:           )}
1115:         </Phase>
1116:       </Card>
1117:     </section>
1118:   );
1119: }
