1121: // ---------------- 4. Adjustment ----------------
1122: const ADJ_TYPES = {
1123:   increase:   { label: 'زيادة',              cls: 'b-green', sign: '+' },
1124:   decrease:   { label: 'نقصان',              cls: 'b-red',   sign: '−' },
1125:   dmg_mark:   { label: 'تسجيل تالف',         cls: 'b-amber', sign: '→' },
1126:   dmg_write:  { label: 'إعدام تالف',         cls: 'b-red',   sign: '×' },
1127:   dmg_restore:{ label: 'استرجاع من التالف',  cls: 'b-blue',  sign: '←' },
1128: };
1129: const ADJ_MAX = 100;
1130: let __adjLineId = 1;
1131: const newAdjLine = (p = {}) => ({ key: __adjLineId++, variantId: null, type: 'increase', qty: '', reason: '', ...p });
1132: 
1133: function AdjustScreen({ go, params }) {
1134:   const { toast, demoState } = useInv();
1135:   const can = useCan();
1136:   const [branchId, setBranchId] = useState(params.branchId || null);
1137:   const [locId, setLocId] = useState(params.locId || null);
1138:   const [lines, setLines] = useState(() => [newAdjLine(params.variantId ? { variantId: params.variantId } : {})]);
1139:   const [tried, setTried] = useState(false);
1140:   const [confirm, setConfirm] = useState(false);
1141:   const [busy, setBusy] = useState(false);
1142:   const [srvErr, setSrvErr] = useState(null);
1143:   const [opening, setOpening] = useState(false);
1144: 
1145:   if (!can('stock.adjust')) return <NoPerm title="تسوية المخزون" perm="تسوية المخزون" go={go} />;
1146: 
1147:   const upd = (key, p) => setLines(ls => ls.map(l => l.key === key ? { ...l, ...p } : l));
1148:   const lineErr = l => {
1149:     const e = {};
1150:     if (!l.variantId) e.variantId = true;
1151:     const q = parseFloat(l.qty);
1152:     if (!l.qty || !(q > 0)) e.qty = 'كمية موجبة';
1153:     if (!l.reason.trim()) e.reason = true;
1154:     return e;
1155:   };
1156:   const errs = lines.map(lineErr);
1157:   const valid = branchId && errs.every(e => !Object.keys(e).length);
1158:   const dupes = lines.filter((l, i) => l.variantId && lines.findIndex(x => x.variantId === l.variantId && x.type === l.type) !== i).length;
1159: 
1160:   const stockOf = vid => INV_STOCK.find(s => s.variantId === vid && s.branchId === branchId && (!locId || s.locId === locId));
1161: 
1162:   const applyOpening = on => {
1163:     setOpening(on);
1164:     setLines(ls => ls.map(l => on ? { ...l, type: 'increase', reason: l.reason || 'رصيد افتتاحي' } : l));
1165:   };
1166: 
1167:   const execute = () => {
1168:     setBusy(true); setSrvErr(null);
1169:     setTimeout(() => {
1170:       setBusy(false);
1171:       if (demoState === 'error') { setSrvErr('الكمية المطلوب خصمها في البند ٢ أكبر من الرصيد المتاح (Insufficient stock · 422).'); return; }
1172:       setConfirm(false); toast(`تم تنفيذ التسوية · ${lines.length} بند`);
1173:       go('moves', { branchId });
1174:     }, 900);
1175:   };
1176: 
1177:   const totals = Object.keys(ADJ_TYPES).map(k => ({ k, n: lines.filter(l => l.type === k && l.variantId).length })).filter(x => x.n);
1178: 
1179:   return (
1180:     <section className="space-y-5">
1181:       <PageHead title="تسوية المخزون" back={{ label: 'أرصدة المخزون', onClick: () => go('stock') }}
1182:         sub="زيادة أو خصم كميات، أو نقلها من وإلى التالف. التسوية تُنفَّذ كعملية واحدة وتنعكس فورًا على الأرصدة والحركات." />
1183: 
1184:       <div className="grid grid-cols-1 lg:grid-cols-12 gap-5 items-start">
1185:         <div className="lg:col-span-9 space-y-5">
1186:           <Card stagger={2}>
1187:             <CardHead title="بيانات العملية" />
1188:             <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
1189:               <Field label="الفرع / المخزن" req error={tried && !branchId ? 'اختر الفرع' : null}>
1190:                 <Sel value={branchId} onChange={v => { setBranchId(v); setLocId(null); }} placeholder="اختر…" options={branchOpts(b => b.active)} className={tried && !branchId ? 'err' : ''} />
1191:               </Field>
1192:               <Field label="موقع التخزين" hint="اختياري — يطبَّق على كل البنود">
1193:                 <Sel value={locId} onChange={setLocId} placeholder={branchId ? 'بدون موقع محدد' : 'اختر الفرع أولًا'} disabled={!branchId} options={branchId ? locOpts(branchId) : []} />
1194:               </Field>
1195:               <div>
1196:                 <span className="field-label">إدخال رصيد افتتاحي</span>
1197:                 <label className="v-subcard px-3.5 py-2 flex items-center justify-between cursor-pointer" style={{ borderRadius: 12 }}>
1198:                   <span className="text-[12px] c-secondary">كل البنود = زيادة</span>
1199:                   <Toggle on={opening} onChange={applyOpening} />
1200:                 </label>
1201:               </div>
1202:             </div>
1203:             {opening && <div className="mt-4"><InlineAlert kind="blue" icon="info" title="رصيد افتتاحي">تُسجَّل الكميات الافتتاحية حاليًا كتسوية زيادة. اكتب سببًا واضحًا لكل بند حتى يسهل تتبّعها في سجل الحركات.</InlineAlert></div>}
1204:           </Card>
1205: 
1206:           <Card stagger={3}>
1207:             <CardHead title="البنود" meta={<span className="num">{lines.length} / {ADJ_MAX}</span>}
1208:               right={<button className="btn btn-soft btn-sm" disabled={lines.length >= ADJ_MAX} onClick={() => setLines(ls => [...ls, newAdjLine(opening ? { reason: 'رصيد افتتاحي' } : {})])}><Icon n="plus" s={13} /> إضافة بند</button>} />
1209:             {dupes > 0 && <div className="mb-3"><InlineAlert kind="amber" title="بنود مكررة">يوجد {dupes} بند مكرر بنفس SKU ونفس نوع التسوية — سيتم دمجها عند التنفيذ.</InlineAlert></div>}
1210:             <div className="overflow-x-auto">
1211:               <table className="vt">
1212:                 <thead><tr><th className="w-8">#</th><th style={{ minWidth: 280 }}>المنتج / المتغير</th><th style={{ minWidth: 170 }}>نوع التسوية</th><th style={{ minWidth: 120 }}>الكمية</th><th style={{ minWidth: 200 }}>السبب</th><th></th></tr></thead>
1213:                 <tbody>
1214:                   {lines.map((l, i) => {
1215:                     const e = tried ? errs[i] : {};
1216:                     const st = l.variantId && branchId ? stockOf(l.variantId) : null;
1217:                     return (
1218:                       <tr key={l.key} className="align-top">
1219:                         <td className="num c-muted pt-4">{i + 1}</td>
1220:                         <td>
1221:                           <div className={e.variantId ? 'rounded-[12px] ring-1 ring-[var(--badge-red-text)]' : ''}><VariantPicker small value={l.variantId} onChange={v => upd(l.key, { variantId: v })} /></div>
1222:                           {st && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح <span className="num c-primary font-semibold">{invFmt(st.available)}</span> · التالف <span className="num">{invFmt(st.damaged)}</span></div>}
1223:                           {l.variantId && branchId && !st && <div className="text-[10.5px] c-muted mt-1 pr-1">لا يوجد رصيد حالي في هذا الفرع</div>}
1224:                         </td>
1225:                         <td><Sel small value={l.type} onChange={v => upd(l.key, { type: v || 'increase' })} options={Object.entries(ADJ_TYPES).map(([k, t]) => ({ value: k, label: t.label }))} /></td>
1226:                         <td>
1227:                           <NumInput small value={l.qty} onChange={v => upd(l.key, { qty: v })} err={e.qty} placeholder="0.0000" />
1228:                           {e.qty && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-red-text)' }}>{e.qty}</div>}
1229:                         </td>
1230:                         <td><input className={`inp inp-sm ${e.reason ? 'err' : ''}`} value={l.reason} onChange={ev => upd(l.key, { reason: ev.target.value })} placeholder="مثال: كسر أثناء التفريغ" /></td>
1231:                         <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1232:                       </tr>
1233:                     );
1234:                   })}
1235:                 </tbody>
1236:               </table>
1237:             </div>
1238:             <div className="mt-3 text-[11px] c-muted flex items-center gap-1.5"><Icon n="info" s={12} /> الكميات موجبة دائمًا وتقبل حتى 4 منازل عشرية. اتجاه الحركة يحدده نوع التسوية.</div>
1239:           </Card>
1240:         </div>
1241: 
1242:         <div className="lg:col-span-3 lg:sticky lg:top-5">
1243:           <Card stagger={4}>
1244:             <h3 className="font-display text-[15px] font-semibold c-primary mb-3">ملخص</h3>
1245:             <div className="space-y-2 text-[12.5px]">
1246:               <div className="flex justify-between"><span className="c-secondary">الفرع</span><span className="font-medium c-primary">{branchId ? invBranch(branchId).name : '—'}</span></div>
1247:               <div className="flex justify-between"><span className="c-secondary">الموقع</span><span className="mono c-primary">{locId ? invLoc(locId).code : '—'}</span></div>
1248:               <div className="flex justify-between"><span className="c-secondary">عدد البنود</span><span className="num font-semibold c-primary">{lines.length}</span></div>
1249:             </div>
1250:             <div className="h-px my-4" style={{ background: 'var(--divider-color)' }} />
1251:             <div className="space-y-1.5">
1252:               {totals.length === 0 && <div className="text-[11.5px] c-muted">لم يتم اختيار أصناف بعد</div>}
1253:               {totals.map(t => <div key={t.k} className="flex items-center justify-between"><Badge cls={ADJ_TYPES[t.k].cls}>{ADJ_TYPES[t.k].label}</Badge><span className="num text-[12px] c-primary font-semibold">{t.n}</span></div>)}
1254:             </div>
1255:             <div className="mt-5 space-y-2">
1256:               <button className="btn btn-orange w-full" onClick={() => { setTried(true); if (valid) { setSrvErr(null); setConfirm(true); } }}>
1257:                 <Icon n="check" s={14} w={2.2} /> تنفيذ التسوية
1258:               </button>
1259:               <button className="btn btn-soft w-full" onClick={() => go('stock')}>إلغاء</button>
1260:             </div>
1261:             {tried && !valid && <div className="text-[11px] mt-3" style={{ color: 'var(--badge-red-text)' }}>أكمل الحقول المطلوبة المظللة بالأحمر.</div>}
1262:           </Card>
1263:         </div>
1264:       </div>
1265: 
1266:       <ConfirmDialog open={confirm} onClose={() => setConfirm(false)} onConfirm={execute} busy={busy} error={srvErr}
1267:         title="تأكيد تنفيذ التسوية" confirmLabel="تنفيذ الآن"
1268:         body={<div className="space-y-3">
1269:           <p>سيتم تنفيذ <b className="c-primary num">{lines.length}</b> بند على <b className="c-primary">{branchId && invBranch(branchId).name}</b>{locId && <> — موقع <span className="mono">{invLoc(locId).code}</span></>}. لا يمكن تعديل أو حذف الحركات بعد التنفيذ؛ للتصحيح أنشئ تسوية عكسية.</p>
