1312:           <FItem label="من تاريخ" w="w-36"><input type="date" value={f.from} onChange={e => set({ from: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1313:           <FItem label="إلى تاريخ" w="w-36"><input type="date" value={f.to} onChange={e => set({ to: e.target.value })} className="inp inp-sm num !bg-[var(--bg-card)]" /></FItem>
1314:         </FilterBar>
1315: 
1316:         <Phase phase={phase} cols={9} rows={8}
1317:           empty={<EmptyState icon="history" title="لا توجد حركات بعد" sub="ستظهر هنا كل عمليات التسوية والتحويل والجرد واستلام الإنتاج بمجرد تنفيذها." />}>
1318:           {page.length === 0 ? <EmptyState icon="filter" title="لا توجد حركات تطابق الفلاتر" sub="وسّع نطاق التاريخ أو امسح بعض الفلاتر." /> : (
1319:             <>
1320:               <div className="overflow-x-auto">
1321:                 <table className="vt">
1322:                   <thead><tr>
1323:                     <th>التاريخ</th><th>المرجع</th><th>SKU</th><th>الفرع</th><th>الموقع</th><th>نوع الحركة</th>
1324:                     <th className="t-num">الكمية</th><th className="t-num">الرصيد قبل ← بعد</th>{showCost && <th className="t-num">تكلفة الوحدة</th>}<th>المنفّذ</th><th>ملاحظات</th>
1325:                   </tr></thead>
