1337:                           <td className="t-num num font-bold" style={{ color: m.qty > 0 ? 'var(--badge-green-text)' : 'var(--badge-red-text)' }}>{m.qty > 0 ? '+' : '−'}{invFmt(Math.abs(m.qty))}</td>
1338:                           <td className="t-num num text-[12px]"><span className="c-muted">{invFmt(m.before)}</span> <span className="c-muted mx-1">→</span> <span className="font-semibold c-primary">{invFmt(m.after)}</span></td>
