1350:                 <div className="flex items-center gap-2">
1351:                   <button className="btn btn-soft btn-sm" disabled={cursor === 0} onClick={() => setCursor(c => Math.max(0, c - PAGE))}><Icon n="chevR" s={13} /> السابق</button>
