1515:                       {a !== null && <div className="text-[10.5px] c-muted mt-1 pr-1">المتاح في المصدر: <span className="num font-semibold c-primary">{invFmt(a)}</span></div>}
1516:                     </td>
1517:                     <td><Sel small value={l.fromLoc} onChange={v => upd(l.key, { fromLoc: v })} placeholder={from ? 'أي موقع' : '—'} disabled={!from} options={from ? locOpts(from) : []} /></td>
1518:                     <td><Sel small value={l.toLoc} onChange={v => upd(l.key, { toLoc: v })} placeholder={to ? 'موقع الاستلام الافتراضي' : '—'} disabled={!to} options={to ? locOpts(to) : []} /></td>
1519:                     <td>
1520:                       <NumInput small value={l.req} onChange={v => upd(l.key, { req: v })} err={tried && !(parseFloat(l.req) > 0)} />
1521:                       {over && <div className="text-[10.5px] mt-1" style={{ color: 'var(--badge-amber-text)' }}>أكبر من المتاح حاليًا</div>}
1522:                     </td>
1523:                     <td className="pt-3"><button className="icon-btn" disabled={lines.length === 1} onClick={() => setLines(ls => ls.filter(x => x.key !== l.key))}><Icon n="trash" s={14} /></button></td>
1524:                   </tr>
1525:                 );
1526:               })}
1527:             </tbody>
1528:           </table>
1529:         </div>
1530:       </Card>
1531:     </section>
1532:   );
