1893: function InlineAlert({ kind = 'red', icon = 'alert', title, children, onClose }) {
1894:   const map = { red: ['--badge-red-bg', '--badge-red-text'], amber: ['--badge-amber-bg', '--badge-amber-text'], blue: ['--badge-blue-bg', '--badge-blue-text'], green: ['--badge-green-bg', '--badge-green-text'] }[kind];
1895:   return (
1896:     <div className="rounded-2xl px-4 py-3 flex items-start gap-3 fade-in" style={{ background: `var(${map[0]})` }}>
1897:       <span style={{ color: `var(${map[1]})` }} className="mt-0.5"><Icon n={icon} s={16} /></span>
1898:       <div className="flex-1 text-[12.5px]">
1899:         {title && <div className="font-semibold" style={{ color: `var(${map[1]})` }}>{title}</div>}
1900:         <div className="c-primary opacity-80 mt-0.5">{children}</div>
1901:       </div>
