1907: // ---------- Modal ----------
1908: function Modal({ open, onClose, title, sub, children, footer, width = 'max-w-lg' }) {
1909:   useEffect(() => {
1910:     if (!open) return;
1911:     const h = e => e.key === 'Escape' && onClose && onClose();
1912:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
1913:   }, [open]);
1914:   if (!open) return null;
1915:   return (
1916:     <div className="fixed inset-0 z-50 flex items-center justify-center p-4 fade-in" style={{ background: 'rgba(0,0,0,.4)', backdropFilter: 'blur(4px)' }} onMouseDown={e => e.target === e.currentTarget && onClose && onClose()}>
1917:       <div className={`v-card ${width} w-full shadow-2xl modal-in flex flex-col max-h-[92vh]`}>
1918:         <div className="flex items-start justify-between gap-4 p-6 pb-4">
1919:           <div>
1920:             <h3 className="font-display text-[18px] font-semibold c-primary">{title}</h3>
1921:             {sub && <p className="text-[12px] c-secondary mt-0.5">{sub}</p>}
1922:           </div>
1923:           <button onClick={onClose} className="w-8 h-8 rounded-full v-subcard flex items-center justify-center c-secondary shrink-0"><Icon n="x" s={14} /></button>
1924:         </div>
1925:         <div className="px-6 pb-2 overflow-y-auto flex-1">{children}</div>
1926:         {footer && <div className="p-6 pt-4 flex items-center justify-start gap-2.5 flex-row-reverse">{footer}</div>}
1927:       </div>
1928:     </div>
1929:   );
1930: }
