1960: // ---------- Variant picker: product → variant/SKU (never stops at product) ----------
1961: function VariantPicker({ value, onChange, placeholder = 'ابحث بالاسم أو SKU أو الباركود', small, exclude = [], allowClear }) {
1962:   const [open, setOpen] = useState(false);
1963:   const [q, setQ] = useState('');
1964:   const ref = useRef();
1965:   useEffect(() => {
1966:     const h = e => ref.current && !ref.current.contains(e.target) && setOpen(false);
1967:     document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h);
1968:   }, []);
1969:   const v = value ? invVariant(value) : null;
1970:   const ql = q.trim().toLowerCase();
1971:   const groups = INV_PRODUCTS.map(p => ({
1972:     ...p,
1973:     variants: p.variants.filter(x => !exclude.includes(x.id) && (!ql || p.name.includes(q) || x.sku.toLowerCase().includes(ql) || x.barcode.includes(ql) || x.attrs.includes(q))),
1974:   })).filter(p => p.variants.length);
1975: 
1976:   return (
1977:     <div ref={ref} className="relative">
1978:       <button type="button" onClick={() => setOpen(o => !o)} className={`inp ${small ? 'inp-sm' : ''} flex items-center justify-between gap-2 text-right`}>
1979:         {v ? (
1980:           <span className="flex items-center gap-2 min-w-0">
1981:             <span className="truncate c-primary">{v.productName}</span>
1982:             <span className="text-[11px] c-muted shrink-0">{v.attrs}</span>
1983:             <span className="mono text-[10.5px] px-1.5 py-0.5 rounded-md shrink-0" style={{ background: 'var(--icon-well-bg)' }}>{v.sku}</span>
1984:           </span>
1985:         ) : <span className="c-muted truncate">{placeholder}</span>}
1986:         <span className="flex items-center gap-1 shrink-0">
1987:           {allowClear && v && <span onClick={e => { e.stopPropagation(); onChange(null); }} className="c-muted hover:c-primary"><Icon n="x" s={12} /></span>}
1988:           <Icon n="chevD" s={13} className="c-muted" />
1989:         </span>
1990:       </button>
1991:       {open && (
1992:         <div className="absolute z-40 mt-1.5 w-full min-w-[320px] v-card shadow-2xl p-2 modal-in" style={{ borderRadius: 16 }}>
1993:           <div className="v-subcard px-3 py-2 rounded-xl flex items-center gap-2 mb-1.5">
1994:             <Icon n="search" s={14} className="c-muted" />
1995:             <input autoFocus value={q} onChange={e => setQ(e.target.value)} placeholder="اسم المنتج، SKU، باركود…" className="bg-transparent text-[12.5px] outline-none flex-1 c-primary" />
1996:             <Icon n="barcode" s={14} className="c-muted" />
1997:           </div>
1998:           <div className="max-h-[260px] overflow-y-auto">
1999:             {groups.length === 0 && <div className="text-center text-[12px] c-muted py-6">لا توجد نتائج مطابقة</div>}
2000:             {groups.map(p => (
2001:               <div key={p.id} className="mb-1">
2002:                 <div className="text-[11px] font-semibold c-secondary px-2.5 pt-2 pb-1 flex items-center gap-1.5"><Icon n="box" s={12} /> {p.name} <span className="c-muted font-normal">· {p.variants.length} متغير</span></div>
2003:                 {p.variants.map(x => (
2004:                   <button type="button" key={x.id} onClick={() => { onChange(x.id); setOpen(false); setQ(''); }}
2005:                     className={`w-full flex items-center justify-between gap-3 px-2.5 py-2 rounded-xl text-right hover:bg-[var(--bg-subcard)] ${value === x.id ? 'bg-[var(--bg-subcard)]' : ''}`}>
2006:                     <span className="text-[12.5px] c-primary pr-4">{x.attrs}</span>
2007:                     <span className="flex items-center gap-2">
2008:                       <span className="mono text-[10.5px] c-muted">{x.barcode}</span>
2009:                       <span className="mono text-[11px] font-semibold c-primary">{x.sku}</span>
2010:                       {value === x.id && <Icon n="check" s={13} className="c-orange" />}
2011:                     </span>
2012:                   </button>
2013:                 ))}
2014:               </div>
2015:             ))}
2016:           </div>
2017:         </div>
2018:       )}
2019:     </div>
2020:   );
2021: }
