1883:   <!-- ================= JAVASCRIPT ================= -->
1884:   <script>
1885:     let currentQty = 1;
1886:     let cartTotalItems = 0;
1887:     let activeCategory = 'all';
1888:     let activeColor = 'all';
1889:     let activePriceRange = 'all';
1890: 
1891:     // Toggle Sidebar Filter
1892:     function toggleSidebar() {
1893:       const sidebar = document.getElementById('sidebar');
1894:       const grid = document.getElementById('productGrid');
1895:       const btn = document.getElementById('filterToggleBtn');
1896:       const btnText = document.getElementById('filterBtnText');
1897: 
1898:       sidebar.classList.toggle('hidden');
1899:       grid.classList.toggle('four-cols');
1900:       btn.classList.toggle('open');
1901: 
1902:       if (sidebar.classList.contains('hidden')) {
1903:         btnText.textContent = 'Show Filters';
1904:       } else {
1905:         btnText.textContent = 'Hide Filters';
1906:       }
1907:     }
1908: 
1909:     // Filter by Category
1910:     function filterByCategory(cat, pillEl) {
1911:       activeCategory = cat;
1912: 
1913:       // Update pills
1914:       document.querySelectorAll('.cat-pill').forEach(pill => {
1915:         pill.classList.remove('active');
1916:       });
1917:       if (pillEl) {
1918:         pillEl.classList.add('active');
1919:       } else {
1920:         document.querySelectorAll('.cat-pill').forEach(pill => {
1921:           if ((cat === 'all' && pill.innerText.includes('All')) ||
1922:               pill.innerText.toLowerCase().includes(cat)) {
1923:             pill.classList.add('active');
1924:           }
1925:         });
1926:       }
1927: 
1928:       // Update sidebar category item active
1929:       document.querySelectorAll('.filter-sidebar .filter-item').forEach(item => {
1930:         item.classList.remove('active');
1931:       });
1932: 
1933:       applyFilters();
1934:     }
1935: 
1936:     // Filter by Color
1937:     function filterByColor(color, btnEl) {
1938:       activeColor = color;
1939:       document.querySelectorAll('.swatch-btn').forEach(btn => btn.classList.remove('active'));
1940:       if (btnEl) btnEl.classList.add('active');
1941:       applyFilters();
1942:     }
1943: 
1944:     // Filter by Price Range
1945:     function filterByPriceRange(range) {
1946:       activePriceRange = range;
1947:       applyFilters();
1948:     }
1949: 
1950:     // Master filter evaluation
1951:     function applyFilters() {
1952:       const cards = document.querySelectorAll('#productGrid .product-card');
1953:       let visibleCount = 0;
1954: 
1955:       cards.forEach(card => {
1956:         const cardCat = card.getAttribute('data-category');
1957:         const cardColor = card.getAttribute('data-color');
1958:         const cardPrice = parseFloat(card.getAttribute('data-price'));
1959: 
1960:         let matchCat = (activeCategory === 'all' || cardCat === activeCategory);
1961:         let matchColor = (activeColor === 'all' || cardColor === activeColor);
1962:         let matchPrice = true;
1963: 
1964:         if (activePriceRange === 'under-90') {
1965:           matchPrice = (cardPrice < 90);
1966:         } else if (activePriceRange === '90-120') {
1967:           matchPrice = (cardPrice >= 90 && cardPrice <= 120);
1968:         } else if (activePriceRange === 'over-120') {
1969:           matchPrice = (cardPrice > 120);
1970:         }
1971: 
1972:         if (matchCat && matchColor && matchPrice) {
1973:           card.style.display = 'block';
1974:           visibleCount++;
1975:         } else {
1976:           card.style.display = 'none';
1977:         }
1978:       });
1979: 
1980:       // Update count & empty state
1981:       document.getElementById('filterItemCount').textContent = `Showing ${visibleCount} piece${visibleCount === 1 ? '' : 's'}`;
1982:       const noResults = document.getElementById('noResults');
1983:       if (visibleCount === 0) {
1984:         noResults.style.display = 'block';
1985:       } else {
1986:         noResults.style.display = 'none';
1987:       }
1988:     }
1989: 
1990:     // Reset Filters
1991:     function resetFilters() {
1992:       activeCategory = 'all';
1993:       activeColor = 'all';
1994:       activePriceRange = 'all';
1995: 
1996:       document.querySelectorAll('.cat-pill').forEach((pill, idx) => {
1997:         if (idx === 0) pill.classList.add('active');
1998:         else pill.classList.remove('active');
1999:       });
2000: 
2001:       document.querySelectorAll('.swatch-btn').forEach((btn, idx) => {
2002:         if (idx === 0) btn.classList.add('active');
2003:         else btn.classList.remove('active');
2004:       });
2005: 
2006:       const defaultRadio = document.querySelector('input[name="priceRange"][value="all"]');
2007:       if (defaultRadio) defaultRadio.checked = true;
2008: 
2009:       applyFilters();
2010:     }
2011: 
2012:     // Sort Products
2013:     function sortProducts() {
2014:       const sortVal = document.getElementById('sortSelect').value;
2015:       const grid = document.getElementById('productGrid');
2016:       const cards = Array.from(grid.querySelectorAll('.product-card'));
2017: 
2018:       cards.sort((a, b) => {
2019:         const priceA = parseFloat(a.getAttribute('data-price'));
2020:         const priceB = parseFloat(b.getAttribute('data-price'));
2021:         const nameA = a.querySelector('.product-name').innerText;
2022:         const nameB = b.querySelector('.product-name').innerText;
2023: 
2024:         if (sortVal === 'price-asc') return priceA - priceB;
2025:         if (sortVal === 'price-desc') return priceB - priceA;
2026:         if (sortVal === 'name') return nameA.localeCompare(nameB);
2027:         return 0; // featured default
2028:       });
2029: 
2030:       cards.forEach(card => grid.appendChild(card));
2031:     }
2032: 
2033:     // Open Product Detail View
2034:     function openProductDetail(title, price, imgUrl, tintClass, sku, desc) {
2035:       document.getElementById('catalogView').classList.add('hidden');
2036:       document.getElementById('productDetailView').classList.add('active');
2037: 
2038:       document.getElementById('pdpTitle').innerHTML = title.replace(" Backpack", "<br>Backpack");
2039:       document.getElementById('pdpBreadcrumbTitle').textContent = title;
2040:       document.getElementById('pdpPrice').textContent = price;
2041:       document.getElementById('pdpSku').textContent = `Style: ${sku || 'SP-2026'}`;
2042:       if (desc) document.getElementById('pdpDesc').textContent = desc;
2043: 
2044:       const mainImg = document.getElementById('pdpMainImage');
2045:       mainImg.src = imgUrl;
2046:       mainImg.className = tintClass || 'tint-pink';
2047: 
2048:       // Reset qty
2049:       currentQty = 1;
2050:       document.getElementById('qtyNumber').textContent = currentQty;
2051: 
2052:       window.scrollTo({ top: 380, behavior: 'smooth' });
2053:     }
2054: 
2055:     // Show Catalog View
2056:     function showCatalog() {
2057:       document.getElementById('productDetailView').classList.remove('active');
2058:       document.getElementById('catalogView').classList.remove('hidden');
2059:       window.scrollTo({ top: 350, behavior: 'smooth' });
2060:     }
2061: 
2062:     // Switch PDP image on thumbnail click
2063:     function switchMainImage(thumbBox, tintClass) {
2064:       document.querySelectorAll('.pdp-thumb-box').forEach(b => b.classList.remove('active'));
2065:       thumbBox.classList.add('active');
2066: 
2067:       const img = thumbBox.querySelector('img');
2068:       const mainImg = document.getElementById('pdpMainImage');
2069:       mainImg.src = img.src;
2070:       mainImg.className = tintClass;
2071:     }
2072: 
2073:     // Set PDP Tint via Swatches
2074:     function setPdpTint(swatchEl, tintClass) {
2075:       document.querySelectorAll('.pdp-swatch').forEach(s => s.classList.remove('active'));
2076:       swatchEl.classList.add('active');
2077: 
2078:       const mainImg = document.getElementById('pdpMainImage');
2079:       mainImg.className = tintClass;
2080:     }
2081: 
2082:     // Size Selection
2083:     function selectSize(btn) {
2084:       document.querySelectorAll('.pdp-size-btn').forEach(b => b.classList.remove('active'));
2085:       btn.classList.add('active');
2086:     }
2087: 
2088:     // Quantity Picker
2089:     function changeQty(delta) {
2090:       currentQty = Math.max(1, currentQty + delta);
2091:       document.getElementById('qtyNumber').textContent = currentQty;
2092:     }
2093: 
2094:     // Add to Cart Interaction
2095:     function addToCart() {
2096:       cartTotalItems += currentQty;
2097:       const badge = document.getElementById('cartCountBadge');
2098:       badge.textContent = cartTotalItems;
2099:       badge.classList.add('bump');
2100:       setTimeout(() => badge.classList.remove('bump'), 300);
2101: 
2102:       const title = document.getElementById('pdpBreadcrumbTitle').textContent;
2103:       showToast(`Added ${currentQty}x "${title}" to your shopping bag!`);
2104:     }
2105: 
2106:     // Wishlist Toggle
2107:     function toggleWishlist(btn) {
2108:       const icon = btn.querySelector('i');
2109:       if (icon.classList.contains('fa-regular')) {
2110:         icon.classList.remove('fa-regular');
2111:         icon.classList.add('fa-solid');
2112:         icon.style.color = '#e11d48';
2113:         showToast('Saved to your wishlist!');
2114:       } else {
2115:         icon.classList.remove('fa-solid');
2116:         icon.classList.add('fa-regular');
2117:         icon.style.color = '';
2118:         showToast('Removed from your wishlist.');
2119:       }
2120:     }
2121: 
2122:     // Show Toast Notification
2123:     function showToast(msg) {
2124:       const toast = document.getElementById('cartToast');
2125:       document.getElementById('toastMsg').textContent = msg;
2126:       toast.classList.add('show');
2127:       setTimeout(() => {
2128:         toast.classList.remove('show');
2129:       }, 3000);
2130:     }
2131: 
2132:     function openCartToast() {
2133:       showToast(`You have ${cartTotalItems} item${cartTotalItems === 1 ? '' : 's'} in your bag.`);
2134:     }
2135: 
2136:     // Smooth Navigation Transition between Pages
2137:     document.querySelectorAll('a[href]').forEach(link => {
2138:       const href = link.getAttribute('href');
2139:       if (href && (href === 'home.html' || href === 'categories.html' || href === 'design.html')) {
2140:         link.addEventListener('click', e => {
2141:           const currentFile = window.location.pathname.split('/').pop() || 'categories.html';
2142:           if (link.target !== '_blank' && !e.ctrlKey && !e.metaKey && href !== currentFile) {
2143:             e.preventDefault();
2144:             document.body.classList.add('page-fade-out');
2145:             setTimeout(() => {
2146:               window.location.href = href;
2147:             }, 180);
2148:           }
2149:         });
2150:       }
2151:     });
2152:   </script>
