118:   uploadImages: (productId: number, files: File[], variantId?: number | null, onProgress?: (n: number) => void) => {
119:     const fd = new FormData();
120:     fd.append('collection', 'images');
121:     if (variantId) fd.append('variant_id', String(variantId));
122:     files.forEach(f => fd.append('files[]', f));   // max 10 في الطلب الواحد
123:     return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, onUploadProgress: progress(onProgress) }).then(r => r.data.data);
124:   },
125:   uploadVideo: (productId: number, file: File, onProgress?: (n: number) => void) => {
126:     const fd = new FormData();
127:     fd.append('collection', 'video');
128:     fd.append('file', file);
129:     return apiClient.post<{ data: AdminMedia[] }>(`${PR}/${productId}/media`, fd, { ...MULTIPART, onUploadProgress: progress(onProgress), timeout: 0 }).then(r => r.data.data);
130:   },
131:   reorder: (productId: number, ids: number[]) => apiClient.put(`${PR}/${productId}/media/reorder`, { ids }).then(r => r.data),
132:   remove: (productId: number, mediaId: number) => apiClient.delete(`${PR}/${productId}/media/${mediaId}`).then(r => r.data),
