18: use Illuminate\Routing\Controllers\Middleware;
19: 
20: class ProductionReceiptController extends Controller implements HasMiddleware
21: {
22:     public static function middleware(): array
23:     {
24:         return [
25:             new Middleware('can:inventory.view', only: ['options', 'index']),
26:         ];
27:     }
28: 
29:     public function options(Request $request): JsonResponse
30:     {
31:         $filters = $request->validate(['search' => ['nullable', 'string', 'max:100']]);
32:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
33:         $branches = Branch::where('is_active', true)->when($branch, fn ($q) => $q->whereKey($branch))
34:             ->with(['locations' => fn ($q) => $q->where('is_active', true)])->orderBy('id')->get();
35:         $variants = ProductVariant::where('is_active', true)->whereHas('product')
36:             ->with('product:id,name_ar')->when($filters['search'] ?? null, function ($q, $search): void {
37:                 $pattern = SearchTerm::pattern($search);
38:                 $q->where(fn ($q) => $q->whereLike('sku', $pattern)->orWhereLike('barcode', $pattern)
39:                     ->orWhereHas('product', fn ($p) => $p->whereLike('name_ar', $pattern)->orWhereLike('name_en', $pattern)));
40:             })->orderBy('id')->limit(50)->get();
41: 
42:         return response()->json(['data' => [
43:             'branches' => $branches->map(fn ($b) => ['id' => $b->id, 'name' => $b->name,
44:                 'locations' => $b->locations->map(fn ($l) => ['id' => $l->id, 'name' => $l->name])]),
45:             'variants' => $variants->map(fn ($v) => ['id' => $v->id, 'label' => $v->product->name_ar.' / '.$v->sku]),
46:         ]]);
47:     }
48: 
49:     public function index(Request $request): JsonResponse
50:     {
51:         $filters = $request->validate(['per_page' => ['nullable', 'integer', 'min:1', 'max:100']]);
52:         $branch = app(BranchAccess::class)->restrictedBranch($request->user());
53:         $receipts = ProductionReceipt::query()->when($branch, fn ($q) => $q->where('branch_id', $branch))
54:             ->orderByDesc('id')->paginate($filters['per_page'] ?? 15);
55:         if (! $request->user()->can('products.view_cost')) {
56:             $receipts->getCollection()->each(function ($receipt): void {
57:                 $receipt->items = array_map(function ($item) {
58:                     unset($item['unit_cost']);
59: 
60:                     return $item;
61:                 }, $receipt->items);
62:             });
63:         }
64: 
65:         return response()->json($receipts);
66:     }
67: 
68:     public function store(StoreProductionReceiptRequest $request, ProductionReceiptService $service): JsonResponse
69:     {
70:         $key = $this->idempotencyKey($request);
71:         abort_if($key === null, 422, 'مفتاح Idempotency-Key مطلوب لاستلام الإنتاج.');
72:         $receipt = $service->receive($request->validated(), $request->user()->id, $key);
73: 
74:         return response()->json(['message' => 'تم استلام الإنتاج وإضافة الكميات للمخزون.', 'data' => $receipt], 201);
75:     }
76: } 1: <?php
