  5: namespace App\Http\Controllers\Api\V1\Pos;
  6: 
  7: use App\Enums\StocktakeStatus;
  8: use App\Enums\TransferStatus;
  9: use App\Http\Controllers\Controller;
 10: use App\Http\Resources\Admin\StockLevelResource;
 11: use App\Models\Stocktake;
 12: use App\Models\StocktakeItem;
 13: use App\Models\StockLevel;
 14: use App\Models\StockTransfer;
 15: use App\Models\User;
 16: use App\Services\StocktakeService;
 17: use App\Services\TransferService;
 18: use Illuminate\Http\JsonResponse;
 19: use Illuminate\Http\Request;
 20: use Illuminate\Http\Resources\Json\AnonymousResourceCollection;
 21: use Illuminate\Validation\Rule;
 22: 
 23: /**
 24:  * عمليات المخزون من شاشة الـ POS:
 25:  * - عرض أرصدة الفرع
 26:  * - طلب تحويل بضاعة
 27:  * - تأكيد استلام تحويلة
 28:  * - مسح الباركود في جلسة الجرد
 29:  */
 30: class PosStockController extends Controller
 31: {
 32:     public function __construct(
 33:         private readonly TransferService $transfers,
 34:         private readonly StocktakeService $stocktakes,
 35:     ) {}
 36: 
 37:     /**
 38:      * GET /pos/stock — أرصدة مخزون الفرع الحالي.
 39:      */
 40:     public function index(Request $request): AnonymousResourceCollection
 41:     {
 42:         $filters = $request->validate([
 43:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 44:             'q'                  => ['nullable', 'string', 'max:100'],
 45:             'low_stock'          => ['nullable', 'boolean'],
 46:             'per_page'           => ['nullable', 'integer', 'min:1', 'max:100'],
 47:         ]);
 48: 
 49:         /** @var User $user */
 50:         $user = $request->user('staff');
 51: 
 52:         $levels = StockLevel::query()
 53:             ->where('branch_id', $user->branch_id)
 54:             ->with(['variant.product', 'location'])
 55:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 56:             ->when($filters['q'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) =>
 57:                 $vq->where('sku', $v)
 58:                     ->orWhere('barcode', $v)
 59:                     ->orWhereHas('product', fn ($pq) => $pq->whereRaw('LOWER(name) LIKE ?', ['%'.mb_strtolower($v).'%']))
 60:             ))
 61:             ->when($filters['low_stock'] ?? null, fn ($q) => $q
 62:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 63:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)')
 64:                 ->whereRaw('COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0) > 0')
 65:                 ->select('stock_levels.*')
 66:             )
 67:             ->orderBy('product_variant_id')
 68:             ->paginate($filters['per_page'] ?? 15);
 69: 
 70:         return StockLevelResource::collection($levels);
 71:     }
 72: 
 73:     /**
 74:      * POST /pos/transfer-requests — طلب تحويل بضاعة إلى الفرع الحالي.
 75:      */
 76:     public function requestTransfer(Request $request): JsonResponse
 77:     {
 78:         /** @var User $user */
 79:         $user = $request->user('staff');
 80: 
 81:         $data = $request->validate([
 82:             'from_branch_id' => ['required', 'integer', 'min:1', 'different:to_branch_id'],
 83:             'items'          => ['required', 'array', 'min:1', 'max:100'],
 84:             'items.*.product_variant_id' => ['required', 'integer', 'min:1'],
 85:             'items.*.requested_qty'      => ['required', 'numeric', 'min:0.0001'],
 86:             'notes'          => ['nullable', 'string', 'max:500'],
 87:         ]);
 88: 
 89:         $data['to_branch_id'] = $user->branch_id;
 90: 
 91:         $transfer = $this->transfers->create($data, $user->id);
 92: 
 93:         return response()->json([
 94:             'message'         => 'تم إرسال طلب التحويل بنجاح وهو في انتظار الاعتماد.',
 95:             'transfer_number' => $transfer->transfer_number,
 96:             'id'              => $transfer->id,
 97:         ], 201);
 98:     }
 99: 
100:     /**
101:      * POST /pos/transfers/{transfer}/receive — تأكيد استلام تحويلة واردة للفرع.
102:      */
103:     public function receiveTransfer(Request $request, StockTransfer $transfer): JsonResponse
104:     {
105:         /** @var User $user */
106:         $user = $request->user('staff');
107: 
108:         // التحقق أن الفرع المستقبل هو فرع الكاشير
109:         if ((int) $transfer->to_branch_id !== (int) $user->branch_id) {
110:             return response()->json(['message' => 'هذه التحويلة ليست موجهة لفرعك.'], 403);
111:         }
112: 
113:         $data = $request->validate([
114:             'items'                  => ['required', 'array', 'min:1'],
115:             'items.*.id'             => ['required', 'integer', 'min:1'],
116:             'items.*.received_qty'   => ['required', 'numeric', 'min:0'],
117:             'items.*.to_location_id' => ['nullable', 'integer', 'min:1'],
118:         ]);
119: 
120:         $transfer = $this->transfers->receive($transfer, $data, $user->id);
121: 
122:         return response()->json([
123:             'message' => 'تم تأكيد استلام التحويلة بنجاح وتم رفع المخزون.',
124:             'id'      => $transfer->id,
125:             'status'  => $transfer->status->value,
126:         ]);
127:     }
128: 
129:     /**
130:      * POST /pos/stocktakes/{stocktake}/scan — مسح باركود في جلسة جرد مفتوحة.
131:      *
132:      * يزيد counted_qty بمقدار 1 (أو بالكمية الممررة) للعنصر الموافق للباركود.
133:      * إذا لم يوجد العنصر في الجلسة يُنشئه.
134:      */
135:     public function scan(Request $request, Stocktake $stocktake): JsonResponse
136:     {
137:         /** @var User $user */
138:         $user = $request->user('staff');
139: 
140:         // التحقق أن جلسة الجرد تتبع الفرع الحالي
141:         if ((int) $stocktake->branch_id !== (int) $user->branch_id) {
142:             return response()->json(['message' => 'جلسة الجرد لا تتبع فرعك.'], 403);
143:         }
144: 
145:         if ($stocktake->status !== StocktakeStatus::Open) {
146:             return response()->json(['message' => 'جلسة الجرد ليست مفتوحة.'], 422);
147:         }
148: 
149:         $data = $request->validate([
150:             'barcode' => ['required', 'string', 'max:100'],
151:             'qty'     => ['nullable', 'numeric', 'min:0.0001', 'max:99999'],
152:         ]);
153: 
154:         $qty = (float) ($data['qty'] ?? 1);
155: 
156:         // البحث عن المتغير بالباركود
157:         $variant = \App\Models\ProductVariant::query()
158:             ->where('barcode', $data['barcode'])
159:             ->first();
160: 
161:         if ($variant === null) {
162:             return response()->json([
163:                 'message' => 'لم يُعثر على صنف بهذا الباركود.',
164:                 'barcode' => $data['barcode'],
165:             ], 404);
166:         }
167: 
168:         // الحصول على الرصيد الفعلي للتوثيق
169:         $stock = StockLevel::query()
170:             ->where('product_variant_id', $variant->id)
171:             ->where('branch_id', $stocktake->branch_id)
172:             ->first();
173: 
174:         // upsert عنصر الجرد
175:         $item = StocktakeItem::query()
176:             ->where('stocktake_id', $stocktake->id)
177:             ->where('product_variant_id', $variant->id)
178:             ->first();
179: 
180:         if ($item === null) {
181:             $item = StocktakeItem::create([
182:                 'stocktake_id'       => $stocktake->id,
183:                 'product_variant_id' => $variant->id,
184:                 'system_qty'         => (float) ($stock?->on_hand ?? 0),
185:                 'counted_qty'        => $qty,
186:             ]);
187:         } else {
188:             $item->increment('counted_qty', $qty);
189:             $item->refresh();
190:         }
191: 
192:         return response()->json([
193:             'message'            => 'تم تسجيل المسح بنجاح.',
194:             'product_variant_id' => $variant->id,
195:             'sku'                => $variant->sku,
196:             'counted_qty'        => $item->counted_qty,
197:             'system_qty'         => $item->system_qty,
198:         ]);
199:     }
200: } 1: <?php
