 5: namespace App\Notifications;
 6: 
 7: use App\Models\User;
 8: use Illuminate\Database\Eloquent\Collection;
 9: 
10: /**
11:  * حلّ مستلمي إشعارات الطاقم: مستخدمون نشطون يملكون أيًا من الصلاحيات
12:  * المعطاة، إضافة إلى حاملي دور Super Admin دائمًا.
13:  */
14: final class StaffRecipients
15: {
16:     /** @param list<string> $permissions */
17:     public static function withAnyPermission(array $permissions): Collection
18:     {
19:         return User::query()
20:             ->where('is_active', true)
21:             ->where(function ($query) use ($permissions): void {
22:                 $query->whereHas('roles', fn ($role) => $role->where('name', 'Super Admin'));
23:                 foreach ($permissions as $permission) {
24:                     $query->orWhereHas('permissions', fn ($perm) => $perm->where('name', $permission));
25:                 }
26:             })
27:             ->get();
28:     }
29: 
30:     /** مديرو فرع معين: نشطون مقيدون بالفرع ويملكون صلاحية المخزون أو Super Admin. */
31:     public static function branchManagers(int $branchId): Collection
32:     {
33:         return User::query()
34:             ->where('is_active', true)
35:             ->where('branch_id', $branchId)
36:             ->where(function ($query): void {
37:                 $query->whereHas('roles', fn ($role) => $role->where('name', 'Super Admin'))
38:                     ->orWhereHas('permissions', fn ($perm) => $perm->where('name', 'inventory.view'));
39:             })
40:             ->get();
41:     }
42: } 1: <?php
