16: 
17: class ProductionReceiptService
18: {
19:     public function __construct(private readonly InventoryService $inventory) {}
20: 
21:     public function receive(array $data, int $userId, string $key): ProductionReceipt
22:     {
23:         app(BranchAccess::class)->assertBranch($userId, (int) $data['branch_id']);
24:         $hash = IdempotencyFingerprint::hash($data);
25:         $existing = ProductionReceipt::where('created_by', $userId)->where('idempotency_key', $key)->first();
26:         if ($existing) {
27:             return $this->replay($existing, $hash);
28:         }
29: 
30:         try {
31:             return DB::transaction(function () use ($data, $userId, $key, $hash): ProductionReceipt {
32:                 DB::statement("SET LOCAL lock_timeout = '5s'");
33:                 $branch = Branch::whereKey($data['branch_id'])->sharedLock()->firstOrFail();
34:                 if (! $branch->is_active) {
35:                     throw new BusinessException('الفرع غير نشط.');
36:                 }
37:                 $variants = ProductVariant::whereIn('id', array_column($data['items'], 'product_variant_id'))
38:                     ->with('product:id,name_ar')->orderBy('id')->lockForUpdate()->get()->keyBy('id');
39: 
40:                 $sortedItems = collect($data['items'])->sortBy('product_variant_id')->values()->all();
41:                 $itemsWithLabels = [];
42: 
43:                 foreach ($sortedItems as $item) {
44:                     $variant = $variants->get($item['product_variant_id']);
45:                     if (! $variant || ! $variant->is_active || ! $variant->product) {
46:                         throw new BusinessException('أحد أصناف الإنتاج غير متاح.');
47:                     }
48:                     $itemsWithLabels[] = [
49:                         ...$item,
50:                         'label' => $variant->product->name_ar.' / '.$variant->sku,
51:                     ];
52:                 }
53: 
54:                 $receipt = ProductionReceipt::create([
55:                     ...$data, 'items' => $itemsWithLabels, 'created_by' => $userId, 'idempotency_key' => $key, 'request_hash' => $hash,
56:                 ]);
57: 
58:                 foreach ($sortedItems as $item) {
59:                     $variant = $variants->get($item['product_variant_id']);
60:                     $quantity = (int) $item['quantity'];
61:                     $unitCost = round((float) $item['unit_cost'], 4);
62:                     $onHand = max(0, (float) StockLevel::where('product_variant_id', $variant->id)->sum('on_hand'));
63:                     $average = (($onHand * (float) $variant->cost_price) + ($quantity * $unitCost)) / ($onHand + $quantity);
64:                     $variant->update(['cost_price' => round($average, 4), 'last_cost_price' => $unitCost]);
65:                     $this->inventory->recordMovement([
66:                         'product_variant_id' => $variant->id,
67:                         'branch_id' => (int) $data['branch_id'],
68:                         'location_id' => $data['location_id'] ?? null,
69:                         'type' => StockMovementType::ProductionReceipt,
70:                         'affected_bucket' => StockBucket::OnHand,
71:                         'quantity' => $quantity, 'unit_cost' => $unitCost,
72:                         'reference_type' => ProductionReceipt::class, 'reference_id' => $receipt->id,
73:                         'created_by' => $userId, 'notes' => $data['notes'] ?? null,
74:                     ]);
75:                 }
76: 
77:                 return $receipt;
78:             }, 3);
79:         } catch (UniqueConstraintViolationException $exception) {
80:             $existing = ProductionReceipt::where('created_by', $userId)->where('idempotency_key', $key)->first();
81:             if ($existing) {
82:                 return $this->replay($existing, $hash);
83:             }
84:             if (ProductionReceipt::where('batch_number', $data['batch_number'])->exists()) {
85:                 throw new BusinessException('رقم دفعة الإنتاج مسجل بالفعل؛ راجع سجل الاستلام.', [], 409);
86:             }
87:             throw $exception;
88:         }
89:     }
90: 
91:     private function replay(ProductionReceipt $receipt, string $hash): ProductionReceipt
92:     {
93:         if (! hash_equals($receipt->request_hash, $hash)) {
94:             throw new BusinessException('مفتاح الطلب مستخدم مع بيانات مختلفة.', [], 409);
95:         }
96: 
97:         return $receipt;
98:     }
99: }  1: <?php
