 45:     public function test_first_movements_create_exactly_one_stock_row_under_concurrency(): void
 46:     {
 47:         $variant = ProductVariant::factory()->create();
 48:         $branch = Branch::factory()->create();
 49:         $data = $this->data($variant, $branch);
 50:         $operation = 'app(App\Services\InventoryService::class)->recordMovement('.var_export($data, true).');';
 51:         $this->race([$operation, $operation]);
 52:         $this->assertSame(1, StockLevel::count());
 53:         $this->assertSame('2.0000', StockLevel::firstOrFail()->on_hand);
 54:         $this->assertSame(2, StockMovement::distinct()->count('reference_number'));
 55:     }
 56: 
 57:     public function test_opposite_multi_item_orders_do_not_deadlock(): void
 58:     {
 59:         $variants = ProductVariant::factory()->count(2)->create();
 60:         $branch = Branch::factory()->create();
 61:         $items = $variants->map(fn ($variant) => ['product_variant_id' => $variant->id, 'quantity' => 1, 'adjustment_type' => 'increase'])->all();
 62:         $jobs = [];
 63:         foreach ([$items, array_reverse($items)] as $order) {
 64:             $jobs[] = 'app(App\Services\InventoryService::class)->applyAdjustments('.var_export(['branch_id' => $branch->id, 'items' => $order], true).', '.$this->staff->id.');';
 65:         }
 66:         $this->race($jobs);
 67:         $this->assertSame(['2.0000', '2.0000'], StockLevel::orderBy('product_variant_id')->pluck('on_hand')->all());
 68:     }
