210:     private function race(array $jobs, array $expected = ['OK', 'OK']): void
211:     {
212:         $barrier = tempnam(sys_get_temp_dir(), 'inventory-race-');
213:         unlink($barrier);
214:         $db = config('database.connections.pgsql');
215:         $environment = ['APP_ENV' => 'testing', 'DB_CONNECTION' => 'pgsql', 'DB_DATABASE' => $db['database'],
216:             'DB_HOST' => $db['host'], 'DB_PORT' => (string) $db['port'], 'DB_USERNAME' => $db['username'],
217:             'DB_PASSWORD' => $db['password'], 'DB_URL' => '', 'CACHE_STORE' => 'array', 'QUEUE_CONNECTION' => 'sync',
218:             'INVENTORY_START_FILE' => $barrier];
219:         $processes = [];
220:         try {
221:             foreach ($jobs as $operation) {
222:                 $script = <<<'PHP'
223: require 'vendor/autoload.php';
224: $app = require 'bootstrap/app.php';
225: $app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
226: Illuminate\Support\Facades\DB::statement("SET lock_timeout = '7s'");
227: echo "READY\n";
228: $deadline = microtime(true) + 12;
229: while (!is_file(getenv('INVENTORY_START_FILE'))) {
230:     if (microtime(true) > $deadline) { exit(4); }
231:     usleep(10000);
232: }
233: try {
234: PHP;
235:                 $script .= $operation;
236:                 $script .= <<<'PHP'
237: echo "OK\n";
238: } catch (App\Exceptions\BusinessException $exception) {
239:     echo "REJECTED\n";
240: } catch (Throwable $exception) {
241:     fwrite(STDERR, get_class($exception).': '.$exception->getMessage());
242:     exit(3);
243: }
244: PHP;
245:                 $process = new Process([PHP_BINARY, '-r', $script], base_path(), $environment, timeout: 15);
246:                 $process->start();
247:                 $processes[] = $process;
248:             }
249:             foreach ($processes as $process) {
250:                 $this->assertTrue($process->waitUntil(fn ($type, $output) => str_contains($output, 'READY')), $process->getErrorOutput());
251:             }
252:             touch($barrier);
253:             $results = [];
254:             foreach ($processes as $process) {
255:                 $process->wait();
256:                 $this->assertTrue($process->isSuccessful(), $process->getErrorOutput());
257:                 $results[] = trim(str_replace('READY', '', $process->getOutput()));
258:             }
259:             $this->assertEqualsCanonicalizing($expected, $results);
260:         } finally {
261:             foreach ($processes as $process) {
262:                 if ($process->isRunning()) {
263:                     $process->stop();
264:                 }
265:             }
266:             foreach ([$barrier, $barrier.'.left', $barrier.'.right'] as $path) {
267:                 if (is_file($path)) {
268:                     unlink($path);
269:                 }
270:             }
271:         }
272:     }
