19: // Backend error contract (verified in code, do not assume otherwise):
20: // - BusinessException (app/Exceptions/BusinessException.php) renders 422 by default
21: //   as { message, errors, code? }. Business-rule failures (insufficient stock,
22: //   disabled variant/location and stale stocktake) come back this way.
23: //   Production's missing key also returns 422 via abort(), with { message }.
24: //   `errors` doubles as the extra-data channel: the stale
25: //   stocktake rejection carries { recount_item_ids, recount_variant_ids } there.
26: // - BusinessException can explicitly override its default to 409; those errors
27: //   retain { message, errors, code? }. HandlesIdempotentCreation rejects changed
28: //   transfer/stocktake payloads with the same key using this override.
29: // - 409 means "conflict, reload then retry with a fresh read":
30: //   version conflict ('تم تعديل التحويل؛ أعد تحميله…'), lock timeout/deadlock
31: //   ('المخزون مشغول بعملية أخرى…', retry with the SAME Idempotency-Key),
32: //   delete-blocked branch/location ('لا يمكن حذف الفرع/الموقع لارتباطه…'),
33: //   unique-constraint races. The only 409 that must NOT auto-retry is
34: //   'مفتاح عدم التكرار … مستخدم (مسبقًا) مع بيانات مختلفة' — the payload changed.
35: // - 404 with { message: 'العنصر المطلوب غير موجود' } (ModelNotFound via
36: //   bootstrap/app.php). 401 is handled by the axios interceptor — screens do
37: //   nothing. Server messages are Arabic: render them verbatim, never translate
38: //   or replace with a generic string.
39: export function normalizeError(e: unknown): ApiError {
40:   const err = e as { response?: { status?: unknown; data?: unknown }; message?: unknown } | null | undefined;
41:   const status = typeof err?.response?.status === 'number' ? err.response.status : 0;
42:   const data = (err?.response?.data ?? {}) as RawErrorBody;
43:   const raw: Record<string, unknown> = data.errors && typeof data.errors === 'object' ? data.errors : {};
44: 
45:   const fields: Record<string, string[]> = {};
46:   Object.entries(raw).forEach(([k, v]) => {
47:     if (k === 'status') return;
48:     fields[k] = toStringList(v);
49:   });
50: 
51:   const summary = raw.status === undefined ? [] : toStringList(raw.status);
52:   const message = typeof data.message === 'string' && data.message !== ''
53:     ? data.message
54:     : e instanceof Error && !err?.response && !('request' in e)
55:       ? e.message
56:       : status === 0
57:       ? 'تعذّر الاتصال بالخادم، تأكد من الإنترنت وحاول تاني'
58:       : 'حدث خطأ غير متوقع، حاول تاني';
59: 
60:   return { status, message, fields, summary };
61: }  1: import React, { useRef, useState } from 'react';
