 11: // الملف الوحيد اللي يعرف الشكلين: شكل الـ UI (الـ mock) وشكل الـ API (قراءة وكتابة).
 12: //
 13: // ملاحظة على شكل الـ VariantResource الحقيقي:
 14: // - اللون بيرجع nested تحت `color: { name_ar, name_en, hex }` مش flat.
 15: // - صور المتغير بترجع تحت مفتاح `images` (MediaResource) مش `media`.
 16: // الدوال هنا بتقبل الشكلين وبتوحّدهم على الـ flat/admin types.
 17: 
 18: export interface UiColor { ar: string; en: string; hex: string }
 19: 
 20: export interface UiVariantRow {
 21:   _id: string;
 22:   serverId?: number;                    // ضيفه علشان تعرف ده update ولا create
 23:   color: UiColor | null;
 24:   size: string; capacity: string;
 25:   sku: string; barcode: string;
 26:   retail: string; wholesale: string; cost: string; compare: string;
 27:   weight: string; reorder: string;
 28:   order: number;                        // 1-based زي الـ mock
 29:   status: 'active' | 'inactive';
 30: }
 31: 
 32: export interface UiBasic {
 33:   ar: string; en: string;
 34:   category: number | null; brand: number | null;
 35:   channel: 'retail' | 'wholesale' | 'both';
 36:   slug: string;
 37:   desc_ar: string; desc_en: string;
 38:   mat_ar: string; mat_en: string;
 39:   l: string; w: string; h: string;
 40:   kg: string; warranty: string; warranty_details: string;
 41:   origin: string; featured: boolean; supplier: number | null;
 42: }
 43: 
 44: export type UiMediaStatus = 'pending' | 'uploading' | 'done' | 'failed';
 45: 
 46: export interface UiMediaItem {
 47:   id: string; serverId?: number;
 48:   variantId?: number;
 49:   name: string; size?: string;
 50:   status: UiMediaStatus; url?: string;
 51:   pct?: number; message?: string;
 52: }
 53: 
 54: export interface UiProductState {
 55:   status: ProductStatus | null; code: string | null;
 56:   basic: UiBasic;
 57:   mode: 'single' | 'matrix';
 58:   axes: { colors: UiColor[]; sizes: string[]; capacities: string[] };
 59:   rows: UiVariantRow[];
 60:   media: { general: UiMediaItem[]; byVariant: Record<string, UiMediaItem[]>; video: UiMediaItem | null };
 61: }
 62: 
 63: export interface UiBrand {
 64:   id?: number;
 65:   ar: string; en: string; slug: string;
 66:   desc_ar: string; desc_en: string;
 67:   order: number; status: 'active' | 'inactive';
 68:   logo: string | null;                  // رابط المعاينة
 69:   products?: number;
 70: }
 71: 
 72: export interface UiBrandForm extends Omit<UiBrand, 'id' | 'logo' | 'products'> {
 73:   logoFile?: File | null;
 74:   removeLogo?: boolean;
 75: }
 76: 
 77: let seq = 0;
 78: function uid(): string {
 79:   seq += 1;
 80:   return `row-${Date.now().toString(36)}-${seq}`;
 81: }
 82: 
 83: function str(v: unknown): string {
 84:   if (v === null || v === undefined) return '';
 85:   return String(v);
 86: }
 87: 
 88: function nullIfEmpty(v: string): string | null {
 89:   const t = v.trim();
 90:   return t === '' ? null : v;
 91: }
