 93: // ---------- البراند ----------
 94: 
 95: export function brandFromApi(b: AdminBrand): UiBrand {
 96:   return {
 97:     id: b.id,
 98:     ar: b.name_ar, en: b.name_en, slug: b.slug,
 99:     desc_ar: b.description_ar ?? '', desc_en: b.description_en ?? '',
100:     order: b.sort_order,
101:     status: b.is_active ? 'active' : 'inactive',
102:     logo: b.logo_url,
103:     products: b.products_count,
104:   };
105: }
106: 
107: export function brandToPayload(u: UiBrandForm): BrandPayload {
108:   const p: BrandPayload = {
109:     name_ar: u.ar,
110:     name_en: u.en,
111:     slug: u.slug.trim() === '' ? null : u.slug,   // فاضي = null والسيرفر يولّده
112:     description_ar: u.desc_ar,
113:     description_en: u.desc_en,
114:     sort_order: u.order,
115:     is_active: u.status === 'active',
116:   };
117:   if (u.logoFile) p.logo = u.logoFile;
118:   else if (u.removeLogo) p.remove_logo = true;    // شال اللوجو من غير رفع جديد
119:   return p;                                       // من غير لوجو جديد ماتبعتش logo خالص
120: }
