309: export const VARIANT_SERVER_KEY_TO_UI: Record<string, string> = {
310:   retail_price: 'retail',
311:   wholesale_price: 'wholesale',
312:   cost_price: 'cost',
313:   compare_at_price: 'compare',
314:   color_name_en: 'color',
315:   color_name_ar: 'color',
316:   color_hex: 'color',
317:   size: 'size',
318:   capacity: 'capacity',
319:   sku: 'sku',
320:   barcode: 'barcode',
321:   reorder_level: 'reorder',
322:   weight_kg: 'weight',
323:   sort_order: 'order',
324:   is_active: 'status',
325: };
