327: export function splitVariantErrorKey(serverKey: string): { index: number; uiField: string } | null {
328:   const m = /^variants\.(\d+)\.(.+)$/.exec(serverKey);
329:   if (!m) return null;
330:   const field = m[2];
331:   return { index: Number(m[1]), uiField: VARIANT_SERVER_KEY_TO_UI[field] ?? field };
332: }
