 265:   text-indent: 0; /* 1 */
 266:   border-color: inherit; /* 2 */
 267:   border-collapse: collapse; /* 3 */
 268: }
 269: 
 270: /*
 271: 1. Change the font styles in all browsers.
 272: 2. Remove the margin in Firefox and Safari.
 273: 3. Remove default padding in all browsers.
 274: */
 275: 
 276: button,
 277: input,
 278: optgroup,
 279: select,
 280: textarea {
 281:   font-family: inherit; /* 1 */
 282:   font-feature-settings: inherit; /* 1 */
 283:   font-variation-settings: inherit; /* 1 */
 284:   font-size: 100%; /* 1 */
 285:   font-weight: inherit; /* 1 */
 286:   line-height: inherit; /* 1 */
 287:   letter-spacing: inherit; /* 1 */
 288:   color: inherit; /* 1 */
 289:   margin: 0; /* 2 */
 290:   padding: 0; /* 3 */
 291: }
 292: 
 293: /*
 294: Remove the inheritance of text transform in Edge and Firefox.
 295: */
 296: 
 297: button,
 298: select {
 299:   text-transform: none;
 300: }
 301: 
 302: /*
 303: 1. Correct the inability to style clickable types in iOS and Safari.
 304: 2. Remove default button styles.
 305: */
 306: 
 307: button,
 308: input:where([type='button']),
 309: input:where([type='reset']),
 310: input:where([type='submit']) {
 311:   -webkit-appearance: button; /* 1 */
 312:   background-color: transparent; /* 2 */
 313:   background-image: none; /* 2 */
 314: }
 315: 
 316: /*
 317: Use the modern Firefox focus style for all focusable elements.
 318: */
 319: 
 320: :-moz-focusring {
 321:   outline: auto;
 322: }
 323: 
 324: /*
 325: Remove the additional \`:invalid\` styles in Firefox. (https://github.com/mozilla/gecko-dev/blob/2f9eacd9d3d995c937b4251a5557d95d494c9be1/layout/style/res/forms.css#L728-L737)
 326: */
 327: 
 328: :-moz-ui-invalid {
 329:   box-shadow: none;
 330: }
 331: 
 332: /*
 333: Add the correct vertical alignment in Chrome and Firefox.
 334: */
 335: 
 336: progress {
 337:   vertical-align: baseline;
 338: }
 339: 
 340: /*
 341: Correct the cursor style of increment and decrement buttons in Safari.
 342: */
 343: 
 344: ::-webkit-inner-spin-button,
 345: ::-webkit-outer-spin-button {
 346:   height: auto;
 347: }
 348: 
 349: /*
 350: 1. Correct the odd appearance in Chrome and Safari.
 351: 2. Correct the outline style in Safari.
 352: */
 353: 
 354: [type='search'] {
 355:   -webkit-appearance: textfield; /* 1 */
 356:   outline-offset: -2px; /* 2 */
 357: }
 358: 
 359: /*
 360: Remove the inner padding in Chrome and Safari on macOS.
 361: */
 362: 
 363: ::-webkit-search-decoration {
 364:   -webkit-appearance: none;
 365: }
 366: 
 367: /*
 368: 1. Correct the inability to style clickable types in iOS and Safari.
 369: 2. Change font properties to \`inherit\` in Safari.
 370: */
 371: 
 372: ::-webkit-file-upload-button {
 373:   -webkit-appearance: button; /* 1 */
 374:   font: inherit; /* 2 */
 375: }
 376: 
 377: /*
 378: Add the correct display in Chrome and Safari.
 379: */
 380: 
 381: summary {
 382:   display: list-item;
 383: }
 384: 
 385: /*
 386: Removes the default spacing and border for appropriate elements.
 387: */
 388: 
 389: blockquote,
 390: dl,
 391: dd,
 392: h1,
 393: h2,
 394: h3,
 395: h4,
 396: h5,
 397: h6,
 398: hr,
 399: figure,
 400: p,
 401: pre {
 402:   margin: 0;
 403: }
 404: 
 405: fieldset {
 406:   margin: 0;
 407:   padding: 0;
 408: }
 409: 
 410: legend {
 411:   padding: 0;
 412: }
 413: 
 414: ol,
 415: ul,
 416: menu {
 417:   list-style: none;
 418:   margin: 0;
 419:   padding: 0;
 420: }
 421: 
 422: /*
 423: Reset default styling for dialogs.
 424: */
 425: dialog {
 426:   padding: 0;
 427: }
 428: 
 429: /*
 430: Prevent resizing textareas horizontally by default.
 431: */
 432: 
 433: textarea {
 434:   resize: vertical;
 435: }
 436: 
 437: /*
 438: 1. Reset the default placeholder opacity in Firefox. (https://github.com/tailwindlabs/tailwindcss/issues/3300)
 439: 2. Set the default placeholder color to the user's configured gray 400 color.
 440: */
 441: 
 442: input::placeholder,
 443: textarea::placeholder {
 444:   opacity: 1; /* 1 */
 445:   color: #9ca3af; /* 2 */
 446: }
 447: 
 448: /*
 449: Set the default cursor for buttons.
 450: */
 451: 
 452: button,
 453: [role="button"] {
 454:   cursor: pointer;
 455: }
 456: 
 457: /*
 458: Make sure disabled buttons don't get the pointer cursor.
 459: */
 460: :disabled {
 461:   cursor: default;
 462: }
 463: 
 464: /*
 465: 1. Make replaced elements \`display: block\` by default. (https://github.com/mozdevs/cssremedy/issues/14)
 466: 2. Add \`vertical-align: middle\` to align replaced elements more sensibly by default. (https://github.com/jensimmons/cssremedy/issues/14#issuecomment-634934210)
 467:    This can trigger a poorly considered lint error in some tools but is included by design.
 468: */
 469: 
 470: img,
 471: svg,
 472: video,
 473: canvas,
 474: audio,
 475: iframe,
 476: embed,
 477: object {
 478:   display: block; /* 1 */
 479:   vertical-align: middle; /* 2 */
 480: }
 481: 
 482: /*
 483: Constrain images and videos to the parent width and preserve their intrinsic aspect ratio. (https://github.com/mozdevs/cssremedy/issues/14)
 484: */
 485: 
 486: img,
 487: video {
 488:   max-width: 100%;
 489:   height: auto;
 490: }
 491: 
 492: /* Make elements with the HTML hidden attribute stay hidden by default */
 493: [hidden]:where(:not([hidden="until-found"])) {
 494:   display: none;
 495: }
