 5: export function hasPermission(
 6:   userPermissions: string[] | null | undefined,
 7:   requiredPermission: string
 8: ): boolean {
 9:   if (!userPermissions || !Array.isArray(userPermissions)) {
10:     return false;
11:   }
12: 
13:   if (userPermissions.includes('*') || userPermissions.includes('super_admin')) {
14:     return true;
15:   }
16: 
17:   if (userPermissions.includes(requiredPermission)) {
18:     return true;
19:   }
20: 
21:   const [module] = requiredPermission.split('.');
22:   if (module && userPermissions.includes(`${module}.*`)) {
23:     return true;
24:   }
25: 
26:   return false;
27: }
28: 
29: export function hasAnyPermission(
30:   userPermissions: string[] | null | undefined,
31:   requiredPermissions: string[]
32: ): boolean {
33:   return requiredPermissions.some((perm) => hasPermission(userPermissions, perm));
34: }
35: 
36: export function hasAllPermissions(
37:   userPermissions: string[] | null | undefined,
38:   requiredPermissions: string[]
39: ): boolean {
40:   return requiredPermissions.every((perm) => hasPermission(userPermissions, perm));
