10: 
11: /**
12:  * مطابقة دورية بين الدفتر والأرصدة (M-8): القاعدة تضمن صحة كل حركة على حدة،
13:  * لكن أي كتابة مباشرة على stock_levels (والـ fillable يسمح بها) لا يكشفها
14:  * شيء آخر. الفحص يتحقق لكل وعاء من أمرين:
15:  * 1. رصيد stock_levels يساوي آخر balance_after في الدفتر لنفس الوعاء.
16:  * 2. تسلسل الدفتر متصل: balance_before لكل حركة يساوي balance_after لسابقتها.
17:  * يُشغَّل دوريًا (جدولة ليلية) ويُرجع كود فشل عند وجود أي فرق للتنبيه.
18:  */
19: class ReconcileInventory extends Command
20: {
21:     protected $signature = 'inventory:reconcile {--branch_id= : قصر الفحص على فرع واحد}';
22: 
23:     protected $description = 'مطابقة أرصدة المخزون مع دفتر الحركات وكشف أي كتابة مباشرة';
24: 
25:     public function handle(): int
26:     {
27:         $branch = $this->option('branch_id');
28:         if ($branch !== null && filter_var($branch, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) === false) {
29:             $this->error('branch_id يجب أن يكون عددًا صحيحًا موجبًا.');
30: 
31:             return self::INVALID;
32:         }
33: 
34:         // One SQL statement sees one committed snapshot, even while sales continue.
35:         // Window functions also catch broken chains and movements without a stock row.
36:         $result = DB::selectOne(<<<'SQL'
37: WITH levels AS (
38:     SELECT * FROM stock_levels WHERE (?::bigint IS NULL OR branch_id = ?::bigint)
39: ), ledger AS (
40:     SELECT *,
41:         LAG(balance_after, 1, 0::numeric) OVER (
42:             PARTITION BY branch_id, location_id, product_variant_id, affected_bucket ORDER BY id
43:         ) AS previous_balance,
44:         ROW_NUMBER() OVER (
45:             PARTITION BY branch_id, location_id, product_variant_id, affected_bucket ORDER BY id DESC
46:         ) AS recency
47:     FROM stock_movements WHERE (?::bigint IS NULL OR branch_id = ?::bigint)
48: ), buckets AS (
49:     SELECT l.id, l.branch_id, l.location_id, l.product_variant_id, b.bucket, b.balance
50:     FROM levels l CROSS JOIN LATERAL (VALUES
51:         ('on_hand', l.on_hand), ('reserved', l.reserved),
52:         ('damaged', l.damaged), ('in_transit', l.in_transit)
53:     ) b(bucket, balance)
54: ), problems AS (
55:     SELECT 'chain' AS issue, id, branch_id, location_id, product_variant_id, affected_bucket AS bucket,
56:         previous_balance AS expected, balance_before AS actual
57:     FROM ledger WHERE balance_before <> previous_balance
58:     UNION ALL
59:     SELECT 'balance', b.id, b.branch_id, b.location_id, b.product_variant_id, b.bucket,
60:         COALESCE(m.balance_after, 0), b.balance
61:     FROM buckets b LEFT JOIN ledger m ON m.recency = 1
62:         AND m.branch_id = b.branch_id AND m.product_variant_id = b.product_variant_id
63:         AND m.location_id IS NOT DISTINCT FROM b.location_id AND m.affected_bucket = b.bucket
64:     WHERE b.balance <> COALESCE(m.balance_after, 0)
65:     UNION ALL
66:     SELECT 'missing_level', m.id, m.branch_id, m.location_id, m.product_variant_id,
67:         m.affected_bucket, m.balance_after, NULL::numeric
68:     FROM ledger m LEFT JOIN levels l ON l.branch_id = m.branch_id
69:         AND l.product_variant_id = m.product_variant_id AND l.location_id IS NOT DISTINCT FROM m.location_id
70:     WHERE m.recency = 1 AND l.id IS NULL
71: )
72: SELECT (SELECT COUNT(*) FROM levels) AS checked, (SELECT COUNT(*) FROM problems) AS problem_count,
73:     COALESCE((SELECT json_agg(p) FROM (SELECT * FROM problems ORDER BY branch_id, product_variant_id, id LIMIT 100) p), '[]'::json) AS samples
74: SQL, [$branch, $branch, $branch, $branch]);
75: 
76:         if ((int) $result->problem_count > 0) {
77:             $samples = json_decode($result->samples, true, flags: JSON_THROW_ON_ERROR);
78:             foreach ($samples as $problem) {
79:                 $this->error(json_encode($problem, JSON_UNESCAPED_UNICODE | JSON_THROW_ON_ERROR));
80:             }
81:             Log::error('Inventory reconciliation failed', ['problem_count' => (int) $result->problem_count, 'samples' => $samples]);
82:             $this->error("المطابقة فشلت: {$result->problem_count} فرق في {$result->checked} صف رصيد.");
83: 
84:             return self::FAILURE;
85:         }
86: 
87:         $this->info("المطابقة سليمة: {$result->checked} صف رصيد مطابق للدفتر.");
88: 
89:         return self::SUCCESS;
90:     }
