 58:                 ->join('product_variants', 'product_variants.id', '=', 'stock_levels.product_variant_id')
 59:                 ->whereRaw('stock_levels.available <= COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0)')
 60:                 // صف بلا حد إعادة طلب فعّال ليس "منخفضًا": صفوف صفرية ينشئها
 61:                 // lockLevels كأثر جانبي كانت تملأ الفلتر وهميًا (L-4).
 62:                 ->whereRaw('COALESCE(NULLIF(stock_levels.reorder_level, 0), product_variants.reorder_level, 0) > 0')
 63:                 ->select('stock_levels.*'))
 64:             ->orderBy('branch_id')
 65:             ->orderBy('product_variant_id')
 66:             ->orderBy('id')
 67:             ->paginate($filters['per_page'] ?? 15);
 68: 
 69:         return StockLevelResource::collection($levels);
 70:     }
 71: 
 72:     /** سجل حركات دفتر الأستاذ من الأحدث للأقدم مع الفلاتر. */
 73:     public function movements(Request $request): AnonymousResourceCollection
 74:     {
 75:         $filters = $request->validate([
 76:             'branch_id' => ['nullable', 'integer', 'min:1'],
 77:             'location_id' => ['nullable', 'integer', 'min:1'],
 78:             'product_id' => ['nullable', 'integer', 'min:1'],
 79:             'product_variant_id' => ['nullable', 'integer', 'min:1'],
 80:             'type' => ['nullable', Rule::in(array_column(StockMovementType::cases(), 'value'))],
 81:             'from_date' => ['nullable', 'date_format:Y-m-d'],
 82:             'to_date' => ['nullable', 'date_format:Y-m-d', Rule::when($request->filled('from_date'), 'after_or_equal:from_date')],
 83:             'per_page' => ['nullable', 'integer', 'min:1', 'max:100'],
 84:         ]);
 85: 
 86:         $movements = StockMovement::query()
 87:             ->when(app(BranchAccess::class)->restrictedBranch($request->user()), fn ($q, $branch) => $q->where('branch_id', $branch))
 88:             ->with(['variant', 'branch', 'location', 'creator'])
 89:             ->when($filters['branch_id'] ?? null, fn ($q, $v) => $q->where('branch_id', $v))
 90:             ->when($filters['location_id'] ?? null, fn ($q, $v) => $q->where('location_id', $v))
 91:             ->when($filters['product_variant_id'] ?? null, fn ($q, $v) => $q->where('product_variant_id', $v))
 92:             ->when($filters['product_id'] ?? null, fn ($q, $v) => $q->whereHas('variant', fn ($vq) => $vq->where('product_id', $v)))
 93:             ->when($filters['type'] ?? null, fn ($q, $v) => $q->where('type', $v))
 94:             // حدود الأيام بأيام العمل (business_timezone) لا UTC، والتخزين يظل UTC
 95:             ->when($filters['from_date'] ?? null, fn ($q, $v) => $q->where('created_at', '>=', Carbon::parse($v, config('app.business_timezone'))->startOfDay()->utc()))
 96:             ->when($filters['to_date'] ?? null, fn ($q, $v) => $q->where('created_at', '<', Carbon::parse($v, config('app.business_timezone'))->addDay()->startOfDay()->utc()))
 97:             ->orderByDesc('id')
 98:             // الدفتر append-only وسيكبر لملايين الصفوف: بلا COUNT(*) وبلا OFFSET —
 99:             // ترقيم بالمؤشر على (branch_id, id DESC) يجعل الصفحات العميقة بنفس
100:             // تكلفة الأولى (M-7). المقايضة: لا قفز لرقم صفحة محدد.
101:             ->cursorPaginate($filters['per_page'] ?? 15);
102: 
103:         return StockMovementResource::collection($movements);
104:     }
