 85:     public function changeStatus(Product $product, ProductStatus $status, User $user): void
 86:     {
 87:         DB::transaction(function () use ($product, $status, $user): void {
 88:             CatalogLock::tree(shared: true);
 89:             // قفل صف المنتج وقسمه قبل الفحص والنشر، عشان مفيش تعديل متزامن يعدي بين الفحص والحفظ
 90:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
 91:             if ($product->category_id) {
 92:                 $this->lockReference(Category::class, (int) $product->category_id, 'category_id');
 93:             }
 94:             $product->refresh();
 95: 
 96:             if ($product->status !== $status && ($product->status === ProductStatus::Published || $status === ProductStatus::Published) && ! $user->can('products.publish')) {
 97:                 throw new BusinessException('ليس لديك صلاحية تغيير نشر المنتجات', [], 403);
 98:             }
 99: 
100:             if ($status === ProductStatus::Published) {
101:                 $this->assertPublishable($product);
102:                 $product->published_at ??= now();
103:             }
104:             $product->status = $status;
105:             $product->save();
106:         });
107:         $product->refresh();
108:     }
