124:         DB::transaction(function () use ($product): void {
125:             $product = Product::whereKey($product->id)->lockForUpdate()->firstOrFail();
126:             // حذف المنتج يحذف متغيراته ناعمًا: أي رصيد على أي منها يُحبس (M-9)
127:             if (StockLevel::query()->whereIn('product_variant_id', $product->variants()->pluck('id'))->hasNonZeroBalance()->exists()) {
128:                 throw new BusinessException('لا يمكن حذف منتج له متغيرات برصيد مخزون؛ صفِّ الأرصدة أولًا.');
129:             }
130:             $product->variants()->delete();  // soft
131:             $product->delete();              // soft
132:         });
