220:     /** تصدير عناصر القائمة كـ CSV بنفس أعمدة الاستيراد عشان إعادة الاستيراد تشتغل. */
221:     public function exportCsv(PriceList $priceList, ?User $user = null): StreamedResponse
222:     {
223:         $this->assertListAccess($user, $priceList);
224: 
225:         return response()->streamDownload(function () use ($priceList): void {
226:             $handle = fopen('php://output', 'w');
227:             try {
228:                 // escape: '' — آلية الهروب الخاصة بـ PHP تكسر الحقول المنتهية بشرطة
229:                 // مائلة ومُهملة في PHP 8.4 (L-5).
230:                 fputcsv($handle, ['sku', 'variant_id', 'product_name', 'min_qty', 'price', 'starts_at', 'ends_at'], escape: '');
231: 
232:                 $priceList->items()
233:                     ->with(['variant.product' => fn ($query) => $query->withTrashed()])
234:                     ->chunkById(500, function ($items) use ($handle): void {
235:                         foreach ($items as $item) {
236:                             fputcsv($handle, [
237:                                 $this->csvText($item->variant?->sku ?? ''),
238:                                 $item->product_variant_id,
239:                                 $this->csvText($item->variant?->product?->name_ar ?? ''),
240:                                 $item->min_qty,
241:                                 $item->price,
242:                                 $item->starts_at?->toIso8601String(),
243:                                 $item->ends_at?->toIso8601String(),
244:                             ], escape: '');
245:                         }
246:                     });
247: 
248:             } catch (\Throwable $e) {
249:                 // فشل في منتصف البث يترك ملفًا مبتورًا عند العميل بحالة 200؛
250:                 // لا يمكن التراجع، لكن الفشل لازم يتسجل (L-5).
251:                 Log::error('فشل تصدير قائمة أسعار أثناء البث', [
252:                     'price_list_id' => $priceList->id,
253:                     'exception' => $e->getMessage(),
254:                 ]);
255: 
256:                 throw $e;
257:             } finally {
258:                 fclose($handle);
259:             }
260:         }, 'price-list-'.$priceList->id.'.csv', [
261:             'Content-Type' => 'text/csv; charset=UTF-8',
262:             'X-Row-Count' => (string) $priceList->items()->count(),
263:         ]);
264:     }
