266:     private function csvText(string $value): string
267:     {
268:         return preg_match('/^[\s]*[=+@\-\t\r\n]/u', $value) ? "'".$value : $value;
269:     }
270: 
271:     /**
272:      * استيراد CSV: كل صف بيحدّث أو ينشئ عنصرًا بمفتاح (القائمة، المتغير، min_qty)
273:      * داخل transaction واحدة. أخطاء الصفوف الفردية بتتجمع في التقرير من غير ما توقف الكل.
274:      *
275:      * @return array{created: int, updated: int, skipped: int, errors: list<array{line: int, message: string}>}
276:      */
277:     public function importCsv(PriceList $priceList, UploadedFile $file, ?User $user = null): array
278:     {
279:         $this->assertListAccess($user, $priceList);
280:         $handle = fopen($file->getRealPath(), 'r');
281:         if ($handle === false) {
282:             throw new BusinessException('تعذرت قراءة ملف الاستيراد.');
283:         }
284:         try {
285:             $header = fgetcsv($handle, escape: '');
286:             if ($header === false) {
287:                 throw new BusinessException('ملف الاستيراد فارغ.');
288:             }
289:             $header[0] = preg_replace('/^\xEF\xBB\xBF/', '', (string) $header[0]);
290:             $columns = array_map(fn ($h) => strtolower(trim((string) $h)), $header);
291:             $index = array_flip($columns);
292:             if (count($index) !== count($columns) || ! isset($index['price']) || (! isset($index['variant_id']) && ! isset($index['sku']))) {
293:                 throw new BusinessException('يجب أن يحتوي الملف على price وsku أو variant_id، دون أعمدة مكررة.');
294:             }
295:             $rows = [];
296:             $line = 1;
297:             while (($row = fgetcsv($handle, escape: '')) !== false) {
298:                 $line++;
299:                 if ($line > 10000) {
300:                     throw new BusinessException('عدد أسطر الملف يتجاوز الحد المسموح.');
301:                 }
302:                 if ($row === [null] || trim(implode('', array_map('strval', $row))) === '') {
303:                     continue;
304:                 }
305:                 if (count($rows) >= 2000) {
306:                     throw new BusinessException('الحد الأقصى للاستيراد المتزامن 2000 صف؛ قسّم الملف إلى أجزاء أصغر.');
307:                 }
308:                 $get = fn (string $key) => isset($index[$key]) ? trim((string) ($row[$index[$key]] ?? '')) : '';
309:                 $rows[] = ['line' => $line, 'variant_id' => $get('variant_id'), 'sku' => $get('sku'),
310:                     'price' => $get('price'), 'min_qty' => $get('min_qty') === '' ? '1' : $get('min_qty'),
311:                     'starts_at' => $get('starts_at') === '' ? null : $get('starts_at'),
312:                     'ends_at' => $get('ends_at') === '' ? null : $get('ends_at')];
313:             }
314:         } finally {
315:             fclose($handle);
316:         }
317: 
318:         $ids = array_values(array_filter(array_map(fn ($row) => filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]), $rows)));
319:         $skus = [];
320:         foreach ($rows as $row) {
321:             // الكتالوج يخزن SKU بأحرف كبيرة؛ مطابقة الاستيراد لا يجب أن تفشل على
322:             // اختلاف الحالة (L-5)، فنجمع كل الصور المحتملة للبحث.
323:             $skus[] = $row['sku'];
324:             $skus[] = $this->unescapeCsvText($row['sku']);
325:             $skus[] = strtoupper($row['sku']);
326:             $skus[] = strtoupper($this->unescapeCsvText($row['sku']));
327:         }
328:         $variants = ProductVariant::query()->where('is_active', true)
329:             ->where(fn ($q) => $q->whereIn('id', $ids)->orWhereIn('sku', array_unique($skus)))->get();
330:         $byId = $variants->keyBy('id');
331:         $bySku = $variants->keyBy('sku');
332:         $report = ['created' => 0, 'updated' => 0, 'skipped' => 0, 'errors' => []];
333:         $valid = [];
334:         foreach ($rows as $row) {
335:             try {
336:                 $variant = $row['variant_id'] !== ''
337:                     ? $byId->get(filter_var($row['variant_id'], FILTER_VALIDATE_INT, ['options' => ['min_range' => 1]]) ?: 0)
338:                     : ($bySku->get($row['sku']) ?? $bySku->get($this->unescapeCsvText($row['sku']))
339:                         ?? $bySku->get(strtoupper($row['sku'])) ?? $bySku->get(strtoupper($this->unescapeCsvText($row['sku']))));
340:                 if ($variant === null || ($row['sku'] !== '' && $row['sku'] !== $variant->sku && strtoupper($row['sku']) !== $variant->sku && $row['sku'] !== $this->csvText($variant->sku) && strtoupper($row['sku']) !== $this->csvText($variant->sku))) {
341:                     throw new BusinessException('الصنف غير موجود أو يوجد تعارض بين sku وvariant_id.');
342:                 }
343:                 $validator = Validator::make($row, [
344:                     'price' => ['required', 'numeric', 'decimal:0,4', 'min:0', 'max:99999999.9999'],
345:                     'min_qty' => ['required', 'numeric', 'decimal:0,4', 'gt:0', 'max:99999999.9999'],
346:                     'starts_at' => ['nullable', 'date'], 'ends_at' => ['nullable', 'date'],
347:                 ]);
348:                 if ($validator->fails()) {
349:                     throw new BusinessException($validator->errors()->first());
350:                 }
351:                 $row['starts_at'] = $this->parseDate($row['starts_at'] ?? '');
352:                 $row['ends_at'] = $this->parseDate($row['ends_at'] ?? '');
353:                 $this->validateDates($row);
354:                 $valid[] = [...$row, 'product_variant_id' => $variant->id];
355:             } catch (BusinessException $exception) {
356:                 $report['skipped']++;
357:                 $report['errors'][] = ['line' => $row['line'], 'message' => $exception->getMessage()];
358:             }
359:         }
360:         // تكرار نفس (متغير، min_qty) داخل الملف: الصف الأخير يكسب، والعدّ مرة واحدة
361:         $deduped = [];
362:         foreach ($valid as $row) {
