367:         DB::transaction(function () use ($valid, $priceList, $user, &$report): void {
368:             $locked = PriceList::query()->lockForUpdate()->findOrFail($priceList->id);
369:             $this->assertListAccess($user, $locked); // إعادة فحص بعد القفل (L-1)
