373:             $existing = PriceListItem::query()
374:                 ->where('price_list_id', $priceList->id)
375:                 ->whereIn('product_variant_id', array_column($valid, 'product_variant_id'))
376:                 ->get(['product_variant_id', 'min_qty'])
377:                 ->map(fn ($item) => $item->product_variant_id.':'.number_format((float) $item->min_qty, 4, '.', ''))
378:                 ->flip();
379: 
380:             $rows = [];
381:             $now = now();
382:             foreach ($valid as $row) {
383:                 $key = $row['product_variant_id'].':'.number_format((float) $row['min_qty'], 4, '.', '');
384:                 $existing->has($key) ? $report['updated']++ : $report['created']++;
385:                 $rows[] = [
386:                     'price_list_id' => $priceList->id,
387:                     'product_variant_id' => $row['product_variant_id'],
388:                     'min_qty' => $row['min_qty'],
389:                     'price' => $row['price'],
390:                     'starts_at' => $row['starts_at'],
391:                     'ends_at' => $row['ends_at'],
392:                     'created_at' => $now,
393:                     'updated_at' => $now,
394:                 ];
395:             }
396: 
397:             foreach (array_chunk($rows, 500) as $chunk) {
398:                 PriceListItem::query()->upsert($chunk, ['price_list_id', 'product_variant_id', 'min_qty'], ['price', 'starts_at', 'ends_at', 'updated_at']);
399:             }
400:         });
401: 
402:         return $report;
403:     }
