405:     private function unescapeCsvText(string $value): string
406:     {
407:         return str_starts_with($value, "'") && $this->csvText(substr($value, 1)) === $value ? substr($value, 1) : $value;
408:     }
409: 
410:     /**
411:      * تحليل صارم للتواريخ: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة فقط.
412:      * القيم بلا إزاحة تُفسَّر بمنطقة عمل (business_timezone) وتُخزَّن UTC —
413:      * لا strtotime: لا "next monday" ولا خلط بين التنسيقين الأمريكي والأوروبي.
414:      */
415:     private function parseDate(string $value): ?string
416:     {
417:         $value = trim($value);
418:         if ($value === '') {
419:             return null;
420:         }
421: 
422:         $businessTz = (string) config('app.business_timezone', 'Africa/Cairo');
423:         $value = preg_replace('/Z$/', '+00:00', $value);
424:         $value = preg_replace_callback('/\.(\d{1,6})([+-]\d{2}:\d{2})$/', fn ($matches) => '.'.str_pad($matches[1], 6, '0').$matches[2], $value);
425:         foreach (['Y-m-d\TH:i:s.uP', 'Y-m-d\TH:i:sP', 'Y-m-d H:i:s', 'Y-m-d'] as $format) {
426:             try {
427:                 $parsed = Carbon::rawCreateFromFormat('!'.$format, $value, $businessTz);
428:             } catch (\Throwable) {
429:                 $parsed = null;
430:             }
431:             if ($parsed !== null && $parsed->format($format) === $value) {
432:                 return $parsed->utc()->format('Y-m-d H:i:s');
433:             }
434:         }
435: 
436:         throw new BusinessException("تاريخ غير صالح: {$value} — الصيغ المقبولة: Y-m-d أو Y-m-d H:i:s أو ISO-8601 مع إزاحة.");
437:     }
438: 
439:     /** تطبيع starts_at/ends_at القادمة من الـ API لنفس قواعد parseDate قبل الحفظ. */
440:     private function normalizeDates(array $data): array
441:     {
442:         foreach (['starts_at', 'ends_at'] as $field) {
443:             if (! array_key_exists($field, $data) || $data[$field] === null) {
444:                 continue;
445:             }
446:             $data[$field] = $data[$field] instanceof DateTimeInterface
447:                 ? Carbon::instance($data[$field])->utc()->format('Y-m-d H:i:s')
448:                 : $this->parseDate((string) $data[$field]);
449:         }
450: 
451:         return $data;
452:     }
453: 
454:     // ----- نطاق الفرع (M4): الموظف المقيد لا يرى/يعدّل إلا قوائم فرعه -----
455:     // مجموعات العملاء كيان مركزي بلا فرع بالتصميم، فلا ينطبق عليها هذا التقييد.
456: 
457:     private function restrictedBranch(?User $user): ?int
458:     {
459:         return $user === null ? null : app(BranchAccess::class)->restrictedBranch($user);
460:     }
461: 
462:     public function assertListAccess(?User $user, PriceList $priceList): void
463:     {
464:         $restricted = $this->restrictedBranch($user);
465:         if ($restricted !== null && $priceList->branch_id !== $restricted) {
466:             // 404 لا 403: كشف الوجود غير متسق مع find() الذي يرجع 404 أصلًا،
467:             // وإخفاء الوجود هو السلوك الموحد لقوائم خارج النطاق (L-6).
468:             throw new ModelNotFoundException('قائمة الأسعار غير موجودة.');
469:         }
470:     }
471: 
472:     private function validateDates(array $data, PriceList|PriceListItem|null $model = null): void
473:     {
474:         $start = array_key_exists('starts_at', $data) ? $data['starts_at'] : $model?->starts_at;
475:         $end = array_key_exists('ends_at', $data) ? $data['ends_at'] : $model?->ends_at;
476:         if ($start !== null && $end !== null && Carbon::parse($end)->lt(Carbon::parse($start))) {
477:             throw new BusinessException('نهاية صلاحية السعر يجب ألا تسبق بدايتها.');
478:         }
479:     }
