101:     public function test_products_filters_and_sorts(): void
102:     {
103:         $catA = Category::factory()->create();
104:         $subA = Category::factory()->create(['parent_id' => $catA->id]);
105:         $brandX = Brand::factory()->create();
106:         $brandY = Brand::factory()->create();
107: 
108:         $p1 = $this->product(['category_id' => $subA->id, 'brand_id' => $brandX->id], ['color_name_en' => 'Black', 'retail_price' => 500]);
109:         $p2 = $this->product(['category_id' => $catA->id, 'brand_id' => $brandY->id], ['color_name_en' => 'Red', 'retail_price' => 1500]);
110:         $p3 = $this->product(['brand_id' => $brandY->id], ['retail_price' => 900, 'color_name_en' => 'Navy', 'color_name_ar' => 'أزرق']);
111:         $this->stock($p1->variants->first(), 3);
112:         Product::factory()->create(['status' => ProductStatus::Draft, 'category_id' => $subA->id]);
113: 
114:         // القسم بالـ slug يشمل الفرعي
115:         $byCat = $this->getJson("/api/v1/store/products?category={$catA->slug}")->assertOk();
116:         $this->assertEqualsCanonicalizing([$p1->id, $p2->id], collect($byCat->json('data'))->pluck('id')->all());
117: 
118:         // علامات متعددة + لون + مدى سعر
119:         $filtered = $this->getJson('/api/v1/store/products?brand[]='.$brandX->slug.'&brand[]='.$brandY->id.'&color=black&price_min=100&price_max=1000')->assertOk();
120:         $this->assertSame([$p1->id], collect($filtered->json('data'))->pluck('id')->all());
121: 
122:         // المتوفر فقط
123:         $inStock = $this->getJson('/api/v1/store/products?in_stock=1')->assertOk();
124:         $this->assertSame([$p1->id], collect($inStock->json('data'))->pluck('id')->all());
125:         $card = collect($inStock->json('data'))->first();
126:         $this->assertTrue($card['in_stock']);
127:         $this->assertArrayNotHasKey('store_available', $card);
128: 
129:         // الفرز بالسعر
130:         $asc = $this->getJson('/api/v1/store/products?sort=price_asc')->assertOk();
131:         $this->assertSame([$p1->id, $p3->id, $p2->id], collect($asc->json('data'))->pluck('id')->all());
132: 
133:         // مخزون في فرع معطّل لا يُحتسب
134:         $p4 = $this->product();
135:         $this->stock($p4->variants->first(), 9, branchActive: false);
136:         $inStock2 = $this->getJson('/api/v1/store/products?in_stock=1')->assertOk();
137:         $this->assertSame([$p1->id], collect($inStock2->json('data'))->pluck('id')->all());
138:     }
