184:     public function test_similar_prioritizes_same_category_then_brand_and_excludes_self(): void
185:     {
186:         $catA = Category::factory()->create();
187:         $catB = Category::factory()->create();
188:         $brandX = Brand::factory()->create();
189:         $brandY = Brand::factory()->create();
190: 
191:         $base = $this->product(['category_id' => $catA->id, 'brand_id' => $brandX->id]);
192:         $sameCat = $this->product(['category_id' => $catA->id, 'brand_id' => $brandY->id]);
193:         $sameBrand = $this->product(['category_id' => $catB->id, 'brand_id' => $brandX->id]);
194:         $unrelated = $this->product(['category_id' => $catB->id, 'brand_id' => $brandY->id]);
195: 
196:         $response = $this->getJson("/api/v1/store/products/{$base->slug}/similar")->assertOk();
197:         $ids = collect($response->json('data'))->pluck('id')->all();
198:         $this->assertSame([$sameCat->id, $sameBrand->id], $ids);
199:         $this->assertNotContains($unrelated->id, $ids);
200:         $this->assertNotContains($base->id, $ids);
