 78: .v-card { background: var(--bg-card); border-radius: 22px; border: 1px solid var(--border-subtle); }
 79: .v-subcard { background: var(--bg-subcard); border-radius: 16px; }
 80: .v-pill { background: var(--bg-card); border: 1px solid var(--border-subtle); }
