114: })().catch(error => { console.error(error); process.exitCode = 1; });   1: /* ALFARID Admin — design tokens derived from the storefront DNA
   2:    (condensed uppercase labels, ink black, pale steel hero band, teal accent, 2px corners) */
   3: :root{
   4:   --ink:#111111; --ink-2:#2c2c2c; --ink-3:#555; --ink-4:#888; --ink-5:#b0b0b0;
   5:   --line:#e9ecef; --line-2:#dcdfe3; --soft:#f4f6f8; --soft-2:#fafbfc;
   6:   --band:#dfe5e9; --accent:#4f7d88; --accent-soft:#e6eef0;
   7:   --danger:#e11d48; --danger-soft:#fdecf0;
   8:   --ok:#2f7a5b; --ok-soft:#e5f2ec;
   9:   --warn:#a76a12; --warn-soft:#fbf1e1;
  10:   --sand:#ede3de; --gold:#d4b38d;
  11:   --r:2px; --r2:4px;
  12:   --display:'Oswald','Alexandria',sans-serif;
  13:   --body:'Poppins','IBM Plex Sans Arabic',sans-serif;
  14:   --mono:'JetBrains Mono',ui-monospace,monospace;
  15:   --ease:cubic-bezier(.25,1,.5,1);
  16:   --side-w:248px;
  17: }
  18: *{margin:0;padding:0;box-sizing:border-box}
  19: html,body{height:100%}
  20: body{font-family:var(--body);color:var(--ink);background:#fff;-webkit-font-smoothing:antialiased;font-size:13.5px;line-height:1.55}
  21: button{font:inherit;color:inherit;background:none;border:0;cursor:pointer}
  22: input,select,textarea{font:inherit;color:inherit}
  23: a{color:inherit;text-decoration:none}
  24: ::selection{background:var(--band)}
  25: .ltr{direction:ltr;text-align:left;unicode-bidi:plaintext}
  26: .mono{font-family:var(--mono);font-size:12px;letter-spacing:0}
  27: .muted{color:var(--ink-4)}
  28: .disp{font-family:var(--display)}
  29: 
  30: /* ============ SHELL ============ */
  31: .app{display:grid;grid-template-columns:var(--side-w) 1fr;min-height:100vh}
  32: .side{background:#fff;border-inline-end:1px solid var(--line);position:sticky;top:0;height:100vh;display:flex;flex-direction:column}
  33: .side-logo{display:flex;align-items:center;gap:10px;padding:24px 22px 20px;font-family:var(--display);font-weight:700;font-size:22px;letter-spacing:3px}
  34: .side-logo svg{width:22px;height:22px}
  35: .side-logo small{font-family:var(--display);font-weight:400;font-size:10px;letter-spacing:1.4px;color:var(--ink-4);display:block;margin-top:-2px}
  36: .side-nav{flex:1;overflow:auto;padding:4px 14px 14px}
  37: .side-group{font-family:var(--display);font-size:11px;letter-spacing:1px;color:var(--ink-4);padding:16px 10px 6px}
  38: .side-item{display:flex;align-items:center;gap:12px;width:100%;padding:9px 12px;border-radius:var(--r);font-size:13px;color:var(--ink-2);transition:background .2s,color .2s;text-align:start}
  39: .side-item i{width:16px;text-align:center;font-size:13px;color:var(--ink-4);transition:color .2s}
  40: .side-item:hover{background:var(--soft)}
  41: .side-item.active{background:var(--ink);color:#fff}
  42: .side-item.active i{color:#fff}
  43: .side-item .lock{margin-inline-start:auto;font-size:10px}
  44: .side-foot{border-top:1px solid var(--line);padding:14px 18px;display:flex;align-items:center;gap:10px}
  45: .avatar{width:34px;height:34px;border-radius:50%;background:var(--band);display:grid;place-items:center;font-family:var(--display);font-weight:600;font-size:13px;flex-shrink:0}
  46: .side-foot .who{flex:1;min-width:0;font-size:12.5px;line-height:1.3}
  47: .side-foot .who b{display:block;font-weight:600}
  48: .side-foot .who span{color:var(--ink-4);font-size:11px}
  49: 
  50: .main{min-width:0;display:flex;flex-direction:column}
  51: .topbar{height:58px;display:flex;align-items:center;gap:16px;padding:0 32px;border-bottom:1px solid var(--line);background:#fff;position:sticky;top:0;z-index:20}
  52: .topbar .branch-chip{display:inline-flex;align-items:center;gap:8px;font-size:12px;padding:6px 12px;background:var(--soft);border-radius:var(--r)}
  53: .topbar .sp{flex:1}
  54: .topbar .ico-btn{width:34px;height:34px;display:grid;place-items:center;border-radius:var(--r);color:var(--ink-2)}
  55: .topbar .ico-btn:hover{background:var(--soft)}
  56: .session-dot{width:7px;height:7px;border-radius:50%;background:var(--ok);display:inline-block}
  57: 
  58: /* hero band header — echoes storefront .top-wrapper */
  59: .page-band{background:var(--band);position:relative;overflow:hidden}
  60: .page-band-in{padding:22px 32px 26px;display:flex;align-items:flex-end;gap:24px;position:relative;z-index:1}
  61: .page-band .decor{position:absolute;inset-inline-start:auto;inset-inline-end:28px;bottom:-26px;width:150px;height:150px;object-fit:contain;transform:rotate(8deg);filter:drop-shadow(0 15px 15px rgba(0,0,0,.12));opacity:.95;pointer-events:none}
  62: .crumbs{display:flex;align-items:center;gap:8px;font-family:var(--display);font-size:11.5px;letter-spacing:.8px;color:var(--ink-3);margin-bottom:8px;flex-wrap:wrap}
  63: .crumbs a{cursor:pointer}
  64: .crumbs a:hover{color:var(--accent)}
  65: .crumbs .sep{opacity:.5}
  66: .crumbs .cur{color:var(--ink);font-weight:600}
  67: .page-title{font-family:var(--display);line-height:1.1;font-size:30px;letter-spacing:.3px}
  68: .page-title .lt{font-weight:300}
  69: .page-title .bd{font-weight:700}
  70: .page-sub{font-size:12.5px;color:var(--ink-3);margin-top:6px;max-width:560px}
  71: .page-actions{margin-inline-start:auto;display:flex;gap:10px;align-items:center}
  72: .page-band.has-decor .page-actions{margin-inline-end:170px}
  73: .content{padding:28px 32px 120px;flex:1}
  74: 
  75: /* ============ BUTTONS ============ */
  76: .btn{display:inline-flex;align-items:center;justify-content:center;gap:9px;font-family:var(--display);font-size:12.5px;font-weight:500;letter-spacing:.6px;padding:9px 18px;border:1px solid var(--ink);border-radius:var(--r);background:var(--ink);color:#fff;transition:all .3s var(--ease);white-space:nowrap;min-height:36px}
  77: .btn:hover{background:var(--ink-2);transform:translateY(-1px);box-shadow:0 4px 12px rgba(0,0,0,.15)}
  78: .btn:active{transform:none;box-shadow:none}
  79: .btn.ghost{background:#fff;color:var(--ink);border-color:var(--line-2)}
  80: .btn.ghost:hover{border-color:var(--ink);box-shadow:none}
  81: .btn.text{background:none;border-color:transparent;color:var(--ink-2);padding-inline:10px}
  82: .btn.text:hover{background:var(--soft);box-shadow:none;transform:none}
  83: .btn.danger{background:var(--danger);border-color:var(--danger)}
  84: .btn.danger.ghost{background:#fff;color:var(--danger);border-color:#f3c3cf}
  85: .btn.accent{background:var(--accent);border-color:var(--accent)}
  86: .btn.sm{min-height:30px;padding:5px 12px;font-size:11.5px}
  87: .btn.lg{min-height:44px;padding:11px 24px;font-size:13.5px}
  88: .btn[disabled]{opacity:.45;pointer-events:none}
  89: .btn .spin{width:13px;height:13px;border:2px solid currentColor;border-inline-end-color:transparent;border-radius:50%;animation:spin .7s linear infinite}
  90: @keyframes spin{to{transform:rotate(360deg)}}
  91: .icon-btn{width:30px;height:30px;display:inline-grid;place-items:center;border-radius:var(--r);color:var(--ink-3);transition:all .2s}
  92: .icon-btn:hover{background:var(--soft);color:var(--ink)}
  93: .icon-btn.danger:hover{background:var(--danger-soft);color:var(--danger)}
  94: .icon-btn[disabled]{opacity:.35;pointer-events:none}
  95: 
  96: /* ============ FIELDS ============ */
  97: .field{display:flex;flex-direction:column;gap:6px;min-width:0}
  98: .field-label{font-size:12.5px;font-weight:500;color:var(--ink-2);display:flex;align-items:center;gap:6px}
  99: .field-label .req{color:var(--danger);font-weight:600}
 100: .field-label .opt{color:var(--ink-4);font-weight:400;font-size:11px}
 101: .field-help{font-size:11.5px;color:var(--ink-4);line-height:1.5}
 102: .field-err{font-size:11.5px;color:var(--danger);display:flex;gap:6px;align-items:flex-start;line-height:1.45}
 103: .field-err i{margin-top:3px;font-size:10px}
 104: .inp{width:100%;height:40px;border:1px solid var(--line-2);border-radius:var(--r);padding:0 12px;background:#fff;outline:none;transition:border-color .2s,box-shadow .2s;font-size:13px}
 105: textarea.inp{height:auto;min-height:84px;padding:10px 12px;resize:vertical;line-height:1.6}
 106: .inp:hover{border-color:#c5cad0}
 107: .inp:focus{border-color:var(--ink);box-shadow:0 0 0 3px rgba(17,17,17,.06)}
 108: .inp.err{border-color:var(--danger);background:#fffafb}
 109: .inp.err:focus{box-shadow:0 0 0 3px rgba(225,29,72,.1)}
 110: .inp[disabled]{background:var(--soft);color:var(--ink-4);cursor:not-allowed}
 111: .inp[readonly]{background:var(--soft-2);border-style:dashed;color:var(--ink-3)}
 112: .inp-wrap{position:relative;display:flex;align-items:center}
 113: .inp-wrap .inp{padding-inline-end:40px}
 114: .inp-wrap .adorn{position:absolute;inset-inline-end:4px;height:32px;min-width:32px;display:grid;place-items:center;color:var(--ink-4);font-size:12px;border-radius:var(--r)}
 115: .inp-wrap .adorn:hover{color:var(--ink);background:var(--soft)}
 116: .inp-wrap .pre{position:absolute;inset-inline-start:12px;color:var(--ink-4);font-size:12px;pointer-events:none}
 117: .inp-wrap.has-pre .inp{padding-inline-start:44px}
 118: .grid{display:grid;gap:18px 20px}
 119: .g2{grid-template-columns:repeat(2,minmax(0,1fr))}
 120: .g3{grid-template-columns:repeat(3,minmax(0,1fr))}
 121: .g4{grid-template-columns:repeat(4,minmax(0,1fr))}
 122: .span2{grid-column:span 2}.span3{grid-column:span 3}.spanall{grid-column:1/-1}
 123: 
 124: /* toggle */
 125: .tgl{display:inline-flex;align-items:center;gap:10px;cursor:pointer;user-select:none;font-size:13px}
 126: .tgl input{display:none}
 127: .tgl .tr{width:36px;height:20px;border-radius:20px;background:#d5d9de;position:relative;transition:background .25s;flex-shrink:0}
 128: .tgl .tr::after{content:"";position:absolute;top:2px;inset-inline-start:2px;width:16px;height:16px;border-radius:50%;background:#fff;box-shadow:0 1px 3px rgba(0,0,0,.2);transition:inset-inline-start .25s var(--ease)}
 129: .tgl input:checked + .tr{background:var(--ink)}
 130: .tgl input:checked + .tr::after{inset-inline-start:18px}
 131: .tgl.disabled{opacity:.5;pointer-events:none}
 132: .chk{display:inline-flex;align-items:center;gap:9px;cursor:pointer;font-size:13px;user-select:none}
 133: .chk input{appearance:none;width:16px;height:16px;border:1.5px solid #b9bfc6;border-radius:2px;display:grid;place-items:center;background:#fff;flex-shrink:0;transition:all .15s;cursor:pointer}
 134: .chk input:checked,.chk input:indeterminate{background:var(--ink);border-color:var(--ink)}
 135: .chk input:checked::after{content:"";width:8px;height:4px;border:2px solid #fff;border-top:0;border-right:0;transform:rotate(-45deg) translate(1px,-1px)}
 136: .chk input:indeterminate::after{content:"";width:8px;height:2px;background:#fff}
 137: .radio-cards{display:grid;gap:12px}
 138: .rcard{border:1px solid var(--line-2);border-radius:var(--r2);padding:16px;cursor:pointer;transition:all .2s;display:flex;gap:12px;align-items:flex-start;background:#fff}
 139: .rcard:hover{border-color:#b9bfc6}
 140: .rcard.on{border-color:var(--ink);box-shadow:inset 0 0 0 1px var(--ink)}
 141: .rcard .dot{width:16px;height:16px;border-radius:50%;border:1.5px solid #b9bfc6;flex-shrink:0;margin-top:2px;display:grid;place-items:center}
 142: .rcard.on .dot{border-color:var(--ink)}
 143: .rcard.on .dot::after{content:"";width:8px;height:8px;border-radius:50%;background:var(--ink)}
 144: .rcard b{display:block;font-weight:600;font-size:13.5px;margin-bottom:2px}
 145: .rcard span{font-size:12px;color:var(--ink-3)}
 146: .seg{display:inline-flex;background:var(--soft);padding:3px;border-radius:var(--r2);gap:2px}
 147: .seg button{font-family:var(--display);font-size:12px;letter-spacing:.4px;padding:6px 14px;border-radius:var(--r);color:var(--ink-3)}
 148: .seg button.on{background:#fff;color:var(--ink);box-shadow:0 1px 3px rgba(0,0,0,.08)}
 149: 
 150: /* searchable select */
 151: .ss{position:relative}
 152: .ss-trigger{display:flex;align-items:center;gap:8px;cursor:pointer;text-align:start}
 153: .ss-trigger .val{flex:1;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}
 154: .ss-trigger .ph{color:var(--ink-5)}
 155: .ss-pop{position:absolute;top:calc(100% + 4px);inset-inline:0;background:#fff;border:1px solid var(--line-2);border-radius:var(--r2);box-shadow:0 12px 32px rgba(0,0,0,.1);z-index:60;overflow:hidden;animation:pop .18s var(--ease)}
 156: @keyframes pop{from{opacity:0;transform:translateY(-4px)}}
 157: .ss-search{display:flex;align-items:center;gap:8px;padding:8px 12px;border-bottom:1px solid var(--line)}
 158: .ss-search input{border:0;outline:0;flex:1;height:28px;font-size:13px}
 159: .ss-list{max-height:240px;overflow:auto;padding:4px}
 160: .ss-opt{display:flex;align-items:center;gap:10px;padding:8px 10px;border-radius:var(--r);cursor:pointer;font-size:13px}
 161: .ss-opt:hover,.ss-opt.hl{background:var(--soft)}
 162: .ss-opt.sel{font-weight:600}
 163: .ss-opt.sel::after{content:"\f00c";font-family:"Font Awesome 6 Free";font-weight:900;margin-inline-start:auto;font-size:11px}
 164: .ss-opt.dis{opacity:.45;cursor:not-allowed}
 165: .ss-opt .why{margin-inline-start:auto;font-size:10.5px;color:var(--ink-4)}
 166: .ss-opt .depth{color:var(--ink-5)}
 167: .ss-empty{padding:22px 12px;text-align:center;color:var(--ink-4);font-size:12.5px}
 168: .ss-loading{padding:6px}
 169: .tags{display:flex;flex-wrap:wrap;gap:6px}
 170: .tag{display:inline-flex;align-items:center;gap:6px;background:var(--soft);border-radius:var(--r);padding:3px 8px;font-size:12px}
 171: .tag button{font-size:10px;color:var(--ink-4)}
 172: .tag button:hover{color:var(--danger)}
 173: 
 174: /* ============ BADGES ============ */
 175: .badge{display:inline-flex;align-items:center;gap:6px;font-family:var(--display);font-size:11px;letter-spacing:.4px;padding:3px 9px;border-radius:var(--r);background:var(--soft);color:var(--ink-3);white-space:nowrap;line-height:1.5}
 176: .badge::before{content:"";width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.8}
 177: .badge.nodot::before{display:none}
 178: .badge.ok{background:var(--ok-soft);color:var(--ok)}
 179: .badge.warn{background:var(--warn-soft);color:var(--warn)}
 180: .badge.danger{background:var(--danger-soft);color:var(--danger)}
 181: .badge.ink{background:var(--ink);color:#fff}
 182: .badge.accent{background:var(--accent-soft);color:var(--accent)}
 183: .badge.line{background:#fff;border:1px solid var(--line-2)}
 184: .star{color:var(--gold)}
 185: 
 186: /* ============ CARD / PANEL ============ */
 187: .panel{background:#fff;border:1px solid var(--line);border-radius:var(--r2)}
 188: .panel-h{display:flex;align-items:center;gap:12px;padding:16px 20px;border-bottom:1px solid var(--line)}
 189: .panel-h h3{font-family:var(--display);font-size:15px;font-weight:600;letter-spacing:.3px}
 190: .panel-h p{font-size:12px;color:var(--ink-4)}
 191: .panel-h .sp{flex:1}
 192: .panel-b{padding:20px}
 193: .sec-title{font-family:var(--display);font-size:12px;letter-spacing:1px;color:var(--ink-4);margin:0 0 12px;display:flex;align-items:center;gap:10px}
 194: .sec-title::after{content:"";flex:1;height:1px;background:var(--line)}
 195: .split{display:grid;grid-template-columns:220px 1fr;gap:32px;align-items:start}
 196: .vnav{display:flex;flex-direction:column;gap:2px;position:sticky;top:80px}
 197: .vnav button{text-align:start;padding:9px 12px;border-radius:var(--r);font-size:13px;color:var(--ink-3);display:flex;gap:10px;align-items:center}
 198: .vnav button i{width:16px;color:var(--ink-5)}
 199: .vnav button:hover{background:var(--soft)}
 200: .vnav button.on{background:var(--soft);color:var(--ink);font-weight:600;box-shadow:inset -2px 0 0 var(--ink)}
 201: 
 202: /* ============ TABS ============ */
 203: .tabs{display:flex;gap:28px;border-bottom:1px solid var(--line);margin-bottom:24px;overflow-x:auto}
 204: .tab{font-family:var(--display);font-size:13.5px;letter-spacing:.4px;color:var(--ink-4);padding:12px 0;position:relative;display:flex;align-items:center;gap:8px;white-space:nowrap;transition:color .2s}
 205: .tab:hover{color:var(--ink)}
 206: .tab.on{color:var(--ink);font-weight:600}
 207: .tab.on::after{content:"";position:absolute;bottom:-1px;inset-inline:0;height:2px;background:var(--ink)}
 208: .tab .n{font-size:10.5px;background:var(--soft);padding:1px 7px;border-radius:10px;font-weight:500;color:var(--ink-3)}
 209: .tab .errdot{width:7px;height:7px;border-radius:50%;background:var(--danger)}
 210: .tab .okdot{color:var(--ok);font-size:11px}
 211: .tab .step{width:20px;height:20px;border-radius:50%;border:1px solid var(--line-2);display:grid;place-items:center;font-size:11px;font-weight:500}
 212: .tab.on .step{background:var(--ink);color:#fff;border-color:var(--ink)}
 213: 
 214: /* ============ TABLE ============ */
 215: .dt{background:#fff;border:1px solid var(--line);border-radius:var(--r2)}
 216: .dt-toolbar{display:flex;align-items:center;gap:10px;padding:14px 16px;border-bottom:1px solid var(--line);flex-wrap:wrap}
 217: .dt-search{position:relative;width:300px}
 218: .dt-search i{position:absolute;inset-inline-start:12px;top:50%;transform:translateY(-50%);color:var(--ink-4);font-size:12px}
 219: .dt-search .inp{padding-inline-start:34px;height:36px}
 220: .dt-filters{display:flex;gap:8px;flex-wrap:wrap;align-items:center}
 221: .fchip{display:inline-flex;align-items:center;gap:8px;height:36px;padding:0 12px;border:1px solid var(--line-2);border-radius:var(--r);font-size:12.5px;background:#fff;cursor:pointer;transition:border-color .2s;position:relative}
 222: .fchip:hover{border-color:var(--ink)}
 223: .fchip.on{border-color:var(--ink);background:var(--ink);color:#fff}
 224: .fchip select{appearance:none;border:0;background:transparent;outline:0;cursor:pointer;padding-inline-end:14px;font-size:12.5px;color:inherit}
 225: .fchip .car{position:absolute;inset-inline-end:10px;font-size:9px;pointer-events:none}
 226: .fchip.on select option{color:var(--ink)}
 227: .active-filters{display:flex;gap:6px;align-items:center;flex-wrap:wrap;padding:10px 16px;border-bottom:1px solid var(--line);background:var(--soft-2)}
 228: .active-filters .lbl{font-size:11.5px;color:var(--ink-4)}
 229: table.tbl{width:100%;border-collapse:collapse}
 230: .tbl th{font-family:var(--display);font-weight:500;font-size:11.5px;letter-spacing:.6px;color:var(--ink-4);text-align:start;padding:11px 16px;border-bottom:1px solid var(--line);background:var(--soft-2);white-space:nowrap}
 231: .tbl td{padding:12px 16px;border-bottom:1px solid var(--line);vertical-align:middle;font-size:13px}
 232: .tbl tbody tr{transition:background .15s}
 233: .tbl tbody tr:hover{background:#fbfcfc}
 234: .tbl tbody tr:last-child td{border-bottom:0}
 235: .tbl .num{font-variant-numeric:tabular-nums}
 236: .tbl .act{white-space:nowrap;text-align:end;width:1%}
 237: .thumb{width:44px;height:44px;border-radius:var(--r);background:var(--soft);display:grid;place-items:center;overflow:hidden;flex-shrink:0}
 238: .thumb img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;padding:3px}
 239: .cell-main{display:flex;align-items:center;gap:12px;min-width:0}
 240: .cell-main b{font-weight:600;display:block;line-height:1.35}
 241: .cell-main small{color:var(--ink-4);font-size:11.5px}
 242: .dt-foot{display:flex;align-items:center;gap:14px;padding:12px 16px;border-top:1px solid var(--line);font-size:12px;color:var(--ink-3);flex-wrap:wrap}
 243: .pager{display:flex;gap:4px;margin-inline-start:auto;align-items:center}
 244: .pager button{min-width:32px;height:32px;border-radius:var(--r);font-size:12px;display:grid;place-items:center;border:1px solid transparent}
 245: .pager button:hover{border-color:var(--line-2)}
 246: .pager button.on{background:var(--ink);color:#fff}
 247: .pager button[disabled]{opacity:.3;pointer-events:none}
 248: .mini-sel{height:30px;border:1px solid var(--line-2);border-radius:var(--r);padding:0 8px;background:#fff;font-size:12px}
 249: .sk{background:linear-gradient(90deg,#f0f2f4 0,#f8f9fa 40%,#f0f2f4 80%);background-size:300% 100%;animation:sk 1.4s ease infinite;border-radius:var(--r);height:12px}
 250: @keyframes sk{from{background-position:100% 0}to{background-position:-100% 0}}
 251: 
 252: /* ============ STATES ============ */
 253: .state{padding:64px 24px;text-align:center;display:flex;flex-direction:column;align-items:center;gap:10px}
 254: .state .glyph{width:64px;height:64px;border-radius:50%;background:var(--soft);display:grid;place-items:center;font-size:22px;color:var(--ink-4);margin-bottom:6px}
 255: .state.err .glyph{background:var(--danger-soft);color:var(--danger)}
 256: .state.lock .glyph{background:var(--band);color:var(--ink-2)}
 257: .state h4{font-family:var(--display);font-size:18px;font-weight:600}
 258: .state p{color:var(--ink-3);max-width:380px;font-size:13px}
 259: .state .code{font-family:var(--mono);font-size:11px;color:var(--ink-4);background:var(--soft);padding:2px 8px;border-radius:var(--r)}
 260: .state .row{display:flex;gap:10px;margin-top:8px}
 261: 
 262: /* alerts / banners */
 263: .alert{display:flex;gap:12px;padding:14px 16px;border-radius:var(--r2);font-size:13px;line-height:1.55;align-items:flex-start;border:1px solid}
 264: .alert > i{margin-top:3px}
 265: .alert b{font-weight:600}
 266: .alert .grow{flex:1}
 267: .alert.info{background:var(--accent-soft);border-color:#cfdfe3;color:#2d5560}
 268: .alert.warn{background:var(--warn-soft);border-color:#f0dcb8;color:#7a4e0c}
 269: .alert.danger{background:var(--danger-soft);border-color:#f6c7d3;color:#9b1236}
 270: .alert.ok{background:var(--ok-soft);border-color:#c8e3d6;color:#235c44}
 271: .alert.ink{background:var(--ink);border-color:var(--ink);color:#fff}
 272: .alert ul{margin:6px 0 0;padding-inline-start:18px}
 273: .alert li{margin:3px 0}
 274: .alert .lnk{text-decoration:underline;text-underline-offset:3px;cursor:pointer;font-weight:500}
 275: .err-summary li{display:flex;gap:10px;align-items:center;list-style:none;padding:6px 0;border-top:1px solid rgba(155,18,54,.12)}
 276: .err-summary ul{padding:0;margin-top:10px}
 277: .err-summary li:first-child{border-top:0}
 278: .err-summary .to{margin-inline-start:auto;font-family:var(--display);font-size:11.5px;letter-spacing:.4px;white-space:nowrap}
 279: 
 280: /* toasts */
 281: .toasts{position:fixed;bottom:24px;left:24px;display:flex;flex-direction:column;gap:10px;z-index:200}
 282: .toast{background:var(--ink);color:#fff;padding:12px 16px;border-radius:var(--r2);font-size:13px;display:flex;gap:10px;align-items:center;box-shadow:0 10px 30px rgba(0,0,0,.2);animation:toastin .35s var(--ease);min-width:260px}
 283: .toast i{color:#8fd3b4}
 284: .toast.err i{color:#ff9db3}
 285: @keyframes toastin{from{opacity:0;transform:translateY(12px)}}
 286: 
 287: /* modal / drawer */
 288: .scrim{position:fixed;inset:0;background:rgba(17,17,17,.38);z-index:100;display:flex;align-items:center;justify-content:center;animation:fade .2s}
 289: @keyframes fade{from{opacity:0}}
 290: .modal{background:#fff;border-radius:var(--r2);width:min(460px,92vw);box-shadow:0 30px 80px rgba(0,0,0,.25);animation:pop .25s var(--ease)}
 291: .modal-b{padding:26px 26px 20px;display:flex;gap:16px}
 292: .modal-b .mi{width:42px;height:42px;border-radius:50%;display:grid;place-items:center;flex-shrink:0;background:var(--soft);font-size:16px}
 293: .modal-b .mi.danger{background:var(--danger-soft);color:var(--danger)}
 294: .modal-b .mi.warn{background:var(--warn-soft);color:var(--warn)}
 295: .modal-b h4{font-family:var(--display);font-size:17px;font-weight:600;margin-bottom:6px}
 296: .modal-b p{color:var(--ink-3);font-size:13px}
 297: .modal-f{display:flex;gap:10px;justify-content:flex-end;padding:14px 26px;background:var(--soft-2);border-top:1px solid var(--line);border-radius:0 0 var(--r2) var(--r2)}
 298: .drawer-scrim{justify-content:flex-start;align-items:stretch}
 299: .drawer{background:#fff;width:min(560px,96vw);height:100%;display:flex;flex-direction:column;box-shadow:20px 0 60px rgba(0,0,0,.15);animation:slidein .35s var(--ease)}
 300: @keyframes slidein{from{transform:translateX(40px);opacity:0}}
 301: .drawer-h{padding:20px 24px;border-bottom:1px solid var(--line);display:flex;align-items:center;gap:12px;background:var(--band)}
 302: .drawer-h h3{font-family:var(--display);font-size:19px;font-weight:600}
 303: .drawer-h .crumbs{margin:0}
 304: .drawer-b{flex:1;overflow:auto;padding:24px}
 305: .drawer-f{padding:14px 24px;border-top:1px solid var(--line);display:flex;gap:10px;align-items:center}
 306: 
 307: /* upload */
 308: .drop{border:1.5px dashed #c8cdd3;border-radius:var(--r2);padding:22px;text-align:center;background:var(--soft-2);transition:all .2s;cursor:pointer;display:flex;flex-direction:column;align-items:center;gap:6px}
 309: .drop:hover,.drop.over{border-color:var(--ink);background:#fff}
 310: .drop .di{width:42px;height:42px;border-radius:50%;background:#fff;border:1px solid var(--line);display:grid;place-items:center;color:var(--ink-3);margin-bottom:4px}
 311: .drop b{font-weight:600;font-size:13px}
 312: .drop .rules{display:flex;gap:6px;flex-wrap:wrap;justify-content:center;margin-top:6px}
 313: .drop .rules span{font-size:11px;background:#fff;border:1px solid var(--line);padding:2px 8px;border-radius:var(--r);color:var(--ink-3)}
 314: .files{display:grid;gap:10px}
 315: .file{display:flex;gap:12px;align-items:center;padding:10px;border:1px solid var(--line);border-radius:var(--r2);background:#fff}
 316: .file.failed{border-color:#f6c7d3;background:#fffafb}
 317: .file .fmeta{flex:1;min-width:0}
 318: .file .fmeta b{font-size:12.5px;font-weight:500;display:block;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
 319: .file .fmeta small{font-size:11px;color:var(--ink-4)}
 320: .prog{height:3px;background:var(--line);border-radius:3px;overflow:hidden;margin-top:6px}
 321: .prog i{display:block;height:100%;background:var(--ink);transition:width .2s}
 322: .img-tile{position:relative;border:1px solid var(--line);border-radius:var(--r2);background:var(--soft);aspect-ratio:1;overflow:hidden;cursor:grab;transition:box-shadow .2s,transform .2s}
 323: .img-tile:hover{box-shadow:0 6px 16px rgba(0,0,0,.08)}
 324: .img-tile.dragging{opacity:.4}
 325: .img-tile.over{outline:2px solid var(--ink);outline-offset:2px}
 326: .img-tile img{width:100%;height:100%;object-fit:contain;mix-blend-mode:multiply;padding:10px}
 327: .img-tile .ord{position:absolute;top:8px;inset-inline-start:8px;width:22px;height:22px;border-radius:50%;background:#fff;font-size:11px;font-weight:600;display:grid;place-items:center;box-shadow:0 1px 3px rgba(0,0,0,.1)}
 328: .img-tile .cover{position:absolute;top:8px;inset-inline-end:8px}
 329: .img-tile .ov{position:absolute;inset-inline:0;bottom:0;padding:8px;background:linear-gradient(transparent,rgba(255,255,255,.95) 40%);display:flex;align-items:center;gap:6px;font-size:11px}
 330: .img-tile .ov .sp{flex:1}
 331: .img-tile.failed{border-color:var(--danger)}
 332: .img-tile .veil{position:absolute;inset:0;background:rgba(255,255,255,.7);display:grid;place-items:center}
 333: 
 334: /* ============ CATEGORY TREE ============ */
 335: .tree{padding:8px}
 336: .tnode{display:flex;align-items:center;gap:8px;padding:8px 10px;border-radius:var(--r);border:1px solid transparent;transition:background .15s;position:relative;cursor:default}
 337: .tnode:hover{background:var(--soft-2)}
 338: .tnode.sel{background:var(--soft);border-color:var(--line-2)}
 339: .tnode .grip{color:var(--ink-5);cursor:grab;font-size:11px;padding:4px}
 340: .tnode .tw{width:20px;height:20px;display:grid;place-items:center;color:var(--ink-4);font-size:10px;border-radius:var(--r)}
 341: .tnode .tw:hover{background:#fff}
 342: .tnode .nm{font-weight:500;font-size:13px}
 343: .tnode .en{font-size:11.5px;color:var(--ink-4)}
 344: .tnode .cnt{font-size:11px;color:var(--ink-4);margin-inline-start:auto;white-space:nowrap}
 345: .tnode .tact{display:flex;gap:2px;opacity:0;transition:opacity .15s}
 346: .tnode:hover .tact,.tnode.sel .tact{opacity:1}
 347: .tnode.drop-in{background:var(--accent-soft);border-color:var(--accent)}
 348: .tnode.drop-bad{background:var(--danger-soft);border-color:#f6c7d3}
 349: .tnode.drop-before::before,.tnode.drop-after::after{content:"";position:absolute;inset-inline:10px;height:2px;background:var(--ink)}
 350: .tnode.drop-before::before{top:-2px}.tnode.drop-after::after{bottom:-2px}
 351: .tnode.moved .nm::after{content:"•";color:var(--accent);margin-inline-start:6px}
 352: .tnode .lvl{font-family:var(--display);font-size:10px;color:var(--ink-5);border:1px solid var(--line);border-radius:var(--r);padding:0 5px}
 353: .drag-tip{position:fixed;z-index:300;background:var(--danger);color:#fff;font-size:11.5px;padding:5px 10px;border-radius:var(--r);pointer-events:none}
 354: .pending-bar{position:sticky;bottom:16px;margin-top:16px;background:var(--ink);color:#fff;border-radius:var(--r2);padding:12px 16px;display:flex;align-items:center;gap:12px;box-shadow:0 12px 30px rgba(0,0,0,.2);animation:toastin .3s var(--ease)}
 355: .pending-bar .sp{flex:1}
 356: .pending-bar .btn.ghost{background:transparent;color:#fff;border-color:#555}
 357: 
 358: /* ============ PRODUCT FORM ============ */
 359: .pf-head{display:flex;gap:16px;align-items:center}
 360: .pf-head .thumb{width:64px;height:64px;background:#fff}
 361: .sticky-bar{position:fixed;bottom:0;inset-inline-start:0;inset-inline-end:var(--side-w);background:rgba(255,255,255,.96);backdrop-filter:blur(8px);border-top:1px solid var(--line);padding:12px 32px;display:flex;align-items:center;gap:12px;z-index:40}
 362: .sticky-bar .sp{flex:1}
 363: .dirty{display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--warn)}
 364: .dirty::before{content:"";width:7px;height:7px;border-radius:50%;background:var(--warn)}
 365: .saved{display:inline-flex;align-items:center;gap:8px;font-size:12px;color:var(--ok)}
 366: .chips-input{display:flex;flex-wrap:wrap;gap:6px;align-items:center;min-height:42px;border:1px solid var(--line-2);border-radius:var(--r);padding:5px 8px;background:#fff}
 367: .chips-input:focus-within{border-color:var(--ink)}
 368: .chips-input input{border:0;outline:0;flex:1;min-width:120px;height:28px;font-size:13px}
 369: .vchip{display:inline-flex;align-items:center;gap:7px;background:var(--soft);border:1px solid var(--line);border-radius:var(--r);padding:3px 6px 3px 9px;font-size:12.5px}
 370: .vchip .sw{width:14px;height:14px;border-radius:50%;border:1px solid rgba(0,0,0,.12)}
 371: .vchip button{color:var(--ink-4);font-size:10px;width:18px;height:18px;display:grid;place-items:center;border-radius:2px}
 372: .vchip button:hover{background:#fff;color:var(--danger)}
 373: .gen-box{border:1px solid var(--line);border-radius:var(--r2);background:var(--soft-2)}
 374: .gen-row{display:grid;grid-template-columns:150px 1fr;gap:16px;align-items:start;padding:14px 18px;border-bottom:1px solid var(--line)}
 375: .gen-row:last-child{border-bottom:0}
 376: .gen-row .gl{font-weight:600;font-size:12.5px;padding-top:10px;display:flex;gap:8px;align-items:center}
 377: .gen-row .gl small{font-weight:400;color:var(--ink-4)}
 378: .gen-foot{display:flex;align-items:center;gap:12px;padding:12px 18px;background:#fff;border-top:1px solid var(--line);border-radius:0 0 var(--r2) var(--r2)}
 379: .bulk-bar{display:flex;align-items:center;gap:10px;padding:10px 14px;background:var(--ink);color:#fff;border-radius:var(--r2) var(--r2) 0 0;font-size:12.5px;flex-wrap:wrap}
 380: .bulk-bar .inp{height:32px;width:110px;background:#222;border-color:#444;color:#fff}
 381: .bulk-bar select.inp{width:130px}
 382: .bulk-bar .btn{min-height:32px}
 383: .bulk-bar .btn.ghost{background:transparent;color:#fff;border-color:#555}
 384: .vt-wrap{border:1px solid var(--line);border-radius:var(--r2);overflow:auto;background:#fff}
 385: .bulk-bar + .vt-wrap{border-radius:0 0 var(--r2) var(--r2);border-top:0}
 386: table.vt{border-collapse:separate;border-spacing:0;width:100%;min-width:1180px}
 387: .vt th{font-family:var(--display);font-weight:500;font-size:11px;letter-spacing:.5px;color:var(--ink-4);text-align:start;padding:9px 8px;border-bottom:1px solid var(--line);background:var(--soft-2);white-space:nowrap;position:sticky;top:0;z-index:2}
 388: .vt th .fd{margin-inline-start:4px;font-size:10px;color:var(--ink-5);padding:2px 4px;border-radius:2px}
 389: .vt th .fd:hover{background:#fff;color:var(--ink)}
 390: .vt td{padding:6px 8px;border-bottom:1px solid var(--line);vertical-align:top}
 391: .vt tr.dup td{background:#fff6f8}
 392: .vt tr.sel td{background:#f7f9fa}
 393: .vt tr.inactive td{opacity:.55}
 394: .vt tr.inactive td:first-child,.vt tr.inactive td:last-child{opacity:1}
 395: .vt .cell{height:34px;width:100%;border:1px solid transparent;border-radius:var(--r);padding:0 8px;background:transparent;outline:0;font-size:12.5px;transition:all .15s}
 396: .vt .cell:hover{border-color:var(--line-2);background:#fff}
 397: .vt .cell:focus{border-color:var(--ink);background:#fff;box-shadow:0 0 0 3px rgba(17,17,17,.06)}
 398: .vt .cell.err{border-color:var(--danger);background:#fffafb}
 399: .vt .cell::placeholder{color:#c3c8ce}
 400: .vt .cell.price{text-align:left;direction:ltr;font-variant-numeric:tabular-nums}
 401: .vt .ce{font-size:10.5px;color:var(--danger);padding:2px 8px 0;line-height:1.3}
 402: .vt .colorcell{display:flex;align-items:center;gap:6px}
 403: .vt .swatch-in{width:24px;height:24px;border-radius:50%;border:1px solid rgba(0,0,0,.12);flex-shrink:0;cursor:pointer;position:relative;overflow:hidden}
 404: .vt .swatch-in input{position:absolute;inset:-6px;opacity:0;cursor:pointer}
 405: .vt .exp td{background:var(--soft-2);padding:12px 16px 16px}
 406: .vt .combo{font-size:11px;color:var(--ink-4);white-space:nowrap}
 407: .cnt-meter{font-size:12px;color:var(--ink-3);display:flex;align-items:center;gap:10px}
 408: .cnt-meter .bar{width:90px;height:4px;background:var(--line);border-radius:4px;overflow:hidden}
 409: .cnt-meter .bar i{display:block;height:100%;background:var(--ink)}
 410: .ready-list{display:flex;flex-direction:column}
 411: .ready{display:flex;gap:14px;align-items:center;padding:14px 18px;border-bottom:1px solid var(--line)}
 412: .ready:last-child{border-bottom:0}
 413: .ready .ri{width:26px;height:26px;border-radius:50%;display:grid;place-items:center;font-size:11px;flex-shrink:0}
 414: .ready.ok .ri{background:var(--ok-soft);color:var(--ok)}
 415: .ready.no .ri{background:var(--danger-soft);color:var(--danger)}
 416: .ready .rt{flex:1}
 417: .ready .rt b{font-weight:500;display:block;font-size:13px}
 418: .ready .rt small{color:var(--ink-4);font-size:11.5px}
 419: .pipeline{display:flex;flex-direction:column;gap:0}
 420: .pstep{display:flex;gap:14px;position:relative;padding-bottom:20px}
 421: .pstep:last-child{padding-bottom:0}
 422: .pstep::before{content:"";position:absolute;top:28px;bottom:0;inset-inline-start:13px;width:1px;background:var(--line-2)}
 423: .pstep:last-child::before{display:none}
 424: .pstep .pi{width:27px;height:27px;border-radius:50%;border:1px solid var(--line-2);background:#fff;display:grid;place-items:center;font-size:11px;font-weight:600;flex-shrink:0;z-index:1}
 425: .pstep.done .pi{background:var(--ok);border-color:var(--ok);color:#fff}
 426: .pstep.run .pi{border-color:var(--ink)}
 427: .pstep.fail .pi{background:var(--danger);border-color:var(--danger);color:#fff}
 428: .pstep b{font-weight:600;font-size:13px;display:block}
 429: .pstep small{font-size:11.5px;color:var(--ink-4)}
 430: 
 431: /* storefront preview card in review */
 432: .sf-card{background:var(--band);border-radius:var(--r2);padding:18px;text-align:center}
 433: .sf-card img{width:100%;height:170px;object-fit:contain;filter:drop-shadow(0 12px 12px rgba(0,0,0,.12))}
 434: .sf-card .nm{font-family:var(--display);font-weight:600;letter-spacing:.5px;margin-top:10px}
 435: .sf-card .pr{font-size:13px;margin-top:2px}
 436: 
 437: /* ============ LOGIN ============ */
 438: .login{min-height:100vh;display:grid;grid-template-columns:1.05fr 1fr}
 439: .login-art{background:var(--band);position:relative;overflow:hidden;display:flex;flex-direction:column;padding:40px 56px}
 440: .login-art .bigtype{font-family:var(--display);line-height:1;margin-top:auto;position:relative;z-index:1}
 441: .login-art .bigtype .lt{display:block;font-size:52px;font-weight:300;letter-spacing:1px}
 442: .login-art .bigtype .bd{display:block;font-size:64px;font-weight:700;letter-spacing:1px}
 443: .login-art p{max-width:380px;color:var(--ink-3);margin-top:16px;font-size:13.5px;position:relative;z-index:1}
 444: .login-art .hero{position:absolute;top:50%;inset-inline-end:-20px;transform:translateY(-62%) rotate(-8deg);width:58%;max-width:440px;filter:drop-shadow(0 30px 30px rgba(0,0,0,.15))}
 445: .login-art .hero2{position:absolute;top:18%;inset-inline-end:46%;width:22%;transform:rotate(12deg);filter:drop-shadow(0 20px 20px rgba(0,0,0,.12));opacity:.95}
 446: .login-art .ring{position:absolute;width:520px;height:520px;border-radius:50%;border:1px solid rgba(0,0,0,.06);top:12%;inset-inline-end:-140px}
 447: .login-form{display:flex;align-items:center;justify-content:center;padding:40px}
 448: .login-form form{width:100%;max-width:380px;display:flex;flex-direction:column;gap:18px}
 449: .login-form h1{font-family:var(--display);font-size:28px;font-weight:600;letter-spacing:.3px}
 450: .login-form .lead{color:var(--ink-3);font-size:13px;margin-top:-10px}
 451: .portal-tabs{display:flex;gap:6px}
 452: 
 453: /* ============ KIT PAGE ============ */
 454: .kit-sec{margin-bottom:40px}
 455: .kit-sec > h2{font-family:var(--display);font-size:20px;font-weight:600;margin-bottom:4px}
 456: .kit-sec > p{color:var(--ink-3);font-size:12.5px;margin-bottom:16px}
 457: .kit-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(280px,1fr));gap:16px}
 458: .kit-cell{border:1px solid var(--line);border-radius:var(--r2);padding:18px;background:#fff}
 459: .kit-cell .kl{font-family:var(--display);font-size:11px;letter-spacing:.8px;color:var(--ink-4);margin-bottom:12px}
 460: 
 461: /* perms */
 462: .perm-grp{border:1px solid var(--line);border-radius:var(--r2);margin-bottom:12px;overflow:hidden}
 463: .perm-grp-h{display:flex;align-items:center;gap:12px;padding:12px 16px;background:var(--soft-2);cursor:pointer}
 464: .perm-grp-h b{font-weight:600;font-size:13.5px}
 465: .perm-grp-h .cnt{margin-inline-start:auto;font-size:11.5px;color:var(--ink-4)}
 466: .perm-list{display:grid;grid-template-columns:repeat(2,1fr);gap:2px 16px;padding:8px 16px 14px}
 467: .perm{display:flex;align-items:center;gap:10px;padding:7px 0}
 468: .perm .k{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);direction:ltr;margin-inline-start:auto}
 469: .role-item{display:flex;align-items:center;gap:10px;padding:12px 14px;border-radius:var(--r);cursor:pointer;border:1px solid transparent}
 470: .role-item:hover{background:var(--soft-2)}
 471: .role-item.on{border-color:var(--ink);background:#fff}
 472: .role-item b{font-weight:600;font-size:13px;display:block}
 473: .role-item small{font-size:11.5px;color:var(--ink-4)}
 474: 
 475: .num-preview{display:flex;align-items:center;gap:14px;padding:16px 18px;background:var(--ink);color:#fff;border-radius:var(--r2)}
 476: .num-preview .big{font-family:var(--mono);font-size:20px;letter-spacing:1px;direction:ltr}
 477: .num-preview small{color:#aaa;font-size:11.5px;display:block}
 478: 
 479: .kv{display:grid;grid-template-columns:140px 1fr;gap:10px 16px;font-size:13px}
 480: .kv dt{color:var(--ink-4)}
 481: 
 482: /* ============ RESPONSIVE: variants become summary rows ============ */
 483: @media (max-width: 900px){
 484:   .app{grid-template-columns:1fr}
 485:   .side{display:none}
 486:   .content{padding:20px 16px 120px}
 487:   .page-band-in{padding:18px 16px 20px;flex-wrap:wrap}
 488:   .page-band .decor{display:none}
 489:   .page-band.has-decor .page-actions{margin-inline-end:0}
 490:   .sticky-bar{inset-inline-end:0;padding:10px 16px}
 491:   .g2,.g3,.g4{grid-template-columns:1fr}
 492:   .span2,.span3{grid-column:auto}
 493:   .split{grid-template-columns:1fr}
 494:   .login{grid-template-columns:1fr}.login-art{display:none}
 495:   table.vt{min-width:0}
 496:   .vt thead{display:none}
 497:   .vt tr.vrow{display:grid;grid-template-columns:1fr 1fr;gap:6px;padding:12px;border-bottom:1px solid var(--line)}
 498:   .vt tr.vrow td{border:0;padding:0}
 499:   .vt tr.vrow td[data-l]::before{content:attr(data-l);display:block;font-size:10.5px;color:var(--ink-4);margin-bottom:2px}
 500:   .vt tr.vrow td.mob-full{grid-column:1/-1}
 501:   .vt tr.vrow td.mob-hide{display:none}
 502:   .vt .cell{border-color:var(--line-2)}
 503:   .gen-row{grid-template-columns:1fr}
 504: }
 505: // ===== Product form: Variants & pricing tab, Media tab =====
 506: const COLOR_PRESETS = [
 507:   { ar: 'أسود', en: 'Black', hex: '#151515' }, { ar: 'جملي', en: 'Camel', hex: '#b98a5a' }, { ar: 'عنابي', en: 'Burgundy', hex: '#6d1f2c' },
 508:   { ar: 'بيج', en: 'Beige', hex: '#d9c7b0' }, { ar: 'كحلي', en: 'Navy', hex: '#1f2a44' }, { ar: 'زيتي', en: 'Olive', hex: '#5b5e3a' }, { ar: 'وردي فاتح', en: 'Blush', hex: '#e8b8bd' },
 509: ];
 510: const SIZE_PRESETS = ['صغير', 'وسط', 'كبير', 'Mini'];
 511: const CAP_PRESETS = ['10L', '15L', '20L', '30L'];
 512: const PRICE_RE = /^\d+(\.\d{1,2})?$/;
 513: const vKey = v => [(v.color_en || '').trim().toLowerCase(), (v.size || '').trim().toLowerCase(), (v.capacity || '').trim().toLowerCase()].join('|');
 514: const blankVariant = (o = {}) => ({ uid: Math.random().toString(36).slice(2, 8), color_ar: '', color_en: '', hex: '', size: '', capacity: '', sku: '', barcode: '', retail: '', wholesale: '', cost: '', compare: '', weight: '', reorder: '', order: '', active: true, ...o });
 515: 
 516: // client-side validation mirrors API rules; returns { idx: { field: msg } }
 517: function validateVariants(vs, channel) {
 518:   const errs = {}; const seen = {};
 519:   const put = (i, k, m) => { errs[i] = errs[i] || {}; errs[i][k] = m; };
 520:   vs.forEach((v, i) => {
 521:     if ((v.color_ar || v.hex) && !v.color_en) put(i, 'color_en', 'اسم اللون بالإنجليزية مطلوب');
 522:     const k = vKey(v); if (seen[k] != null) { put(i, 'combo', 'تركيبة مكررة مع الصف ' + (seen[k] + 1)); put(seen[k], 'combo', 'تركيبة مكررة مع الصف ' + (i + 1)); } else seen[k] = i;
 523:     ['retail', 'wholesale', 'cost', 'compare'].forEach(f => { if (v[f] !== '' && !PRICE_RE.test(String(v[f]))) put(i, f, 'رقم بحد أقصى منزلتين عشريتين'); });
 524:     if (v.active) {
 525:       if ((channel === 'retail' || channel === 'both') && v.retail === '') put(i, 'retail', 'مطلوب للتجزئة');
 526:       if ((channel === 'wholesale' || channel === 'both') && v.wholesale === '') put(i, 'wholesale', 'مطلوب للجملة');
 527:     }
 528:     if (v.compare !== '' && v.retail !== '' && +v.compare <= +v.retail) put(i, 'compare', 'يجب أن يكون أعلى من سعر التجزئة');
 529:   });
 530:   return errs;
 531: }
 532: 
 533: function ChipAxis({ label, hint, values, onChange, presets, placeholder }) {
 534:   const [t, setT] = useState('');
 535:   const add = v => { v = v.trim(); if (v && !values.includes(v)) onChange([...values, v]); setT(''); };
 536:   return (
 537:     <div className="gen-row">
 538:       <div className="gl">{label}<small>{hint}</small></div>
 539:       <div>
 540:         <div className="chips-input">
 541:           {values.map(v => <span key={v} className="vchip">{v}<button onClick={() => onChange(values.filter(x => x !== v))} aria-label="إزالة"><i className="fa-solid fa-xmark"></i></button></span>)}
 542:           <input value={t} onChange={e => setT(e.target.value)} placeholder={values.length ? '' : placeholder} onKeyDown={e => { if (e.key === 'Enter' || e.key === ',') { e.preventDefault(); add(t); } if (e.key === 'Backspace' && !t && values.length) onChange(values.slice(0, -1)); }} />
 543:         </div>
 544:         <div style={{ display: 'flex', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>
 545:           {presets.filter(p => !values.includes(p)).map(p => <button key={p} className="btn text sm" style={{ border: '1px dashed var(--line-2)' }} onClick={() => add(p)}>+ {p}</button>)}
 546:         </div>
 547:       </div>
 548:     </div>
 549:   );
 550: }
 551: 
 552: function ColorAxis({ colors, onChange }) {
 553:   const [n, setN] = useState({ ar: '', en: '', hex: '#8a6a4a' }); const [err, setErr] = useState(null);
 554:   const add = c => {
 555:     if (!c.en) { setErr('اسم اللون بالإنجليزية مطلوب لأنه جزء من التركيبة الفريدة.'); return; }
 556:     if (colors.some(x => x.en.toLowerCase() === c.en.toLowerCase())) { setErr('هذا اللون مضاف بالفعل.'); return; }
 557:     onChange([...colors, c]); setN({ ar: '', en: '', hex: '#8a6a4a' }); setErr(null);
 558:   };
 559:   return (
 560:     <div className="gen-row">
 561:       <div className="gl">الألوان<small>اختياري</small></div>
 562:       <div>
 563:         <div className="chips-input" style={{ minHeight: 38 }}>
 564:           {colors.map(c => <span key={c.en} className="vchip"><span className="sw" style={{ background: c.hex }}></span>{c.ar || c.en} <span className="muted ltr" style={{ fontSize: 11 }}>{c.ar ? c.en : ''}</span><button onClick={() => onChange(colors.filter(x => x !== c))}><i className="fa-solid fa-xmark"></i></button></span>)}
 565:           {!colors.length && <span className="muted" style={{ fontSize: 12.5, padding: '0 4px' }}>لم تُضف ألوان — اختر من الجاهز أو أضف لونًا</span>}
 566:         </div>
 567:         <div style={{ display: 'flex', gap: 6, marginTop: 8, flexWrap: 'wrap' }}>
 568:           {COLOR_PRESETS.filter(p => !colors.some(c => c.en === p.en)).map(p => <button key={p.en} className="btn text sm" style={{ border: '1px dashed var(--line-2)', gap: 6 }} onClick={() => add(p)}><span className="sw" style={{ width: 12, height: 12, borderRadius: '50%', background: p.hex, display: 'inline-block', border: '1px solid rgba(0,0,0,.1)' }}></span>{p.ar}</button>)}
 569:         </div>
 570:         <div style={{ display: 'grid', gridTemplateColumns: '40px 1fr 1fr auto', gap: 8, marginTop: 10, alignItems: 'center' }}>
 571:           <label className="swatch-in" style={{ width: 40, height: 40, borderRadius: 2, border: '1px solid var(--line-2)', background: n.hex, position: 'relative', overflow: 'hidden', cursor: 'pointer' }}>
 572:             <input type="color" value={n.hex} onChange={e => setN({ ...n, hex: e.target.value })} style={{ position: 'absolute', inset: -6, opacity: 0, cursor: 'pointer' }} aria-label="قيمة اللون" /></label>
 573:           <input className="inp" placeholder="اسم اللون بالعربي" value={n.ar} onChange={e => setN({ ...n, ar: e.target.value })} />
 574:           <input className={'inp ltr ' + (err ? 'err' : '')} dir="ltr" placeholder="English name *" value={n.en} onChange={e => { setN({ ...n, en: e.target.value }); setErr(null); }} onKeyDown={e => e.key === 'Enter' && add(n)} />
 575:           <Btn kind="ghost" onClick={() => add(n)}>إضافة</Btn>
 576:         </div>
 577:         {err && <div className="field-err" style={{ marginTop: 6 }}><i className="fa-solid fa-circle-exclamation"></i>{err}</div>}
 578:       </div>
 579:     </div>
 580:   );
 581: }
 582: 
 583: function VariantsTab({ p, setP, variants, setVariants, vErrs, canCost, isNew }) {
 584:   const [axes, setAxes] = useState(p.axes);
 585:   const [sel, setSel] = useState(new Set()); const [exp, setExp] = useState(new Set());
 586:   const [bulk, setBulk] = useState({ field: 'retail', val: '' }); const [confirmMode, setConfirmMode] = useState(null);
 587:   const cache = useRef({});
 588:   useEffect(() => { variants.forEach(v => { cache.current[vKey(v)] = v; }); }, [variants]);
 589:   const combos = useMemo(() => {
 590:     const C = axes.colors.length ? axes.colors : [null], S = axes.sizes.length ? axes.sizes : [null], K = axes.caps.length ? axes.caps : [null];
 591:     const out = []; C.forEach(c => S.forEach(s => K.forEach(k => out.push({ color_ar: c ? c.ar : '', color_en: c ? c.en : '', hex: c ? c.hex : '', size: s || '', capacity: k || '' })))); return out;
 592:   }, [axes]);
 593:   const existingKeys = new Set(variants.map(vKey));
 594:   const toAdd = combos.filter(c => !existingKeys.has(vKey(c)));
 595:   const comboKeys = new Set(combos.map(vKey));
 596:   const orphan = variants.filter(v => !comboKeys.has(vKey(v)));
 597:   const generate = () => {
 598:     // preserves typed values: keeps existing rows, restores cached rows, appends new
 599:     const keep = variants.filter(v => comboKeys.has(vKey(v)));
 600:     const added = toAdd.map(c => cache.current[vKey(c)] ? { ...cache.current[vKey(c)] } : blankVariant(c));
 601:     const next = [...keep, ...added].slice(0, 100);
 602:     setVariants(next); setP(x => ({ ...x, axes })); setSel(new Set());
 603:   };
 604:   const upd = (i, k, v) => setVariants(vs => vs.map((r, j) => j === i ? { ...r, [k]: v } : r));
 605:   const fillDown = k => { const from = sel.size ? Math.min(...sel) : 0; const val = variants[from][k]; setVariants(vs => vs.map((r, j) => j > from && (!sel.size || sel.has(j)) ? { ...r, [k]: val } : r)); };
 606:   const applyBulk = () => { if (!PRICE_RE.test(bulk.val)) return; setVariants(vs => vs.map((r, j) => sel.has(j) ? { ...r, [bulk.field]: bulk.val } : r)); };
 607:   const removeSel = () => { setVariants(vs => vs.filter((_, j) => !sel.has(j))); setSel(new Set()); };
 608:   const nav = (e, r, c) => {
 609:     const m = { ArrowDown: 1, Enter: 1, ArrowUp: -1 }[e.key]; if (!m) return; e.preventDefault();
 610:     const el = document.querySelector(`[data-vr="${r + m}"][data-vc="${c}"]`); if (el) { el.focus(); el.select && el.select(); }
 611:   };
 612:   const chReq = { retail: p.channel !== 'wholesale', wholesale: p.channel !== 'retail' };
 613:   const priceCols = [['retail', 'سعر التجزئة', chReq.retail], ['wholesale', 'سعر الجملة', chReq.wholesale], ...(canCost ? [['cost', 'التكلفة', false]] : []), ['compare', 'سعر المقارنة', false]];
 614:   const allSel = variants.length > 0 && sel.size === variants.length;
 615:   const usedAxes = { color: variants.some(v => v.color_en || v.color_ar), size: variants.some(v => v.size), cap: variants.some(v => v.capacity) };
 616: 
 617:   if (!p.mode) return (
 618:     <div className="panel" style={{ maxWidth: 760 }}>
 619:       <div className="panel-h"><div><h3>هل المنتج له أكثر من شكل؟</h3><p>اختر طريقة الإدخال. يمكنك التغيير لاحقًا قبل الحفظ.</p></div></div>
 620:       <div className="panel-b radio-cards g2" style={{ display: 'grid' }}>
 621:         <div className="rcard" onClick={() => { setP(x => ({ ...x, mode: 'single' })); setVariants([blankVariant()]); }}><span className="dot"></span><div><b>منتج بمتغير واحد</b><span>شكل واحد وسعر واحد — مثل محفظة كروت بلون واحد.</span></div></div>
 622:         <div className="rcard" onClick={() => setP(x => ({ ...x, mode: 'multi' }))}><span className="dot"></span><div><b>ألوان ومقاسات وسعات متعددة</b><span>ولّد التركيبات تلقائيًا: اللون × المقاس × السعة.</span></div></div>
 623:       </div>
 624:     </div>
 625:   );
 626: 
 627:   const errCount = Object.keys(vErrs).length;
 628:   return <div className="grid" style={{ gap: 22 }}>
 629:     <div style={{ display: 'flex', alignItems: 'center', gap: 12 }}>
 630:       <div className="seg">
 631:         <button className={p.mode === 'single' ? 'on' : ''} onClick={() => p.mode !== 'single' && setConfirmMode('single')}>متغير واحد</button>
 632:         <button className={p.mode === 'multi' ? 'on' : ''} onClick={() => p.mode !== 'multi' && setP(x => ({ ...x, mode: 'multi' }))}>متغيرات متعددة</button>
 633:       </div>
 634:       <span style={{ flex: 1 }}></span>
 635:       <span className="muted" style={{ fontSize: 12 }}>قناة البيع: <b style={{ color: 'var(--ink)' }}>{CHANNELS[p.channel]}</b> — الأسعار المطلوبة تتبعها</span>
 636:     </div>
 637: 
 638:     {!canCost && <Alert tone="info" icon="fa-solid fa-eye-slash">عمود «التكلفة» مخفي لأنك لا تملك صلاحية <span className="mono">products.view_cost</span>. القيم الحالية لن تتغير عند الحفظ.</Alert>}
 639: 
 640:     {p.mode === 'single' ? (
 641:       <div className="panel"><div className="panel-h"><h3>بيانات المتغير</h3></div><div className="panel-b grid g4">
 642:         {(() => { const v = variants[0] || blankVariant(); const e = vErrs[0] || {}; return <>
 643:           <Field label="SKU" opt help={isNew ? 'يتولد تلقائيًا عند تركه فارغًا.' : null}><Input ltr className="mono" value={v.sku} onChange={x => upd(0, 'sku', x.target.value)} placeholder="AUTO" /></Field>
 644:           <Field label="الباركود" opt help={isNew ? 'يتولد من الخادم عند تركه فارغًا.' : null}><Input ltr className="mono" value={v.barcode} onChange={x => upd(0, 'barcode', x.target.value)} placeholder="AUTO" /></Field>
 645:           <Field label="اللون (عربي)" opt><Input value={v.color_ar} onChange={x => upd(0, 'color_ar', x.target.value)} /></Field>
 646:           <Field label="اللون (إنجليزي)" req={!!(v.color_ar || v.hex)} error={e.color_en}><Input ltr value={v.color_en} error={e.color_en} onChange={x => upd(0, 'color_en', x.target.value)} /></Field>
 647:           {priceCols.map(([k, l, r]) => <Field key={k} label={l} req={r} error={e[k]}><div className="inp-wrap"><Input ltr value={v[k]} error={e[k]} onChange={x => upd(0, k, x.target.value)} placeholder="0.00" inputMode="decimal" /><span className="adorn" style={{ fontSize: 10.5 }}>EGP</span></div></Field>)}
 648:           <Field label="وزن المتغير (كجم)" opt><Input ltr value={v.weight} onChange={x => upd(0, 'weight', x.target.value)} /></Field>
 649:           <Field label="حد إعادة الطلب" opt help="الكمية الافتتاحية تُضاف من حركة المخزون."><Input ltr value={v.reorder} onChange={x => upd(0, 'reorder', x.target.value)} /></Field>
 650:         </>; })()}
 651:       </div></div>
 652:     ) : <>
 653:       <div className="gen-box">
 654:         <div className="panel-h" style={{ background: '#fff', borderRadius: '4px 4px 0 0' }}><div><h3>مولّد المتغيرات</h3><p>أداة إدخال فقط — يتم إرسال الصفوف الناتجة كمتغيرات.</p></div></div>
 655:         <ColorAxis colors={axes.colors} onChange={c => setAxes(a => ({ ...a, colors: c }))} />
 656:         <ChipAxis label="المقاسات" hint="اختياري" values={axes.sizes} onChange={s => setAxes(a => ({ ...a, sizes: s }))} presets={SIZE_PRESETS} placeholder="اكتب مقاسًا واضغط Enter" />
 657:         <ChipAxis label="السعة" hint="اختياري" values={axes.caps} onChange={s => setAxes(a => ({ ...a, caps: s }))} presets={CAP_PRESETS} placeholder="مثال: 20L" />
 658:         <div className="gen-foot">
 659:           <span className="mono" style={{ fontSize: 12.5 }}>{Math.max(axes.colors.length, 1)} × {Math.max(axes.sizes.length, 1)} × {Math.max(axes.caps.length, 1)} = <b>{combos.length}</b></span>
 660:           <span className="muted" style={{ fontSize: 12 }}>{toAdd.length ? `${toAdd.length} تركيبة جديدة` : 'لا تركيبات جديدة'}{orphan.length ? ` · ${orphan.length} ستُزال` : ''} · القيم المكتوبة تبقى كما هي</span>
 661:           <span style={{ flex: 1 }}></span>
 662:           {combos.length > 100 && <span className="field-err">الحد الأقصى ١٠٠ متغير في الطلب الواحد</span>}
 663:           <Btn icon="fa-solid fa-wand-magic-sparkles" disabled={(!toAdd.length && !orphan.length) || combos.length > 100} onClick={generate}>{variants.length ? 'تحديث التركيبات' : 'توليد التركيبات'}</Btn>
 664:         </div>
 665:       </div>
 666: 
 667:       {variants.length > 0 && <div>
 668:         <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 10 }}>
 669:           <h3 className="disp" style={{ fontSize: 16, fontWeight: 600 }}>المتغيرات</h3>
 670:           <div className="cnt-meter"><div className="bar"><i style={{ width: variants.length + '%' }}></i></div>{variants.length} / 100</div>
 671:           {errCount > 0 && <Badge tone="danger">{errCount} صفوف بها أخطاء</Badge>}
 672:           <span style={{ flex: 1 }}></span>
 673:           <span className="muted" style={{ fontSize: 11.5 }}><i className="fa-regular fa-keyboard"></i> ↑ ↓ Enter للتنقل بين الخلايا</span>
 674:         </div>
 675:         {sel.size > 0 && <div className="bulk-bar">
 676:           <b>{sel.size} محدد</b><span style={{ opacity: .4 }}>|</span>
 677:           <span>تطبيق</span>
 678:           <select className="inp" value={bulk.field} onChange={e => setBulk({ ...bulk, field: e.target.value })}>{priceCols.map(([k, l]) => <option key={k} value={k}>{l}</option>)}</select>
 679:           <input className="inp ltr" dir="ltr" placeholder="0.00" value={bulk.val} onChange={e => setBulk({ ...bulk, val: e.target.value })} onKeyDown={e => e.key === 'Enter' && applyBulk()} />
 680:           <Btn kind="accent" size="sm" onClick={applyBulk} disabled={!PRICE_RE.test(bulk.val)}>على الصفوف المحددة</Btn>
 681:           <span style={{ flex: 1 }}></span>
 682:           <Btn kind="ghost" size="sm" icon="fa-solid fa-toggle-off" onClick={() => setVariants(vs => vs.map((r, j) => sel.has(j) ? { ...r, active: false } : r))}>تعطيل</Btn>
 683:           <Btn kind="ghost" size="sm" icon="fa-regular fa-trash-can" onClick={removeSel}>حذف التركيبات غير المتاحة</Btn>
 684:           <button className="icon-btn" style={{ color: '#fff' }} onClick={() => setSel(new Set())}><i className="fa-solid fa-xmark"></i></button>
 685:         </div>}
 686:         <div className="vt-wrap">
 687:           <table className="vt">
 688:             <thead><tr>
 689:               <th style={{ width: 36 }}><Check checked={allSel} indeterminate={sel.size > 0 && !allSel} onChange={v => setSel(v ? new Set(variants.map((_, i) => i)) : new Set())} /></th>
 690:               {usedAxes.color && <th style={{ width: 210 }}>اللون</th>}
 691:               {usedAxes.size && <th style={{ width: 90 }}>المقاس</th>}
 692:               {usedAxes.cap && <th style={{ width: 80 }}>السعة</th>}
 693:               <th style={{ width: 150 }}>SKU</th><th style={{ width: 150 }}>الباركود</th>
 694:               {priceCols.map(([k, l, r]) => <th key={k} style={{ width: 118 }}>{l}{r && <span style={{ color: 'var(--danger)' }}> *</span>}<button className="fd" title={sel.size ? 'نسخ القيمة لأسفل في المحدد' : 'نسخ قيمة الصف الأول لكل الصفوف'} onClick={() => fillDown(k)}><i className="fa-solid fa-arrow-down-long"></i></button></th>)}
