 738: // ---------------- Media ----------------
 739: function MediaTab({ media, setMedia, variants, isNew, savedOnce }) {
 740:   const [dragI, setDragI] = useState(null); const [overI, setOverI] = useState(null);
 741:   const pendingNote = isNew && !savedOnce;
 742:   const addFiles = (target) => {
 743:     const pool = [IMG.bag1, IMG.bag2, IMG.bag3, IMG.shoulder];
 744:     const n = Math.min(3, 10 - media.general.length);
 745:     const files = Array.from({ length: n }).map((_, k) => ({ id: Math.random().toString(36).slice(2), src: pool[(media.general.length + k) % pool.length], name: `laila-${media.general.length + k + 1}.jpg`, size: (1.2 + k * .7).toFixed(1) + 'MB', state: pendingNote ? 'pending' : 'uploading', p: 0, variant: target || null }));
 746:     setMedia(m => ({ ...m, general: [...m.general, ...files] }));
 747:     if (!pendingNote) files.forEach(f => simulate(f.id));
 748:   };
 749:   const simulate = id => { let v = 0; const t = setInterval(() => { v += 12 + Math.random() * 18; setMedia(m => ({ ...m, general: m.general.map(f => f.id === id ? { ...f, p: Math.min(v, 100), state: v >= 100 ? 'done' : 'uploading' } : f) })); if (v >= 100) clearInterval(t); }, 220); };
 750:   const reorder = (from, to) => setMedia(m => { const g = [...m.general]; const [x] = g.splice(from, 1); g.splice(to, 0, x); return { ...m, general: g }; });
 751:   const generalOnly = media.general.filter(f => !f.variant);
 752:   const colorGroups = [...new Set(variants.map(v => v.color_en).filter(Boolean))];
 753:   const Tile = ({ f, idx }) => {
 754:     const gi = media.general.indexOf(f);
 755:     return <div className={'img-tile ' + (dragI === gi ? 'dragging ' : '') + (overI === gi ? 'over ' : '') + (f.state === 'failed' ? 'failed' : '')} draggable
 756:       onDragStart={() => setDragI(gi)} onDragOver={e => { e.preventDefault(); setOverI(gi); }} onDragLeave={() => setOverI(null)} onDrop={() => { reorder(dragI, gi); setDragI(null); setOverI(null); }} onDragEnd={() => { setDragI(null); setOverI(null); }}>
 757:       <img src={f.src} alt="" />
 758:       <span className="ord">{idx + 1}</span>
 759:       {idx === 0 && !f.variant && <span className="cover"><Badge tone="ink" nodot>الغلاف</Badge></span>}
 760:       {f.state === 'uploading' && <div className="veil"><div style={{ width: '70%' }}><div className="prog"><i style={{ width: f.p + '%' }}></i></div><div style={{ fontSize: 11, textAlign: 'center', marginTop: 4 }}>{Math.round(f.p)}%</div></div></div>}
 761:       {f.state === 'failed' && <div className="veil" style={{ background: 'rgba(255,245,247,.85)' }}><div style={{ textAlign: 'center', padding: 8 }}><i className="fa-solid fa-circle-exclamation" style={{ color: 'var(--danger)' }}></i><div style={{ fontSize: 11, margin: '4px 0 6px', color: 'var(--danger)' }}>{f.err || 'فشل الرفع'}</div><Btn size="sm" kind="ghost" onClick={() => { setMedia(m => ({ ...m, general: m.general.map(x => x.id === f.id ? { ...x, state: 'uploading', p: 0 } : x) })); simulate(f.id); }}>إعادة المحاولة</Btn></div></div>}
 762:       <div className="ov">
 763:         {f.state === 'pending' ? <span className="muted"><i className="fa-regular fa-clock"></i> بانتظار الحفظ</span> : f.state === 'done' ? <span style={{ color: 'var(--ok)' }}><i className="fa-solid fa-check"></i> مرفوعة</span> : <span></span>}
 764:         <span className="sp"></span>
 765:         <button className="icon-btn danger" style={{ width: 24, height: 24 }} onClick={() => setMedia(m => ({ ...m, general: m.general.filter(x => x.id !== f.id) }))} aria-label="حذف"><i className="fa-regular fa-trash-can" style={{ fontSize: 11 }}></i></button>
 766:       </div>
 767:     </div>;
 768:   };
 769:   return <div className="grid" style={{ gap: 22 }}>
 770:     {pendingNote && <Alert tone="info" icon="fa-solid fa-cloud-arrow-up" title="يمكنك اختيار الصور الآن">الرفع الفعلي يبدأ تلقائيًا بعد حفظ المنتج ومتغيراته — الصور المختارة محفوظة في النموذج.</Alert>}
 771:     <div className="panel">
 772:       <div className="panel-h"><div><h3>صور المنتج العامة</h3><p>اسحب لإعادة الترتيب — الصورة الأولى هي الغلاف في المتجر.</p></div><span className="sp"></span><span className="muted" style={{ fontSize: 12 }}>{generalOnly.length} صورة</span></div>
 773:       <div className="panel-b">
 774:         <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(140px,1fr))', gap: 14 }}>
 775:           {generalOnly.map((f, i) => <Tile key={f.id} f={f} idx={i} />)}
 776:           <div className="drop" style={{ aspectRatio: '1', justifyContent: 'center', padding: 12 }} onClick={() => addFiles(null)}>
 777:             <div className="di"><i className="fa-solid fa-plus"></i></div><b style={{ fontSize: 12 }}>إضافة صور</b>
 778:           </div>
 779:         </div>
 780:         <div className="drop" style={{ marginTop: 14, padding: 12, flexDirection: 'row', justifyContent: 'center', cursor: 'default' }}>
 781:           <div className="rules" style={{ margin: 0 }}><span>JPG · PNG · WebP</span><span>حتى 10 صور في الرفعة</span><span>5MB لكل صورة</span><span>حتى 6000×6000</span></div>
 782:         </div>
 783:       </div>
 784:     </div>
 785:     {colorGroups.length > 0 && <div className="panel">
 786:       <div className="panel-h"><div><h3>صور مرتبطة بالمتغيرات</h3><p>تظهر عند اختيار العميل لهذا المتغير. اختر المتغير ثم أضف صوره.</p></div></div>
 787:       <div className="panel-b grid" style={{ gap: 0 }}>
 788:         {colorGroups.map(c => { const vs = variants.filter(v => v.color_en === c); const imgs = media.general.filter(f => f.variant === c); return (
 789:           <div key={c} style={{ display: 'flex', gap: 16, alignItems: 'center', padding: '12px 0', borderBottom: '1px solid var(--line)' }}>
 790:             <span className="vchip" style={{ minWidth: 150 }}><span className="sw" style={{ background: vs[0].hex }}></span>{vs[0].color_ar || c} <span className="muted ltr" style={{ fontSize: 11 }}>{c}</span></span>
 791:             <span className="muted" style={{ fontSize: 11.5, width: 90 }}>{vs.length} متغيرات</span>
 792:             <div style={{ display: 'flex', gap: 8, flex: 1, flexWrap: 'wrap' }}>
 793:               {imgs.map((f, i) => <div key={f.id} style={{ width: 64 }}><Tile f={f} idx={i} /></div>)}
 794:               <button className="drop" style={{ width: 64, height: 64, padding: 0, justifyContent: 'center' }} onClick={() => addFiles(c)}><i className="fa-solid fa-plus muted"></i></button>
 795:             </div>
 796:           </div>); })}
 797:       </div>
 798:     </div>}
 799:     <div className="panel">
 800:       <div className="panel-h"><div><h3>فيديو المنتج</h3><p>فيديو واحد للمنتج — غير مرتبط بمتغير.</p></div></div>
 801:       <div className="panel-b">
 802:         {media.video ? <div className="file">
 803:           <div className="thumb" style={{ width: 80, height: 54, background: 'var(--ink)', color: '#fff' }}><i className="fa-solid fa-play"></i></div>
 804:           <div className="fmeta"><b className="ltr" style={{ textAlign: 'right' }}>laila-360-spin.mp4</b><small>38.4MB · 0:24</small>{media.video === 'uploading' && <div className="prog"><i style={{ width: '64%' }}></i></div>}</div>
 805:           {media.video === 'uploading' ? <span className="muted" style={{ fontSize: 12 }}>64%</span> : media.video === 'pending' ? <Badge>بانتظار الحفظ</Badge> : <Badge tone="ok">مرفوع</Badge>}
 806:           <button className="icon-btn danger" onClick={() => setMedia(m => ({ ...m, video: null }))}><i className="fa-regular fa-trash-can"></i></button>
 807:         </div> : <div className="drop" onClick={() => setMedia(m => ({ ...m, video: pendingNote ? 'pending' : 'uploading' }))}>
 808:           <div className="di"><i className="fa-solid fa-film"></i></div><b>أضف فيديو للمنتج</b><div className="rules"><span>MP4 · MOV · WebM</span><span>حتى 50MB</span></div></div>}
 809:       </div>
 810:     </div>
 811:   </div>;
