 820: function Field({ label, req, opt, help, error, children, className = '', htmlFor }) {
 821:   return (
 822:     <div className={'field ' + className}>
 823:       {label && <label className="field-label" htmlFor={htmlFor}>{label}{req && <span className="req" aria-label="مطلوب">*</span>}{opt && <span className="opt">(اختياري)</span>}</label>}
 824:       {children}
 825:       {error ? <div className="field-err" role="alert"><i className="fa-solid fa-circle-exclamation"></i><span>{error}</span></div>
 826:         : help ? <div className="field-help">{help}</div> : null}
 827:     </div>
 828:   );
 829: }
