 831: function Input({ error, ltr, className = '', ...p }) {
 832:   return <input className={'inp ' + (error ? 'err ' : '') + (ltr ? 'ltr ' : '') + className} dir={ltr ? 'ltr' : undefined} {...p} />;
 833: }
 834: function TextArea({ error, ltr, ...p }) {
 835:   return <textarea className={'inp ' + (error ? 'err' : '')} dir={ltr ? 'ltr' : undefined} {...p} />;
 836: }
 837: function PasswordInput({ error, ...p }) {
 838:   const [show, setShow] = useState(false);
 839:   return (
 840:     <div className="inp-wrap">
 841:       <input className={'inp ltr ' + (error ? 'err' : '')} dir="ltr" type={show ? 'text' : 'password'} {...p} />
 842:       <button type="button" className="adorn" onClick={() => setShow(s => !s)} aria-label={show ? 'إخفاء كلمة المرور' : 'إظهار كلمة المرور'}>
 843:         <i className={'fa-regular ' + (show ? 'fa-eye-slash' : 'fa-eye')}></i>
 844:       </button>
 845:     </div>
 846:   );
 847: }
 848: function Toggle({ checked, onChange, label, disabled }) {
 849:   return (
 850:     <label className={'tgl ' + (disabled ? 'disabled' : '')}>
 851:       <input type="checkbox" checked={!!checked} onChange={e => onChange && onChange(e.target.checked)} disabled={disabled} />
 852:       <span className="tr"></span>{label && <span>{label}</span>}
 853:     </label>
 854:   );
 855: }
 856: function Check({ checked, indeterminate, onChange, label, disabled }) {
 857:   const r = useRef();
 858:   useEffect(() => { if (r.current) r.current.indeterminate = !!indeterminate; }, [indeterminate]);
 859:   return (
 860:     <label className="chk" onClick={e => e.stopPropagation()}>
 861:       <input ref={r} type="checkbox" checked={!!checked} disabled={disabled} onChange={e => onChange && onChange(e.target.checked)} />
 862:       {label && <span>{label}</span>}
 863:     </label>
 864:   );
 865: }
 866: function Badge({ tone = '', children, nodot }) { return <span className={'badge ' + tone + (nodot ? ' nodot' : '')}>{children}</span>; }
 867: function StatusBadge({ active }) { return active ? <Badge tone="ok">نشط</Badge> : <Badge>غير نشط</Badge>; }
