 869: function Btn({ kind = '', size = '', icon, loading, children, ...p }) {
 870:   return (
 871:     <button className={['btn', kind, size].join(' ')} disabled={loading || p.disabled} {...p}>
 872:       {loading ? <span className="spin"></span> : icon ? <i className={icon}></i> : null}
 873:       {children}
 874:     </button>
 875:   );
 876: }
