 878: // ---- Searchable select (single / multi), with loading + empty + disabled options
 879: function SearchSelect({ options = [], value, onChange, placeholder = 'اختر…', multi, error, loadingDelay = 450, emptyText = 'لا توجد نتائج مطابقة', disabled, renderOpt, searchPh = 'ابحث…', clearable }) {
 880:   const [open, setOpen] = useState(false);
 881:   const [q, setQ] = useState('');
 882:   const [loading, setLoading] = useState(false);
 883:   const [hl, setHl] = useState(0);
 884:   const ref = useRef();
 885:   useEffect(() => {
 886:     if (!open) return;
 887:     const h = e => { if (ref.current && !ref.current.contains(e.target)) setOpen(false); };
 888:     document.addEventListener('mousedown', h); return () => document.removeEventListener('mousedown', h);
 889:   }, [open]);
 890:   useEffect(() => { if (open) { setLoading(true); const t = setTimeout(() => setLoading(false), loadingDelay); return () => clearTimeout(t); } }, [open, q]);
 891:   const filtered = options.filter(o => !q || (o.label + ' ' + (o.sub || '')).toLowerCase().includes(q.toLowerCase()));
 892:   const sel = multi ? options.filter(o => (value || []).includes(o.value)) : options.find(o => o.value === value);
 893:   const pick = o => {
 894:     if (o.disabled) return;
 895:     if (multi) { const v = value || []; onChange(v.includes(o.value) ? v.filter(x => x !== o.value) : [...v, o.value]); }
 896:     else { onChange(o.value); setOpen(false); }
 897:   };
 898:   return (
 899:     <div className="ss" ref={ref}>
 900:       <button type="button" disabled={disabled} className={'inp ss-trigger ' + (error ? 'err' : '')} onClick={() => setOpen(o => !o)} aria-haspopup="listbox" aria-expanded={open}>
 901:         <span className="val">
 902:           {multi ? (sel.length ? sel.map(s => s.label).join('، ') : <span className="ph">{placeholder}</span>)
 903:             : sel ? sel.label : <span className="ph">{placeholder}</span>}
 904:         </span>
 905:         {clearable && !multi && sel && <i className="fa-solid fa-xmark muted" onClick={e => { e.stopPropagation(); onChange(null); }}></i>}
 906:         <i className="fa-solid fa-chevron-down" style={{ fontSize: 10, color: 'var(--ink-4)' }}></i>
 907:       </button>
 908:       {open && (
 909:         <div className="ss-pop" role="listbox">
 910:           <div className="ss-search"><i className="fa-solid fa-magnifying-glass muted" style={{ fontSize: 12 }}></i>
 911:             <input autoFocus value={q} placeholder={searchPh} onChange={e => { setQ(e.target.value); setHl(0); }}
 912:               onKeyDown={e => {
 913:                 if (e.key === 'ArrowDown') { e.preventDefault(); setHl(h => Math.min(h + 1, filtered.length - 1)); }
 914:                 if (e.key === 'ArrowUp') { e.preventDefault(); setHl(h => Math.max(h - 1, 0)); }
 915:                 if (e.key === 'Enter') { e.preventDefault(); filtered[hl] && pick(filtered[hl]); }
 916:                 if (e.key === 'Escape') setOpen(false);
 917:               }} />
 918:           </div>
 919:           {loading ? (
 920:             <div className="ss-loading">{[70, 55, 80].map((w, i) => <div key={i} style={{ padding: '10px' }}><div className="sk" style={{ width: w + '%' }}></div></div>)}</div>
 921:           ) : filtered.length === 0 ? (
 922:             <div className="ss-empty"><i className="fa-regular fa-folder-open" style={{ display: 'block', fontSize: 18, marginBottom: 6 }}></i>{emptyText}{q && <> عن «{q}»</>}</div>
 923:           ) : (
 924:             <div className="ss-list">
 925:               {filtered.map((o, i) => {
 926:                 const isSel = multi ? (value || []).includes(o.value) : o.value === value;
 927:                 return (
 928:                   <div key={o.value ?? 'null'} className={'ss-opt ' + (isSel ? 'sel ' : '') + (o.disabled ? 'dis ' : '') + (i === hl ? 'hl' : '')} onMouseEnter={() => setHl(i)} onClick={() => pick(o)} title={o.why}>
 929:                     {renderOpt ? renderOpt(o) : <><span>{o.label}</span>{o.sub && <span className="muted" style={{ fontSize: 11.5 }}>{o.sub}</span>}</>}
 930:                     {o.why && <span className="why">{o.why}</span>}
 931:                   </div>
 932:                 );
 933:               })}
 934:             </div>
 935:           )}
 936:         </div>
 937:       )}
 938:     </div>
 939:   );
 940: }
