 942: // ---- states
 943: function EmptyState({ icon = 'fa-regular fa-folder-open', title, text, action }) {
 944:   return <div className="state"><div className="glyph"><i className={icon}></i></div><h4>{title}</h4>{text && <p>{text}</p>}{action && <div className="row">{action}</div>}</div>;
 945: }
 946: function ErrorState({ onRetry, code = '500', text = 'تعذّر تحميل البيانات من الخادم. تحقق من اتصالك وحاول مرة أخرى.' }) {
 947:   return <div className="state err"><div className="glyph"><i className="fa-solid fa-triangle-exclamation"></i></div><h4>حدث خطأ أثناء التحميل</h4><p>{text}</p><span className="code">HTTP {code}</span><div className="row"><Btn kind="ghost" icon="fa-solid fa-rotate-right" onClick={onRetry}>إعادة المحاولة</Btn></div></div>;
 948: }
 949: function NoAccessState({ perm, go }) {
 950:   return <div className="state lock"><div className="glyph"><i className="fa-solid fa-lock"></i></div><h4>ليس لديك صلاحية لعرض هذه الصفحة</h4><p>هذه الصفحة تتطلب صلاحية خاصة. تواصل مع مدير النظام لإضافتها إلى دورك.</p>{perm && <span className="code ltr">403 · {perm}</span>}<div className="row"><Btn kind="ghost" onClick={() => go && go('/products')}>العودة للمنتجات</Btn></div></div>;
 951: }
