 953: function Alert({ tone = 'info', icon, title, children, action, onClose }) {
 954:   const ic = icon || { info: 'fa-solid fa-circle-info', warn: 'fa-solid fa-triangle-exclamation', danger: 'fa-solid fa-circle-exclamation', ok: 'fa-solid fa-circle-check', ink: 'fa-solid fa-circle-info' }[tone];
 955:   return (
 956:     <div className={'alert ' + tone} role={tone === 'danger' ? 'alert' : 'status'}>
 957:       <i className={ic}></i>
 958:       <div className="grow">{title && <b>{title}</b>}{title && children ? <div>{children}</div> : children}</div>
 959:       {action}
 960:       {onClose && <button className="icon-btn" onClick={onClose} aria-label="إغلاق"><i className="fa-solid fa-xmark"></i></button>}
 961:     </div>
 962:   );
 963: }
 964: 
 965: // ---- Confirm modal; supports server rejection state
 966: function ConfirmModal({ open, tone = 'danger', icon, title, text, confirmLabel = 'تأكيد', onConfirm, onClose, rejectWith }) {
 967:   const [state, setState] = useState('idle'); const [err, setErr] = useState(null);
 968:   useEffect(() => { if (open) { setState('idle'); setErr(null); } }, [open]);
 969:   if (!open) return null;
 970:   const go = async () => {
 971:     setState('loading'); await sleep(700);
 972:     if (rejectWith) { setErr(rejectWith); setState('rejected'); return; }
 973:     onConfirm && onConfirm(); onClose();
 974:   };
 975:   return (
 976:     <div className="scrim" onMouseDown={e => e.target === e.currentTarget && onClose()}>
 977:       <div className="modal" role="dialog" aria-modal="true">
 978:         <div className="modal-b">
 979:           <div className={'mi ' + tone}><i className={icon || 'fa-regular fa-trash-can'}></i></div>
 980:           <div style={{ flex: 1 }}>
 981:             <h4>{title}</h4><p>{text}</p>
 982:             {state === 'rejected' && <div style={{ marginTop: 14 }}><Alert tone="danger" title="رفض الخادم العملية">{err}</Alert></div>}
 983:           </div>
 984:         </div>
 985:         <div className="modal-f">
 986:           <Btn kind="ghost" onClick={onClose}>{state === 'rejected' ? 'إغلاق' : 'إلغاء'}</Btn>
 987:           {state !== 'rejected' && <Btn kind={tone === 'danger' ? 'danger' : ''} loading={state === 'loading'} onClick={go}>{confirmLabel}</Btn>}
 988:         </div>
 989:       </div>
 990:     </div>
 991:   );
 992: }
 993: 
 994: function Drawer({ open, title, crumbs, onClose, children, footer, dirty }) {
 995:   const [ask, setAsk] = useState(false);
 996:   if (!open) return null;
 997:   const tryClose = () => dirty ? setAsk(true) : onClose();
 998:   return (
 999:     <div className="scrim drawer-scrim" onMouseDown={e => e.target === e.currentTarget && tryClose()}>
1000:       <div className="drawer" role="dialog" aria-modal="true">
1001:         <div className="drawer-h">
1002:           <div style={{ flex: 1 }}>{crumbs && <div className="crumbs">{crumbs}</div>}<h3>{title}</h3></div>
1003:           <button className="icon-btn" onClick={tryClose} aria-label="إغلاق"><i className="fa-solid fa-xmark"></i></button>
1004:         </div>
1005:         <div className="drawer-b">{children}</div>
1006:         {footer && <div className="drawer-f">{footer}</div>}
1007:       </div>
1008:       <ConfirmModal open={ask} tone="warn" icon="fa-solid fa-pen-to-square" title="تغييرات غير محفوظة"
1009:         text="لديك تعديلات لم تُحفظ بعد. إذا أغلقت الآن ستفقد هذه التعديلات." confirmLabel="تجاهل التغييرات"
1010:         onConfirm={onClose} onClose={() => setAsk(false)} />
1011:     </div>
1012:   );
1013: }
