1015: // ---- Page header (breadcrumb + title + primary action), echoes storefront hero band
1016: function PageHeader({ crumbs = [], light, bold, sub, actions, decor }) {
1017:   const { go } = useApp();
1018:   return (
1019:     <div className={'page-band ' + (decor ? 'has-decor' : '')}>
1020:       <div className="page-band-in">
1021:         <div>
1022:           <nav className="crumbs" aria-label="breadcrumb">
1023:             {crumbs.map((c, i) => <React.Fragment key={i}>
1024:               {i > 0 && <span className="sep">/</span>}
1025:               {i === crumbs.length - 1 ? <span className="cur">{c[0]}</span> : <a onClick={() => c[1] && go(c[1])}>{c[0]}</a>}
1026:             </React.Fragment>)}
1027:           </nav>
1028:           <h1 className="page-title">{light && <span className="lt">{light} </span>}<span className="bd">{bold}</span></h1>
1029:           {sub && <p className="page-sub">{sub}</p>}
1030:         </div>
1031:         {actions && <div className="page-actions">{actions}</div>}
1032:       </div>
1033:       {decor && <img className="decor" src={decor} alt="" />}
1034:     </div>
1035:   );
1036: }
