1111: // ---- Image uploader for single (category/brand logo) with constraints shown upfront
1112: function SingleImageUpload({ value, onChange, rules = ['JPG · PNG · WebP', 'حتى 4MB', 'حتى 6000×6000', 'SVG غير مدعوم'], error }) {
1113:   const [st, setSt] = useState(value ? 'done' : 'idle'); const [p, setP] = useState(0);
1114:   const pick = () => {
1115:     setSt('up'); setP(0);
1116:     let v = 0; const t = setInterval(() => { v += 18; setP(Math.min(v, 100)); if (v >= 100) { clearInterval(t); setSt('done'); onChange && onChange(IMG.bag3); } }, 120);
1117:   };
1118:   if (st === 'done' && value) return (
1119:     <div className="file">
1120:       <div className="thumb" style={{ width: 64, height: 64 }}><img src={value} alt="" /></div>
1121:       <div className="fmeta"><b className="ltr" style={{ textAlign: 'right' }}>category-cover.webp</b><small>1200×1200 · 312KB</small></div>
1122:       <Btn kind="ghost" size="sm" onClick={pick}>استبدال</Btn>
1123:       <button className="icon-btn danger" onClick={() => { onChange(null); setSt('idle'); }} aria-label="إزالة الصورة"><i className="fa-regular fa-trash-can"></i></button>
1124:     </div>
1125:   );
1126:   return (
1127:     <div>
1128:       <div className="drop" onClick={st === 'idle' ? pick : undefined} style={error ? { borderColor: 'var(--danger)' } : null}>
1129:         {st === 'up' ? <>
1130:           <b>جاري الرفع… {p}%</b><div className="prog" style={{ width: 200 }}><i style={{ width: p + '%' }}></i></div>
1131:         </> : <>
1132:           <div className="di"><i className="fa-solid fa-arrow-up-from-bracket"></i></div>
1133:           <b>اسحب الصورة هنا أو اضغط للاختيار</b>
1134:           <div className="rules">{rules.map(r => <span key={r}>{r}</span>)}</div>
1135:         </>}
1136:       </div>
1137:       {error && <div className="field-err" style={{ marginTop: 6 }}><i className="fa-solid fa-circle-exclamation"></i>{error}</div>}
1138:     </div>
1139:   );
1140: }
1141: 
