1312: 
1313: // ── useTweaks ───────────────────────────────────────────────────────────────
1314: // Single source of truth for tweak values. setTweak persists via the host
1315: // (__edit_mode_set_keys → host rewrites the EDITMODE block on disk).
1316: function useTweaks(defaults) {
1317:   const [values, setValues] = React.useState(defaults);
1318:   const setTweak = React.useCallback((keyOrEdits, val) => {
1319:     const edits = typeof keyOrEdits === 'object' && keyOrEdits !== null
1320:       ? keyOrEdits : { [keyOrEdits]: val };
1321:     setValues((prev) => ({ ...prev, ...edits }));
1322:     window.parent.postMessage({ type: '__edit_mode_set_keys', edits }, '*');
1323:     window.dispatchEvent(new CustomEvent('tweakchange', { detail: edits }));
1324:   }, []);
1325:   return [values, setTweak];
1326: }
1327: 
1328: // ── TweaksPanel ─────────────────────────────────────────────────────────────
1329: // Floating shell. Registers the protocol listener BEFORE announcing
1330: // availability — if the announce ran first, the host's activate could land
1331: // before our handler exists and the toolbar toggle would silently no-op.
1332: // The close button posts __edit_mode_dismissed so the host's toolbar toggle
1333: // flips off in lockstep; the host echoes __deactivate_edit_mode back which
1334: // is what actually hides the panel.
1335: function TweaksPanel({ title = 'Tweaks', noDeckControls = false, children }) {
1336:   const [open, setOpen] = React.useState(false);
1337:   const dragRef = React.useRef(null);
1338:   // Auto-inject a rail toggle when a <deck-stage> is on the page. The
1339:   // toggle drives the deck's per-viewer _railVisible via window message;
1340:   // state is mirrored from the same localStorage key the deck reads so
1341:   // the control reflects reality across reloads. The mechanism is the
1342:   // message — authors who want custom placement can post it directly
1343:   // and pass noDeckControls to suppress this one.
1344:   const hasDeckStage = React.useMemo(
1345:     () => typeof document !== 'undefined' && !!document.querySelector('deck-stage'),
1346:     [],
1347:   );
1348:   // deck-stage enables its rail in connectedCallback, but this panel can
1349:   // mount before that element has upgraded. The initial read catches the
1350:   // common case; the listener covers mounting first. (Older deck-stage.js
1351:   // copies still wait for the host's __omelette_rail_enabled postMessage —
1352:   // same listener handles those.)
1353:   const [railEnabled, setRailEnabled] = React.useState(
1354:     () => hasDeckStage && !!document.querySelector('deck-stage')?._railEnabled,
1355:   );
1356:   React.useEffect(() => {
1357:     if (!hasDeckStage || railEnabled) return undefined;
1358:     const onMsg = (e) => {
1359:       if (e.data && e.data.type === '__omelette_rail_enabled') setRailEnabled(true);
1360:     };
1361:     window.addEventListener('message', onMsg);
1362:     return () => window.removeEventListener('message', onMsg);
1363:   }, [hasDeckStage, railEnabled]);
1364:   const [railVisible, setRailVisible] = React.useState(() => {
1365:     try { return localStorage.getItem('deck-stage.railVisible') !== '0'; } catch (e) { return true; }
1366:   });
1367:   const toggleRail = (on) => {
1368:     setRailVisible(on);
1369:     window.postMessage({ type: '__deck_rail_visible', on }, '*');
1370:   };
1371:   const offsetRef = React.useRef({ x: 16, y: 16 });
1372:   const PAD = 16;
1373: 
1374:   const clampToViewport = React.useCallback(() => {
1375:     const panel = dragRef.current;
1376:     if (!panel) return;
1377:     const w = panel.offsetWidth, h = panel.offsetHeight;
1378:     const maxRight = Math.max(PAD, window.innerWidth - w - PAD);
1379:     const maxBottom = Math.max(PAD, window.innerHeight - h - PAD);
1380:     offsetRef.current = {
1381:       x: Math.min(maxRight, Math.max(PAD, offsetRef.current.x)),
1382:       y: Math.min(maxBottom, Math.max(PAD, offsetRef.current.y)),
1383:     };
1384:     panel.style.right = offsetRef.current.x + 'px';
1385:     panel.style.bottom = offsetRef.current.y + 'px';
1386:   }, []);
1387: 
1388:   React.useEffect(() => {
1389:     if (!open) return;
1390:     clampToViewport();
1391:     if (typeof ResizeObserver === 'undefined') {
1392:       window.addEventListener('resize', clampToViewport);
1393:       return () => window.removeEventListener('resize', clampToViewport);
1394:     }
1395:     const ro = new ResizeObserver(clampToViewport);
1396:     ro.observe(document.documentElement);
1397:     return () => ro.disconnect();
1398:   }, [open, clampToViewport]);
1399: 
1400:   React.useEffect(() => {
1401:     const onMsg = (e) => {
1402:       const t = e?.data?.type;
1403:       if (t === '__activate_edit_mode') setOpen(true);
1404:       else if (t === '__deactivate_edit_mode') setOpen(false);
1405:     };
1406:     window.addEventListener('message', onMsg);
1407:     window.parent.postMessage({ type: '__edit_mode_available' }, '*');
1408:     return () => window.removeEventListener('message', onMsg);
1409:   }, []);
1410: 
1411:   const dismiss = () => {
1412:     setOpen(false);
1413:     window.parent.postMessage({ type: '__edit_mode_dismissed' }, '*');
1414:   };
1415: 
1416:   const onDragStart = (e) => {
1417:     const panel = dragRef.current;
1418:     if (!panel) return;
1419:     const r = panel.getBoundingClientRect();
1420:     const sx = e.clientX, sy = e.clientY;
1421:     const startRight = window.innerWidth - r.right;
1422:     const startBottom = window.innerHeight - r.bottom;
1423:     const move = (ev) => {
1424:       offsetRef.current = {
1425:         x: startRight - (ev.clientX - sx),
1426:         y: startBottom - (ev.clientY - sy),
1427:       };
1428:       clampToViewport();
1429:     };
1430:     const up = () => {
1431:       window.removeEventListener('mousemove', move);
1432:       window.removeEventListener('mouseup', up);
1433:     };
1434:     window.addEventListener('mousemove', move);
1435:     window.addEventListener('mouseup', up);
1436:   };
1437: 
1438:   if (!open) return null;
1439:   return (
1440:     <>
1441:       <style>{__TWEAKS_STYLE}</style>
1442:       <div ref={dragRef} className="twk-panel" data-noncommentable=""
1443:            style={{ right: offsetRef.current.x, bottom: offsetRef.current.y }}>
1444:         <div className="twk-hd" onMouseDown={onDragStart}>
1445:           <b>{title}</b>
1446:           <button className="twk-x" aria-label="Close tweaks"
1447:                   onMouseDown={(e) => e.stopPropagation()}
1448:                   onClick={dismiss}>✕</button>
1449:         </div>
1450:         <div className="twk-body">
1451:           {children}
1452:           {hasDeckStage && railEnabled && !noDeckControls && (
1453:             <TweakSection label="Deck">
1454:               <TweakToggle label="Thumbnail rail" value={railVisible} onChange={toggleRail} />
1455:             </TweakSection>
1456:           )}
1457:         </div>
1458:       </div>
1459:     </>
1460:   );
1461: }
