1463: // ── Layout helpers ──────────────────────────────────────────────────────────
1464: 
1465: function TweakSection({ label, children }) {
1466:   return (
1467:     <>
1468:       <div className="twk-sect">{label}</div>
1469:       {children}
1470:     </>
1471:   );
1472: }
1473: 
1474: function TweakRow({ label, value, children, inline = false }) {
1475:   return (
1476:     <div className={inline ? 'twk-row twk-row-h' : 'twk-row'}>
1477:       <div className="twk-lbl">
1478:         <span>{label}</span>
1479:         {value != null && <span className="twk-val">{value}</span>}
1480:       </div>
1481:       {children}
1482:     </div>
1483:   );
1484: }
1485: 
1486: // ── Controls ────────────────────────────────────────────────────────────────
1487: 
1488: function TweakSlider({ label, value, min = 0, max = 100, step = 1, unit = '', onChange }) {
1489:   return (
1490:     <TweakRow label={label} value={`${value}${unit}`}>
1491:       <input type="range" className="twk-slider" min={min} max={max} step={step}
1492:              value={value} onChange={(e) => onChange(Number(e.target.value))} />
1493:     </TweakRow>
1494:   );
1495: }
1496: 
1497: function TweakToggle({ label, value, onChange }) {
1498:   return (
1499:     <div className="twk-row twk-row-h">
1500:       <div className="twk-lbl"><span>{label}</span></div>
1501:       <button type="button" className="twk-toggle" data-on={value ? '1' : '0'}
1502:               role="switch" aria-checked={!!value}
1503:               onClick={() => onChange(!value)}><i /></button>
1504:     </div>
1505:   );
1506: }
1507: 
1508: function TweakRadio({ label, value, options, onChange }) {
1509:   const trackRef = React.useRef(null);
1510:   const [dragging, setDragging] = React.useState(false);
1511:   // The active value is read by pointer-move handlers attached for the lifetime
1512:   // of a drag — ref it so a stale closure doesn't fire onChange for every move.
1513:   const valueRef = React.useRef(value);
1514:   valueRef.current = value;
1515: 
1516:   // Segments wrap mid-word once per-segment width runs out. The track is
1517:   // ~248px (280 panel − 28 body pad − 4 seg pad), each button loses 12px
1518:   // to its own padding, and 11.5px system-ui averages ~6.3px/char — so 2
1519:   // options fit ~16 chars each, 3 fit ~10. Past that (or >3 options), fall
1520:   // back to a dropdown rather than wrap.
1521:   const labelLen = (o) => String(typeof o === 'object' ? o.label : o).length;
1522:   const maxLen = options.reduce((m, o) => Math.max(m, labelLen(o)), 0);
1523:   const fitsAsSegments = maxLen <= ({ 2: 16, 3: 10 }[options.length] ?? 0);
1524:   if (!fitsAsSegments) {
1525:     // <select> emits strings — map back to the original option value so the
1526:     // fallback stays type-preserving (numbers, booleans) like the segment path.
1527:     const resolve = (s) => {
1528:       const m = options.find((o) => String(typeof o === 'object' ? o.value : o) === s);
1529:       return m === undefined ? s : typeof m === 'object' ? m.value : m;
1530:     };
1531:     return <TweakSelect label={label} value={value} options={options}
1532:                         onChange={(s) => onChange(resolve(s))} />;
1533:   }
1534:   const opts = options.map((o) => (typeof o === 'object' ? o : { value: o, label: o }));
1535:   const idx = Math.max(0, opts.findIndex((o) => o.value === value));
1536:   const n = opts.length;
1537: 
1538:   const segAt = (clientX) => {
1539:     const r = trackRef.current.getBoundingClientRect();
1540:     const inner = r.width - 4;
1541:     const i = Math.floor(((clientX - r.left - 2) / inner) * n);
1542:     return opts[Math.max(0, Math.min(n - 1, i))].value;
1543:   };
1544: 
1545:   const onPointerDown = (e) => {
1546:     setDragging(true);
1547:     const v0 = segAt(e.clientX);
1548:     if (v0 !== valueRef.current) onChange(v0);
1549:     const move = (ev) => {
1550:       if (!trackRef.current) return;
1551:       const v = segAt(ev.clientX);
1552:       if (v !== valueRef.current) onChange(v);
1553:     };
1554:     const up = () => {
1555:       setDragging(false);
1556:       window.removeEventListener('pointermove', move);
1557:       window.removeEventListener('pointerup', up);
1558:     };
1559:     window.addEventListener('pointermove', move);
1560:     window.addEventListener('pointerup', up);
1561:   };
1562: 
1563:   return (
1564:     <TweakRow label={label}>
1565:       <div ref={trackRef} role="radiogroup" onPointerDown={onPointerDown}
1566:            className={dragging ? 'twk-seg dragging' : 'twk-seg'}>
1567:         <div className="twk-seg-thumb"
1568:              style={{ left: `calc(2px + ${idx} * (100% - 4px) / ${n})`,
1569:                       width: `calc((100% - 4px) / ${n})` }} />
1570:         {opts.map((o) => (
1571:           <button key={o.value} type="button" role="radio" aria-checked={o.value === value}>
1572:             {o.label}
1573:           </button>
1574:         ))}
1575:       </div>
1576:     </TweakRow>
1577:   );
1578: }
1579: 
1580: function TweakSelect({ label, value, options, onChange }) {
1581:   return (
1582:     <TweakRow label={label}>
1583:       <select className="twk-field" value={value} onChange={(e) => onChange(e.target.value)}>
1584:         {options.map((o) => {
1585:           const v = typeof o === 'object' ? o.value : o;
1586:           const l = typeof o === 'object' ? o.label : o;
1587:           return <option key={v} value={v}>{l}</option>;
1588:         })}
1589:       </select>
1590:     </TweakRow>
1591:   );
1592: }
1593: 
1594: function TweakText({ label, value, placeholder, onChange }) {
1595:   return (
1596:     <TweakRow label={label}>
1597:       <input className="twk-field" type="text" value={value} placeholder={placeholder}
1598:              onChange={(e) => onChange(e.target.value)} />
1599:     </TweakRow>
1600:   );
1601: }
1602: 
1603: function TweakNumber({ label, value, min, max, step = 1, unit = '', onChange }) {
1604:   const clamp = (n) => {
1605:     if (min != null && n < min) return min;
1606:     if (max != null && n > max) return max;
1607:     return n;
1608:   };
1609:   const startRef = React.useRef({ x: 0, val: 0 });
1610:   const onScrubStart = (e) => {
1611:     e.preventDefault();
1612:     startRef.current = { x: e.clientX, val: value };
1613:     const decimals = (String(step).split('.')[1] || '').length;
1614:     const move = (ev) => {
1615:       const dx = ev.clientX - startRef.current.x;
1616:       const raw = startRef.current.val + dx * step;
1617:       const snapped = Math.round(raw / step) * step;
1618:       onChange(clamp(Number(snapped.toFixed(decimals))));
1619:     };
1620:     const up = () => {
1621:       window.removeEventListener('pointermove', move);
1622:       window.removeEventListener('pointerup', up);
1623:     };
1624:     window.addEventListener('pointermove', move);
1625:     window.addEventListener('pointerup', up);
1626:   };
1627:   return (
1628:     <div className="twk-num">
1629:       <span className="twk-num-lbl" onPointerDown={onScrubStart}>{label}</span>
1630:       <input type="number" value={value} min={min} max={max} step={step}
1631:              onChange={(e) => onChange(clamp(Number(e.target.value)))} />
1632:       {unit && <span className="twk-num-unit">{unit}</span>}
1633:     </div>
1634:   );
1635: }
1636: 
1637: // Relative-luminance contrast pick — checkmarks drawn over a swatch need to
1638: // read on both #111 and #fafafa without per-option configuration. Hex input
1639: // only (#rgb / #rrggbb); named or rgb()/hsl() colors fall through to "light".
1640: function __twkIsLight(hex) {
1641:   const h = String(hex).replace('#', '');
1642:   const x = h.length === 3 ? h.replace(/./g, (c) => c + c) : h.padEnd(6, '0');
1643:   const n = parseInt(x.slice(0, 6), 16);
1644:   if (Number.isNaN(n)) return true;
1645:   const r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
1646:   return r * 299 + g * 587 + b * 114 > 148000;
1647: }
1648: 
1649: const __TwkCheck = ({ light }) => (
1650:   <svg viewBox="0 0 14 14" aria-hidden="true">
1651:     <path d="M3 7.2 5.8 10 11 4.2" fill="none" strokeWidth="2.2"
1652:           strokeLinecap="round" strokeLinejoin="round"
1653:           stroke={light ? 'rgba(0,0,0,.78)' : '#fff'} />
1654:   </svg>
1655: );
1656: 
1657: // TweakColor — curated color/palette picker. Each option is either a single
1658: // hex string or an array of 1-5 hex strings; the card adapts — a lone color
1659: // renders solid, a palette renders colors[0] as the hero (left ~2/3) with the
1660: // rest stacked in a sharp column on the right. onChange emits the
1661: // option in the shape it was passed (string stays string, array stays array).
1662: // Without options it falls back to the native color input for back-compat.
1663: function TweakColor({ label, value, options, onChange }) {
1664:   if (!options || !options.length) {
1665:     return (
1666:       <div className="twk-row twk-row-h">
1667:         <div className="twk-lbl"><span>{label}</span></div>
1668:         <input type="color" className="twk-swatch" value={value}
1669:                onChange={(e) => onChange(e.target.value)} />
1670:       </div>
1671:     );
1672:   }
1673:   // Native <input type=color> emits lowercase hex per the HTML spec, so
1674:   // compare case-insensitively. String() guards JSON.stringify(undefined),
1675:   // which returns the primitive undefined (no .toLowerCase).
1676:   const key = (o) => String(JSON.stringify(o)).toLowerCase();
1677:   const cur = key(value);
1678:   return (
1679:     <TweakRow label={label}>
1680:       <div className="twk-chips" role="radiogroup">
1681:         {options.map((o, i) => {
1682:           const colors = Array.isArray(o) ? o : [o];
1683:           const [hero, ...rest] = colors;
1684:           const sup = rest.slice(0, 4);
1685:           const on = key(o) === cur;
1686:           return (
1687:             <button key={i} type="button" className="twk-chip" role="radio"
1688:                     aria-checked={on} data-on={on ? '1' : '0'}
1689:                     aria-label={colors.join(', ')} title={colors.join(' · ')}
1690:                     style={{ background: hero }}
1691:                     onClick={() => onChange(o)}>
1692:               {sup.length > 0 && (
1693:                 <span>
1694:                   {sup.map((c, j) => <i key={j} style={{ background: c }} />)}
1695:                 </span>
1696:               )}
1697:               {on && <__TwkCheck light={__twkIsLight(hero)} />}
1698:             </button>
1699:           );
1700:         })}
1701:       </div>
1702:     </TweakRow>
1703:   );
1704: }
1705: 
1706: function TweakButton({ label, onClick, secondary = false }) {
1707:   return (
1708:     <button type="button" className={secondary ? 'twk-btn secondary' : 'twk-btn'}
1709:             onClick={onClick}>{label}</button>
1710:   );
1711: }
1712: 
1713: Object.assign(window, {
1714:   useTweaks, TweaksPanel, TweakSection, TweakRow,
1715:   TweakSlider, TweakToggle, TweakRadio, TweakSelect,
1716:   TweakText, TweakNumber, TweakColor, TweakButton,
1717: });
