1719: // ── TweakSuggestionBar (flag-gated addon) ───────────────────────────────────
1720: (function () {
1721:   const s = document.createElement('style');
1722:   s.textContent = `
1723:     @keyframes twk-blink{50%{opacity:0}}
1724:     @keyframes twk-fadein{from{opacity:0;transform:translateX(4px)}to{opacity:1;transform:none}}
