1763: // Typewriter-cycles through `suggestions`. Clicking the field while a
1764: // suggestion is animating freezes it as ghost text; Tab accepts it into the
1765: // input. Enter posts __edit_mode_chat (host drops the text into the chat
1766: // composer for the user to send). After the cycle the static placeholder
1767: // types in and "Ideas" appears — clicking asks for three more suggestions.
1768: function TweakSuggestionBar({
1769:   suggestions = [],
1770:   placeholder = 'Describe a tweak…',
1771:   ideasPrompt = 'Suggest three more tweak ideas for this design and update the suggestions on TweakSuggestionBar.',
1772: }) {
1773:   const [val, setVal] = React.useState('');
1774:   const [ghost, setGhost] = React.useState('');
1775:   const [focused, setFocused] = React.useState(false);
1776:   const inputRef = React.useRef(null);
1777:   const tw = useTwkTypewriter(suggestions, { placeholder, enabled: !val && !ghost && !focused });
1778: 
1779:   const freeze = () => {
1780:     tw.markPlayed();
1781:     if (val || ghost) return;
1782:     const target = !tw.done ? suggestions[tw.idx] : '';
1783:     if (target) setGhost(target);
1784:     inputRef.current?.focus();
1785:   };
1786: 
1787:   const submit = () => {
1788:     const v = (val || ghost).trim();
1789:     if (!v) return;
1790:     __twkSendChat(v);
1791:     setVal('');
1792:     setGhost('');
1793:   };
1794: 
1795:   const onKeyDown = (e) => {
1796:     if (e.key === 'Tab' && ghost && !val) {
1797:       e.preventDefault();
1798:       setVal(ghost);
1799:       setGhost('');
1800:     } else if (e.key === 'Enter') {
1801:       e.preventDefault();
1802:       submit();
1803:     } else if (e.key === 'Escape') {
1804:       setGhost('');
1805:     }
1806:   };
1807: 
1808:   const requestIdeas = () => __twkSendChat(ideasPrompt);
1809: 
1810:   const showAnim = !val && !ghost && !focused && !tw.done;
1811:   const showStatic = !val && !ghost && !focused && tw.done;
1812: 
1813:   return (
1814:     <div className="twk-sugg" onMouseDown={freeze}>
1815:       <div className="twk-sugg-field">
1816:         <input
1817:           ref={inputRef}
1818:           value={val}
1819:           placeholder={focused && !ghost ? placeholder : ''}
1820:           onChange={(e) => { setVal(e.target.value); setGhost(''); }}
1821:           onFocus={() => { setFocused(true); tw.markPlayed(); }}
1822:           onBlur={() => { setFocused(false); if (!val) setGhost(''); }}
1823:           onKeyDown={onKeyDown}
1824:         />
1825:         {showAnim && (
1826:           <div className="twk-sugg-ghost">
1827:             {tw.text}<span className="twk-sugg-caret" />
1828:           </div>
1829:         )}
1830:         {showStatic && (
1831:           <div className="twk-sugg-ghost">
1832:             {tw.tail}{tw.tail.length < placeholder.length && <span className="twk-sugg-caret" />}
1833:           </div>
1834:         )}
1835:         {ghost && !val && (
1836:           <div className="twk-sugg-ghost hint">{ghost}</div>
1837:         )}
1838:       </div>
1839:       {val || ghost ? (
1840:         <button className="twk-sugg-send"
1841:                 onMouseDown={(e) => { e.stopPropagation(); e.preventDefault(); }}
1842:                 onClick={submit}>
1843:           Add
1844:         </button>
1845:       ) : tw.done && !focused ? (
1846:         <button className="twk-sugg-ideas"
1847:                 onMouseDown={(e) => { e.stopPropagation(); e.preventDefault(); }}
1848:                 onClick={requestIdeas}>
1849:           Ideas <__TwkSpark />
1850:         </button>
1851:       ) : null}
1852:     </div>
1853:   );
1854: }
