1856: // Minimal type→pause→erase cycler. Plays once per unique `items` content per
1857: // session — a reload from a tweak-value write skips straight to done; a new
1858: // suggestion set (after "Ideas") gets a fresh animation.
1859: function useTwkTypewriter(items, { placeholder, typeMs = 35, eraseMs = 22, pauseMs = 1800, enabled = true } = {}) {
1860:   // Dep mirrors the memo body verbatim so collidable joins like
1861:   // ['a\nb','c'] vs ['a','b','c'] don't share a stale sessionStorage key
1862:   // (gen-spark PR #28600 Bugbot R3 — minor divergence from Tiffany's
1863:   // `items.join('\n')` dep; upstream report pending).
1864:   const key = React.useMemo(() => '__twk_played:' + JSON.stringify(items), [JSON.stringify(items)]);
1865:   const played = () => { try { return sessionStorage.getItem(key) === '1'; } catch { return false; } };
1866: 
1867:   const [text, setText] = React.useState('');
1868:   const [tail, setTail] = React.useState(() => (items.length === 0 || played() ? placeholder : ''));
1869:   const [idx, setIdx] = React.useState(0);
1870:   const [done, setDone] = React.useState(() => items.length === 0 || played());
1871:   const phase = React.useRef('type');
1872:   const n = React.useRef(0);
1873: 
1874:   const markPlayed = React.useCallback(() => {
1875:     try { sessionStorage.setItem(key, '1'); } catch {}
1876:     setDone(true);
1877:   }, [key]);
1878: 
1879:   React.useEffect(() => {
1880:     const skip = items.length === 0 || played();
1881:     setText(''); setIdx(0);
1882:     setDone(skip);
1883:     setTail(skip ? placeholder : '');
1884:     phase.current = 'type'; n.current = 0;
1885:   }, [key]);
1886: 
1887:   React.useEffect(() => {
1888:     if (done || !enabled) return;
1889:     const item = items[idx] ?? '';
1890:     let t;
1891:     const tick = () => {
1892:       if (phase.current === 'type') {
1893:         n.current++;
1894:         setText(item.slice(0, n.current));
1895:         if (n.current >= item.length) { phase.current = 'pause'; t = setTimeout(tick, pauseMs); }
1896:         else t = setTimeout(tick, typeMs + Math.random() * 20);
1897:       } else if (phase.current === 'pause') {
1898:         phase.current = 'erase'; t = setTimeout(tick, eraseMs);
1899:       } else {
1900:         n.current--;
1901:         setText(item.slice(0, n.current));
1902:         if (n.current <= 0) {
1903:           if (idx === items.length - 1) { markPlayed(); return; }
1904:           phase.current = 'type'; setIdx((i) => i + 1);
1905:         } else t = setTimeout(tick, eraseMs);
1906:       }
1907:     };
1908:     phase.current = 'type'; n.current = 0; setText('');
1909:     t = setTimeout(tick, 400);
1910:     return () => clearTimeout(t);
1911:   }, [idx, done, key, enabled, typeMs, eraseMs, pauseMs]);
1912: 
1913:   React.useEffect(() => {
1914:     if (!done || tail === placeholder) return;
1915:     let i = 0;
1916:     const t = setInterval(() => {
1917:       i++; setTail(placeholder.slice(0, i));
1918:       if (i >= placeholder.length) clearInterval(t);
1919:     }, 28);
1920:     return () => clearInterval(t);
1921:   }, [done, placeholder]);
1922: 
1923:   return { text, tail, idx, done, markPlayed };
1924: }
