2051: function App() {
2052:   const [tw, setTweak] = useTweaks(TWEAK_DEFAULTS);
2053:   const [route, setRoute] = useState(parseHash());
2054:   const [toasts, setToasts] = useState([]);
2055:   const [sessionExpired, setSessionExpired] = useState(false);
2056:   useEffect(() => { const h = () => setRoute(parseHash()); window.addEventListener('hashchange', h); return () => window.removeEventListener('hashchange', h); }, []);
2057:   useEffect(() => { document.documentElement.style.setProperty('--accent', tw.accent); document.documentElement.style.setProperty('--band', tw.band); }, [tw.accent, tw.band]);
2058:   useEffect(() => { window.scrollTo(0, 0); }, [route.path]);
2059:   const go = (path, query) => { location.hash = buildHash(path, query); };
2060:   const setQuery = patch => { const q = { ...route.query, ...patch }; location.hash = buildHash(route.path, q); };
2061:   const toast = (text, tone) => { const id = Math.random(); setToasts(t => [...t, { id, text, tone }]); setTimeout(() => setToasts(t => t.filter(x => x.id !== id)), 3200); };
2062:   const can = p => {
2063:     if (!p) return true;
2064:     if (p === 'products.view_cost') return tw.canViewCost;
2065:     if (p === 'products.publish') return tw.canPublish;
2066:     if (p === 'roles.manage') return tw.canManageRoles;
2067:     return true;
2068:   };
2069:   const ctx = { route, go, setQuery, toast, can, tw, sessionExpired, setSessionExpired, forceState: tw.dataState === 'normal' ? null : tw.dataState };
2070:   const p = route.path.split('/').filter(Boolean);
2071:   let page;
2072:   if (p[0] === 'login' || !p[0]) page = <LoginPage />;
2073:   else {
2074:     let inner;
2075:     if (tw.dataState === 'forbidden' && p[0] !== 'kit') inner = <><PageHeader crumbs={[['الرئيسية', '/products'], ['غير مصرح']]} bold="غير مصرح" /><div className="content"><div className="panel"><NoAccessState perm={'products.view'} go={go} /></div></div></>;
2076:     else if (p[0] === 'products' && p[1]) inner = <ProductForm id={p[1]} key={p[1]} />;
2077:     else if (p[0] === 'products') inner = <ProductsPage />;
2078:     else if (p[0] === 'categories') inner = <CategoriesPage />;
2079:     else if (p[0] === 'brands') inner = <BrandsPage />;
2080:     else if (p[0] === 'branches' && p[1]) inner = <BranchDetail id={+p[1]} />;
2081:     else if (p[0] === 'branches') inner = <BranchesPage />;
2082:     else if (p[0] === 'users') inner = <UsersPage />;
