2433: Object.assign(window, { ProductForm });// ===== Phase 2: Categories tree, Brands, Products list =====
2434: const MAX_DEPTH = 3;
2435: function subtreeHeight(list, id) { const kids = list.filter(c => c.parent === id); return 1 + (kids.length ? Math.max(...kids.map(k => subtreeHeight(list, k.id))) : 0); }
2436: function isDescendant(list, id, maybeChild) { let c = list.find(x => x.id === maybeChild); while (c) { if (c.parent === id) return true; c = list.find(x => x.id === c.parent); } return false; }
2437: function depthOf(list, id) { let d = 0, c = list.find(x => x.id === id); while (c) { d++; c = list.find(x => x.id === c.parent); } return d; }
2438: function totalProducts(list, id) { return list.filter(c => c.parent === id).reduce((a, k) => a + totalProducts(list, k.id), list.find(c => c.id === id).products); }
