2450: 
2451:   const validDrop = (dragId, targetId, pos) => {
2452:     const t = list.find(c => c.id === targetId);
2453:     const newParent = pos === 'in' ? targetId : t.parent;
2454:     if (dragId === targetId) return 'لا يمكن نقل القسم داخل نفسه';
2455:     if (newParent && (newParent === dragId || isDescendant(list, dragId, newParent))) return 'لا يمكن النقل داخل أحد الأقسام الفرعية';
2456:     const pd = newParent ? depthOf(list, newParent) : 0;
