2462:       const t = L.find(c => c.id === targetId);
2463:       const newParent = pos === 'in' ? targetId : t.parent;
2464:       let sibs = L.filter(c => c.parent === newParent && c.id !== dragId).sort((a, b) => a.order - b.order);
2465:       let idx = pos === 'in' ? sibs.length : sibs.findIndex(s => s.id === targetId) + (pos === 'after' ? 1 : 0);
2466:       const moving = { ...L.find(c => c.id === dragId), parent: newParent };
2467:       sibs.splice(idx, 0, moving);
2468:       const orderMap = Object.fromEntries(sibs.map((s, i) => [s.id, i + 1]));
2469:       return L.map(c => c.id === dragId ? { ...moving, order: orderMap[c.id] } : orderMap[c.id] ? { ...c, order: orderMap[c.id] } : c);
2470:     });
