3003:                 <div key={o[0]} className={'rcard ' + (ret === o[0] ? 'on' : '')} onClick={d(() => setRet(o[0]))}><span className="dot"></span><div><b>{o[1]}</b><span>{o[2]}</span></div></div>)}
