19:     private static function canonicalize(mixed $value, ?string $field = null): mixed
20:     {
21:         if (is_numeric($value) && in_array($field, [
22:             'amount', 'subtotal', 'tax_amount', 'unit_cost', 'unit_price', 'line_total',
23:             'grand_total', 'discount_amount', 'total', 'total_amount', 'paid_amount',
24:             'expected_total',
25:         ], true)) {
26:             return (int) round(((float) $value) * 100);
27:         }
28: 
29:         if (is_string($value) && is_numeric($value)
30:             && ($field === 'id' || str_ends_with($field ?? '', '_id')
31:                 || in_array($field, ['qty', 'amount', 'received_good_qty', 'received_damaged_qty', 'quantity', 'requested_qty', 'counted_qty', 'approved_qty', 'shipped_qty', 'received_qty'], true))) {
32:             $value = $value + 0;
33:         }
34: 
35:         if (is_float($value) && floor($value) === $value && abs($value) <= 9007199254740991) {
36:             return (int) $value;
37:         }
38: 
39:         if (! is_array($value)) {
40:             return $value;
41:         }
42: 
43:         $isList = array_is_list($value);
44:         $mapped = [];
45:         foreach ($value as $key => $item) {
46:             $mapped[$key] = self::canonicalize($item, is_string($key) ? $key : null);
47:         }
48: 
49:         if ($isList && $mapped !== [] && self::isItemList($mapped)) {
50:             usort($mapped, self::itemSort(...));
51:         }
52: 
53:         if (! $isList) {
54:             ksort($mapped);
55:         }
56: 
57:         return $mapped;
58:     }
59: 
60:     /** @param list<mixed> $items */
61:     private static function isItemList(array $items): bool
62:     {
63:         foreach ($items as $item) {
64:             if (! is_array($item) || (! isset($item['id']) && ! isset($item['order_item_id']) && ! isset($item['purchase_order_item_id']) && ! isset($item['product_variant_id']))) {
65:                 return false;
66:             }
67:         }
68: 
69:         return true;
70:     }
71: 
72:     /** @param array<string, mixed> $left */
73:     private static function itemSort(array $left, array $right): int
74:     {
75:         foreach (['order_item_id', 'purchase_order_item_id', 'id', 'product_variant_id'] as $key) {
76:             if (isset($left[$key], $right[$key])) {
77:                 return $left[$key] <=> $right[$key];
78:             }
79:         }
80: 
81:         return 0;
82:     }
