 21: /**
 22:  * القلب النابض للمخزون — الطريق الوحيد لتغيير أي رصيد في النظام.
 23:  *
 24:  * قاعدة صارمة: ممنوع تعديل stock_levels من أي Controller أو Model آخر.
 25:  * كل تغيير يمر من هنا: تسجيل حركة في دفتر الأستاذ (stock_movements) أولًا،
 26:  * ثم تحديث الرصيد — داخل نفس الـ transaction ومع قفل الصف.
 27:  */
 28: class InventoryService
 29: {
 30:     public function __construct(private readonly SettingService $settings) {}
 31: 
 32:     /**
 33:      * الدالة المركزية الوحيدة لتغيير أي رصيد في النظام.
 34:      *
 35:      * @param  array{product_variant_id: int, branch_id: int, location_id?: int|null, type: StockMovementType|string, affected_bucket: StockBucket|string, quantity: float|int|string, unit_cost?: float|null, reference_type?: string|null, reference_id?: int|null, created_by?: int|null, notes?: string|null}  $data
 36:      */
 37:     public function recordMovement(array $data, ?StockLevel $prelockedLevel = null): StockMovement
 38:     {
 39:         $apply = function () use ($data, $prelockedLevel): StockMovement {
 40:             $rawQty = $data['quantity'];
 41:             if (! is_numeric($rawQty) || ! is_finite((float) $rawQty) || abs((float) $rawQty) > 99999999.9999) {
 42:                 throw new BusinessException('كمية الحركة غير صالحة.');
 43:             }
 44:             // Work in ten-thousandths to avoid floating point residues at zero.
 45:             $units = (int) round((float) $rawQty * 10000);
 46:             $qty = $units / 10000;
 47: 
 48:             if ($units === 0) {
 49:                 throw new BusinessException('كمية الحركة يجب ألا تساوي صفرًا.');
 50:             }
 51: 
 52:             $type = $data['type'] instanceof StockMovementType ? $data['type'] : StockMovementType::from($data['type']);
 53:             $bucket = $data['affected_bucket'] instanceof StockBucket ? $data['affected_bucket'] : StockBucket::from($data['affected_bucket']);
 54:             $this->assertValidMovementSemantics($type, $bucket, $units);
 55:             $locationId = $data['location_id'] ?? null;
 56: 
 57:             // صف مقفول مسبقًا من المستدعي (lockLevels): لا إعادة قفل ولا فحص موقع —
 58:             // المستدعي ضمن الصف والموقع عند القفل. خلاف ذلك نقفل هنا ونتحقق.
 59:             if ($prelockedLevel !== null) {
 60:                 if ((int) $prelockedLevel->product_variant_id !== (int) $data['product_variant_id']
 61:                     || (int) $prelockedLevel->branch_id !== (int) $data['branch_id']
 62:                     || ($prelockedLevel->location_id === null ? null : (int) $prelockedLevel->location_id) !== ($locationId === null ? null : (int) $locationId)) {
 63:                     throw new \LogicException('الصف المقفول مسبقًا لا يطابق مفتاح الحركة.');
 64:                 }
 65:                 $stock = $prelockedLevel;
 66:             } else {
 67:                 if ($locationId !== null && ! Location::query()->whereKey($locationId)->where('branch_id', $data['branch_id'])->exists()) {
 68:                     throw new BusinessException('الموقع لا يتبع الفرع المحدد.');
 69:                 }
 70: 
 71:                 $stock = $this->lockLevels([[
 72:                     'product_variant_id' => $data['product_variant_id'],
 73:                     'branch_id' => $data['branch_id'],
 74:                     'location_id' => $locationId,
 75:                 ]])->first();
 76:             }
 77: 
 78:             if ($bucket === StockBucket::OnHand && $units > 0) {
 79:                 $variant = $stock->variant;
 80:                 if ($variant === null || $variant->trashed() || ! $variant->is_active
 81:                     || ($stock->location_id !== null && ! $stock->location?->is_active)) {
 82:                     throw new BusinessException('الإدخال يتطلب متغيرًا وموقعًا نشطين.');
 83:                 }
 84:             }
 85: 
 86:             $bucketKey = $bucket->value;
 87:             $before = (float) $stock->{$bucketKey};
 88:             $afterUnits = (int) round($before * 10000) + $units;
 89:             $after = $afterUnits / 10000;
 90:             if ($afterUnits > 999999999999) {
 91:                 throw new BusinessException('الرصيد يتجاوز الحد المسموح.');
 92:             }
 93: 
 94:             // 2. التحقق: الرصيد المستهدف لا ينزل تحت الصفر
 95:             if ($after < 0) {
 96:                 throw new BusinessException("الرصيد غير كافٍ في ({$bucketKey}) لإتمام العملية.");
 97:             }
 98: 
 99:             // 3. التحقق: الكمية المتاحة للبيع لا تصبح سالبة بعد الحركة
100:             //    (يغطي حجز/تالف جديد أكبر من المتاح، وسحب فعلي يبتلع محجوزًا أو تالفًا)
101:             $onHand = $bucket === StockBucket::OnHand ? $after : (float) $stock->on_hand;
102:             $reserved = $bucket === StockBucket::Reserved ? $after : (float) $stock->reserved;
103:             $damaged = $bucket === StockBucket::Damaged ? $after : (float) $stock->damaged;
104:             $availableAfter = (int) round($onHand * 10000) - (int) round($reserved * 10000) - (int) round($damaged * 10000);
105: 
106:             if ($availableAfter < 0) {
107:                 $availableNow = (float) $stock->on_hand - (float) $stock->reserved - (float) $stock->damaged;
108: 
109:                 throw new BusinessException("الكمية المتاحة للبيع ({$availableNow}) غير كافية لإتمام العملية.");
110:             }
111: 
112:             // منفّذ الحركة إلزامي: من console/queue بلا مستخدم مصادق وبلا created_by
113:             // صريح، الفشل الواضح أفضل من QueryException على قيد NOT NULL.
114:             $createdBy = $data['created_by'] ?? auth()->id();
115:             if ($createdBy === null) {
116:                 throw new \LogicException('recordMovement يتطلب created_by صريحًا عند غياب مستخدم مصادق.');
117:             }
118: 
119:             // مرجع الدفتر يُخزن بالاسم القصير من morph map إن وُجد (stock_transfer/stocktake)
120:             // حتى لا تكسر إعادة تسمية الكلاسات أثر التدقيق؛ الأسماء الكاملة القديمة تظل مقروءة.
121:             $referenceType = $data['reference_type'] ?? null;
122:             if (is_string($referenceType) && class_exists($referenceType)) {
123:                 $referenceType = (new $referenceType)->getMorphClass();
124:             }
125: 
126:             // 4. تسجيل الحركة في دفتر الأستاذ (Ledger)
127:             $movement = StockMovement::query()->create([
128:                 'reference_number' => $this->settings->generateNextNumber('movement'),
129:                 'product_variant_id' => $data['product_variant_id'],
130:                 'branch_id' => $data['branch_id'],
131:                 'location_id' => $locationId,
132:                 'type' => $type,
133:                 'affected_bucket' => $bucket,
134:                 'quantity' => $qty,
135:                 'balance_before' => $before,
136:                 'balance_after' => $after,
137:                 'unit_cost' => $data['unit_cost'] ?? null,
138:                 'reference_type' => $referenceType,
139:                 'reference_id' => $data['reference_id'] ?? null,
140:                 'created_by' => $createdBy,
141:                 'notes' => $data['notes'] ?? null,
142:             ]);
143: 
144:             // 5. تحديث جدول الأرصدة من واقع الحركة
145:             $stock->{$bucketKey} = $after;
146:             $stock->save();
147: 
148:             // 6. حدث انخفاض المخزون: فقط عند عبور حد إعادة الطلب الفعّال نزولًا
149:             //    (الحد الفعّال = حد صف الرصيد إن وُجد وإلا حد المتغير) حتى لا
150:             //    تتكرر التنبيهات مع كل حركة والرصيد تحت الحد أصلًا.
151:             // حد المتغير متاح بلا استعلام إضافي: lockLevels يحمّل العلاقة
152:             // جزئيًا بالأعمدة id/is_active/deleted_at/reorder_level.
153:             $level = (float) $stock->reorder_level;
154:             if ($level <= 0) {
155:                 $level = (float) ($stock->variant?->reorder_level ?? 0);
156:             }
157:             if ($level > 0) {
158:                 $effectOnAvailable = match ($bucket) {
159:                     StockBucket::OnHand => $units,
160:                     StockBucket::Reserved, StockBucket::Damaged => -$units,
161:                     default => 0,
162:                 };
163:                 $availableBeforeUnits = $availableAfter - $effectOnAvailable;
164:                 $availableAfterQty = $availableAfter / 10000;
165:                 if ($availableBeforeUnits / 10000 > $level && $availableAfterQty <= $level) {
166:                     StockLowDetected::dispatch(
167:                         (int) $stock->product_variant_id,
168:                         (int) $stock->branch_id,
169:                         $availableAfterQty,
170:                         $level,
171:                     );
172:                 }
173:             }
174: 
175:             return $movement;
176:         };
177: 
178:         if ($prelockedLevel !== null) {
179:             if (DB::transactionLevel() === 0) {
180:                 throw new \LogicException('Prelocked stock requires an active transaction.');
181:             }
182: 
183:             return $apply();
184:         }
185: 
186:         return DB::transaction($apply);
187:     }
