343:     /** Acquire every stock key before a multi-item operation, in one global order. */
344:     public function lockLevels(array $keys): Collection
345:     {
346:         if (DB::transactionLevel() === 0) {
347:             throw new \LogicException('Stock locks require an active transaction.');
348:         }
349:         // انتظار محدود للأقفال داخل هذه المعاملة فقط؛ التنافس الطويل يتحول لرفض
350:         // واضح (409) بدل تعليق الطلب حتى مهلة PHP-FPM.
351:         DB::statement("SET LOCAL lock_timeout = '5s'");
352:         $keys = collect($keys)->unique(fn ($key) => $this->levelKey($key))
353:             ->sortBy(fn ($key) => [(int) $key['branch_id'], (int) ($key['location_id'] ?? 0), (int) $key['product_variant_id']]);
354:         if ($keys->isEmpty()) {
355:             return collect();
356:         }
357:         $now = now();
358: 
359:         try {
360:             // الإدخال نفسه قد ينتظر قفلًا: ON CONFLICT ينتظر معاملة أخرى أدخلت
361:             // نفس المفتاح ولم تعتمد بعد، فيخضع لنفس lock_timeout — لازم يكون
362:             // جوه الـ try حتى يتحول الانتظار الطويل لـ 409 لا 500 (M-2).
363:             DB::table('stock_levels')->insertOrIgnore($keys->map(fn ($key) => [
364:                 'product_variant_id' => $key['product_variant_id'], 'branch_id' => $key['branch_id'],
365:                 'location_id' => $key['location_id'] ?? null, 'created_at' => $now, 'updated_at' => $now,
366:             ])->values()->all());
367: 
368:             $levels = StockLevel::query()->with(['variant:id,is_active,deleted_at,reorder_level', 'location:id,is_active'])->where(function ($query) use ($keys): void {
369:                 foreach ($keys->groupBy(fn ($key) => $key['branch_id'].':'.($key['location_id'] ?? 0)) as $group) {
370:                     $identity = $group->first();
371:                     $query->orWhere(fn ($scope) => $scope->where('branch_id', $identity['branch_id'])
372:                         ->where('location_id', $identity['location_id'] ?? null)
373:                         ->whereIn('product_variant_id', $group->pluck('product_variant_id')->all()));
374:                 }
375:             })->orderBy('branch_id')->orderByRaw('location_id ASC NULLS FIRST')->orderBy('product_variant_id')
376:                 ->lockForUpdate()->get()->keyBy(fn ($stock) => $this->levelKey($stock->getAttributes()));
377:         } catch (QueryException $e) {
378:             // 55P03 = lock_timeout، و40P01 = deadlock — كلاهما ازدحام مؤقت
379:             // على الأقفال، فيُرجع 409 قابلًا لإعادة المحاولة لا 500 (M-2).
380:             if (in_array($e->errorInfo[0] ?? $e->getCode(), ['55P03', '40P01'], true)) {
381:                 throw new BusinessException('المخزون مشغول بعملية أخرى الآن؛ أعد المحاولة بعد لحظات.', [], 409);
382:             }
383: 
384:             throw $e;
385:         }
386: 
387:         return $levels;
388:     }
389: 
390:     public function levelKey(array $key): string
391:     {
392:         return $key['branch_id'].':'.($key['location_id'] ?? 0).':'.$key['product_variant_id'];
393:     }
394: 
395:     private function assertValidMovementSemantics(StockMovementType $type, StockBucket $bucket, int $units): void
396:     {
397:         [$allowed, $positive] = match ($type) {
398:             StockMovementType::ProductionReceipt, StockMovementType::PurchaseReceipt, StockMovementType::SaleReturn,
399:             StockMovementType::AdjustmentIn, StockMovementType::StocktakeGain, StockMovementType::TransferIn => [[StockBucket::OnHand], true],
400:             StockMovementType::Sale, StockMovementType::AdjustmentOut,
401:             StockMovementType::StocktakeLoss, StockMovementType::TransferOut,
402:             StockMovementType::DamageWriteOff => [[StockBucket::OnHand], false],
403:             StockMovementType::Damage => [[StockBucket::Damaged], true],
404:             StockMovementType::DamageRelease => [[StockBucket::Damaged], false],
405:             StockMovementType::Reserve => [[StockBucket::Reserved], true],
406:             StockMovementType::ReleaseReserve => [[StockBucket::Reserved], false],
407:             StockMovementType::TransferInTransit => [[StockBucket::InTransit], true],
408:             StockMovementType::TransferTransitRelease, StockMovementType::TransferShortage => [[StockBucket::InTransit], false],
409:         };
410:         if (! in_array($bucket, $allowed, true) || ($units > 0) !== $positive) {
411:             throw new BusinessException('نوع الحركة لا يطابق وعاء المخزون أو اتجاه الكمية.');
412:         }
413:     }
