 19: /**
 20:  * محرك التسعير المركزي — يُستدعى من المتجر والجملة والـ POS ولوحة الإدارة.
 21:  *
 22:  * شجرة الأولويات:
 23:  * 1. سعر خاص بالعميل (customer_specific)
 24:  * 2. سعر مجموعة العميل (customer_group)
 25:  * 3. قائمة النوع (wholesale/distributor للمعتمدين فقط، وإلا retail)؛ وقناة
 26:  *    جملة/موزع بلا عنصر مطابق ترجع لقوائم retail النشطة قبل السعر الأساسي.
 27:  * 4. السعر الأساسي للمتغير (base_price، المتوافق مع retail_price من المرحلة 2).
 28:  *
 29:  * خصم مجموعة العميل (discount_percentage) لا يصنع مستوى مستقلًا: يُطبق فوق ناتج
 30:  * المستويين 3/4 (سعر القناة)، ولا يُخصم من سعر خاص بالعميل أو سعر قائمة المجموعة.
 31:  * متغير بلا retail_price ولا قائمة مطابقة = غير مُسعَّر، ويرمي BusinessException.
 32:  *
 33:  * داخل كل مستوى: القائمة المخصصة للفرع أولًا، ثم أعلى شريحة كمية محققة،
 34:  * ثم أولوية القائمة، ثم السعر الأقل.
 35:  */
 36: class PricingService
 37: {
 38:     /** Resolve storefront prices in SQL using the same owner, tier and priority rules as resolve(). */
 39:     public function withStorePrice(Builder $variants, ?Customer $customer): Builder
 40:     {
 41:         $eligible = $customer !== null && $customer->status === CustomerStatus::Approved;
 42:         $channel = $this->channelFor($customer);
 43:         $group = $eligible ? $customer->customerGroup : null;
 44:         $group = $group?->is_active ? $group : null;
 45:         $factor = $this->discountFactor($group?->discount_percentage ?? '0');
 46:         $items = $this->eligibleItems(null, 1, null, Carbon::now())
 47:             ->where(function ($q) use ($eligible, $customer, $group, $channel): void {
 48:                 $q->whereIn('price_lists.type', array_unique([$channel->value, PriceListType::Retail->value]));
 49:                 if ($eligible) {
 50:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
 51:                         ->where('price_lists.customer_id', $customer->id));
 52:                 }
 53:                 if ($group !== null) {
 54:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
 55:                         ->where('price_lists.customer_group_id', $group->id));
 56:                 }
 57:             })
 58:             ->select([])
 59:             ->selectRaw("price_list_items.price * CASE WHEN price_lists.type IN ('customer_specific', 'customer_group') THEN 1::numeric ELSE ?::numeric END", [$factor])
 60:             ->orderByRaw("CASE WHEN price_lists.type = 'customer_specific' THEN 0 WHEN price_lists.type = 'customer_group' THEN 1 WHEN price_lists.type = ? THEN 2 ELSE 3 END", [$channel->value]);
 61:         $items = $this->ordered($items)->limit(1);
 62: 
 63:         return $variants->select('product_variants.*')
 64:             ->selectRaw('ROUND(COALESCE(('.$items->toSql().'), product_variants.retail_price * ?)::numeric, 2) AS store_price', [...$items->getBindings(), $factor]);
 65:     }
 66: 
 67:     /**
 68:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
 69:      */
 70:     public function resolve(
 71:         ProductVariant $variant,
 72:         ?Customer $customer = null,
 73:         float $qty = 1,
 74:         ?int $branchId = null,
 75:     ): array {
 76:         if (! is_finite($qty) || $qty <= 0) {
 77:             throw new BusinessException('كمية التسعير يجب أن تكون موجبة.');
 78:         }
 79:         $now = Carbon::now();
 80: 
 81:         $baseQuery = $this->eligibleItems($variant, $qty, $branchId, $now);
 82:         $channel = $this->channelFor($customer);
 83:         $eligibleCustomer = $customer !== null && $customer->status === CustomerStatus::Approved;
 84: 
 85:         // الأولوية 1: سعر خاص بالعميل
 86:         if ($eligibleCustomer) {
 87:             $item = $this->ordered((clone $baseQuery)
 88:                 ->where('price_lists.type', PriceListType::CustomerSpecific)
 89:                 ->where('price_lists.customer_id', $customer->id)
 90:             )->first();
 91: 
 92:             if ($item !== null) {
 93:                 return $this->formatResponse($item->price, PriceListType::CustomerSpecific->value, (int) $item->price_list_id, $variant, $channel);
 94:             }
 95:         }
 96: 
 97:         // الأولوية 2: سعر مجموعة العميل
 98:         $group = $eligibleCustomer ? $customer->customerGroup()->where('is_active', true)->first() : null;
 99:         if ($group !== null) {
100:             $item = $this->ordered((clone $baseQuery)
101:                 ->where('price_lists.type', PriceListType::CustomerGroup)
102:                 ->where('price_lists.customer_group_id', $group->id)
103:             )->first();
104: 
105:             if ($item !== null) {
106:                 return $this->formatResponse($item->price, PriceListType::CustomerGroup->value, (int) $item->price_list_id, $variant, $channel);
107:             }
108:         }
109: 
110:         // الأولوية 3: قائمة نوع العميل (أو القطاعي افتراضيًا)
111:         $item = $this->ordered((clone $baseQuery)
112:             ->where('price_lists.type', $channel)
113:         )->first();
114: 
115:         // قناة جملة/موزع بلا عنصر في قائمتها ترجع لقوائم القطاعي النشطة قبل
116:         // السعر الأساسي — وإلا دفع عميل الجملة أكثر من عميل التجزئة (M-1).
117:         if ($item === null && $channel !== PriceListType::Retail) {
118:             $item = $this->ordered((clone $baseQuery)
119:                 ->where('price_lists.type', PriceListType::Retail)
120:             )->first();
121: 
122:             if ($item !== null) {
123:                 $channel = PriceListType::Retail;
124:             }
125:         }
126: 
127:         if ($item !== null) {
128:             $channelPrice = (string) $item->price;
129:             $channelListId = (int) $item->price_list_id;
130:             $channelSource = $channel->value;
131:         } elseif ($variant->retail_price === null) {
132:             // الأولوية 4 مستحيلة: لا قائمة مطابقة ولا سعر قطاعي — الصنف غير مُسعَّر
133:             // ولا يجوز أن يخرج بسعر صفر ليُباع مجانًا.
134:             throw new BusinessException('الصنف غير مُسعَّر: لا توجد قائمة أسعار مطابقة ولا سعر قطاعي للمتغير.');
135:         } else {
136:             // الأولوية 4: السعر الأساسي الموحد؛ أسعار الجملة والموزعين تأتي من القوائم.
137:             $channelPrice = $this->basePrice($variant, $channel);
138:             $channelListId = null;
139:             $channelSource = 'base_price';
140:         }
141: 
142:         // خصم مجموعة العميل يُطبق "فوق" سعر القناة المحسوب (قائمة القناة أو الأساسي)،
143:         // ولا يتجاوزه أبدًا — فلا يخسر العميل سعر جملة/موزع أفضل بسبب خصم مجموعته.
144:         if ($group !== null && (float) $group->discount_percentage > 0) {
145:             return $this->formatResponse(
146:                 (string) BigDecimal::of($channelPrice)->multipliedBy($this->discountFactor($group->discount_percentage)),
147:                 'customer_group_discount',
148:                 $channelListId,
149:                 $variant,
150:                 $channel,
151:             );
152:         }
153: 
154:         return $this->formatResponse($channelPrice, $channelSource, $channelListId, $variant, $channel);
155:     }
156: 
157:     /**
158:      * سلم شرائح الكميات الساري لهذا العميل على المتغير: نقاط التحول هي كل
159:      * قيم min_qty في القوائم المؤهلة له (خاصة/مجموعة/قناة/قطاعي احتياطي)،
160:      * وسعر كل شريحة هو ناتج resolve نفسه عند حدّها الأدنى — فالسلم مطابق
161:      * دائمًا لما سيُحصَّل فعليًا عند تلك الكمية.
162:      *
163:      * @return list<array{min_qty: float, unit_price: float}>
164:      */
165:     public function tiersFor(ProductVariant $variant, Customer $customer): array
166:     {
167:         $now = Carbon::now();
168:         $channel = $this->channelFor($customer);
169:         $eligible = $customer->status === CustomerStatus::Approved;
170:         $groupId = $eligible ? $customer->customerGroup()->where('is_active', true)->value('id') : null;
171: 
172:         $breakpoints = $this->eligibleItems($variant, PHP_FLOAT_MAX, null, $now)
173:             ->where(function ($q) use ($eligible, $customer, $groupId, $channel): void {
174:                 $q->where('price_lists.type', $channel->value)
175:                     ->orWhere('price_lists.type', PriceListType::Retail->value);
176:                 if ($eligible) {
177:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerSpecific)
178:                         ->where('price_lists.customer_id', $customer->id));
179:                 }
180:                 if ($groupId !== null) {
181:                     $q->orWhere(fn ($q) => $q->where('price_lists.type', PriceListType::CustomerGroup)
182:                         ->where('price_lists.customer_group_id', $groupId));
183:                 }
184:             })
185:             ->pluck('price_list_items.min_qty')
186:             ->map(fn ($v) => (float) $v)
187:             ->unique()
188:             ->sort()
189:             ->values();
190: 
191:         $points = collect([1.0])->merge($breakpoints)->unique()->sort()->values();
192: 
193:         return $points
194:             ->map(fn (float $minQty) => [
195:                 'min_qty' => $minQty,
196:                 'unit_price' => $this->resolve($variant, $customer, max(1.0, $minQty))['unit_price'],
197:             ])
198:             ->values()
199:             ->all();
200:     }
201: 
202:     /** قناة التسعير: الجملة/الموزع للحسابات المعتمدة فقط، وغير ذلك قطاعي. */
203:     private function channelFor(?Customer $customer): PriceListType
204:     {
205:         if ($customer !== null
206:             && in_array($customer->type, [CustomerType::Wholesale, CustomerType::Distributor], true)
207:             && $customer->status === CustomerStatus::Approved) {
208:             return PriceListType::from($customer->type->value);
209:         }
210: 
211:         return PriceListType::Retail;
212:     }
213: 
214:     private function basePrice(ProductVariant $variant, PriceListType $channel): ?string
215:     {
216:         return $variant->retail_price === null ? null : $variant->base_price;
217:     }
218: 
219:     private function discountFactor(string $percentage): string
220:     {
221:         return (string) BigDecimal::of('100')->minus($percentage)->dividedBy('100', 8);
222:     }
223: 
224:     /** كل عناصر التسعير السارية لهذا المتغير والكمية والفرع والوقت. */
225:     private function eligibleItems(?ProductVariant $variant, float $qty, ?int $branchId, Carbon $now): Builder
226:     {
227:         return PriceListItem::query()
228:             ->select('price_list_items.*')
229:             ->join('price_lists', 'price_lists.id', '=', 'price_list_items.price_list_id')
230:             ->where('price_lists.is_active', true)
231:             ->when($variant !== null,
232:                 fn ($q) => $q->where('price_list_items.product_variant_id', $variant->id),
233:                 fn ($q) => $q->whereColumn('price_list_items.product_variant_id', 'product_variants.id'))
234:             ->where('price_list_items.min_qty', '<=', $qty)
235:             ->where(fn ($q) => $q->whereNull('price_lists.starts_at')->orWhere('price_lists.starts_at', '<=', $now))
236:             ->where(fn ($q) => $q->whereNull('price_lists.ends_at')->orWhere('price_lists.ends_at', '>=', $now))
237:             ->where(fn ($q) => $q->whereNull('price_list_items.starts_at')->orWhere('price_list_items.starts_at', '<=', $now))
238:             ->where(fn ($q) => $q->whereNull('price_list_items.ends_at')->orWhere('price_list_items.ends_at', '>=', $now))
239:             ->where(function ($q) use ($branchId): void {
240:                 $q->whereNull('price_lists.branch_id');
241:                 if ($branchId !== null) {
242:                     $q->orWhere('price_lists.branch_id', $branchId);
243:                 }
244:             });
245:     }
246: 
247:     /** ترتيب داخل المستوى الواحد: فرع مخصص أولًا، أعلى شريحة، أعلى أولوية، أقل سعر. */
248:     private function ordered(Builder $query): Builder
249:     {
250:         return $query
251:             ->orderByRaw('price_lists.branch_id IS NULL ASC')
252:             ->orderByDesc('price_list_items.min_qty')
253:             ->orderByDesc('price_lists.priority')
254:             ->orderBy('price_list_items.price');
255:     }
256: 
257:     /**
258:      * @return array{unit_price: float, base_price: float, source: string, price_list_id: int|null}
259:      */
260:     private function formatResponse(string|float $unitPrice, string $source, ?int $priceListId, ProductVariant $variant, PriceListType $channel): array
261:     {
262:         return [
263:             'unit_price' => (float) (string) BigDecimal::of((string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
264:             'base_price' => (float) (string) BigDecimal::of($this->basePrice($variant, $channel) ?? (string) $unitPrice)->toScale(2, RoundingMode::HalfUp),
265:             'source' => $source,
266:             'price_list_id' => $priceListId,
267:         ];
268:     }
