156:     private function resolveCategory(int|string $value): ?Category
157:     {
158:         $category = Category::query()->where('is_active', true)->where('slug', $value)->first();
159: 
160:         return $category ?? (ctype_digit((string) $value) && strlen((string) $value) <= 18
