166:     /**
167:      * سعر عرض بطاقة المنتج: أرخص متغير نشط قابل للتسعير عبر PricingService
168:      * (متغير بلا سعر ولا قائمة يُتخطى بدل كسر القائمة كلها).
169:      *
170:      * @return array{price: float, base_price: float, compare_at: float|null, discount_percentage: int|null, variant_id: int}|null
171:      */
172:     public function displayPrice(Product $product, ?Customer $customer): ?array
173:     {
174:         $variants = $product->relationLoaded('variants')
175:             ? $product->variants
176:             : $product->variants()->where('is_active', true)->orderBy('sort_order')->get();
177: 
178:         $best = null;
179:         foreach ($variants as $variant) {
180:             try {
181:                 $resolved = $this->variantPrice($variant, $customer);
182:             } catch (BusinessException) {
183:                 continue;
184:             }
185: 
186:             $price = (float) $resolved['unit_price'];
187:             $compareAt = $variant->compare_at_price !== null ? (float) $variant->compare_at_price : null;
188:             $basis = max((float) $compareAt, (float) $resolved['base_price']);
189: 
190:             $display = [
191:                 'price' => $price,
192:                 'base_price' => (float) $resolved['base_price'],
193:                 'compare_at' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1 ? $basis : null,
194:                 'discount_percentage' => $basis > $price && (int) round((1 - $price / $basis) * 100) >= 1
195:                     ? (int) round((1 - $price / $basis) * 100) : null,
196:                 'variant_id' => $variant->id,
197:             ];
198:             if ($best === null || $price < $best['price']) {
199:                 $best = $display;
200:             }
201:         }
202: 
203:         return $best;
204:     }
