213:     public function variantPrice(ProductVariant $variant, ?Customer $customer): array
214:     {
215:         if (! array_key_exists('store_price', $variant->getAttributes())) {
216:             return $this->pricing->resolve($variant, $customer, 1);
217:         }
218:         if ($variant->store_price === null) {
219:             throw new BusinessException('الصنف غير مُسعَّر.');
220:         }
221: 
222:         return ['unit_price' => (float) $variant->store_price, 'base_price' => (float) ($variant->retail_price === null ? $variant->store_price : $variant->base_price)];
223:     }
