290:             ->where(function ($q) use ($product): void {
291:                 $q->where('products.category_id', $product->category_id);
292:             })
293:             ->reorder()
294:             ->orderByRaw('CASE WHEN products.category_id = ? THEN 0 ELSE 1 END', [$product->category_id])
