245:   return rows.map((r, index) => <Fragment key={r.id}><tr className="hover:opacity-90 transition"><td className="py-3 pl-3.5 pr-2">{" "}<input type="checkbox" className="row-activity-check rounded border-gray-300 accent-[#e0491f] cursor-pointer" checked={selectedActivities.includes(r.id)} onChange={event => setSelectedActivities(ids => event.target.checked ? [...ids, r.id] : ids.filter(id => id !== r.id))} />{" "}</td><td className="py-3 px-3 font-medium" style={{
246:         "color": "var(--text-secondary)"
247:       }}>{"" + r.id}</td><td className="py-3 px-3">{" "}<div className="flex items-center gap-2.5">{" "}<span className="w-6 h-6 rounded-lg flex items-center justify-center text-white text-[11px] font-bold shrink-0" style={{
248:             "background": r.color
249:           }}>A</span>{" "}<span className="font-semibold" style={{
250:             "color": "var(--text-primary)"
251:           }}>{"" + r.name}</span>{" "}</div>{" "}</td><td className="py-3 px-3 font-semibold" style={{
252:         "color": "var(--text-primary)"
253:       }}>{"" + r.price}</td><td className="py-3 px-3">{" "}<span className={"inline-flex items-center gap-1.5 text-[12px] font-medium " + (r.status === 'Completed' ? 'text-emerald-500' : 'text-amber-500') + ""}>{" "}<span className={"w-1.5 h-1.5 rounded-full " + (r.status === 'Completed' ? 'bg-emerald-500' : 'bg-amber-500') + ""}></span>{" "}{r.status}{" "}</span>{" "}</td><td className="py-3 px-3 flex items-center justify-between" style={{
254:         "color": "var(--text-secondary)"
