259: function renderChatThreads() {
260:   const q = chatQuery.toLowerCase();
261:   const threads = state.chats.filter(c => {
262:     if (state.chatFilter === 'unread' && c.unread === 0) return false;
263:     return c.name.toLowerCase().includes(q);
264:   });
265:   return threads.map((c, index) => {
266:     const isSelected = c.id === state.activeChatId;
267:     const lastMsg = c.messages[c.messages.length - 1]?.text || '';
268:     return <Fragment key={c.id}>{" "}<div data-chat-id={c.id} className={"chat-thread-item relative rounded-2xl p-3 flex items-center justify-between gap-2.5 cursor-pointer transition " + (isSelected ? 'v-subcard' : 'hover:opacity-85') + ""} onClick={() => selectChat(c.id)}>{" "}{isSelected ? <><span className="w-1 h-7 rounded-full bg-[#e0491f] absolute left-0"></span></> : ''}{" "}<div className="flex items-center gap-3 min-w-0">{" "}<div className="w-9 h-9 rounded-full flex items-center justify-center text-white font-bold text-xs shrink-0 relative" style={{
269:             "background": c.avatarBg
270:           }}>{" "}<span>{"" + c.avatarText}</span>{" "}<span className="w-2.5 h-2.5 rounded-full bg-emerald-500 absolute -bottom-0.5 -right-0.5" style={{
271:               "boxShadow": "0 0 0 2px var(--bg-card)"
272:             }}></span>{" "}</div>{" "}<div className="min-w-0">{" "}<div className="text-[13px] font-semibold truncate" style={{
273:               "color": "var(--text-primary)"
274:             }}>{"" + c.name}</div>{" "}<div className="text-[11.5px] truncate" style={{
275:               "color": "var(--text-muted)"
276:             }}>{lastMsg}</div>{" "}</div>{" "}</div>{" "}<div className="flex flex-col items-end gap-1 shrink-0">{" "}<span className="text-[10.5px]" style={{
277:             "color": "var(--text-muted)"
278:           }}>{"" + c.time}</span>{" "}{c.unread > 0 ? <><span className="w-4 h-4 rounded-full bg-[#e0491f] text-white text-[10px] font-bold flex items-center justify-center">{"" + c.unread}</span></> : ''}{" "}</div>{" "}</div>{" "}</Fragment>;
279:   });
280: }
