282: function renderActiveChat() {
283:   const chat = state.chats.find(c => c.id === state.activeChatId) || state.chats[0];
284:   return chat.messages.map((m, index) => {
285:     if (m.sender === 'them') {
286:       return <Fragment key={index}>{" "}<div className="max-w-[360px] v-subcard rounded-2xl rounded-tl-xs px-4 py-2.5 text-[12.5px] leading-relaxed" style={{
287:           "color": "var(--text-primary)"
288:         }}>{" "}<div>{"" + m.text}</div>{" "}<div className="text-[10px] text-right mt-1" style={{
289:             "color": "var(--text-muted)"
290:           }}>{"" + m.time}</div>{" "}</div>{" "}</Fragment>;
291:     }
292:     return <Fragment key={index}>{" "}<div className="max-w-[360px] ml-auto rounded-2xl rounded-tr-xs px-4 py-2.5 text-[12.5px] leading-relaxed bg-[#e0491f] text-white">{" "}<div>{"" + m.text}</div>{" "}<div className="text-[10px] text-right mt-1 text-white/75">{"" + m.time}</div>{" "}</div>{" "}</Fragment>;
293:   });
294: }
