103: const MULTIPART = { headers: { 'Content-Type': 'multipart/form-data' } };
104: 
105: function categoryFormData(p: CategoryPayload, spoofPut = false): FormData {
106:   const fd = new FormData();
107:   if (spoofPut) fd.append('_method', 'PUT');
108:   const put = (key: string, v: unknown) => {
109:     if (v === undefined) return;                       // مش هيتبعت
110:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
111:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
112:     if (v instanceof Blob) return fd.append(key, v);
113:     fd.append(key, String(v));
114:   };
115:   put('parent_id', p.parent_id);
116:   put('name_ar', p.name_ar);
117:   put('name_en', p.name_en);
118:   put('slug', p.slug);
119:   put('description_ar', p.description_ar);
120:   put('description_en', p.description_en);
121:   put('sort_order', p.sort_order);
122:   put('is_active', p.is_active);
123:   if (p.image) put('image', p.image);
124:   if (p.remove_image) put('remove_image', true);
125:   return fd;
126: }
