130: export const categoriesApi = {
131:   tree: (signal?: AbortSignal) =>
132:     apiClient.get<{ data: AdminCategory[] }>(CAT, { params: { tree: 1 }, signal }).then((r) => r.data.data),
133:   show: (id: number) =>
134:     apiClient.get<{ data: AdminCategory }>(`${CAT}/${id}`).then((r) => r.data.data),
135:   create: (p: CategoryPayload, onProgress?: (pct: number) => void) =>
136:     apiClient.post<{ data: AdminCategory }>(CAT, categoryFormData(p), {
137:       ...MULTIPART,
138:       onUploadProgress: (e) => onProgress?.(Math.round((e.loaded / (e.total || 1)) * 100)),
139:     }).then((r) => r.data.data),
140:   update: (id: number, p: CategoryPayload, onProgress?: (pct: number) => void) =>
141:     apiClient.post<{ data: AdminCategory }>(`${CAT}/${id}`, categoryFormData(p, true), {
142:       ...MULTIPART,
143:       onUploadProgress: (e) => onProgress?.(Math.round((e.loaded / (e.total || 1)) * 100)),
144:     }).then((r) => r.data.data),
145:   remove: (id: number) =>
146:     apiClient.delete<{ message: string }>(`${CAT}/${id}`).then((r) => r.data),
147:   reorder: (items: CategoryReorderItem[]) =>
148:     apiClient.put<{ message: string }>(`${CAT}/reorder`, { items }).then((r) => r.data),
149: };
