165: function brandFormData(p: BrandPayload, spoofPut = false): FormData {
166:   const fd = new FormData();
167:   if (spoofPut) fd.append('_method', 'PUT');
168:   const put = (key: string, v: unknown) => {
169:     if (v === undefined) return;                       // مش هيتبعت
170:     if (v === null) return fd.append(key, '');         // Laravel يحوّلها null
171:     if (typeof v === 'boolean') return fd.append(key, v ? '1' : '0'); // مهم: مش "true"
172:     if (v instanceof Blob) return fd.append(key, v);
173:     fd.append(key, String(v));
174:   };
175:   put('name_ar', p.name_ar);
176:   put('name_en', p.name_en);
177:   put('slug', p.slug);
178:   put('description_ar', p.description_ar);
179:   put('description_en', p.description_en);
180:   put('sort_order', p.sort_order);
181:   put('is_active', p.is_active);
182:   if (p.logo) put('logo', p.logo);
183:   if (p.remove_logo) put('remove_logo', true);
184:   return fd;
185: }
