 14: class SettingService
 15: {
 16:     /** @var array<string, array{0: string, 1: int}> بادئة وحشو الترقيم لكل نوع — يُقرآن مرة واحدة لكل طلب (M11). */
 17:     private array $numberingConfig = [];
 18: 
 19:     private const CACHE_KEY = 'app_settings_static';
 20: 
 21:     private const CACHE_TTL_SECONDS = 3600;
 22: 
 23:     /** @var list<string> */
 24:     private const NUMBERING_COUNTER_KEYS = [
 25:         'invoice_next_number',
 26:         'order_next_number',
 27:         'purchase_order_next_number',
 28:         'quotation_next_number',
 29:         'movement_next_number',
 30:         'transfer_next_number',
 31:         'stocktake_next_number',
 32:         'return_next_number',
 33:         'purchase_request_next_number',
 34:         'delivery_next_number',
 35:         'supplier_invoice_next_number',
 36:         'supplier_payment_next_number',
 37:     ];
 38: 
 39:     /** مستندات داخلية تُرقَّم بتسلسل PostgreSQL (فجوات مقبولة) حتى لا يُحتجز قفل العداد داخل معاملات طويلة. */
 40:     private const SEQUENCE_TYPES = [
 41:         'order' => 'order_next_number',
 42:         'purchase_order' => 'purchase_order_next_number',
 43:         'quotation' => 'quotation_next_number',
 44:         'transfer' => 'transfer_next_number',
 45:         'stocktake' => 'stocktake_next_number',
 46:         'return' => 'return_next_number',
 47:         'purchase_request' => 'purchase_request_next_number',
 48:         'delivery' => 'delivery_next_number',
 49:         'supplier_invoice' => 'supplier_invoice_next_number',
 50:         'supplier_payment' => 'supplier_payment_next_number',
 51:     ];
 52: 
 53:     /**
 54:      * Return all settings grouped by their group name, with values cast to their declared types.
 55:      * Numbering counters are read fresh because they change for every generated document number.
 56:      *
 57:      * @return array<string, array<string, mixed>>
 58:      */
 59:     public function getAllGrouped(): array
 60:     {
 61:         $grouped = Cache::remember(self::CACHE_KEY, self::CACHE_TTL_SECONDS, function (): array {
 62:             return Setting::query()
 63:                 ->whereNotIn('key', self::NUMBERING_COUNTER_KEYS)
 64:                 ->orderBy('group')
 65:                 ->orderBy('key')
 66:                 ->get()
 67:                 ->groupBy('group')
 68:                 ->map(fn ($settings): array => $settings
 69:                     ->mapWithKeys(fn (Setting $setting): array => [
 70:                         $setting->key => $this->castValue($setting->value, $setting->type),
 71:                     ])
 72:                     ->all())
 73:                 ->all();
 74:         });
 75: 
 76:         $counters = Setting::query()
 77:             ->whereIn('key', self::NUMBERING_COUNTER_KEYS)
 78:             ->orderBy('key')
 79:             ->get()
 80:             ->mapWithKeys(fn (Setting $setting): array => [
 81:                 $setting->key => $this->castValue($setting->value, $setting->type),
 82:             ])
 83:             ->all();
 84: 
 85:         if (isset($counters['movement_next_number'])) {
 86:             $counters['movement_next_number'] = $this->nextMovementNumber();
 87:         }
 88:         foreach (self::SEQUENCE_TYPES as $type => $key) {
 89:             if (isset($counters[$key])) {
 90:                 $counters[$key] = $this->nextDocumentNumber($type);
 91:             }
 92:         }
 93: 
 94:         if ($counters !== []) {
 95:             $grouped['numbering'] = array_merge($grouped['numbering'] ?? [], $counters);
 96:             ksort($grouped['numbering']);
 97:         }
 98: 
 99:         return $grouped;
100:     }
101: 
102:     public function get(string $key, mixed $default = null): mixed
103:     {
104:         foreach ($this->getAllGrouped() as $settings) {
105:             if (array_key_exists($key, $settings)) {
106:                 return $settings[$key];
107:             }
108:         }
109: 
110:         return $default;
111:     }
112: 
113:     /**
114:      * Update a flat key/value map atomically and invalidate the cached settings after commit.
115:      *
116:      * @param  array<string, mixed>  $settings
117:      *
118:      * @throws JsonException
119:      */
120:     public function updateBatch(array $settings): void
121:     {
122:         DB::transaction(function () use ($settings): void {
123:             $movementSequenceTarget = null;
124:             /** @var array<string, int> $documentSequenceTargets */
125:             $documentSequenceTargets = [];
126:             $lockedSettings = Setting::query()
127:                 ->whereIn('key', array_keys($settings))
128:                 ->orderBy('key')
129:                 ->lockForUpdate()
130:                 ->get()
131:                 ->keyBy('key');
132: 
133:             $missingKeys = array_diff(array_keys($settings), $lockedSettings->keys()->all());
134: 
135:             if ($missingKeys !== []) {
136:                 throw new InvalidArgumentException('Settings are not initialized: '.implode(', ', $missingKeys));
137:             }
138: 
139:             foreach ($settings as $key => $value) {
140:                 /** @var Setting $setting */
141:                 $setting = $lockedSettings->get($key);
142: 
143:                 if (in_array($key, self::NUMBERING_COUNTER_KEYS, true)) {
144:                     $value = max($this->counterValue($setting->value), $this->counterValue($value));
145:                     if ($key === 'movement_next_number') {
146:                         $value = max($value, $this->nextMovementNumber());
147:                         $movementSequenceTarget = $value;
148:                     }
149:                     $sequenceType = array_search($key, self::SEQUENCE_TYPES, true);
150:                     if (is_string($sequenceType)) {
151:                         $value = max($value, $this->nextDocumentNumber($sequenceType));
152:                         $documentSequenceTargets[$sequenceType] = $value;
153:                     }
154:                 }
155: 
156:                 $setting->value = $value === null && str_ends_with($key, '_prefix')
157:                     ? ''
158:                     : $this->serializeValue($value, $setting->type);
159:                 $setting->save();
160:             }
161: 
162:             DB::afterCommit(fn () => $this->clearCache());
163: 
164:             if ($movementSequenceTarget !== null) {
165:                 // مزامنة التسلسل بعد الاعتماد لا داخله: ALTER SEQUENCE داخل
166:                 // المعاملة كان يحجب كل nextval (أي كل حركات المخزون) حتى نهاية
167:                 // معاملة الإعدادات (L-9). الدالة تقفل الترقيم لمدة الاستعلام
168:                 // نفسه وتنسّق رفع الحد الأدنى مع كل تخصيص جديد لمنع إعادة رقم.
169:                 DB::afterCommit(function () use ($movementSequenceTarget): void {
170:                     DB::selectOne('SELECT inventory_movement_number(?) AS number', [$movementSequenceTarget]);
171:                 });
172:             }
173:             if ($documentSequenceTargets !== []) {
174:                 DB::afterCommit(function () use ($documentSequenceTargets): void {
175:                     foreach ($documentSequenceTargets as $type => $minimum) {
176:                         DB::selectOne('SELECT document_next_number(?, ?) AS number', [$type, $minimum]);
177:                     }
178:                 });
179:             }
180:         }, attempts: 3);
181:     }
182: 
183:     /**
184:      * Atomically return and increment the next document number for the requested type.
185:      *
186:      * @throws JsonException
187:      */
188:     public function generateNextNumber(string $type): string
189:     {
190:         if ($type === 'movement') {
191:             [$prefix, $padding] = $this->numberingConfig('movement', 'movement_prefix', 'movement_padding');
192:             $number = DB::selectOne('SELECT inventory_movement_number() AS number')->number;
193: 
194:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
195:         }
196:         if (isset(self::SEQUENCE_TYPES[$type])) {
197:             $definitions = $this->numberingDefinitions();
198:             $definition = $definitions[$type];
199:             [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
200:             $number = DB::selectOne('SELECT document_next_number(?) AS number', [$type])->number;
201: 
202:             return $prefix.str_pad((string) $number, $padding, '0', STR_PAD_LEFT);
203:         }
204:         $definitions = $this->numberingDefinitions();
205: 
206:         if (! isset($definitions[$type])) {
207:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
208:         }
209: 
210:         $definition = $definitions[$type];
211:         [$prefix, $padding] = $this->numberingConfig($type, $definition['prefix'], $definition['padding']);
212: 
213:         return DB::transaction(function () use ($definition, $prefix, $padding): string {
214:             // العداد وحده يُقفل ويُقرأ طازجًا كل مرة؛ البادئة والحشو من ذاكرة الطلب.
215:             $nextSetting = Setting::query()
216:                 ->where('key', $definition['next'])
217:                 ->lockForUpdate()
218:                 ->first();
219: 
220:             if ($nextSetting === null) {
221:                 throw new InvalidArgumentException("Required numbering setting [{$definition['next']}] is missing.");
222:             }
223: 
224:             $nextValue = $this->counterValue($nextSetting->value);
225: 
226:             $formatted = $prefix.str_pad((string) $nextValue, $padding, '0', STR_PAD_LEFT);
227:             $nextSetting->value = (string) ($nextValue + 1);
228:             $nextSetting->save();
229: 
230:             return $formatted;
231:         }, attempts: 3);
232:     }
233: 
234:     /**
235:      * بادئة وحشو نوع ترقيم — قراءة واحدة لكل طلب بدل استعلام مع كل حركة/مستند.
236:      *
237:      * @return array{0: string, 1: int}
238:      */
239:     private function numberingConfig(string $type, string $prefixKey, string $paddingKey): array
240:     {
241:         return $this->numberingConfig[$type] ??= (function () use ($prefixKey, $paddingKey): array {
242:             $settings = Setting::query()->whereIn('key', [$prefixKey, $paddingKey])->pluck('value', 'key');
243: 
244:             foreach ([$prefixKey, $paddingKey] as $key) {
245:                 if (! $settings->has($key)) {
246:                     throw new InvalidArgumentException("Required numbering setting [{$key}] is missing.");
247:                 }
248:             }
249: 
250:             return [(string) $settings[$prefixKey], max(0, (int) $settings[$paddingKey])];
251:         })();
252:     }
253: 
254:     public function clearCache(): void
255:     {
256:         Cache::forget(self::CACHE_KEY);
257:         $this->numberingConfig = [];
258:     }
259: 
260:     /**
261:      * @return array<string, array{prefix: string, next: string, padding: string}>
262:      */
263:     private function numberingDefinitions(): array
264:     {
265:         return [
266:             'invoice' => ['prefix' => 'invoice_prefix', 'next' => 'invoice_next_number', 'padding' => 'invoice_padding'],
267:             'order' => ['prefix' => 'order_prefix', 'next' => 'order_next_number', 'padding' => 'order_padding'],
268:             'purchase_order' => ['prefix' => 'purchase_order_prefix', 'next' => 'purchase_order_next_number', 'padding' => 'purchase_order_padding'],
269:             'quotation' => ['prefix' => 'quotation_prefix', 'next' => 'quotation_next_number', 'padding' => 'quotation_padding'],
270:             'transfer' => ['prefix' => 'transfer_prefix', 'next' => 'transfer_next_number', 'padding' => 'transfer_padding'],
271:             'stocktake' => ['prefix' => 'stocktake_prefix', 'next' => 'stocktake_next_number', 'padding' => 'stocktake_padding'],
272:             'return' => ['prefix' => 'return_prefix', 'next' => 'return_next_number', 'padding' => 'return_padding'],
273:             'purchase_request' => ['prefix' => 'purchase_request_prefix', 'next' => 'purchase_request_next_number', 'padding' => 'purchase_request_padding'],
274:             'delivery' => ['prefix' => 'delivery_prefix', 'next' => 'delivery_next_number', 'padding' => 'delivery_padding'],
275:             'supplier_invoice' => ['prefix' => 'supplier_invoice_prefix', 'next' => 'supplier_invoice_next_number', 'padding' => 'supplier_invoice_padding'],
276:             'supplier_payment' => ['prefix' => 'supplier_payment_prefix',    'next' => 'supplier_payment_next_number',    'padding' => 'supplier_payment_padding'],
277:             'shift' => ['prefix' => 'shift_prefix',               'next' => 'shift_next_number',               'padding' => 'shift_padding'],
278:             'expense' => ['prefix' => 'expense_prefix',             'next' => 'expense_next_number',             'padding' => 'expense_padding'],
279:             'treasury_transfer' => ['prefix' => 'treasury_transfer_prefix',   'next' => 'treasury_transfer_next_number',   'padding' => 'treasury_transfer_padding'],
280:             'payment_notice' => ['prefix' => 'payment_notice_prefix',      'next' => 'payment_notice_next_number',      'padding' => 'payment_notice_padding'],
281:         ];
282:     }
283: 
284:     private function nextMovementNumber(): int
285:     {
286:         $sequence = DB::selectOne('SELECT last_value, is_called FROM stock_movement_number_seq');
287: 
288:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
289:     }
290: 
291:     private function nextDocumentNumber(string $type): int
292:     {
293:         if (! isset(self::SEQUENCE_TYPES[$type])) {
294:             throw new InvalidArgumentException("Unsupported numbering type [{$type}].");
295:         }
296:         $sequence = DB::selectOne("SELECT last_value, is_called FROM document_{$type}_number_seq");
297: 
298:         return (int) $sequence->last_value + ($sequence->is_called ? 1 : 0);
299:     }
300: 
301:     private function counterValue(mixed $value): int
302:     {
303:         $number = (is_int($value) || is_string($value))
304:             ? filter_var($value, FILTER_VALIDATE_INT, ['options' => ['min_range' => 1, 'max_range' => PHP_INT_MAX - 1]])
305:             : false;
306:         if ($number === false) {
307:             throw new BusinessException('قيمة عداد الترقيم يجب أن تكون عددًا صحيحًا موجبًا ضمن النطاق المسموح');
308:         }
309: 
310:         return $number;
311:     }
312: 
313:     private function castValue(?string $value, string $type): mixed
314:     {
315:         if ($value === null) {
316:             return null;
317:         }
318: 
319:         return match ($type) {
320:             'boolean' => filter_var($value, FILTER_VALIDATE_BOOLEAN),
321:             'integer' => (int) $value,
322:             'float' => (float) $value,
323:             'json' => json_decode($value, true, 512, JSON_THROW_ON_ERROR),
324:             default => $value,
325:         };
326:     }
327: 
328:     /** @throws JsonException */
329:     private function serializeValue(mixed $value, string $type): ?string
330:     {
331:         if ($value === null) {
332:             return null;
333:         }
334: 
335:         if ($type === 'json') {
336:             return json_encode($value, JSON_THROW_ON_ERROR);
337:         }
338: 
339:         if ($type === 'boolean') {
340:             return filter_var($value, FILTER_VALIDATE_BOOLEAN) ? '1' : '0';
341:         }
342: 
343:         return (string) $value;
344:     }
