  92: function BranchForm({ open, branch, onClose }) {
  93:   const isEdit = branch && branch.id;
  94:   const [v, setV] = useState({});
  95:   const [errs, setErrs] = useState({});
  96:   const [busy, setBusy] = useState(false);
  97:   useEffect(() => { if (open) { setV({ type: 'branch', status: 'active', ...branch }); setErrs({}); } }, [open]);
  98:   const set = (k) => (e) => setV({ ...v, [k]: e && e.target ? e.target.value : e });
  99:   const save = () => {
 100:     setBusy(true);
 101:     setTimeout(() => {
 102:       setBusy(false);
 103:       const e = {};
 104:       if (!v.name) e.name = 'اسم الفرع مطلوب';
 105:       if (!v.code) e.code = 'الكود مطلوب';
 106:       else if (v.code === 'BR-NSR' && !isEdit) e.code = 'هذا الكود مستخدم بالفعل لفرع آخر'; // simulated 422
 107:       if (v.email && !/^\S+@\S+\.\S+$/.test(v.email)) e.email = 'صيغة البريد غير صحيحة';
 108:       setErrs(e);
 109:       if (!Object.keys(e).length) { vtoast(isEdit ? 'تم حفظ التعديلات' : 'تم إنشاء الفرع'); onClose(); }
 110:     }, 700);
 111:   };
 112:   return (
 113:     <Drawer open={open} onClose={onClose} title={isEdit ? 'تعديل الفرع' : 'فرع جديد'} subtitle={isEdit ? branch.code : 'الاسم والكود والنوع مطلوبين'}
 114:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-ink" onClick={save} disabled={busy}>{busy && <Spinner size={14} />}{isEdit ? 'حفظ التعديلات' : 'إنشاء الفرع'}</button></>}>
 115:       {Object.keys(errs).length > 0 && <Banner tone="red" icon="alertCircle" title="راجع الحقول المظللة" className="mb-5 pop">{Object.keys(errs).length} حقل يحتاج تصحيح قبل الحفظ.</Banner>}
 116:       <div className="space-y-4">
 117:         <Field label="النوع" required>
 118:           <div className="grid grid-cols-2 gap-2.5">
 119:             {[['branch', 'فرع', 'نقطة بيع وتخزين', 'store'], ['warehouse', 'مخزن', 'تخزين فقط', 'warehouse']].map(([k, l, s, ic]) => (
 120:               <button key={k} type="button" onClick={() => setV({ ...v, type: k })} className={cx('rounded-[16px] p-3.5 text-start border transition flex items-center gap-3', v.type === k ? 'border-[var(--accent)] bg-[var(--accent-soft)]' : 'border-[var(--border-field)] hover:bg-[var(--bg-subcard)]')}>
 121:                 <span className={cx('w-9 h-9 rounded-full flex items-center justify-center', v.type === k ? 'bg-acc' : 'v-well')}><Icon name={ic} size={16} /></span>
 122:                 <span><span className="block text-[13px] font-semibold t-1">{l}</span><span className="block text-[11px] t-3">{s}</span></span>
 123:               </button>
 124:             ))}
 125:           </div>
 126:         </Field>
 127:         <div className="grid grid-cols-[1.4fr_1fr] gap-3">
 128:           <Field label="اسم الفرع" required error={errs.name}><Input value={v.name || ''} onChange={set('name')} error={errs.name} placeholder="مثال: فرع مدينة نصر" /></Field>
 129:           <Field label="الكود" required error={errs.code} hint={!errs.code && 'حروف إنجليزية وأرقام'}><Input ltr value={v.code || ''} onChange={(e) => setV({ ...v, code: e.target.value.toUpperCase() })} error={errs.code} placeholder="BR-001" /></Field>
 130:         </div>
 131:         <div className="grid grid-cols-2 gap-3">
 132:           <Field label="الهاتف"><Input ltr value={v.phone || ''} onChange={set('phone')} placeholder="+20 1xx xxx xxxx" /></Field>
 133:           <Field label="البريد الإلكتروني" error={errs.email}><Input ltr value={v.email || ''} onChange={set('email')} error={errs.email} placeholder="branch@company.com" /></Field>
 134:         </div>
 135:         <Field label="المدينة"><Input value={v.city || ''} onChange={set('city')} /></Field>
 136:         <Field label="العنوان"><Textarea value={v.address || ''} onChange={set('address')} rows={2} /></Field>
 137:         <div className="v-subcard p-4 flex items-center justify-between gap-3">
 138:           <div><div className="text-[13px] font-semibold t-1">الفرع نشط</div><div className="text-[11.5px] t-3">الفروع غير النشطة ما تظهرش في اختيارات البيع والتحويل.</div></div>
 139:           <Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} />
 140:         </div>
 141:       </div>
 142:     </Drawer>
 143:   );
 144: }
