 146: function BranchDetail({ id }) {
 147:   const { user } = useApp();
 148:   const b = BRANCHES.find((x) => String(x.id) === String(id)) || BRANCHES[2];
 149:   const [q, setQ] = useQueryState({ tab: 'locations', ltype: '', lsearch: '' });
 150:   const [phase, retry] = useLoad([q.ltype, q.lsearch]);
 151:   const [form, setForm] = useState(null);
 152:   const [del, setDel] = useState(null);
 153:   const locs = LOCATIONS.filter((l) => (!q.ltype || l.type === q.ltype) && (!q.lsearch || (l.name + l.code).includes(q.lsearch)));
 154:   const typeTone = { shelf: 'gray', zone: 'blue', bin: 'gray', damaged: 'red', receiving: 'green' };
 155:   return (
 156:     <div className="space-y-5">
 157:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'الفروع', href: '#/branches' }, { label: b.name }]} title={b.name} badge={<><Badge tone={b.type === 'warehouse' ? 'blue' : 'acc'}>{b.type === 'warehouse' ? 'مخزن' : 'فرع'}</Badge><StatusBadge s={b.status} /></>}
 158:         subtitle={<span className="ltr inline-block">{b.code}</span>}
 159:         actions={<><button className="btn btn-soft" onClick={() => nav('/branches')}><Icon name="arrowRight" size={14} />كل الفروع</button>{user.can('branches.manage') && <button className="btn btn-outline"><Icon name="edit" size={14} />تعديل الفرع</button>}</>} />
 160:       <div className="grid lg:grid-cols-[300px_1fr] gap-5 items-start">
 161:         <div className="v-card p-5 stagger s2">
 162:           <div className="text-[12.5px] font-semibold t-2 mb-2">بيانات الفرع</div>
 163:           <div className="v-divide">
 164:             <KV k="الهاتف" v={b.phone || '—'} ltr />
 165:             <KV k="البريد" v={b.email || '—'} ltr />
 166:             <KV k="المدينة" v={b.city} />
 167:             <KV k="المستخدمون" v={<span className="num">{b.users}</span>} />
 168:           </div>
 169:           <div className="v-subcard p-3.5 mt-3 text-[12px] t-2 leading-relaxed flex gap-2"><Icon name="pin" size={14} className="mt-0.5" />{b.address || 'لا يوجد عنوان مسجل'}</div>
 170:         </div>
 171:         <div className="space-y-4 stagger s3">
 172:           <Tabs value={q.tab} onChange={(t) => setQ({ tab: t })} tabs={[{ value: 'locations', label: 'مواقع التخزين', count: LOCATIONS.length }, { value: 'users', label: 'المستخدمون', count: b.users }]} />
 173:           {q.tab === 'locations' ? (
 174:             <DataTable state={phase} onRetry={retry} rows={locs} filtered={q.ltype || q.lsearch}
 175:               empty={!(q.ltype || q.lsearch) && <EmptyState icon="layers" title="لا توجد مواقع تخزين في هذا الفرع" body="ابدأ بمنطقة الاستلام، وبعدها الرفوف والخانات." action={<button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />موقع جديد</button>} />}
 176:               toolbar={
 177:                 <div className="flex flex-wrap items-center justify-between gap-2">
 178:                   <div className="flex flex-wrap items-center gap-2">
 179:                     <SearchBox value={q.lsearch} onChange={(v) => setQ({ lsearch: v })} placeholder="ابحث بالاسم أو الكود…" width={240} />
 180:                     <div className="seg">
 181:                       <button className={cx(!q.ltype && 'on')} onClick={() => setQ({ ltype: '' })}>الكل</button>
 182:                       {Object.entries(LOCATION_TYPES).map(([k, l]) => <button key={k} className={cx(q.ltype === k && 'on')} onClick={() => setQ({ ltype: k })}>{l}</button>)}
 183:                     </div>
 184:                   </div>
 185:                   {user.can('locations.manage') && <button className="btn btn-ink btn-sm" onClick={() => setForm({})}><Icon name="plus" size={14} />موقع تخزين</button>}
 186:                 </div>
 187:               }
 188:               columns={[
 189:                 { key: 'name', label: 'الموقع', render: (r) => <div className="font-semibold t-1">{r.name}</div> },
 190:                 { key: 'code', label: 'الكود', render: (r) => <span className="ltr inline-block text-[12px] font-semibold px-2 py-0.5 rounded-md v-well">{r.code}</span> },
 191:                 { key: 'type', label: 'النوع', render: (r) => <Badge tone={typeTone[r.type]}>{LOCATION_TYPES[r.type]}</Badge> },
 192:                 { key: 'status', label: 'الحالة', render: (r) => <StatusBadge s={r.status} /> },
 193:                 { key: 'a', label: '', render: (r) => user.can('locations.manage') && <RowActions onEdit={() => setForm(r)} onDelete={() => setDel(r)} /> },
 194:               ]} />
 195:           ) : (
 196:             <div className="v-card p-2"><div className="v-divide">{USERS.filter((u) => u.branch === b.id || u.id < 3).slice(0, 4).map((u) => (
 197:               <div key={u.id} className="flex items-center gap-3 p-3"><Avatar name={u.name} size={34} /><div className="flex-1"><div className="text-[13px] font-semibold t-1">{u.name}</div><div className="text-[11.5px] t-3 ltr text-end inline-block">{u.email}</div></div><Badge>{ROLES.find((r) => r.id === u.roles[0]).name}</Badge></div>
 198:             ))}</div></div>
 199:           )}
 200:         </div>
 201:       </div>
 202:       <Drawer open={!!form} onClose={() => setForm(null)} title={form && form.id ? 'تعديل موقع التخزين' : 'موقع تخزين جديد'} subtitle={<>داخل <b className="t-1">{b.name}</b></>} width={460}
 203:         footer={<><button className="btn btn-soft" onClick={() => setForm(null)}>إلغاء</button><button className="btn btn-ink" onClick={() => { vtoast('تم حفظ موقع التخزين'); setForm(null); }}>حفظ</button></>}>
 204:         {form && <LocationFormBody loc={form} branch={b} />}
 205:       </Drawer>
 206:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} danger title={`حذف «${del && del.name}»؟`} message="سيتم حذف موقع التخزين من هذا الفرع." confirmLabel="حذف"
 207:         serverError={del && del.type !== 'bin' ? { title: 'تعذّر الحذف', body: 'الموقع عليه أرصدة مخزون حالية. انقل الكميات لموقع آخر أو عطّل الموقع بدل حذفه.' } : null} />
 208:     </div>
 209:   );
 210: }
 211: function LocationFormBody({ loc, branch }) {
 212:   const [v, setV] = useState({ type: 'shelf', status: 'active', ...loc });
 213:   return (
 214:     <div className="space-y-4">
 215:       <div className="v-subcard p-3.5 flex items-center gap-3"><span className="w-9 h-9 rounded-full b-acc flex items-center justify-center"><Icon name={branch.type === 'warehouse' ? 'warehouse' : 'store'} size={16} /></span><div className="text-[12.5px]"><div className="font-semibold t-1">{branch.name}</div><div className="t-3 ltr inline-block">{branch.code}</div></div><Icon name="lock" size={14} className="t-3 ms-auto" /></div>
 216:       <Field label="الاسم" required><Input value={v.name || ''} onChange={(e) => setV({ ...v, name: e.target.value })} placeholder="مثال: رف A-03" /></Field>
 217:       <Field label="الكود" required hint="فريد داخل الفرع"><Input ltr value={v.code || ''} onChange={(e) => setV({ ...v, code: e.target.value.toUpperCase() })} placeholder="A-03" /></Field>
 218:       <Field label="النوع" required>
 219:         <div className="grid grid-cols-5 gap-2">
 220:           {Object.entries(LOCATION_TYPES).map(([k, l]) => (
 221:             <button key={k} type="button" onClick={() => setV({ ...v, type: k })} className={cx('h-11 rounded-[14px] text-[12px] font-semibold border transition', v.type === k ? 'border-[var(--accent)] bg-[var(--accent-soft)] t-acc' : 'border-[var(--border-field)] t-2 hover:bg-[var(--bg-subcard)]')}>{l}</button>
 222:           ))}
 223:         </div>
 224:       </Field>
 225:       <div className="v-subcard p-4 flex items-center justify-between"><div className="text-[13px] font-semibold t-1">نشط</div><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
 226:     </div>
 227:   );
 228: }
