 230: /* ====================== ROLES ====================== */
 231: function RolesPage() {
 232:   const { user } = useApp();
 233:   const [sel, setSel] = useState(2);
 234:   const [roles, setRoles] = useState(ROLES);
 235:   const role = roles.find((r) => r.id === sel);
 236:   const [perms, setPerms] = useState(role.perms);
 237:   const [name, setName] = useState(role.name);
 238:   const [search, setSearch] = useState('');
 239:   const [open, setOpen] = useState({ products: true, categories: true });
 240:   const [phase] = useLoad([]);
 241:   useEffect(() => { setPerms(role.perms); setName(role.name); }, [sel]);
 242:   if (!user.can('roles.manage')) return <Forbidden perm="roles.manage" />;
 243:   const dirty = JSON.stringify([...perms].sort()) !== JSON.stringify([...role.perms].sort()) || name !== role.name;
 244:   const toggle = (k) => setPerms(perms.includes(k) ? perms.filter((p) => p !== k) : [...perms, k]);
 245:   const total = PERM_GROUPS.reduce((a, g) => a + g.perms.length, 0);
 246:   return (
 247:     <div className="space-y-5">
 248:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'الأدوار' }]} title="الأدوار والصلاحيات" subtitle="كل دور مجموعة صلاحيات. المستخدم ممكن ياخد أكتر من دور."
 249:         actions={<button className="btn btn-ink" onClick={() => { const id = Date.now(); setRoles([...roles, { id, name: 'دور جديد', users: 0, perms: [] }]); setSel(id); }}><Icon name="plus" size={15} />دور جديد</button>} />
 250:       <div className="grid lg:grid-cols-[300px_1fr] gap-5 items-start">
 251:         <div className="v-card p-2 stagger s2">
 252:           {phase === 'loading' ? [0, 1, 2, 3].map((i) => <div key={i} className="p-3 flex items-center gap-3"><Skel w={36} h={36} r={999} /><div className="flex-1 space-y-1.5"><Skel w="60%" h={10} /><Skel w="35%" h={8} /></div></div>) :
 253:             roles.map((r) => (
 254:               <button key={r.id} onClick={() => setSel(r.id)} className={cx('w-full flex items-center gap-3 p-3 rounded-[16px] text-start transition', sel === r.id ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]')}>
 255:                 <span className={cx('w-9 h-9 rounded-full flex items-center justify-center', sel === r.id ? 'bg-acc' : 'v-well')}><Icon name="shield" size={16} /></span>
 256:                 <span className="flex-1 min-w-0"><span className="block text-[13px] font-semibold t-1 truncate">{r.name}</span><span className="block text-[11.5px] t-3"><span className="num">{r.users}</span> مستخدم · <span className="num">{r.perms.length}</span> صلاحية</span></span>
 257:                 {r.system && <Badge>نظام</Badge>}
 258:               </button>
 259:             ))}
 260:         </div>
 261:         <div className="v-card stagger s3 overflow-hidden">
 262:           <div className="p-6 v-border-b">
 263:             <div className="grid md:grid-cols-[1fr_auto] gap-4 items-end">
 264:               <Field label="اسم الدور" required><Input value={name} onChange={(e) => setName(e.target.value)} disabled={role.system} /></Field>
 265:               <div className="flex items-center gap-4">
 266:                 <div className="text-end"><div className="text-[11.5px] t-3">الصلاحيات المحددة</div><div className="font-display text-[22px] font-bold t-1 num">{perms.length}<span className="text-[14px] t-3 font-medium"> / {total}</span></div></div>
 267:               </div>
 268:             </div>
 269:             <div className="mt-4 h-2 rounded-full hatched-track overflow-hidden"><div className="h-full rounded-full hatched-acc transition-all" style={{ width: `${(perms.length / total) * 100}%` }} /></div>
 270:             {role.system && <Banner tone="blue" icon="info" className="mt-4">دور النظام بيمتلك كل الصلاحيات ولا يمكن تعديله.</Banner>}
 271:           </div>
 272:           <div className="p-6 space-y-3">
 273:             <SearchBox value={search} onChange={setSearch} placeholder="ابحث عن صلاحية بالعربي أو بالمفتاح…" width="100%" />
 274:             {PERM_GROUPS.map((g) => {
 275:               const list = g.perms.filter(([k, l]) => !search || l.includes(search) || k.includes(search.toLowerCase()));
 276:               if (!list.length) return null;
 277:               const on = g.perms.filter(([k]) => perms.includes(k)).length;
 278:               const all = on === g.perms.length; const some = on > 0 && !all;
 279:               const isOpen = open[g.key] || !!search;
 280:               return (
 281:                 <div key={g.key} className="v-subcard overflow-hidden">
 282:                   <div className="flex items-center gap-3 p-3.5">
 283:                     <Check on={all} mixed={some} disabled={role.system} onChange={() => setPerms(all ? perms.filter((p) => !g.perms.some(([k]) => k === p)) : [...new Set([...perms, ...g.perms.map(([k]) => k)])])} />
 284:                     <button className="flex-1 flex items-center gap-3 text-start" onClick={() => setOpen({ ...open, [g.key]: !isOpen })}>
 285:                       <span className="w-8 h-8 rounded-full flex items-center justify-center" style={{ background: 'var(--bg-card)' }}><Icon name={g.icon} size={15} className="t-2" /></span>
 286:                       <span className="flex-1 text-[13px] font-semibold t-1">{g.label}</span>
 287:                       <span className="text-[11.5px] t-3 num">{on}/{g.perms.length}</span>
 288:                       <Icon name="chevDown" size={14} className={cx('t-3 transition', isOpen && 'rotate-180')} />
 289:                     </button>
 290:                   </div>
 291:                   {isOpen && (
 292:                     <div className="px-3.5 pb-3.5 grid sm:grid-cols-2 gap-2">
 293:                       {list.map(([k, l]) => {
 294:                         const sensitive = k === 'products.view_cost' || k === 'branches.access_all' || k === 'products.publish';
 295:                         return (
 296:                           <label key={k} onClick={() => !role.system && toggle(k)} className={cx('flex items-center gap-3 p-3 rounded-[14px] cursor-pointer transition', perms.includes(k) ? 'bg-[var(--bg-card)] shadow-sm' : 'hover:bg-[var(--bg-card)]')}>
 297:                             <Check on={perms.includes(k)} disabled={role.system} />
 298:                             <span className="flex-1 min-w-0">
 299:                               <span className="flex items-center gap-1.5 text-[12.5px] font-medium t-1">{l}{sensitive && <Badge tone="amber" className="!py-0 !text-[10px]">حساسة</Badge>}</span>
 300:                               <span className="block text-[10.5px] t-3 ltr text-end">{k}</span>
 301:                             </span>
 302:                           </label>
 303:                         );
 304:                       })}
 305:                     </div>
 306:                   )}
 307:                 </div>
 308:               );
 309:             })}
 310:           </div>
 311:         </div>
 312:       </div>
 313:       {!role.system && <StickyBar dirty={dirty} note={dirty && 'المفاتيح الأصلية بتتبعت للـ API كما هي'}>
 314:         <button className="btn btn-ghost" disabled={!dirty} onClick={() => { setPerms(role.perms); setName(role.name); }}>تراجع</button>
 315:         <button className="btn btn-ink" disabled={!dirty} onClick={() => { setRoles(roles.map((r) => r.id === sel ? { ...r, perms, name } : r)); vtoast('تم حفظ الدور'); }}>حفظ الدور</button>
 316:       </StickyBar>}
 317:     </div>
 318:   );
 319: }
