 355: function UserForm({ open, u, onClose }) {
 356:   const isEdit = u && u.id;
 357:   const [v, setV] = useState({});
 358:   const [showPw, setShowPw] = useState(false);
 359:   const [errs, setErrs] = useState({});
 360:   useEffect(() => { if (open) { setV({ status: 'active', roles: [], branch: null, allBranches: false, ...u }); setErrs({}); } }, [open]);
 361:   const canAll = (v.roles || []).some((id) => ROLES.find((r) => r.id === id).perms.includes('branches.access_all'));
 362:   const save = () => {
 363:     const e = {};
 364:     if (!v.name) e.name = 'الاسم مطلوب';
 365:     if (!v.email) e.email = 'البريد مطلوب'; else if (v.email === 'sara.m@vortix.store' && !isEdit) e.email = 'البريد مسجّل لمستخدم آخر';
 366:     if (!isEdit && !v.password) e.password = 'كلمة المرور مطلوبة عند الإنشاء'; else if (v.password && v.password.length < 8) e.password = 'كلمة المرور لازم تكون ٨ أحرف على الأقل';
 367:     setErrs(e); if (!Object.keys(e).length) { vtoast(isEdit ? 'تم تحديث المستخدم' : 'تم إنشاء المستخدم'); onClose(); }
 368:   };
 369:   return (
 370:     <Drawer open={open} onClose={onClose} title={isEdit ? 'تعديل المستخدم' : 'مستخدم جديد'} subtitle={isEdit ? v.email : 'الاسم والبريد وكلمة المرور مطلوبين'}
 371:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-ink" onClick={save}>{isEdit ? 'حفظ' : 'إنشاء المستخدم'}</button></>}>
 372:       <div className="space-y-4">
 373:         <Field label="الاسم" required error={errs.name}><Input value={v.name || ''} onChange={(e) => setV({ ...v, name: e.target.value })} error={errs.name} /></Field>
 374:         <Field label="البريد الإلكتروني" required error={errs.email}><Input ltr icon="mail" value={v.email || ''} onChange={(e) => setV({ ...v, email: e.target.value })} error={errs.email} placeholder="name@company.com" /></Field>
 375:         <Field label="كلمة المرور" required={!isEdit} error={errs.password} hint={isEdit ? 'اتركها فارغة للإبقاء على كلمة المرور الحالية' : '٨ أحرف على الأقل'}>
 376:           <div className="relative">
 377:             <input type={showPw ? 'text' : 'password'} value={v.password || ''} onChange={(e) => setV({ ...v, password: e.target.value })} className={cx('v-input ltr pe-12', errs.password && 'is-error')} placeholder={isEdit ? '••••••••' : ''} />
 378:             <button type="button" onClick={() => setShowPw(!showPw)} className="absolute top-1/2 -translate-y-1/2 end-1.5 icon-btn !w-8 !h-8"><Icon name={showPw ? 'eyeOff' : 'eye'} size={15} /></button>
 379:           </div>
 380:         </Field>
 381:         <Field label="الهاتف"><Input ltr value={v.phone || ''} onChange={(e) => setV({ ...v, phone: e.target.value })} placeholder="+20 1xx xxx xxxx" /></Field>
 382:         <Field label="الأدوار" hint="الصلاحيات النهائية = مجموع صلاحيات الأدوار المختارة">
 383:           <SearchSelect multi value={v.roles} onChange={(r) => setV({ ...v, roles: r })} options={ROLES.map((r) => ({ value: r.id, label: r.name, sub: `${r.perms.length} صلاحية` }))} placeholder="اختر دورًا أو أكثر" />
 384:         </Field>
 385:         <Field label="الفرع" hint={!v.branch && !v.allBranches ? '«بدون فرع» تعني إن المستخدم مش مربوط بفرع — ومش معناها الوصول لكل الفروع.' : null}>
 386:           <SearchSelect value={v.allBranches ? null : v.branch} disabled={v.allBranches} onChange={(b) => setV({ ...v, branch: b })} placeholder="بدون فرع" emptyText="لا يوجد فرع بهذا الاسم"
 387:             options={BRANCHES.map((b) => ({ value: b.id, label: b.name, sub: b.code, icon: <Icon name={b.type === 'warehouse' ? 'warehouse' : 'store'} size={14} className="t-3" />, disabled: b.status !== 'active', note: b.status !== 'active' ? 'غير نشط' : null }))} />
 388:         </Field>
 389:         <div className={cx('rounded-[16px] p-4 border', canAll ? 'border-[var(--border-field)]' : 'border-dashed border-[var(--border-field)] opacity-70')}>
 390:           <div className="flex items-start gap-3">
 391:             <span className="w-9 h-9 rounded-full b-acc flex items-center justify-center shrink-0"><Icon name="globe" size={16} /></span>
 392:             <div className="flex-1"><div className="text-[13px] font-semibold t-1">الوصول لكل الفروع</div>
 393:               <div className="text-[11.5px] t-3 mt-0.5 leading-relaxed">{canAll ? 'امتياز صريح — يتطلب دورًا يحتوي صلاحية الوصول لكل الفروع.' : <>غير متاح: لا يوجد دور مختار فيه صلاحية <span className="ltr inline-block">branches.access_all</span>.</>}</div></div>
 394:             <Toggle on={v.allBranches && canAll} disabled={!canAll} onChange={(on) => setV({ ...v, allBranches: on })} />
 395:           </div>
 396:         </div>
 397:         <div className="v-subcard p-4 flex items-center justify-between"><div><div className="text-[13px] font-semibold t-1">الحساب نشط</div><div className="text-[11.5px] t-3">إيقاف الحساب يمنع تسجيل الدخول فورًا.</div></div><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
 398:       </div>
 399:     </Drawer>
 400:   );
 401: }
