 403: /* ====================== SETTINGS ====================== */
 404: function SettingsPage() {
 405:   const { user } = useApp();
 406:   const [sec, setSec] = useQueryState({ s: 'company' });
 407:   const init = { company_name: 'Vortix Home', company_name_en: 'Vortix Home LLC', tax_number: '512-889-301', cr: '88231', tax_enabled: true, tax_rate: 14, prices_include_tax: true,
 408:     num: { invoice: { prefix: 'INV-', pad: 6, next: 1042, year: true }, purchase: { prefix: 'PO-', pad: 5, next: 318, year: true }, transfer: { prefix: 'TR-', pad: 5, next: 77, year: false }, return: { prefix: 'RT-', pad: 5, next: 24, year: true } },
 409:     return_mode: 'days', return_days: 14, self_approve: false, logo: '' };
 410:   const [v, setV] = useState(init);
 411:   const [saved, setSaved] = useState(init);
 412:   const [conflict, setConflict] = useState(false);
 413:   const dirty = JSON.stringify(v) !== JSON.stringify(saved);
 414:   useUnsavedGuard(dirty);
 415:   if (!user.can('settings.view')) return <Forbidden perm="settings.view" />;
 416:   const ro = !user.can('settings.update');
 417:   const sections = [['company', 'بيانات الشركة', 'building'], ['tax', 'الضرائب', 'percent'], ['numbering', 'ترقيم المستندات', 'hash'], ['returns', 'سياسة الإرجاع', 'rotate'], ['purchases', 'المشتريات', 'receipt']];
 418:   const preview = (n) => `${n.prefix}${n.year ? '2026-' : ''}${String(n.next).padStart(n.pad, '0')}`;
 419:   const setNum = (k, patch) => setV({ ...v, num: { ...v.num, [k]: { ...v.num[k], ...patch } } });
 420:   const numLabels = { invoice: 'فواتير البيع', purchase: 'أوامر الشراء', transfer: 'التحويلات', return: 'المرتجعات' };
 421:   return (
 422:     <div className="space-y-5">
 423:       <PageHeader crumbs={[{ label: 'الإدارة' }, { label: 'الإعدادات' }]} title="الإعدادات" subtitle="إعدادات عامة بتأثر على كل الفروع والمستندات." badge={ro && <Badge tone="amber"><Icon name="eye" size={11} />قراءة فقط</Badge>} />
 424:       {conflict && <Banner tone="amber" icon="refresh" title="الإعدادات اتعدلت من مستخدم آخر (409)" className="pop" onClose={() => setConflict(false)}
 425:         action={<button className="btn btn-sm btn-ink" onClick={() => { setConflict(false); vtoast('تم تحميل أحدث نسخة', 'info'); }}>تحميل أحدث نسخة</button>}>
 426:         تعديلاتك لسه موجودة هنا. حمّل النسخة الأحدث وراجع الفروقات قبل الحفظ مرة أخرى.
 427:       </Banner>}
 428:       <div className="grid lg:grid-cols-[240px_1fr] gap-5 items-start">
 429:         <div className="v-card p-2 lg:sticky lg:top-5 stagger s2">
 430:           {sections.map(([k, l, ic]) => (
 431:             <button key={k} onClick={() => setSec({ s: k })} className={cx('w-full flex items-center gap-3 p-2.5 rounded-[14px] text-[13px] font-medium transition text-start', sec.s === k ? 'bg-ink' : 't-2 hover:bg-[var(--bg-subcard)] hover:t-1')}>
 432:               <span className={cx('w-8 h-8 rounded-full flex items-center justify-center', sec.s === k ? 'bg-white/15' : 'v-well')}><Icon name={ic} size={15} /></span>{l}
 433:             </button>
 434:           ))}
 435:         </div>
 436:         <div className="space-y-5 stagger s3">
 437:           {sec.s === 'company' && (
 438:             <SectionCard title="بيانات الشركة" subtitle="تظهر في رأس الفواتير والمستندات المطبوعة.">
 439:               <div className="space-y-5">
 440:                 <Field label="لوجو الشركة" hint="حاليًا الحقل company_logo نصّي (رابط). الرفع المباشر يحتاج مسار رفع في الـ API — لحين توفره أدخل رابط الصورة.">
 441:                   <div className="flex items-center gap-4">
 442:                     <div className="w-[72px] h-[72px] rounded-[18px] checker shrink-0 flex items-center justify-center t-3 overflow-hidden">{v.logo ? <div className="w-full h-full" style={{ background: 'radial-gradient(circle at 30% 25%, #ff8a65 0%, #e0491f 75%)' }} /> : <Icon name="image" size={20} />}</div>
 443:                     <div className="flex-1"><Input ltr icon="link" value={v.logo} onChange={(e) => setV({ ...v, logo: e.target.value })} disabled={ro} placeholder="https://cdn.company.com/logo.png" /></div>
 444:                     <button className="btn btn-soft" disabled title="يتطلب مسار رفع في الـ API"><Icon name="upload" size={14} />رفع<Badge tone="amber" className="!py-0 !text-[9.5px]">قريبًا</Badge></button>
 445:                   </div>
 446:                 </Field>
 447:                 <div className="grid md:grid-cols-2 gap-4">
 448:                   <Field label="اسم الشركة (عربي)" required><Input value={v.company_name} onChange={(e) => setV({ ...v, company_name: e.target.value })} readOnly={ro} /></Field>
 449:                   <Field label="اسم الشركة (إنجليزي)"><Input ltr value={v.company_name_en} onChange={(e) => setV({ ...v, company_name_en: e.target.value })} readOnly={ro} /></Field>
 450:                   <Field label="السجل التجاري"><Input ltr value={v.cr} onChange={(e) => setV({ ...v, cr: e.target.value })} readOnly={ro} /></Field>
 451:                   <Field label="البطاقة الضريبية"><Input ltr value={v.tax_number} onChange={(e) => setV({ ...v, tax_number: e.target.value })} readOnly={ro} /></Field>
 452:                 </div>
 453:               </div>
 454:             </SectionCard>
 455:           )}
 456:           {sec.s === 'tax' && (
 457:             <SectionCard title="الضرائب">
 458:               <div className="space-y-4">
 459:                 <div className="v-subcard p-4 flex items-center justify-between"><div><div className="text-[13px] font-semibold t-1">تفعيل ضريبة القيمة المضافة</div><div className="text-[11.5px] t-3">تُحسب على فواتير البيع والشراء.</div></div><Toggle on={v.tax_enabled} disabled={ro} onChange={(x) => setV({ ...v, tax_enabled: x })} /></div>
 460:                 <div className="grid md:grid-cols-2 gap-4">
 461:                   <Field label="نسبة الضريبة" required hint="منزلتين عشريتين بحد أقصى"><Input ltr suffix="%" value={v.tax_rate} onChange={(e) => setV({ ...v, tax_rate: e.target.value })} disabled={!v.tax_enabled || ro} /></Field>
 462:                   <Field label="الأسعار المدخلة">
 463:                     <Seg value={v.prices_include_tax ? 'inc' : 'exc'} onChange={(x) => !ro && setV({ ...v, prices_include_tax: x === 'inc' })} options={[{ value: 'inc', label: 'شاملة الضريبة' }, { value: 'exc', label: 'غير شاملة' }]} />
 464:                   </Field>
 465:                 </div>
 466:                 <div className="v-subcard p-4 text-[12.5px] flex items-center justify-between"><span className="t-2">مثال: منتج بسعر <b className="t-1 num">1,000</b></span><span className="t-1 font-semibold num">{v.prices_include_tax ? `صافي ${fmtMoney(1000 / (1 + v.tax_rate / 100))} + ضريبة ${fmtMoney(1000 - 1000 / (1 + v.tax_rate / 100))}` : `الإجمالي ${fmtMoney(1000 * (1 + v.tax_rate / 100))}`}</span></div>
 467:               </div>
 468:             </SectionCard>
 469:           )}
 470:           {sec.s === 'numbering' && (
 471:             <SectionCard title="ترقيم المستندات" subtitle="المعاينة توضح شكل رقم المستند التالي.">
 472:               <div className="space-y-3">
 473:                 {Object.entries(v.num).map(([k, n]) => (
 474:                   <div key={k} className="v-subcard p-4">
 475:                     <div className="flex flex-wrap items-center justify-between gap-3 mb-3.5">
 476:                       <div className="text-[13px] font-semibold t-1">{numLabels[k]}</div>
 477:                       <div className="flex items-center gap-2 text-[11.5px] t-3">المستند التالي
 478:                         <span className="ltr font-display text-[15px] font-bold px-3 py-1 rounded-full t-1" style={{ background: 'var(--bg-card)', border: '1px solid var(--border-subtle)' }}>
 479:                           <span className="t-acc">{n.prefix}</span>{n.year && <span className="t-2">2026-</span>}<span>{String(n.next).padStart(n.pad, '0')}</span>
 480:                         </span>
 481:                       </div>
 482:                     </div>
 483:                     <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
 484:                       <Field label="البادئة"><Input ltr value={n.prefix} onChange={(e) => setNum(k, { prefix: e.target.value })} readOnly={ro} /></Field>
 485:                       <Field label="عدد الخانات"><Input ltr type="number" min={1} max={10} value={n.pad} onChange={(e) => setNum(k, { pad: +e.target.value || 1 })} readOnly={ro} /></Field>
 486:                       <Field label="الرقم التالي"><Input ltr type="number" value={n.next} onChange={(e) => setNum(k, { next: +e.target.value || 1 })} readOnly={ro} /></Field>
 487:                       <Field label="إضافة السنة"><div className="h-[42px] flex items-center"><Toggle on={n.year} disabled={ro} onChange={(x) => setNum(k, { year: x })} /></div></Field>
 488:                     </div>
 489:                   </div>
 490:                 ))}
 491:               </div>
 492:             </SectionCard>
 493:           )}
 494:           {sec.s === 'returns' && (
 495:             <SectionCard title="سياسة الإرجاع" subtitle="بتتطبق على فواتير البيع في كل الفروع.">
 496:               <div className="grid md:grid-cols-3 gap-3">
 497:                 {[['off', 'متوقف', 'لا يُسمح بالإرجاع', 'ban', 'return_enabled=false'], ['unlimited', 'بدون حد زمني', 'الإرجاع مسموح في أي وقت', 'rotate', 'return_days=null'], ['days', 'خلال عدد أيام', 'من تاريخ الفاتورة', 'clock', `return_days=${v.return_days}`]].map(([k, l, s, ic, api]) => (
 498:                   <button key={k} disabled={ro} onClick={() => setV({ ...v, return_mode: k })} className={cx('rounded-[18px] p-4 text-start border transition', v.return_mode === k ? 'border-[var(--accent)] bg-[var(--accent-soft)]' : 'border-[var(--border-field)] hover:bg-[var(--bg-subcard)]')}>
 499:                     <div className="flex items-center justify-between"><span className={cx('w-9 h-9 rounded-full flex items-center justify-center', v.return_mode === k ? 'bg-acc' : 'v-well')}><Icon name={ic} size={16} /></span><span className={cx('w-5 h-5 rounded-full border-2 flex items-center justify-center', v.return_mode === k ? 'border-[var(--accent)]' : 'border-[var(--border-field)]')}>{v.return_mode === k && <span className="w-2.5 h-2.5 rounded-full bg-[var(--accent)]" />}</span></div>
 500:                     <div className="text-[13.5px] font-semibold t-1 mt-3">{l}</div><div className="text-[11.5px] t-3 mt-0.5">{s}</div>
 501:                     <div className="text-[10px] t-3 mt-3 ltr text-end opacity-70">{api}</div>
 502:                   </button>
