 508:                   <div className="flex gap-1.5">{[7, 14, 30].map((d) => <button key={d} onClick={() => setV({ ...v, return_days: d })} className={cx('h-8 px-3 rounded-full text-[12px] font-semibold num', v.return_days === d ? 'bg-ink' : 'btn-outline')}>{d}</button>)}</div>
 509:                   <span className="text-[12px] t-2">فاتورة يوم ١ أكتوبر تقبل الإرجاع حتى <b className="t-1 num">{v.return_days + 1}</b> أكتوبر.</span>
 510:                 </div>
