 527:         <button className="btn btn-ink" disabled={!dirty} onClick={() => { if (v.company_name === 'تعارض') { setConflict(true); return; } setSaved(v); vtoast('تم حفظ الإعدادات'); }}>حفظ الإعدادات</button>
 528:       </StickyBar>}
 529:     </div>
