 535: // Phase 2 — Categories tree, Brands, Products list
 536: 
 537: /* ====================== CATEGORIES ====================== */
 538: const MAX_DEPTH = 3;
 539: function treeDepth(n) { return 1 + Math.max(0, ...(n.children || []).map(treeDepth)); }
 540: function findNode(nodes, id, parent = null, depth = 1) {
 541:   for (const n of nodes) {
 542:     if (n.id === id) return { node: n, parent, depth };
 543:     const r = findNode(n.children || [], id, n, depth + 1); if (r) return r;
 544:   }
 545:   return null;
 546: }
 547: function isDescendant(node, id) { return (node.children || []).some((c) => c.id === id || isDescendant(c, id)); }
 548: function removeNode(nodes, id) { return nodes.filter((n) => n.id !== id).map((n) => ({ ...n, children: removeNode(n.children || [], id) })); }
 549: function insertInto(nodes, parentId, node) {
 550:   if (parentId == null) return [...nodes, node];
 551:   return nodes.map((n) => n.id === parentId ? { ...n, children: [...(n.children || []), node] } : { ...n, children: insertInto(n.children || [], parentId, node) });
 552: }
 553: function sumProducts(n) { return (n.products || 0) + (n.children || []).reduce((a, c) => a + sumProducts(c), 0); }
 554: 
 555: function CategoriesPage() {
 556:   const { user } = useApp();
 557:   const [tree, setTree] = useState(CATEGORIES);
 558:   const [saved, setSaved] = useState(CATEGORIES);
 559:   const [open, setOpen] = useState({ 1: true, 11: true, 2: true });
 560:   const [sel, setSel] = useState(11);
 561:   const [drag, setDrag] = useState(null);
 562:   const [over, setOver] = useState(null);
 563:   const [invalid, setInvalid] = useState(null);
 564:   const [form, setForm] = useState(null);
 565:   const [del, setDel] = useState(null);
 566:   const [disable, setDisable] = useState(null);
 567:   const [search, setSearch] = useState('');
 568:   const [phase, retry] = useLoad([]);
 569:   if (!user.can('categories.view')) return <Forbidden perm="categories.view" />;
 570:   const dirty = JSON.stringify(tree) !== JSON.stringify(saved);
 571:   const canManage = user.can('categories.manage');
 572: 
 573:   const canDropInto = (dragId, targetId) => {
 574:     if (dragId === targetId) return { ok: false, why: 'لا يمكن نقل القسم داخل نفسه' };
 575:     const d = findNode(tree, dragId); if (!d) return { ok: false };
 576:     if (targetId != null) {
 577:       if (isDescendant(d.node, targetId)) return { ok: false, why: 'لا يمكن نقل القسم داخل أحد أقسامه الفرعية' };
 578:       const t = findNode(tree, targetId);
 579:       if (t.depth + treeDepth(d.node) > MAX_DEPTH) return { ok: false, why: `النقل هنا يتجاوز الحد الأقصى (${MAX_DEPTH} مستويات)` };
 580:     }
 581:     return { ok: true };
 582:   };
 583:   const doMove = (dragId, targetId) => {
 584:     const chk = canDropInto(dragId, targetId);
 585:     if (!chk.ok) { vtoast(chk.why, 'error'); return; }
 586:     const d = findNode(tree, dragId);
 587:     setTree(insertInto(removeNode(tree, dragId), targetId, d.node));
 588:     if (targetId) setOpen({ ...open, [targetId]: true });
 589:   };
 590: 
 591:   const selected = sel && findNode(tree, sel);
 592:   const flat = flattenCats(tree);
 593:   const matches = (n) => !search || n.ar.includes(search) || n.en.toLowerCase().includes(search.toLowerCase()) || (n.children || []).some(matches);
 594: 
 595:   const Node = ({ n, depth }) => {
 596:     const has = (n.children || []).length > 0;
 597:     const isOpen = open[n.id] || !!search;
 598:     const chk = drag != null && over === n.id ? canDropInto(drag, n.id) : null;
 599:     if (!matches(n)) return null;
 600:     return (
 601:       <div>
 602:         <div draggable={canManage} onDragStart={(e) => { e.stopPropagation(); setDrag(n.id); }} onDragEnd={() => { setDrag(null); setOver(null); setInvalid(null); }}
 603:           onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); if (over !== n.id) { setOver(n.id); const c = canDropInto(drag, n.id); setInvalid(c.ok ? null : c.why); } }}
 604:           onDrop={(e) => { e.preventDefault(); e.stopPropagation(); doMove(drag, n.id); setDrag(null); setOver(null); setInvalid(null); }}
 605:           onClick={() => setSel(n.id)}
 606:           className={cx('group flex items-center gap-2 h-12 pe-2 rounded-[14px] cursor-pointer transition relative',
 607:             sel === n.id ? 'bg-[var(--bg-subcard)]' : 'hover:bg-[var(--bg-subcard)]',
 608:             drag === n.id && 'opacity-40',
 609:             chk && (chk.ok ? 'ring-2 ring-[var(--accent)] bg-[var(--accent-soft)]' : 'ring-2 ring-[var(--badge-red-text)] bg-[var(--badge-red-bg)]'))}
 610:           style={{ paddingInlineStart: 8 + (depth - 1) * 26 }}>
 611:           {depth > 1 && <span className="absolute top-0 bottom-1/2 w-3 border-b border-s rounded-es-lg" style={{ insetInlineStart: (depth - 1) * 26 - 10, borderColor: 'var(--border-field)' }} />}
 612:           {canManage && <span className="t-3 opacity-0 group-hover:opacity-100 cursor-grab"><Icon name="drag" size={14} /></span>}
 613:           <button onClick={(e) => { e.stopPropagation(); setOpen({ ...open, [n.id]: !isOpen }); }} className={cx('w-6 h-6 rounded-full flex items-center justify-center t-3 hover:bg-[var(--bg-card)]', !has && 'invisible')}>
 614:             <Icon name="chevLeft" size={13} className={cx('transition', isOpen && '-rotate-90')} />
 615:           </button>
 616:           <span className={cx('w-8 h-8 rounded-[10px] flex items-center justify-center shrink-0', depth === 1 ? '' : 'v-well')} style={depth === 1 ? { background: n.img || IMG[0] } : null}>
 617:             {depth > 1 && <Icon name={has ? (isOpen ? 'folderOpen' : 'folder') : 'tag'} size={14} />}
 618:           </span>
 619:           <div className="flex-1 min-w-0">
 620:             <div className="flex items-center gap-2"><span className={cx('text-[13px] truncate', depth === 1 ? 'font-semibold t-1' : 'font-medium t-1', n.status === 'inactive' && 'opacity-50')}>{n.ar}</span>{n.status === 'inactive' && <Badge className="!py-0 !text-[10px]">غير نشط</Badge>}</div>
 621:             <div className="text-[11px] t-3 ltr text-end inline-block">{n.en}</div>
 622:           </div>
 623:           <span className="text-[11px] t-3 num hidden sm:inline">{sumProducts(n)} منتج</span>
 624:           <span className="text-[10px] font-bold w-5 h-5 rounded-full v-well flex items-center justify-center num">{depth}</span>
 625:           {canManage && (
 626:             <div className="flex items-center opacity-0 group-hover:opacity-100 transition" onClick={(e) => e.stopPropagation()}>
 627:               {depth < MAX_DEPTH ? <button title="إضافة قسم فرعي" className="icon-btn !w-8 !h-8" onClick={() => setForm({ parent: n.id })}><Icon name="plus" size={14} /></button>
 628:                 : <span title="الحد الأقصى ٣ مستويات" className="icon-btn !w-8 !h-8 opacity-30 cursor-not-allowed"><Icon name="plus" size={14} /></span>}
 629:               <button title="تعديل" className="icon-btn !w-8 !h-8" onClick={() => setForm(n)}><Icon name="edit" size={14} /></button>
 630:               <button title="حذف" className="icon-btn !w-8 !h-8" onClick={() => setDel(n)}><Icon name="trash" size={14} /></button>
 631:             </div>
 632:           )}
 633:         </div>
 634:         {chk && !chk.ok && <div className="pop text-[11px] font-semibold flex items-center gap-1 my-1" style={{ color: 'var(--badge-red-text)', paddingInlineStart: 40 + (depth - 1) * 26 }}><Icon name="ban" size={12} />{chk.why}</div>}
 635:         {has && isOpen && <div className="mt-0.5 space-y-0.5">{n.children.map((c) => <Node key={c.id} n={c} depth={depth + 1} />)}</div>}
 636:       </div>
 637:     );
 638:   };
 639: 
 640:   return (
 641:     <div className="space-y-5">
 642:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'الأقسام' }]} title="الأقسام" subtitle={`شجرة أقسام حتى ${MAX_DEPTH} مستويات. اسحب لإعادة الترتيب أو استخدم «نقل إلى».`}
 643:         actions={canManage && <button className="btn btn-ink" onClick={() => setForm({ parent: null })}><Icon name="plus" size={15} />قسم رئيسي</button>} />
 644:       <div className="grid lg:grid-cols-[1fr_340px] gap-5 items-start">
 645:         <div className="v-card p-4 stagger s2">
 646:           <div className="flex flex-wrap items-center justify-between gap-2 mb-3 px-1">
 647:             <SearchBox value={search} onChange={setSearch} placeholder="ابحث في الأقسام…" width={260} />
 648:             <div className="flex items-center gap-1.5">
 649:               <button className="btn btn-ghost btn-sm" onClick={() => setOpen(Object.fromEntries(flat.map((f) => [f.id, true])))}>فتح الكل</button>
 650:               <button className="btn btn-ghost btn-sm" onClick={() => setOpen({})}>طي الكل</button>
 651:             </div>
 652:           </div>
 653:           {phase === 'loading' ? <div className="space-y-2 p-2">{[0, 1, 2, 3, 4, 5].map((i) => <div key={i} className="flex items-center gap-3 h-11" style={{ paddingInlineStart: (i % 3) * 26 }}><Skel w={32} h={32} r={10} /><Skel w={`${40 - (i % 3) * 8}%`} h={10} /></div>)}</div>
 654:             : phase === 'error' ? <ErrorState onRetry={retry} />
 655:             : phase === 'empty' ? <EmptyState icon="tree" title="لا توجد أقسام بعد" body="ابدأ بقسم رئيسي، وبعدها أضف أقسام فرعية لحد ٣ مستويات." action={<button className="btn btn-ink" onClick={() => setForm({ parent: null })}><Icon name="plus" size={15} />قسم رئيسي</button>} />
 656:             : (
 657:               <div className="space-y-0.5" onDragOver={(e) => e.preventDefault()}>
 658:                 {tree.map((n) => <Node key={n.id} n={n} depth={1} />)}
 659:                 {drag != null && (
 660:                   <div onDragOver={(e) => { e.preventDefault(); setOver('root'); }} onDrop={(e) => { e.preventDefault(); doMove(drag, null); setDrag(null); setOver(null); }}
 661:                     className={cx('pop mt-2 h-12 rounded-[14px] border-2 border-dashed flex items-center justify-center text-[12px] font-semibold', over === 'root' ? 'border-[var(--accent)] t-acc bg-[var(--accent-soft)]' : 'border-[var(--border-field)] t-3')}>
 662:                     أفلت هنا لجعله قسمًا رئيسيًا
 663:                   </div>
 664:                 )}
 665:               </div>
 666:             )}
 667:           <div className="flex items-center gap-4 mt-4 pt-3 px-1 v-border-t text-[11px] t-3">
 668:             <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded ring-2 ring-[var(--accent)]" />إفلات مسموح</span>
 669:             <span className="flex items-center gap-1.5"><span className="w-3 h-3 rounded ring-2 ring-[var(--badge-red-text)]" />إفلات غير مسموح</span>
 670:             <span className="flex items-center gap-1.5"><span className="w-4 h-4 rounded-full v-well text-[9px] font-bold flex items-center justify-center">2</span>رقم المستوى</span>
 671:           </div>
