 673: 
 674:         {/* Detail / move-to panel */}
 675:         <div className="space-y-4 lg:sticky lg:top-5 stagger s3">
 676:           {selected ? (
 677:             <div className="v-card overflow-hidden">
 678:               <div className="h-24 relative" style={{ background: (tree.find((t) => t.id === sel || isDescendant(t, sel)) || {}).img || IMG[0] }}>
 679:                 <span className="absolute bottom-3 start-4 text-[10.5px] font-semibold px-2 py-0.5 rounded-full bg-white/90 text-[#18151c]">المستوى {selected.depth}</span>
 680:               </div>
 681:               <div className="p-5">
 682:                 <div className="flex items-start justify-between gap-2">
 683:                   <div><div className="font-display text-[17px] font-semibold t-1">{selected.node.ar}</div><div className="text-[12px] t-3 ltr inline-block">{selected.node.en} · /{selected.node.slug}</div></div>
 684:                   <StatusBadge s={selected.node.status} />
 685:                 </div>
 686:                 <div className="text-[11.5px] t-3 mt-3 flex items-center gap-1 flex-wrap">{flat.find((f) => f.id === sel).path.map((p, i, a) => <React.Fragment key={i}><span className={i === a.length - 1 ? 't-1 font-semibold' : ''}>{p}</span>{i < a.length - 1 && <Icon name="chevLeft" size={11} />}</React.Fragment>)}</div>
 687:                 <div className="grid grid-cols-2 gap-2.5 mt-4">
 688:                   <div className="v-subcard p-3"><div className="text-[11px] t-3">أقسام فرعية</div><div className="font-display text-[20px] font-bold t-1 num">{(selected.node.children || []).length}</div></div>
 689:                   <div className="v-subcard p-3"><div className="text-[11px] t-3">منتجات</div><div className="font-display text-[20px] font-bold t-1 num">{sumProducts(selected.node)}</div></div>
 690:                 </div>
 691:                 {canManage && <>
 692:                   <div className="mt-5"><Field label="نقل إلى" hint="بديل للسحب — الأقسام اللي تتجاوز الحد أو تقع داخل نفس الفرع غير متاحة.">
 693:                     <SearchSelect value={selected.parent ? selected.parent.id : '__root'} clearable={false} asyncSim={false}
 694:                       onChange={(pid) => doMove(sel, pid === '__root' ? null : pid)}
 695:                       options={[{ value: '__root', label: 'بدون أب (قسم رئيسي)', depth: 0 }, ...flat.filter((f) => f.depth < MAX_DEPTH - 1 + 1).map((f) => {
 696:                         const c = canDropInto(sel, f.id);
 697:                         return { value: f.id, label: f.ar, depth: f.depth, disabled: !c.ok, note: !c.ok ? (f.id === sel ? 'نفسه' : c.why.includes('الحد') ? 'يتجاوز الحد' : 'فرعي منه') : null };
 698:                       })]} />
 699:                   </Field></div>
 700:                   <div className="flex items-center gap-2 mt-4">
 701:                     <button className="btn btn-soft flex-1" onClick={() => setForm(selected.node)}><Icon name="edit" size={14} />تعديل</button>
 702:                     <button className="btn btn-outline flex-1" onClick={() => setDisable(selected.node)}>{selected.node.status === 'active' ? 'تعطيل' : 'تفعيل'}</button>
 703:                   </div>
 704:                 </>}
 705:               </div>
 706:             </div>
