 714:       </StickyBar>}
 715: 
 716:       <CategoryForm open={!!form} value={form} tree={tree} onClose={() => setForm(null)} />
 717:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} danger title={`حذف قسم «${del && del.ar}»؟`} message="سيتم حذف القسم نهائيًا." confirmLabel="حذف القسم"
 718:         serverError={del && ((del.children || []).length || sumProducts(del)) ? { title: 'لا يمكن حذف هذا القسم', body: 'القسم مرتبط بيانات لازم تتنقل الأول:', items: [(del.children || []).length && `${del.children.length} أقسام فرعية`, sumProducts(del) && `${sumProducts(del)} منتج مرتبط`].filter(Boolean) } : null} />
 719:       <ConfirmDialog open={!!disable} onClose={() => setDisable(null)} title={disable && disable.status === 'active' ? `تعطيل «${disable.ar}»؟` : `تفعيل «${disable && disable.ar}»؟`}
 720:         message={disable && disable.status === 'active' ? 'القسم المعطل وأقسامه الفرعية مش هيظهروا في المتجر.' : 'سيظهر القسم في المتجر.'} icon="ban" confirmLabel={disable && disable.status === 'active' ? 'تعطيل' : 'تفعيل'}
 721:         serverError={disable && disable.status === 'active' && sumProducts(disable) ? { title: 'تعذّر تعطيل القسم', body: `يوجد منتجات منشورة تحت هذا القسم أو أقسامه الفرعية. حوّلها لمسودة أو انقلها لقسم آخر أولًا.`, items: ['كنبة زاوية «ميلانو» — منشور', 'كنبة سرير «فليكس» — منشور', `+ ${Math.max(0, sumProducts(disable) - 2)} منتج آخر`] } : null} />
 722:     </div>
 723:   );
 724: }
