 726: function CategoryForm({ open, value, tree, onClose }) {
 727:   const isEdit = value && value.id;
 728:   const [v, setV] = useState({});
 729:   const [slugTouched, setSlugTouched] = useState(false);
 730:   const [errs, setErrs] = useState({});
 731:   const [lang, setLang] = useState('ar');
 732:   useEffect(() => { if (open) { setV({ status: 'active', order: 1, ...value }); setSlugTouched(!!(value && value.slug)); setErrs({}); } }, [open]);
 733:   const autoSlug = (v.en || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
 734:   const flat = flattenCats(tree);
 735:   const parentId = isEdit ? (findNode(tree, value.id) || {}).parent && findNode(tree, value.id).parent.id : v.parent;
 736:   const save = () => {
 737:     const e = {};
 738:     if (!v.ar) e.ar = 'الاسم العربي مطلوب';
 739:     if (!v.en) e.en = 'الاسم الإنجليزي مطلوب';
 740:     setErrs(e); if (!Object.keys(e).length) { vtoast(isEdit ? 'تم تحديث القسم' : 'تم إنشاء القسم'); onClose(); }
 741:   };
 742:   return (
 743:     <Drawer open={open} onClose={onClose} title={isEdit ? 'تعديل القسم' : (v.parent ? 'قسم فرعي جديد' : 'قسم رئيسي جديد')} subtitle={v.parent && !isEdit ? <>تحت <b className="t-1">{flat.find((f) => f.id === v.parent).ar}</b></> : null} width={540}
 744:       footer={<><button className="btn btn-soft" onClick={onClose}>إلغاء</button><button className="btn btn-ink" onClick={save}>{isEdit ? 'حفظ' : 'إنشاء القسم'}</button></>}>
 745:       <div className="space-y-4">
 746:         <div className="grid grid-cols-2 gap-3">
 747:           <Field label="الاسم بالعربي" required error={errs.ar}><Input value={v.ar || ''} onChange={(e) => setV({ ...v, ar: e.target.value })} error={errs.ar} /></Field>
 748:           <Field label="الاسم بالإنجليزي" required error={errs.en}><Input ltr value={v.en || ''} onChange={(e) => setV({ ...v, en: e.target.value })} error={errs.en} /></Field>
 749:         </div>
 750:         <Field label="القسم الأب" hint="اختياري — اتركه فارغًا لقسم رئيسي">
 751:           <SearchSelect value={parentId || null} onChange={(p) => setV({ ...v, parent: p })} placeholder="بدون أب (قسم رئيسي)"
 752:             options={flat.map((f) => ({ value: f.id, label: f.ar, depth: f.depth, disabled: f.depth >= MAX_DEPTH - 1 || (isEdit && (f.id === value.id || isDescendant(value, f.id))), note: f.depth >= MAX_DEPTH - 1 ? 'المستوى ٣' : null }))} />
 753:         </Field>
 754:         <Field label="الرابط (slug)" hint={!slugTouched ? <>هيتولد تلقائيًا من الاسم الإنجليزي</> : null} aside={slugTouched && <button className="text-[11px] font-semibold t-acc" onClick={() => { setSlugTouched(false); setV({ ...v, slug: '' }); }}>استخدام التلقائي</button>}>
 755:           <div className="relative"><span className="absolute top-1/2 -translate-y-1/2 left-3.5 text-[12.5px] t-3 ltr">/categories/</span>
 756:             <input className="v-input ltr" style={{ paddingLeft: 98 }} value={slugTouched ? v.slug || '' : autoSlug} placeholder="auto-generated" onChange={(e) => { setSlugTouched(true); setV({ ...v, slug: e.target.value }); }} />
 757:           </div>
 758:         </Field>
 759:         <Field label="الوصف" aside={<Seg value={lang} onChange={setLang} options={[{ value: 'ar', label: 'عربي' }, { value: 'en', label: 'EN' }]} />}>
 760:           {lang === 'ar' ? <Textarea value={v.desc_ar || ''} onChange={(e) => setV({ ...v, desc_ar: e.target.value })} /> : <Textarea className="ltr" dir="ltr" value={v.desc_en || ''} onChange={(e) => setV({ ...v, desc_en: e.target.value })} />}
 761:         </Field>
 762:         <Field label="صورة القسم"><ImageField value={v.img} onChange={(x) => setV({ ...v, img: x })} /></Field>
 763:         <div className="grid grid-cols-[120px_1fr] gap-3">
 764:           <Field label="الترتيب"><Input ltr type="number" value={v.order || ''} onChange={(e) => setV({ ...v, order: e.target.value })} /></Field>
 765:           <div className="v-subcard p-3.5 flex items-center justify-between self-end h-[42px] !rounded-[13px]"><span className="text-[12.5px] font-semibold t-1">نشط</span><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
 766:         </div>
 767:       </div>
 768:     </Drawer>
 769:   );
 770: }
