 772: /* ====================== BRANDS ====================== */
 773: function BrandsPage() {
 774:   const { user } = useApp();
 775:   const [q, setQ] = useQueryState({ search: '', status: '' });
 776:   const [phase, retry] = useLoad([q.search, q.status]);
 777:   const [form, setForm] = useState(null);
 778:   const [del, setDel] = useState(null);
 779:   if (!user.can('brands.view')) return <Forbidden perm="brands.view" />;
 780:   const rows = BRANDS.filter((b) => (!q.search || (b.ar + b.en).toLowerCase().includes(q.search.toLowerCase())) && (!q.status || b.status === q.status));
 781:   return (
 782:     <div className="space-y-5">
 783:       <PageHeader crumbs={[{ label: 'الكتالوج' }, { label: 'البراندات' }]} title="البراندات" subtitle="العلامات التجارية المرتبطة بالمنتجات."
 784:         actions={user.can('brands.manage') && <button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />براند جديد</button>} />
 785:       <div className="stagger s2">
 786:         <DataTable state={phase} onRetry={retry} rows={rows} filtered={q.search || q.status}
 787:           empty={!(q.search || q.status) && <EmptyState icon="tag" title="لا توجد براندات بعد" action={<button className="btn btn-ink" onClick={() => setForm({})}><Icon name="plus" size={15} />براند جديد</button>} />}
 788:           toolbar={<div className="flex items-center gap-2 flex-wrap">
 789:             <SearchBox value={q.search} onChange={(v) => setQ({ search: v })} placeholder="ابحث عن براند…" />
 790:             <div className="seg">{[['', 'الكل'], ['active', 'نشط'], ['inactive', 'غير نشط']].map(([k, l]) => <button key={k} className={cx(q.status === k && 'on')} onClick={() => setQ({ status: k })}>{l}</button>)}</div>
 791:           </div>}
 792:           columns={[
 793:             { key: 'logo', label: 'البراند', render: (r) => <div className="flex items-center gap-3">
 794:               <span className="w-11 h-11 rounded-[14px] shrink-0 flex items-center justify-center overflow-hidden checker">{r.logo ? <span className="w-full h-full flex items-center justify-center text-white font-display font-bold text-[15px]" style={{ background: r.logo }}>{r.en[0]}</span> : <Icon name="image" size={16} className="t-3" />}</span>
 795:               <div><div className="font-semibold t-1">{r.ar}</div><div className="text-[11.5px] t-3 ltr inline-block">{r.en}</div></div></div>,
 796:               skel: () => <div className="flex items-center gap-3"><Skel w={44} h={44} r={14} /><div className="space-y-1.5 flex-1"><Skel w="50%" h={10} /><Skel w="30%" h={8} /></div></div> },
 797:             { key: 'slug', label: 'الرابط', render: (r) => <span className="ltr inline-block text-[12px] t-2">/{r.slug}</span> },
 798:             { key: 'products', label: 'المنتجات', render: (r) => <span className="num font-semibold t-1">{r.products}</span> },
 799:             { key: 'order', label: 'الترتيب', render: (r) => <span className="num t-2">{r.order}</span> },
 800:             { key: 'status', label: 'الحالة', render: (r) => <StatusBadge s={r.status} /> },
 801:             { key: 'a', label: '', render: (r) => user.can('brands.manage') && <RowActions onEdit={() => setForm(r)} onDelete={() => setDel(r)} /> },
 802:           ]} />
 803:       </div>
 804:       <Drawer open={!!form} onClose={() => setForm(null)} title={form && form.id ? 'تعديل البراند' : 'براند جديد'} width={520}
 805:         footer={<><button className="btn btn-soft" onClick={() => setForm(null)}>إلغاء</button><button className="btn btn-ink" onClick={() => { vtoast('تم حفظ البراند'); setForm(null); }}>حفظ</button></>}>
 806:         {form && <BrandFormBody b={form} />}
 807:       </Drawer>
 808:       <ConfirmDialog open={!!del} onClose={() => setDel(null)} danger title={`حذف «${del && del.ar}»؟`} message="سيتم حذف البراند نهائيًا." confirmLabel="حذف"
 809:         serverError={del && del.products ? { title: 'لا يمكن حذف البراند', body: `البراند مرتبط بـ ${del.products} منتج. انقل المنتجات لبراند آخر، أو عطّل البراند بدل حذفه.` } : null} />
 810:     </div>
 811:   );
 812: }
 813: function BrandFormBody({ b }) {
 814:   const [v, setV] = useState({ status: 'active', ...b });
 815:   return (
 816:     <div className="space-y-4">
 817:       <Field label="اللوجو"><ImageField value={v.logo} onChange={(x) => setV({ ...v, logo: x })} label="رفع لوجو" /></Field>
 818:       <div className="grid grid-cols-2 gap-3">
 819:         <Field label="الاسم بالعربي" required><Input value={v.ar || ''} onChange={(e) => setV({ ...v, ar: e.target.value })} /></Field>
 820:         <Field label="الاسم بالإنجليزي" required><Input ltr value={v.en || ''} onChange={(e) => setV({ ...v, en: e.target.value })} /></Field>
 821:       </div>
 822:       <Field label="الرابط (slug)" hint="اتركه فارغًا ليتولد من الاسم الإنجليزي"><Input ltr value={v.slug || ''} placeholder={(v.en || '').toLowerCase().replace(/[^a-z0-9]+/g, '-')} onChange={(e) => setV({ ...v, slug: e.target.value })} /></Field>
 823:       <Field label="الوصف بالعربي"><Textarea rows={2} /></Field>
 824:       <Field label="الوصف بالإنجليزي"><Textarea rows={2} className="ltr" dir="ltr" /></Field>
 825:       <div className="grid grid-cols-[120px_1fr] gap-3">
 826:         <Field label="الترتيب"><Input ltr type="number" value={v.order || ''} onChange={(e) => setV({ ...v, order: e.target.value })} /></Field>
 827:         <div className="v-subcard p-3.5 flex items-center justify-between self-end h-[42px] !rounded-[13px]"><span className="text-[12.5px] font-semibold t-1">نشط</span><Toggle on={v.status === 'active'} onChange={(on) => setV({ ...v, status: on ? 'active' : 'inactive' })} /></div>
 828:       </div>
 829:     </div>
 830:   );
 831: }
