 916: Object.assign(window, { CategoriesPage, BrandsPage, ProductsPage, MAX_DEPTH });// Phase 0 — Shared components gallery (all states)
 917: function CompSection({ title, sub, children }) {
 918:   return (
 919:     <div className="v-card p-6">
 920:       <div className="mb-5"><h2 className="font-display text-[16px] font-semibold t-1">{title}</h2>{sub && <p className="text-[12.5px] t-2 mt-0.5">{sub}</p>}</div>
 921:       {children}
 922:     </div>
 923:   );
 924: }
 925: function StateLabel({ children }) { return <div className="text-[10.5px] font-semibold t-3 mb-2 uppercase tracking-wide">{children}</div>; }
