 927: function ComponentsPage() {
 928:   const [sel, setSel] = useState(null);
 929:   const [multi, setMulti] = useState([2]);
 930:   const [confirm, setConfirm] = useState(null);
 931:   const [tState, setTState] = useState('ready');
 932:   const [files, setFiles] = useState([
 933:     { id: 1, name: 'front.jpg', size: '2.1MB', status: 'done', bg: IMG[0] },
 934:     { id: 2, name: 'side.png', size: '3.8MB', status: 'uploading', progress: 64, bg: IMG[1] },
 935:     { id: 3, name: 'detail.webp', size: '5.6MB', status: 'failed', error: 'الحجم يتجاوز 5MB', bg: IMG[2] },
 936:     { id: 4, name: 'top.jpg', size: '1.2MB', status: 'queued', bg: IMG[3] },
 937:   ]);
 938:   const [api, setApi] = useState(null);
 939:   const res = fakeQuery(BRANCHES.slice(0, 4), { page: 1, per_page: 4 });
 940:   const apiErrors = {
 941:     401: { tone: 'amber', icon: 'lock', t: 'انتهت الجلسة', b: 'نافذة إعادة تسجيل الدخول — وبنرجّع المستخدم لنفس الصفحة.' },
 942:     403: { tone: 'amber', icon: 'shield', t: 'غير مسموح', b: 'ليس لديك صلاحية لتنفيذ هذا الإجراء. الأزرار المرتبطة بتختفي أو تتعطّل حسب الصلاحية.' },
 943:     409: { tone: 'amber', icon: 'refresh', t: 'تعارض في البيانات', b: 'السجل اتعدل من مستخدم آخر. حمّل أحدث نسخة قبل الحفظ.' },
 944:     422: { tone: 'red', icon: 'alertCircle', t: 'بيانات غير صالحة', b: 'الأخطاء بتترَبط بالحقول عن طريق adapter للفورم — بما فيها المسارات المتداخلة زي variants.2.retail_price.' },
 945:     429: { tone: 'amber', icon: 'clock', t: 'محاولات كثيرة', b: 'حاول مرة أخرى بعد ٦٠ ثانية. الزر بيتعطّل مع عداد تنازلي.' },
