1152: function flattenCats(nodes, depth = 0, path = []) {
1153:   return nodes.flatMap((n) => [{ ...n, depth, path: [...path, n.ar] }, ...flattenCats(n.children || [], depth + 1, [...path, n.ar])]);
1154: }
