1253:   if (!p) return null;
1254:   const colors = [PRESET_COLORS[0], PRESET_COLORS[1], PRESET_COLORS[4]];
1255:   const sizes = ['240×160', '280×180'];
1256:   const rows = [];
1257:   colors.forEach((c) => sizes.forEach((s, j) => rows.push({ ...emptyVariant(c, s, '', rows.length), sku: `MIL-${c.en.slice(0, 3).toUpperCase()}-${j + 1}`, barcode: `62210${40000 + rows.length * 37}`, retail: String(28500 + j * 6400), wholesale: String(24000 + j * 5200), cost: String(17800 + j * 3900), compare: j ? '' : '31900' })));
1258:   return {
1259:     status: p.status, code: p.code,
1260:     basic: { ar: p.ar, en: p.en, category: 111, brand: 1, channel: p.channel, slug: 'milano-corner-sofa', desc_ar: 'كنبة زاوية بتصميم معاصر، هيكل من خشب الزان المجفف وإسفنج عالي الكثافة.', desc_en: 'Contemporary corner sofa with kiln-dried beech frame and high-density foam.', mat_ar: 'قماش شانيل', mat_en: 'Chenille fabric', l: '280', w: '180', h: '85', kg: '96', warranty: '24', warranty_details: 'ضمان على الهيكل ضد عيوب التصنيع', origin: 'مصر', featured: p.featured, supplier: null },
