1555:     const names = ['living-room-01.jpg', 'angle-left.png', 'fabric-closeup.webp', 'lifestyle.jpg', 'top-view.jpg'];
1556:     const fresh = Array.from({ length: n }).map((_, i) => ({ id: Math.random().toString(36).slice(2), name: names[(media.general.length + i) % names.length], size: (1 + Math.random() * 3).toFixed(1) + 'MB', status: saved ? 'uploading' : 'queued', progress: 0, bg: IMG[(media.general.length + i + 2) % IMG.length] }));
1557:     if (target === 'general') {
1558:       if (media.general.length + n > 10) { setSizeErr('الحد الأقصى ١٠ صور في طلب الرفع الواحد'); return; }
1559:       const next = { ...media, general: [...media.general, ...fresh] };
1560:       setMedia(next);
1561:       if (saved) simulateUpload(next, fresh.map((f) => f.id));
1562:     } else {
1563:       setMedia({ ...media, byVariant: { ...media.byVariant, [target]: [...(media.byVariant[target] || []), ...fresh.slice(0, 1).map((f) => ({ ...f, status: saved ? 'done' : 'queued' }))] } });
1564:     }
1565:   };
1566:   const simulateUpload = (start, ids) => {
