1569:       pct += 20;
1570:       cur = { ...cur, general: cur.general.map((f) => ids.includes(f.id) ? { ...f, progress: pct, status: pct >= 100 ? (f.name.includes('webp') ? 'failed' : 'done') : 'uploading', error: f.name.includes('webp') && pct >= 100 ? 'الأبعاد تتجاوز 6000×6000' : null } : f) };
1571:       setMedia(cur);
1572:       if (pct >= 100) clearInterval(t);
1573:     }, 220);
1574:   };
