1750:             : d === 'upload_fail' ? <><button className="btn btn-soft" onClick={onClose}>لاحقًا</button><button className="btn btn-ink" onClick={onRetryUpload}><Icon name="refresh" size={14} />إعادة رفع الصور الفاشلة</button></>
1751:             : <button className="btn btn-ink" onClick={onClose}>فهمت</button>}
1752:         </div>
1753:       )}
1754:     </Modal>
