1758: Object.assign(window, { ProductForm });// Layout shell, router, permissions context, login
1759: const AppCtx = createContext(null);
1760: const useApp = () => useContext(AppCtx);
1761: 
1762: /* ---------- Hash router with query (URL-persisted page/search/filters) ---------- */
1763: function parseHash() {
1764:   const h = location.hash.replace(/^#/, '') || '/products';
1765:   const [path, qs] = h.split('?');
1766:   const q = Object.fromEntries(new URLSearchParams(qs || ''));
1767:   return { path, q, parts: path.split('/').filter(Boolean) };
1768: }
1769: function useRoute() {
1770:   const [r, setR] = useState(parseHash());
1771:   useEffect(() => { const h = () => setR(parseHash()); window.addEventListener('hashchange', h); return () => window.removeEventListener('hashchange', h); }, []);
1772:   return r;
1773: }
1774: function nav(path, q) {
1775:   const qs = q ? new URLSearchParams(Object.entries(q).filter(([, v]) => v !== null && v !== undefined && v !== '' && v !== false)).toString() : '';
1776:   location.hash = path + (qs ? '?' + qs : '');
1777: }
1778: // Update query in place (replace), keeps URL as source of truth for list state
1779: function useQueryState(defaults) {
1780:   const r = useRoute();
1781:   const state = { ...defaults, ...r.q };
1782:   const set = (patch) => {
1783:     const next = { ...state, ...patch };
1784:     Object.keys(defaults).forEach((k) => { if (String(next[k]) === String(defaults[k])) delete next[k]; });
1785:     const qs = new URLSearchParams(Object.entries(next).filter(([, v]) => v !== null && v !== undefined && v !== '')).toString();
1786:     history.replaceState(null, '', '#' + r.path + (qs ? '?' + qs : ''));
1787:     window.dispatchEvent(new HashChangeEvent('hashchange'));
1788:   };
1789:   return [state, set];
1790: }
1791: 
1792: /* ---------- Simulated latency hook, honouring the global "screen state" tweak ---------- */
1793: function useLoad(deps = [], ms = 650) {
1794:   const { screenState } = useApp();
1795:   const [phase, setPhase] = useState('loading');
1796:   const [nonce, setNonce] = useState(0);
1797:   useEffect(() => {
1798:     setPhase('loading');
1799:     if (screenState === 'loading') return;
1800:     const t = setTimeout(() => setPhase(screenState === 'error' ? 'error' : screenState === 'empty' ? 'empty' : 'ready'), ms);
1801:     return () => clearTimeout(t);
1802:   }, [...deps, nonce, screenState]);
1803:   return [phase, () => setNonce((n) => n + 1)];
1804: }
