1840:   return <span className="rounded-full inline-flex items-center justify-center font-bold shrink-0 text-[#18151c]" style={{ width: size, height: size, background: bg, fontSize: size * 0.36, border: '1px solid rgba(0,0,0,.05)' }}>{initials}</span>;
1841: }
