1843: function TopBar({ route }) {
1844:   const { user, setTheme, theme, logout } = useApp();
1845:   const [menu, setMenu] = useState(false);
1846:   const ref = useRef(null);
1847:   useOutside(ref, () => setMenu(false), menu);
1848:   const groups = NAV.slice(0, 2);
1849:   const groupOf = (k) => groups.find((g) => g.items.some((i) => i.key === k));
1850:   const activeGroup = groupOf(route.parts[0]);
1851:   return (
1852:     <header className="flex items-center justify-between gap-4 mb-6">
1853:       <Brand onClick={() => nav('/products')} />
1854:       <nav className="v-pill rounded-full p-1.5 hidden md:flex items-center gap-1 shadow-sm">
1855:         {groups.flatMap((g) => g.items).filter((i) => !i.perm || user.can(i.perm)).map((i) => {
1856:           const on = route.parts[0] === i.key;
1857:           return <a key={i.key} href={i.href} className={cx('px-4 lg:px-5 py-2 rounded-full text-[13px] font-medium transition-colors', on ? 'bg-ink' : 't-2 hover:t-1')}>{i.label}</a>;
1858:         })}
1859:       </nav>
1860:       <div className="flex items-center gap-3">
1861:         <div className="v-pill rounded-full px-4 py-2.5 flex items-center gap-4 shadow-sm">
1862:           <button title="بحث سريع" className="t-1 hover:opacity-70"><Icon name="search" size={17} sw={2} /></button>
1863:           <button title="الإشعارات" className="relative t-1 hover:opacity-70"><Icon name="bell" size={17} sw={2} /><span className="absolute -top-0.5 -end-0.5 w-2 h-2 rounded-full bg-[var(--accent)]" style={{ boxShadow: '0 0 0 2px var(--bg-card)' }} /></button>
1864:           <button title="المساعدة" className="t-1 hover:opacity-70"><Icon name="help" size={17} sw={2} /></button>
1865:         </div>
1866:         <div className="relative" ref={ref}>
1867:           <button onClick={() => setMenu(!menu)} className="v-pill rounded-full p-1.5 pe-4 flex items-center gap-2.5 shadow-sm hover:opacity-95 transition text-start">
1868:             <Avatar name={user.name} />
1869:             <div className="leading-tight hidden sm:block">
1870:               <div className="text-[13px] font-semibold t-1">{user.name}</div>
1871:               <div className="text-[11px] t-2">{user.roleName}</div>
1872:             </div>
1873:             <Icon name="chevDown" size={14} className="t-2 ms-1" />
1874:           </button>
1875:           {menu && (
1876:             <div className="pop absolute end-0 mt-2 w-[260px] v-card p-2 z-50" style={{ boxShadow: 'var(--shadow-pop)' }}>
1877:               <div className="px-3 py-2.5">
1878:                 <div className="text-[13px] font-semibold t-1">{user.name}</div>
1879:                 <div className="text-[11.5px] t-3 ltr text-end">{user.email}</div>
1880:               </div>
1881:               <div className="v-subcard p-1 m-1 flex">
1882:                 {['light', 'dark'].map((t) => <button key={t} onClick={() => setTheme(t)} className={cx('flex-1 h-8 rounded-xl text-[12px] font-medium flex items-center justify-center gap-1.5', theme === t ? 'bg-[var(--seg-active-bg)] t-1 shadow-sm' : 't-2')}><Icon name={t === 'light' ? 'sun' : 'moon'} size={14} />{t === 'light' ? 'فاتح' : 'داكن'}</button>)}
1883:               </div>
1884:               <button onClick={logout} className="w-full flex items-center gap-2.5 px-3 py-2.5 rounded-xl text-[12.5px] t-1 hover:bg-[var(--bg-subcard)]"><Icon name="logout" size={15} className="t-2" />تسجيل الخروج</button>
1885:             </div>
1886:           )}
1887:         </div>
1888:       </div>
1889:     </header>
1890:   );
1891: }
