1902:             <Icon name={t === 'light' ? 'sun' : 'moon'} size={16} />
1903:           </button>
1904:         ))}
1905:       </div>
1906:       <div className="v-pill rounded-full p-1.5 flex flex-col items-center gap-2 shadow-sm w-[44px] mt-4">
1907:         {items.map((i, idx) => {
1908:           const allowed = !i.perm || user.can(i.perm);
1909:           if (!allowed) return null;
1910:           const on = route.parts[0] === i.key;
1911:           const sep = idx > 0 && items[idx - 1].group !== i.group;
1912:           return (
1913:             <React.Fragment key={i.key}>
1914:               {sep && <span className="w-4 h-px my-0.5" style={{ background: 'var(--divider-color)' }} />}
1915:               <a href={i.href} onMouseEnter={() => setHover(i.key)} onMouseLeave={() => setHover(null)} className={cx('relative w-8 h-8 rounded-full flex items-center justify-center transition', on ? 'bg-acc' : 't-2 hover:t-1 hover:bg-[var(--bg-subcard)]')}>
1916:                 <Icon name={i.icon} size={16} />
1917:                 {hover === i.key && <span className="pop absolute start-full ms-3 whitespace-nowrap px-3 py-1.5 rounded-full text-[11.5px] font-semibold bg-ink z-50 pointer-events-none">{i.label}</span>}
1918:               </a>
1919:             </React.Fragment>
1920:           );
1921:         })}
1922:       </div>
1923:       <div className="v-pill rounded-full p-1.5 flex flex-col items-center gap-1.5 shadow-sm w-[44px] mt-10">
