1944: /* ---------- Login ---------- */
1945: function LoginScreen({ onLogin, scenario: initScenario }) {
1946:   const [email, setEmail] = useState('karim@vortix.store');
1947:   const [pw, setPw] = useState('');
1948:   const [show, setShow] = useState(false);
1949:   const [busy, setBusy] = useState(false);
1950:   const [err, setErr] = useState(null);
1951:   const [fieldErr, setFieldErr] = useState({});
1952:   const [lock, setLock] = useState(0);
1953:   const [attempts, setAttempts] = useState(0);
1954:   useEffect(() => {
1955:     if (initScenario === 'error') { setErr('fail'); setPw('wrongpass'); }
1956:     if (initScenario === 'throttle') { setErr('throttle'); setLock(58); }
1957:     if (initScenario === 'busy') { setBusy(true); setPw('••••••••'); }
1958:   }, [initScenario]);
1959:   useEffect(() => { if (lock <= 0) return; const t = setTimeout(() => setLock(lock - 1), 1000); return () => clearTimeout(t); }, [lock]);
1960:   const submit = (e) => {
1961:     e.preventDefault();
1962:     const fe = {};
1963:     if (!email) fe.email = 'البريد الإلكتروني مطلوب';
1964:     else if (!/^\S+@\S+\.\S+$/.test(email)) fe.email = 'صيغة البريد الإلكتروني غير صحيحة';
1965:     if (!pw) fe.pw = 'كلمة المرور مطلوبة';
1966:     setFieldErr(fe); if (Object.keys(fe).length) return;
1967:     setBusy(true); setErr(null);
1968:     setTimeout(() => {
1969:       setBusy(false);
1970:       if (pw === 'admin123') { onLogin(); return; }
1971:       const n = attempts + 1; setAttempts(n);
1972:       if (n >= 3) { setErr('throttle'); setLock(60); } else setErr('fail');
1973:     }, 900);
1974:   };
1975:   const locked = lock > 0;
1976:   return (
1977:     <div className="min-h-screen grid lg:grid-cols-[1fr_1.05fr] gap-5 p-5">
1978:       <div className="flex flex-col">
1979:         <div className="flex items-center justify-between"><Brand /><span className="text-[12px] t-3">العربية · <span className="ltr">EN</span></span></div>
1980:         <div className="flex-1 flex items-center justify-center py-10">
1981:           <form onSubmit={submit} className="w-full max-w-[400px] stagger s2" noValidate>
1982:             <h1 className="font-display text-[34px] font-semibold tracking-[-0.02em] t-1">مرحبًا بعودتك</h1>
1983:             <p className="text-[13.5px] t-2 mt-1.5">سجّل الدخول للوحة إدارة الكتالوج والمخزون.</p>
1984: 
1985:             {err === 'fail' && (
1986:               <div className="pop mt-6"><Banner tone="red" icon="alertCircle" title="بيانات الدخول غير صحيحة">تأكد من البريد وكلمة المرور. تبقّى <b className="num">{Math.max(0, 3 - attempts) || 2}</b> محاولات قبل الإيقاف المؤقت.</Banner></div>
1987:             )}
1988:             {err === 'throttle' && (
1989:               <div className="pop mt-6 rounded-[18px] p-4 b-amber">
1990:                 <div className="flex items-start gap-3">
1991:                   <span className="w-8 h-8 rounded-full flex items-center justify-center shrink-0" style={{ background: 'color-mix(in oklab, currentColor 14%, transparent)' }}><Icon name="clock" size={16} /></span>
1992:                   <div className="flex-1 text-[12.5px] leading-relaxed pt-1">
1993:                     <div className="font-semibold text-[13px]">محاولات كثيرة</div>
1994:                     <div className="opacity-90">{locked ? <>يمكنك المحاولة مرة أخرى خلال <b className="num">{lock}</b> ثانية.</> : 'يمكنك المحاولة الآن.'}</div>
1995:                     <div className="mt-2.5 h-1.5 rounded-full overflow-hidden" style={{ background: 'color-mix(in oklab, currentColor 14%, transparent)' }}><div className="h-full rounded-full bg-current transition-all duration-1000" style={{ width: `${(lock / 60) * 100}%` }} /></div>
1996:                   </div>
1997:                 </div>
1998:               </div>
1999:             )}
2000: 
2001:             <div className="space-y-4 mt-6">
2002:               <Field label="البريد الإلكتروني" required error={fieldErr.email}>
2003:                 <Input type="email" ltr icon="mail" value={email} onChange={(e) => setEmail(e.target.value)} error={fieldErr.email} placeholder="name@company.com" disabled={busy || locked} autoComplete="username" />
2004:               </Field>
2005:               <Field label="كلمة المرور" required error={fieldErr.pw}>
2006:                 <div className="relative">
2007:                   <Icon name="lock" size={15} className="absolute top-1/2 -translate-y-1/2 start-3.5 t-3 pointer-events-none" />
2008:                   <input type={show ? 'text' : 'password'} value={pw} onChange={(e) => setPw(e.target.value)} disabled={busy || locked} placeholder="••••••••" autoComplete="current-password"
2009:                     className={cx('v-input ltr ps-10 pe-12', fieldErr.pw && 'is-error')} />
2010:                   <button type="button" onClick={() => setShow(!show)} className="absolute top-1/2 -translate-y-1/2 end-1.5 icon-btn !w-8 !h-8" title={show ? 'إخفاء كلمة المرور' : 'إظهار كلمة المرور'}><Icon name={show ? 'eyeOff' : 'eye'} size={15} /></button>
2011:                 </div>
2012:               </Field>
2013:             </div>
2014:             <button type="submit" disabled={busy || locked} className="btn btn-ink btn-lg w-full mt-6">
2015:               {busy ? <><Spinner size={15} />جارٍ التحقق…</> : locked ? <>انتظر <span className="num">{lock}</span> ث</> : 'تسجيل الدخول'}
2016:             </button>
2017:             <p className="text-[11.5px] t-3 mt-4 text-center leading-relaxed">نسيت كلمة المرور؟ تواصل مع مدير النظام لإعادة تعيينها.<br /><span className="opacity-70">للتجربة: كلمة المرور <span className="ltr inline-block font-semibold">admin123</span></span></p>
2018:           </form>
2019:         </div>
2020:         <div className="text-[11px] t-3 flex justify-between"><span>© ٢٠٢٦ Vortix</span><span className="ltr">v2.4.0</span></div>
2021:       </div>
2022:       <div className="hidden lg:block v-orange rounded-[28px] relative overflow-hidden p-10 stagger s3">
2023:         <div className="absolute -bottom-24 -start-24 w-[420px] h-[420px] rounded-full" style={{ background: 'radial-gradient(circle, rgba(255,255,255,.22), transparent 65%)' }} />
2024:         <div className="relative h-full flex flex-col justify-between">
2025:           <span className="text-[12px] font-semibold px-3 py-1 rounded-full bg-white/15 self-start">لوحة الإدارة</span>
2026:           <div>
2027:             <div className="font-display text-[44px] leading-[1.15] font-semibold tracking-[-0.02em] max-w-[460px]">كتالوج واحد. كل الفروع. كل القنوات.</div>
2028:             <div className="grid grid-cols-3 gap-3 mt-10 max-w-[520px]">
2029:               {[['مسودة', 'ابدأ بالبيانات'], ['صور', 'ارفع بعد الحفظ'], ['نشر', 'بعد قائمة الجاهزية']].map(([a, b], i) => (
2030:                 <div key={a} className="rounded-[18px] p-4 bg-white/12 backdrop-blur-sm" style={{ background: 'rgba(255,255,255,.12)' }}>
2031:                   <div className="w-7 h-7 rounded-full bg-white text-[#e0491f] text-[12px] font-bold flex items-center justify-center num">{i + 1}</div>
2032:                   <div className="mt-3 text-[14px] font-semibold">{a}</div>
2033:                   <div className="text-[11.5px] text-white/75 mt-0.5">{b}</div>
2034:                 </div>
2035:               ))}
2036:             </div>
2037:             <div className="mt-4 h-2 rounded-full max-w-[520px]" style={{ background: 'repeating-linear-gradient(-60deg, rgba(255,255,255,.45) 0, rgba(255,255,255,.45) 1.5px, transparent 1.5px, transparent 5.5px)' }} />
2038:           </div>
2039:         </div>
2040:       </div>
2041:     </div>
2042:   );
2043: }
