2045: /* ---------- Unsaved-changes guard ---------- */
2046: function useUnsavedGuard(dirty) {
2047:   useEffect(() => {
2048:     const h = (e) => { if (dirty) { e.preventDefault(); e.returnValue = ''; } };
2049:     window.addEventListener('beforeunload', h);
2050:     return () => window.removeEventListener('beforeunload', h);
2051:   }, [dirty]);
2052: }
