2472: /* ---------------- Modal / Confirm ---------------- */
2473: function Modal({ open, onClose, children, width = 460, title, subtitle, icon, iconTone = 'acc', footer }) {
2474:   useEffect(() => {
2475:     if (!open) return;
2476:     const h = (e) => e.key === 'Escape' && onClose && onClose();
2477:     window.addEventListener('keydown', h); return () => window.removeEventListener('keydown', h);
2478:   }, [open]);
2479:   if (!open) return null;
2480:   return (
2481:     <div className="fixed inset-0 z-[70] flex items-center justify-center p-4 fade" style={{ background: 'var(--overlay)', backdropFilter: 'blur(3px)' }} onMouseDown={(e) => e.target === e.currentTarget && onClose && onClose()}>
2482:       <div className="pop v-card w-full overflow-hidden" style={{ maxWidth: width, boxShadow: 'var(--shadow-pop)', borderRadius: 26 }}>
2483:         {(title || icon) && (
2484:           <div className="p-6 pb-0 flex items-start gap-3.5">
2485:             {icon && <span className={cx('w-11 h-11 rounded-full flex items-center justify-center shrink-0', 'b-' + iconTone)}><Icon name={icon} size={19} /></span>}
2486:             <div className="flex-1 min-w-0 pt-0.5">
2487:               <h3 className="font-display text-[17px] font-semibold t-1">{title}</h3>
2488:               {subtitle && <p className="text-[13px] t-2 mt-1 leading-relaxed text-pretty">{subtitle}</p>}
2489:             </div>
2490:             {onClose && <button className="icon-btn -mt-1 -me-1" onClick={onClose}><Icon name="x" size={16} /></button>}
2491:           </div>
2492:         )}
2493:         <div className="p-6">{children}</div>
2494:         {footer && <div className="px-6 pb-6 -mt-2 flex items-center justify-end gap-2">{footer}</div>}
2495:       </div>
2496:     </div>
2497:   );
2498: }
