2500: // Confirm with server-rejection state
2501: function ConfirmDialog({ open, onClose, title, message, confirmLabel = 'تأكيد', danger, onConfirm, serverError, icon }) {
2502:   const [busy, setBusy] = useState(false);
2503:   const [err, setErr] = useState(null);
2504:   useEffect(() => { if (open) { setErr(null); setBusy(false); } }, [open]);
2505:   const go = async () => {
2506:     setBusy(true); setErr(null);
2507:     await new Promise((r) => setTimeout(r, 700));
2508:     if (serverError) { setErr(serverError); setBusy(false); return; }
2509:     setBusy(false); onConfirm && onConfirm(); onClose();
2510:   };
2511:   return (
2512:     <Modal open={open} onClose={busy ? null : onClose} title={title} subtitle={message} icon={icon || (danger ? 'trash' : 'alert')} iconTone={danger ? 'red' : 'amber'}>
2513:       {err && (
2514:         <div className="pop rounded-2xl p-3.5 mb-1 flex gap-3 b-red">
2515:           <Icon name="ban" size={17} className="mt-0.5" />
2516:           <div className="text-[12.5px] leading-relaxed">
2517:             <div className="font-semibold">{err.title}</div>
2518:             <div className="opacity-90 mt-0.5">{err.body}</div>
2519:             {err.items && <ul className="mt-2 space-y-1">{err.items.map((i) => <li key={i} className="flex items-center gap-1.5"><span className="w-1 h-1 rounded-full bg-current" />{i}</li>)}</ul>}
2520:           </div>
2521:         </div>
2522:       )}
2523:       <div className="flex items-center justify-end gap-2 mt-3">
2524:         <button className="btn btn-soft" onClick={onClose} disabled={busy}>{err ? 'إغلاق' : 'إلغاء'}</button>
2525:         {!err && <button className={cx('btn', danger ? 'btn-acc' : 'btn-ink')} style={danger ? { background: 'var(--badge-red-text)', boxShadow: 'none' } : null} onClick={go} disabled={busy}>
2526:           {busy && <Spinner size={14} />}{confirmLabel}
2527:         </button>}
2528:       </div>
2529:     </Modal>
2530:   );
2531: }
