2603: /* ---------------- Pagination (server meta) ---------------- */
2604: function Pagination({ meta, onPage, onPerPage }) {
2605:   const { current_page: p, last_page: last, per_page, total, from, to } = meta;
2606:   const pages = [];
2607:   for (let i = 1; i <= last; i++) if (i === 1 || i === last || Math.abs(i - p) <= 1) pages.push(i); else if (pages[pages.length - 1] !== '…') pages.push('…');
2608:   return (
2609:     <div className="flex flex-wrap items-center justify-between gap-3 px-5 py-3.5 v-border-t">
2610:       <div className="flex items-center gap-3 text-[12px] t-2">
2611:         <span>عرض <b className="t-1 num">{from}–{to}</b> من <b className="t-1 num">{total}</b></span>
2612:         <span className="w-px h-4" style={{ background: 'var(--divider-color)' }} />
2613:         <span className="flex items-center gap-1.5">لكل صفحة
2614:           <select value={per_page} onChange={(e) => onPerPage(+e.target.value)} className="h-8 rounded-full px-2.5 text-[12px] font-semibold outline-none" style={{ background: 'var(--bg-subcard)', color: 'var(--text-primary)' }}>
2615:             {[10, 15, 25, 50].map((n) => <option key={n} value={n}>{n}</option>)}
2616:           </select>
2617:         </span>
2618:       </div>
2619:       <div className="flex items-center gap-1">
2620:         <button className="icon-btn" disabled={p <= 1} onClick={() => onPage(p - 1)} style={{ opacity: p <= 1 ? .35 : 1 }}><Icon name="chevRight" size={15} /></button>
2621:         {pages.map((n, i) => n === '…' ? <span key={i} className="w-8 text-center t-3 text-[12px]">…</span> : (
2622:           <button key={i} onClick={() => onPage(n)} className={cx('min-w-[32px] h-8 px-2 rounded-full text-[12px] font-semibold num transition', n === p ? 'bg-ink' : 't-2 hover:bg-[var(--bg-subcard)]')}>{n}</button>
2623:         ))}
2624:         <button className="icon-btn" disabled={p >= last} onClick={() => onPage(p + 1)} style={{ opacity: p >= last ? .35 : 1 }}><Icon name="chevLeft" size={15} /></button>
2625:       </div>
2626:     </div>
2627:   );
2628: }
