2762: /* ---------------- File upload tile ---------------- */
2763: // status: queued | uploading | done | failed
2764: function FileTile({ file, onRemove, onRetry, draggable, onDragStart, onDragOver, onDrop, index, primary, compact, children }) {
2765:   const st = file.status;
2766:   return (
2767:     <div draggable={draggable} onDragStart={onDragStart} onDragOver={onDragOver} onDrop={onDrop}
